  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "*",
      "Resource": "*"
    }
  ]
}
\end{lstlisting}

\begin{lstlisting}[style=textstyle, caption={Sample \protect\UseVerb{credentials.json} file used to store the IAM user's access key.}, label={cap:paper_wsdm2022-sec:usage-subsec:getting-started:credentials}]
