\begin{tabular}{lp{7cm}}
  \toprule
   \textbf{Subfolder} & \textbf{Description}  \\
    \midrule
	\spverb|build/task/| & Contains the configuration of the task to deploy. \\
	\midrule
	\spverb|build/config/| & Contains the encrypted credentials used to unlock the \spverb|Generator| component. \\
	\midrule
	\spverb|build/environments/| & Contains the development and production environments. \\
	\midrule
	\spverb|build/mturk/| & Contains three files needed to publish the task using \mturk. \\
