  caption={Example of a valid \index{HIT}HIT set containing one task unit, designed and deployed using \crowdframe.},
  label={cap:paper_wsdm2022-sec:system-design-subsec:hits-lst:hit-fragment}]
[
  {
    "unit_id": "unit_0",
    "token_input": "ABCDEFGHILM",
    "token_output": "MNOPQRSTUVZ",
    "documents_number": 1,
    "documents": [
      {
        "id": "identifier_1",
        "text": "Lorem ipsum dolor sit amet"
