 \chapter{Section~\ref{cap:paper_is2022}: Multidimensional Scale For Reviews Quality Judgment}

 \label{cap:paper_is2022-appendix:mult-scale-rev}

 This appendix reports the adapted version of the multiple dimensions of truthfulness (Section~\ref{cap:paper_ipm2021-sec:exp-setup-subsec:seven-dim}) used to judge product review quality, as presented to workers during the crowdsourcing task. This list should be compared with the instructions in Appendix~\ref{cap:paper_ipm2021:-appendix:instructions}.


\begin{tcolorbox}[breakable,title=Review Quality Dimensions]
\begin{itemize}
    \item \index{Overall Truthfulness}\emph{Overall Truthfulness}: measures the overall truthfulness and trustworthiness of the review
    \begin{itemize}
        \item Example (label: +2 Completely Agree): ``They fit great, look great, are quite comfortable and are just what I was looking for!''
    \end{itemize}

    \item \index{Reliability}\emph{Reliability}: the review is considered reliable, as opposed to reporting unreliable information
    \begin{itemize}
        \item Example (label: +2 Completely Agree): ``They fit great, look great, are quite comfortable and are just what I was looking for!''
    \end{itemize}

    \item \index{Neutrality}\emph{Neutrality}: the review is expressed in objective terms, as opposed to being subjective or biased
    \begin{itemize}
        \item Example (label: -2 Completely Disagree): ``Love them!!''
    \end{itemize}

    \item \index{Comprehensibility}\emph{Comprehensibility}: the review is comprehensible / understandable / readable as opposed to difficult to understand
    \begin{itemize}
        \item Example (label: +2 Completely Agree): ``They run big. Order a full size smaller.''
    \end{itemize}

    \item \index{Precision}\emph{Precision}: the review is precise / specific, as opposed to vague
    \begin{itemize}
        \item Example (label: +2 Completely Agree): ``They run big. Order a full size smaller.''
    \end{itemize}

    \item \index{Completeness}\emph{Completeness}: the review is complete as opposed to partial
    \begin{itemize}
        \item Example (label: +2 Completely Agree): ``I actually have 3 pairs of these trainers. They are very comfortable, there is a neoprene sleeve that goes around your ankle that makes them the most comfortable for me compared to normal athletic shoes. They run a little narrow – for me this is perfect, but you may want to round up on the size or try on in the store first if your feet are on the wider side.''
    \end{itemize}

    \item \index{Informativeness}\emph{Informativeness}: the review allows deriving useful information as opposed to well-known facts and/or tautologies
    \begin{itemize}
        \item Example (label: +1 Agree): ``Love these shoes! Needed new running shoes and these are perfect. Light weight and fit great!''
    \end{itemize}
\end{itemize}
\end{tcolorbox}

