\section{The Recursive Solution}
Our recursive solution is based on the \textit {linearization} of the NLTV system described by \eqref{eqn:dynEqn} and \eqref{eqn:measEqn}. Our derivation follows the least squares principle \cite{muske1993receding,ling1999receding}. Assume we have the approximate state estimates:
\begin{equation*}
\tilde{\mathbf{X}}_k=\left[\tilde{\mathbf{x}}_{0|0},\tilde{\mathbf{x}}_{1|1},\tilde{\mathbf{x}}_{2|2},\tilde{\mathbf{x}}_{3|3},\cdots,\tilde{\mathbf{x}}_{k|k}\right].
\end{equation*}
Then, we define the a priori state approximation as:
\begin{equation*} \tilde{\mathbf{X}}_{k+1}^{-}=\left[\bar{\mathbf{x}}_{0},\tilde{\mathbf{x}}_{1|0},\tilde{\mathbf{x}}_{2|1},\tilde{\mathbf{x}}_{3|2},\tilde{\mathbf{x}}_{4|3},\cdots,\tilde{\mathbf{x}}_{k+1|k}\right]
\end{equation*}
% where $\tilde{\mathbf{x}}_{j+1|j}=f_j(\tilde{\mathbf{x}}_{j|j})$.
The dynamic model \eqref{eqn:dynEqn} and the measurement model \eqref{eqn:measEqn} are linearized at $\tilde{\mathbf{X}}_k$ and $\tilde{\mathbf{X}}_{k+1}^{-}$, respectively. Thus, the NLTV system approximates a linear time-variant (LTV) system:
\begin{IEEEeqnarray}{rcl}
\mathbf{x}_{k+1}&=&\mathbf{A}_k\mathbf{x}_k+\mathbf{u}_k+\mathbf{w}_k \label{eqn:linearizedDyn}
\\
\mathbf{y}_k&=&\mathbf{C}_k\mathbf{x}_k+\mathbf{d}_k+\mathbf{v}_k\label{eqn:linearizedMeas}
\end{IEEEeqnarray}
where
\begin{gather}
\mathbf{A}_k=\left[{\partial{f_k}}/{\partial \mathbf{x}_{k}}\right]_{\mathbf{x}_k=\tilde{\mathbf{x}}_{k|k}}, \quad \mathbf{C}_k=\left[{\partial{h_k}}/{\partial \mathbf{x}_{k}}\right]_{\mathbf{x}_k=\tilde{\mathbf{x}}_{k|k-1}}\nonumber
\\
\mathbf{u}_k=f_k(\tilde{\mathbf{x}}_{k|k})-\mathbf{A}_k\tilde{\mathbf{x}}_{k|k}\nonumber
\\
\mathbf{d}_k=h_k(\tilde{\mathbf{x}}_{k|k-1})-\mathbf{C}_k\tilde{\mathbf{x}}_{k|k-1}.\nonumber
\end{gather}
The constraints on system noise in \eqref{eqn:mhe} are linearized correspondingly:
\begin{IEEEeqnarray}{rcl}
\hat{\mathbf{w}}_{j|k}&=&\hat{\mathbf{x}}_{j+1|k}-\mathbf{A}_j\hat{\mathbf{x}}_{j|k}-\mathbf{u}_j\label{eqn:U_noise}
\\
\hat{\mathbf{v}}_{j|k}&=&\mathbf{y}_{j}-\mathbf{C}_j\hat{\mathbf{x}}_{j|k}-\mathbf{d}_j.\label{eqn:V_noise}
\end{IEEEeqnarray}

% In the following derivation, we discuss the recursive solution only for receding horizon state estimation since the solution to the BLS estimation can be acquired by applying a global horizon.

\begin{lemma}\label{lemma1} Given the prior state estimate $\hat{\mathbf{x}}_{k-N|k-N-1}$ and the state noise estimates given measurements up to time $k$, i.e., $\hat{\mathbf{\Omega}}_N^{k-N}=[\hat{\mathbf{w}}_{k-N-1|k}^T, \hat{\mathbf{w}}_{k-N|k}^T,\cdots,\hat{\mathbf{w}}_{k-1|k}^T]^T$, the state estimate at time $j$ $(k-N \leq j \leq k, k \geq N)$ is:
\begin{IEEEeqnarray}{rcl}
\hat{\mathbf{x}}_{j|k}&=&\mathbf{A}_{j-1}^{j-(k-N)}\hat{\mathbf{x}}_{k-N|k-N-1}\nonumber
\\
&&+\sum_{i=0}^{j-(k-N)-1}\mathbf{A}_{j-1}^{j-(k-N)-i-1}\mathbf{u}_{k-N+i}\nonumber
\\
&&+\sum_{i=0}^{j-(k-N)}\mathbf{A}_{j-1}^{j-(k-N)-i}\hat{\mathbf{w}}_{k-N-1+i|k}\label{eqn:x_expression}
\end{IEEEeqnarray}
where,
\begin{gather*}
\mathbf{A}_{k}^0=\mathbf{I},\quad \mathbf{A}_{-1}^0=\mathbf{I},\quad \mathbf{A}_{k}^N=\prod_{i=0}^{N-1} \mathbf{A}_{k-i},\quad \hat{\mathbf{x}}_{0|-1}=\bar{\mathbf{x}}_0, 
\end{gather*}
\end{lemma}
where $\mathbf{I}$ denotes the identity matrix. Lemma 1 can be proved by induction. 

% See Appendix \ref{sec:lemma1}.

Substituting \eqref{eqn:U_noise}, \eqref{eqn:V_noise}, and \eqref{eqn:x_expression} into the minimization problem \eqref{eqn:mhe} yields:
\begin{IEEEeqnarray}{rcl}\label{eqn:lsMhe}   &&\min_{\hat{\mathbf{\Omega}}_N^{k-N}}\Phi_k=\hat{\mathbf{\Omega}}_N^{{k-N}^T}\tilde{\mathbf{Q}}_N^{k-N}\hat{\mathbf{\Omega}}_N^{k-N}+
\\
&&\left(\mathbf{B}_N^{k-N}-\mathbf{D}_N^{k-N}\hat{\mathbf{\Omega}}_N^{k-N}\right)^T\mathbf{R}_N^{k-N}\left(\mathbf{B}_N^{k-N}-\mathbf{D}_N^{k-N}\hat{\mathbf{\Omega}}_N^{k-N}\right)\nonumber
\end{IEEEeqnarray}
where the giant covariance matrices describing the system statistics in the current horizon are
\begin{gather}
    \tilde{\mathbf{Q}}_N^{k-N}=diag\{\mathbf{P}_{k-N}^{-1},\mathbf{Q}_{k-N}^{-1},\cdots,\mathbf{Q}_{k-1}^{-1}\}\label{eqn:Q}
    \\
    {\mathbf{R}}_N^{k-N}=diag\{\mathbf{R}_{k-N}^{-1},\mathbf{R}_{k-N+1}^{-1},\cdots,\mathbf{R}_{k}^{-1}\}.\label{eqn:R}
\end{gather}
The giant vector involving all measurements in the horizon is defined as:
\begin{equation}
    \mathbf{B}_N^{k-N}=\left[\mathbf{b}_{k-N}^T,\mathbf{b}_{k-N+1}^T,\cdots,\mathbf{b}_{k}^T\right]^T\label{eqn:B}
\end{equation}
where
\begin{gather}
    \mathbf{b}_j=\mathbf{y}_j-\mathbf{C}_j\mathbf{A}_{j-1}^{j-(k-N)}\hat{\mathbf{x}}_{k-N|k-N-1}-\nonumber
\\
\mathbf{C}_j\sum_{i=0}^{j-(k-N)-1}\mathbf{A}_{j-1}^{j-(k-N)-i-1}\mathbf{u}_{k-N+i}-\mathbf{d}_j.\label{eqn:b}
\end{gather}
The relationship between the measurements and states in the horizon is represented by:
\begin{gather}
\mathbf{D}_N^{k-N}=\label{eqn:D}
\\
\begin{bmatrix}
&\mathbf{C}_{k-N}&0&\cdots&0
\\
&\mathbf{C}_{k-N+1}\mathbf{A}_{k-N}&\mathbf{C}_{k-N+1}&\cdots&0
\\
&\mathbf{C}_{k-N+2}\mathbf{A}_{k-N+1}^2&\mathbf{C}_{k-N+2}\mathbf{A}_{k-N+1}&\cdots&0
\\
&\vdots&\vdots&\vdots&\vdots
\\
&\mathbf{C}_{k-1}\mathbf{A}_{k-2}^{N-1}&\mathbf{C}_{k-1}\mathbf{A}_{k-2}^{N-2}&\cdots&0
\\
&\mathbf{C}_{k}\mathbf{A}_{k-1}^{N}&\mathbf{C}_{k}\mathbf{A}_{k-1}^{N-1}&\cdots&\mathbf{C}_{k}\nonumber
\end{bmatrix}
\end{gather}
The least squares problem described by \eqref{eqn:lsMhe} can be solved as:
\begin{equation}\label{eqn:omega}
\hat{\mathbf{\Omega}}_N^{k-N}=\left(\mathbf{E}_N^{k-N}+\tilde{\mathbf{Q}}_N^{k-N}\right)^{-1}\mathbf{G}_N^{k-N}\mathbf{B}_N^{k-N}
\end{equation}
where
\begin{gather}
\mathbf{E}_N^{k-N}=\mathbf{D}_N^{{k-N}^T}\mathbf{R}_N^{k-N}\mathbf{D}_N^{k-N}\label{eqn:E}
\\
\mathbf{G}_N^{k-N}=\mathbf{D}_N^{{k-N}^T}\mathbf{R}_N^{k-N}.\label{eqn:G}
\end{gather}
% $\mathbf{E}_N^{k-N}$ and $\mathbf{G}_N^{k-N}$ can be written in recursive formats:
% \begin{gather*}
%     \mathbf{E}_N^{k-N}=\begin{bmatrix}
% \mathbf{E}_{N-1}^{k-N}+\tilde{\mathbf{A}}_{N-1}^{{k-1}^T}\mathbf{F}_0^{k}\tilde{\mathbf{A}}_{N-1}^{{k-1}}&\tilde{\mathbf{A}}_{N-1}^{{k-1}^T}\mathbf{F}_0^{k}
% \\
% \mathbf{F}_0^{k}\tilde{\mathbf{A}}_{N-1}^{{k-1}}&\mathbf{F}_0^{k}
% \end{bmatrix}
% \\
% \mathbf{G}_N^{k-N}=\begin{bmatrix}
% \mathbf{G}_{N-1}^{k-N}&\tilde{\mathbf{A}}_{N-1}^{{k-1}^T}\mathbf{G}_0^{k}
% \\
% 0&\mathbf{G}_0^{k}
% \end{bmatrix}
% \end{gather*}
% where
% \begin{gather*}
% \mathbf{F}_0^{k}=\mathbf{C}_k^T\mathbf{R}_k^{-1}\mathbf{C}_k
% \\
% \mathbf{G}_0^{k}=\mathbf{C}_k^T\mathbf{R}_k^{-1}.
% \end{gather*}
Substituting \eqref{eqn:linearizedDyn} and \eqref{eqn:omega} into \eqref{eqn:x_expression} yields the recursive state estimate:
\begin{IEEEeqnarray}{rcl}\label{eqn:solution}
\hat{\mathbf{x}}_{k+1|k}&=&\mathbf{A}_{k}^{N+1}\hat{\mathbf{x}}_{k-N|k-N-1}+\sum_{i=0}^{N}\mathbf{A}_{k}^{N-i}\mathbf{u}_{k-N+i}\nonumber
\\
&&+\mathbf{L}_N^{k-N}\mathbf{B}_N^{k-N}
\end{IEEEeqnarray}
where
\begin{gather}
    \mathbf{L}_N^{k-N}=\tilde{\mathbf{A}}_N^k\left(\mathbf{E}_N^{k-N}+\tilde{\mathbf{Q}}_N^{k-N}\right)^{-1}\mathbf{G}_N^{k-N}\label{eqn:L}
    \\
\tilde{\mathbf{A}}_{N}^{k}=\left[\mathbf{A}_{k}^{N+1},\mathbf{A}_{k}^{N},\cdots,\mathbf{A}_{k}\right].\label{eqn:tildeA} 
\end{gather}



% \mathbf{C}_k=\left[\frac{\partial{h_k}}{\partial \mathbf{x}_{k}}\right]_{\mathbf{x}_k=\tilde{\mathbf{x}}_{k|k-1}},

% \{\tilde{\mathbf{x}}_{k-N|k-N-1},\cdots,\tilde{\mathbf{x}}_{k|k-1}\}\gets\{\hat{\mathbf{x}}_{k-N|k-N-1}^{(N)},\cdots,\hat{\mathbf{x}}_{k|k-1}^{(N)}\},

\begin{algorithm}[!t]
\caption{Recursive MHE at time $k$}\label{alg:1}
\KwIn{$\{\mathbf{y}_{k-N},\cdots,\mathbf{y}_k\}$, 
\\
$\quad\quad \{\mathbf{Q}_{k-N},\cdots,\mathbf{Q}_{k-1}\},\{\mathbf{R}_{k-N},\cdots,\mathbf{R}_k\}$,
\\
$\quad\quad \{\hat{\mathbf{x}}_{k-N|k-N-1}^{(N)},\cdots,\hat{\mathbf{x}}_{k|k-1}^{(N)}\}, \{\mathbf{P}_{k-N},\cdots,\mathbf{P}_{k}\}$}

\KwOut{$\hat{\mathbf{x}}_{k+1|k}^{(N)}$}

Linearize the system \eqref{eqn:dynEqn}, \eqref{eqn:measEqn}\;

Prepare system statistics using \eqref{eqn:Q} and \eqref{eqn:R}\;

Prepare measurements using \eqref{eqn:B} and \eqref{eqn:b}\;

Assemble matrices using \eqref{eqn:D}, \eqref{eqn:E}, \eqref{eqn:G}, \eqref{eqn:tildeA}, \eqref{eqn:L}\;

Compute $\hat{\mathbf{x}}_{k+1|k}^{(N)}$ using \eqref{eqn:solution}, and update to $\mathbf{P}_{k+1}$\; 

\Horizon{$\{\mathbf{y}_{k-N+1},\cdots,\mathbf{y}_{k+1}\}$
\\$\quad\{\mathbf{Q}_{k-N+1},\cdots,\mathbf{Q}_{k}\},\{\mathbf{R}_{k-N+1},\cdots,\mathbf{R}_{k+1}\}$,
\\$\{\hat{\mathbf{x}}_{k-N+1|k-N}^{(N)},\cdots,\hat{\mathbf{x}}_{k+1|k}^{(N)}\}, \{\mathbf{P}_{k-N+1},\cdots,\mathbf{P}_{k+1}\}$}
\end{algorithm}


\section{UNIFICATION}
In this section, we unify the classic EKF and popular FGO into the MHE framework. \textit {To the best of our knowledge, our work is the first to provide the conditions under which EKF and MHE achieve equivalence {\bfseries for any horizon size in NLTV systems}.} Additionally, we highlight the connection between FGO and MHE. 

