\subsection{Equivalence between MHE and EKF}
To derive and prove the conditions for the equivalence between EKF and MHE, we followed the idea in \cite{muske1993receding} by extending it from LTI systems to NLTV ones.

\begin{lemma}\label{lemma2}
The filtering algebraic Riccati matrix $\mathbf{P}_k$, which is the solution to
\begin{IEEEeqnarray}{rcl}\label{eqn:riccati}
&&\mathbf{P}_{k}=\mathbf{Q}_{k-1}+\mathbf{A}_{k-1}[\mathbf{P}_{k-1}-
\\
&&\mathbf{P}_{k-1}\mathbf{C}_{k-1}^T\left(\mathbf{C}_{k-1}\mathbf{P}_{k-1}\mathbf{C}_{k-1}^T+\mathbf{R}_{k-1}\right)^{-1}\mathbf{C}_{k-1}\mathbf{P}_{k-1}]\mathbf{A}_{k-1}^T\nonumber
\end{IEEEeqnarray},
can be computed as follows for all $N \geq 0$ and $k>N$:
\begin{equation}\label{eqn:lemma2_right_side}
\mathbf{P}_k=\tilde{\mathbf{A}}_N^{k-1}\left(\mathbf{E}_N^{k-N-1}+\tilde{\mathbf{Q}}_N^{k-N-1}\right)^{-1}\tilde{\mathbf{A}}_N^{{k-1}^T}+\mathbf{Q}_{k-1}.
\end{equation}
\end{lemma}
The proof is given in Appendix \ref{sec:lemma2}.

\begin{corollary}\label{corollary2.1}
From Lemma 2, we can derive the following identity
\begin{equation*}
\left(\mathbf{P}_k^{-1}+\mathbf{C}_k^T\mathbf{R}_k^{-1}\mathbf{C}_k\right)^{-1}=\tilde{\mathbf{E}}_0^{{k}^{-1}}+\mathbf{\Lambda}_N^{k-N-1}
\end{equation*}
where
\begin{gather*}
\tilde{\mathbf{E}}_0^{{k}}=\mathbf{C}_k^T\mathbf{R}_k^{-1}\mathbf{C}_k+\mathbf{Q}_{k-1}^{-1}
\\
\mathbf{\Lambda}_N^{k-N-1}=\tilde{\mathbf{E}}_0^{{k}^{-1}}\mathbf{Q}_{k-1}^{-1}\tilde{\mathbf{A}}_{N}^{k-1}\mathbf{W}_{N}^{{k-N-1}^{-1}}\tilde{\mathbf{A}}_{N}^{{k-1}^T}\mathbf{Q}_{k-1}^{-1}\tilde{\mathbf{E}}_0^{{k}^{-1}}
\\
\mathbf{W}_{N}^{k-N-1}=\mathbf{E}_{N}^{k-N-1}+\tilde{Q}_{N}^{k-N-1}+\tilde{\mathbf{A}}_N^{{k-1}^T}\mathbf{\Theta}_{k-1}\tilde{\mathbf{A}}_N^{{k-1}}
\\
\mathbf{\Theta}_{k-1}=\mathbf{Q}_{k-1}^{-1}-\mathbf{Q}_{k-1}^{-1}\tilde{\mathbf{E}}_0^{{k}^{-1}}\mathbf{Q}_{k-1}^{-1}
\end{gather*}
\end{corollary}
% The proof can be found in Appendix \ref{sec:corollary2.1}.

\begin{lemma}\label{lemma3}
For $k\geq N$ and $N > 0$, $\mathbf{L}_N^{k-N}$ can be computed as follows: 
\begin{IEEEeqnarray*}{rcl}
&&\mathbf{L}_{N}^{k-N}=
\\
&&[\left(\mathbf{A}_k-\mathbf{A}_k\mathbf{K_k}\mathbf{C}_k\right)\tilde{\mathbf{A}}_{N-1}^{k-1}\left(\mathbf{E}_{N-1}^{k-N}+\tilde{\mathbf{Q}}_{N-1}^{k-N}\right)^{-1}\mathbf{G}_{N-1}^{k-N},
\\
&&\mathbf{A}_k\mathbf{K}_k].
\end{IEEEeqnarray*}
where 
\begin{equation}\label{eqn:kalmanGain}
    \mathbf{K}_k=(\mathbf{P}_k^{-1}+\mathbf{C}_k^{T}\mathbf{R}_k^{-1}\mathbf{C}_k)^{-1}\mathbf{C}_k^{T}\mathbf{R}_k^{-1}. 
\end{equation}
\end{lemma}
The proof is provided in \ref{sec:lemma3}.
% Lemma \ref{lemma3} can be proved by substituting the recursive format of $\mathbf{E}_{N}^{k-N}$ and $\mathbf{G}_{N}^{k-N}$ into $\mathbf{L}_{N}^{k-N}$ and performing the partitioned matrix inversion. 

We denote the state estimates of EKF and MHE as $\hat{\mathbf{x}}_{k+1|k}^{(EKF)}$ and $\hat{\mathbf{x}}_{k+1|k}^{(N)}$, respectively. Considering Lemma \ref{lemma2}, Lemma \ref{lemma3}, and Corollary \ref{corollary2.1}, we give the following theorem.

\begin{theorem} \label{the:MheEkf}
If an NLTV system described by \eqref{eqn:dynEqn} and \eqref{eqn:measEqn} is linearized around the following two groups of approximate states, respectively:
\begin{IEEEeqnarray}{rCl}
\tilde{\mathbf{x}}_{k|k}&=&\tilde{\mathbf{x}}_{k|k-1}+\mathbf{K}_k\left(\mathbf{y}_k-h_k(\tilde{\mathbf{x}}_{k|k-1})\right) \label{eqn:taylorDyn}
\\
\tilde{\mathbf{x}}_{k|k-1}&=&\left\{\begin{array}{ll} 
\bar{\mathbf{x}}_0 & \mbox{if $k=0$};
\\
\hat{\mathbf{x}}_{k|k-1}^{(k-1)} & \mbox{if $0<k\leq N$};
\\
\hat{\mathbf{x}}_{k|k-1}^{(N)} & \mbox{if $k> N$}
\end{array}\right.\label{eqn:taylorMeas}
\end{IEEEeqnarray}
where $\mathbf{P}_k$ is the solution of the discrete filtering Riccati equation \eqref{eqn:riccati}, we will have 
\begin{equation*}
\hat{\mathbf{x}}_{k+1|k}^{(N)}=\hat{\mathbf{x}}_{k+1|k}^{(EKF)}, N \in \mathbb{N}.
\end{equation*}
\end{theorem}
The proof is given in Appendix \ref{sec:the1}.

\begin{remark}
Under the conditions specified in \autoref{the:MheEkf}, an algebraic expression for MHE is analytically derived, formulating a filtering-based MHE and establishing the equivalence to EKF accordingly. Since EKF is a recursive solution to the BLS estimation \cite{muske1993receding,robertson1996moving}, MHE can unify EKF and BLS, as shown by Fig. \ref{fig:ekf_bls_mhe}.

\autoref{the:MheEkf} indicates that the nonlinear measurement equation \eqref{eqn:measEqn} at time $k$ should be linearized using the MHE prediction at that time, based on measurements available up to time $k-1$. Note that the horizon size must be truncated if there are not sufficient measurements to construct a complete horizon. The approximate states used to linearize the state transition equation \eqref{eqn:dynEqn} and the measurement equation \eqref{eqn:measEqn} follow a relationship analogous to the update phase in EKF, as demonstrated in \eqref{eqn:taylorDyn}. In fact, the coefficient matrix $\mathbf{K}_k$ is essentially another form of the Kalman gain matrix, which can be proved using the matrix inversion lemma \cite{higham2002accuracy}. Such recursive MHE is summarized in Algorithm \ref{alg:1}. We display here the case where the time $k$ is larger than the horizon size $N$, while other cases can be easily derived from it. 
\end{remark}

Fig. \ref{fig:ekf_mhe} displays the difference in positioning results of EKF and MHE with various horizon sizes, where MHE is implemented according to Theorem \ref{the:MheEkf}. The data is from the GSDC 2021 dataset with an identifier ``2020-05-14-US-MTV-1" \cite{fu2020android}. Fig. \ref{fig:ekf_mhe} illustrates that EKF is equivalent to MHE regardless of the horizon size. The nanometer-level difference between them is due to the expected floating-point noise resulting from their different implementations.



