\begin{equation}\label{eqn:lemma2}
\mathbf{P}_k=\mathbf{A}_{k-1}\left(\mathbf{P}_{k-1}^{-1}+\mathbf{C}_{k-1}^T\mathbf{R}_{k-1}^{-1}\mathbf{C}_{k-1}\right)^{-1}\mathbf{A}_{k-1}^T+\mathbf{Q}_{k-1}.
