%  \boldsymbol{\mathcal{Q}}_{j+N-2}=\mathbf{Q}_{j+N-2}^{-1}-\mathbf{Q}_{j+N-2}^{-1}\tilde{\mathbf{E}}_0^{{j+N-1}^{-1}}\mathbf{Q}_{j+N-2}^{-1}
% \end{gather*}

On the other hand, considering \eqref{eqn:E} can be computed recursively, i.e.:
\begin{equation}\label{eqn:RecurE}
    \mathbf{E}_N^{k-N}=\begin{bmatrix}
\mathbf{E}_{N-1}^{k-N}+\tilde{\mathbf{A}}_{N-1}^{{k-1}^T}\mathbf{F}_0^{k}\tilde{\mathbf{A}}_{N-1}^{{k-1}}&\tilde{\mathbf{A}}_{N-1}^{{k-1}^T}\mathbf{F}_0^{k}
\\
\mathbf{F}_0^{k}\tilde{\mathbf{A}}_{N-1}^{{k-1}}&\mathbf{F}_0^{k}
\end{bmatrix},
\end{equation}
where $\mathbf{F}_0^{k}=\mathbf{C}_k^T\mathbf{R}_k^{-1}\mathbf{C}_k$, the right side of \eqref{eqn:lemma2_right_side} is written as:
\begin{equation*}
    \tilde{\mathbf{A}}_N^{j+N-1}\begin{bmatrix}
        \boldsymbol{\mathcal{E}}_{N-1}^{j-1}&\mathbf{F}_{N-1}^{j+N-1}
        \\
        \mathbf{F}_{N-1}^{{j+N-1}^T}&\tilde{\mathbf{E}}_0^{j+N-1}
    \end{bmatrix}^{-1}\tilde{\mathbf{A}}_N^{{j+N-1}^T}+\mathbf{Q}_{j+N-1},
\end{equation*}
where 
\begin{gather*}
    \boldsymbol{\mathcal{E}}_{N-1}^{j-1}=\mathbf{E}_{N-1}^{j-1}+\tilde{\mathbf{A}}_{N-1}^{{j+N-2}^T}\mathbf{F}_0^{j+N-1}\tilde{\mathbf{A}}_{N-1}^{j+N-2}+\tilde{\mathbf{Q}}_{N-1}^{j-1}
    \\
    \mathbf{F}_{N-1}^{j+N-1}=\tilde{\mathbf{A}}_{N-1}^{{j+N-2}^T}\mathbf{F}_0^{j+N-1},
\end{gather*}
which can be reformulated exactly the same as the right side of \eqref{eqn:lemma2_inter} according to the formula of blockwise inversion \cite{lu2002inverses}. Therefore, Lemma \ref{lemma2} also holds for $N$, which proves the lemma by induction.

% \subsection{Proof of Corollary 2.1}\label{sec:corollary2.1}

\subsection{Proof of Lemma \ref{lemma3}}\label{sec:lemma3}
 % the recursive form of $\mathbf{E}_N^{k-N}$ 
 Substituting \eqref{eqn:RecurE} into \eqref{eqn:L} and expanding the expression with the formula for block matrix inversion \cite{lu2002inverses} yield:
\begin{IEEEeqnarray}{rcl}
    \mathbf{L}_N^{k-N}&=&\mathbf{A}_k[\tilde{\mathbf{E}}_0^{k^{-1}}\mathbf{Q}_{k-1}^{-1}\tilde{\mathbf{A}}_{N-1}^{k-1}\mathbf{W}_{N-1}^{k-N}\mathbf{G}_{N-1}^{k-N},\nonumber
    \\
    &&(\mathbf{\Lambda}_{N-1}^{k-N}+\tilde{\mathbf{E}}_0^{k^{-1}})\mathbf{G}_0^k]\label{eqn:lemma3_inter}
\end{IEEEeqnarray}
We separately handle each component of $\mathbf{L}_N^{k-N}$ shown by \eqref{eqn:lemma3_inter}. By performing the matrix inversion lemma \cite{higham2002accuracy} on $\mathbf{W}_{N-1}^{k-N}$ and applying Lemma \ref{lemma2}, we can rewrite the first component as:
\begin{IEEEeqnarray*}{rcl}
    &&\tilde{\mathbf{E}}_0^{k^{-1}}\mathbf{Q}_{k-1}^{-1}\tilde{\mathbf{A}}_{N-1}^{k-1}\mathbf{W}_{N-1}^{k-N}\mathbf{G}_{N-1}^{k-N}=
    \\
    &&\left[\mathbf{I}-\mathbf{K}_k\mathbf{C}_k\right]\tilde{\mathbf{A}}_{N-1}^{k-1}\left(\mathbf{E}_{N-1}^{{k-N}}+\tilde{\mathbf{Q}}_{N-1}^{k-N}\right)\mathbf{G}_{N-1}^{k-N}.
\end{IEEEeqnarray*}
Then, applying Corollary \ref{corollary2.1} to the second component yields:
\begin{equation*}
    (\mathbf{\Lambda}_{N-1}^{k-N}+\tilde{\mathbf{E}}_0^{k^{-1}})\mathbf{G}_0^k=\mathbf{K}_k,
\end{equation*}
which proves Lemma \ref{lemma3}.

\subsection{Proof of Theorem \ref{the:MheEkf}}\label{sec:the1}
The proof is by induction with respect to $N$. For $N=0$ and $k\geq 0$, according to the conditions described by \eqref{eqn:taylorDyn} and \eqref{eqn:taylorMeas}, the equation \eqref{eqn:L} is reformulated as:
\begin{IEEEeqnarray*}{rcl}
   \hat{\mathbf{x}}_{k+1|k}^{(0)}&=&\mathbf{A}_{k}\hat{\mathbf{x}}_{k|k-1}^{(0)}+\mathbf{u}_{k}+\mathbf{L}_0^{k}\mathbf{B}_0^{k}
\\
&=&\mathbf{A}_{k}\left(\hat{\mathbf{x}}_{k|k-1}^{(0)}+\mathbf{K}_k\mathbf{b}_k\right)+\mathbf{u}_k
\\
&=&f_k\left(\hat{\mathbf{x}}_{k|k-1}^{(0)}+\mathbf{K}_k\left(\mathbf{y}_k-h_k(\hat{\mathbf{x}}_{k|k-1}^{(0)})\right)\right)=\hat{\mathbf{x}}_{k+1|k}^{(EKF)} 
\end{IEEEeqnarray*}
Thus, we can assume that Theorem \ref{the:MheEkf} holds for $N=M\geq 0$:
\begin{IEEEeqnarray*}{rcl}
\hat{\mathbf{x}}_{k+1|k}^{(M)}&=&f_k\left(\hat{\mathbf{x}}_{k|k-1}^{(M)}+\mathbf{K}_k\left(\mathbf{y}_k-h_k(\hat{\mathbf{x}}_{k|k-1}^{(M)})\right)\right)
\\
&=&\hat{\mathbf{x}}_{k+1|k}^{(EKF)}
\end{IEEEeqnarray*}

Then, we continue to prove the theorem for $N=M+1$ on a case-by-case basis.

1) When $k=0$, we can obtain the following equality:
\begin{equation*}  \hat{\mathbf{x}}_{1|0}^{(M+1)}=\hat{\mathbf{x}}_{1|0}^{(0)}=\hat{\mathbf{x}}_{1|0}^{(EKF)}
\end{equation*}

2) When $0<k\leq M+1$, considering $\hat{\mathbf{x}}_{k|k-1}^{(M+1)}=\hat{\mathbf{x}}_{k|k-1}^{(M)}=\hat{\mathbf{x}}_{k|k-1}^{(k-1)}$, we can get the following equality by substituting Lemma \ref{lemma3} to \eqref{eqn:x_expression}:
\begin{IEEEeqnarray*}{rcl}
\hat{\mathbf{x}}_{k+1|k}^{(M+1)}&=&\mathbf{A}_{k}^{k+1}\bar{\mathbf{x}}_{0}+\sum_{i=0}^{k}\mathbf{A}_{k}^{k-i}\mathbf{u}_{i}+\mathbf{L}_{k}^{0}\mathbf{B}_{k}^{0}
\\
&=&f_k(\hat{\mathbf{x}}_{k|k-1}^{(M)}+\mathbf{K}_k\left[\mathbf{y}_k-h_k(\hat{\mathbf{x}}_{k|k-1}^{(M)})\right])=\hat{\mathbf{x}}_{k+1|k}^{(EKF)}  
\end{IEEEeqnarray*}

3) When $k>M+1$, we use induction again but with respect to $k$ to prove the equivalence. If $k=M+2$, according to \eqref{eqn:L}, Lemma \ref{lemma3}, conditions \eqref{eqn:taylorDyn}\eqref{eqn:taylorMeas}, and case (2), we have:
\begin{equation*}
\hat{x}_{M+3|M+2}^{(M+1)}=\hat{\mathbf{x}}_{M+3|M+2}^{(EKF)}=\hat{x}_{M+3|M+2}^{(M)}
\end{equation*}

% \begin{IEEEeqnarray}{rcl}
% \hat{x}_{M+3|M+2}^{(M+1)}&=&\mathbf{A}_{M+2}^{M+2}\hat{\mathbf{x}}_{1|0}^{(M+1)}+\nonumber
% \\
% &&\sum_{i=0}^{M+1}\mathbf{A}_{M+2}^{M+1-i}\mathbf{u}_{i+1}+\mathbf{L}_{M+1}^{1}\mathbf{B}_{M+1}^{1}\nonumber
% \\
% &=&f_{M+2}(\hat{\mathbf{x}}_{M+2|M+1}^{(M)}\nonumber
% \\
% &&+\mathbf{K}_{M+2}\left[\mathbf{y}_{M+2}-h_{M+2}(\hat{\mathbf{x}}_{M+2|M+1}^{(M)})\right])\nonumber
% \\
% &=&\hat{\mathbf{x}}_{M+3|M+2}^{(EKF)}\nonumber
% \end{IEEEeqnarray}

Therefore, we can assume the following equality holds for $k=\eta >M+1$:
\begin{equation}
\hat{x}_{\eta+1|\eta}^{(M+1)}=\hat{\mathbf{x}}_{\eta+1|\eta}^{(EKF)}=\hat{\mathbf{x}}_{\eta+1|\eta}^{(M)}\label{eqn:induction_inter_eta}
\end{equation}

% \begin{IEEEeqnarray}{rcl}
% \hat{x}_{\eta+1|\eta}^{(M+1)}&=&\mathbf{A}_{\eta}^{M+2}\hat{\mathbf{x}}_{\eta-M-1|\eta-M-2}^{(M+1)}+\nonumber
% \\
% &&\sum_{i=0}^{M+1}\mathbf{A}_{\eta}^{M+1-i}\mathbf{u}_{\eta-M-1+i}+\mathbf{L}_{M+1}^{\eta-M-1}\mathbf{B}_{M+1}^{\eta-M-1}\nonumber
% \\
% &=&f_{\eta}(\hat{\mathbf{x}}_{\eta|\eta-1}^{(M)}+\mathbf{K}_{\eta}\left[\mathbf{y}_{\eta}-h_{\eta}(\hat{\mathbf{x}}_{\eta|\eta-1}^{(M)})\right])\nonumber
% \\
% &=&\hat{\mathbf{x}}_{\eta+1|\eta}^{(EKF)}=\hat{\mathbf{x}}_{\eta+1|\eta}^{(M)}.\label{eqn:induction_inter_eta}
% \end{IEEEeqnarray}


% \begin{equation*}
% \hat{\mathbf{x}}_{\eta+1|\eta}^{(M+1)}=\hat{\mathbf{x}}_{\eta+1|\eta}^{(EKF)}=\hat{\mathbf{x}}_{\eta+1|\eta}^{(M)}.
% \end{equation*}

Then, for $k=\eta+1$, according to \eqref{eqn:L}, Lemma \ref{lemma3}, conditions \eqref{eqn:taylorDyn}\eqref{eqn:taylorMeas}, and \eqref{eqn:induction_inter_eta}, we have:
\begin{IEEEeqnarray*}{rcl}
\hat{\mathbf{x}}_{\eta+2|\eta+1}^{(M+1)}&=&\mathbf{A}_{\eta+1}^{M+2}\hat{\mathbf{x}}_{\eta-M|\eta-M-1}^{(M+1)}+
\\
&&\sum_{i=0}^{M+1}\mathbf{A}_{\eta+1}^{M+1-i}\mathbf{u}_{\eta-M+i}+\mathbf{L}_{M+1}^{\eta-M}\mathbf{B}_{M+1}^{\eta-M}
\\
&=&f_{\eta+1}(\hat{\mathbf{x}}_{\eta+1|\eta}^{(M)}+\mathbf{K}_{\eta+1}\left[\mathbf{y}_{\eta+1}-h_{\eta+1}(\hat{\mathbf{x}}_{\eta+1|\eta}^{(M)})\right])
\\
&=&\hat{\mathbf{x}}_{\eta+2|\eta+1}^{(EKF)}.
\end{IEEEeqnarray*}
%=\hat{\mathbf{x}}_{\eta+2|\eta+1}^{(M)}

Therefore, Theorem \ref{the:MheEkf} also holds for $k>M+1$, which proves the theorem for $N=M+1$. The theorem is proved.


