\begin{lemma}[\hspace*{-0.3em}\cite{scully2020gittins}] \label{mg1bound}
If $\mathbbm{E}[p^{2}(\log p)^{+}]<\infty$, 
\begin{align*}
\mathbbm{E}[F^{\mathrm{SRPT}_{1,1}}_{\rho}]=\omega\Big(\log \frac{1}{1-\rho}\Big).
