\section{Optimality of $\mathsf{NP}$-$\mathsf{SRPT}$ Beyond Finite Task Size}\label{secdis}
Up to this point, we have focused on job size distributions with finite task, which is rather restrictive. It is natural to consider relaxations of this assumption.  In this section, we turn to other classes of job size distributions with unbounded support on task workload. These results provide complement to our developments about the theory of the asymptotic optimality of $\mathsf{NP}$-$\mathsf{SRPT}$ .

\subsection{Warm up--random number of tasks}
%Suppose that there are random number of jobs, and the number of tasks in each job are independently distributed, then the expected value of the total number of tasks $\mathbbm{E}[n_{t}]=\mathbbm{E}[n]\cdot \mathbbm[n_{i}]<\infty$, given that $\mathbbm{E}[n], \mathbbm{E}[n_{i}]<\infty$. 

In the following proposition, we analyze the order of the expected value of the maximum task size, if 
\begin{enumerate}[label=(\alph*), ref=(\alph*)]
    \item\label{item:a}  the moment generating function of the job size distribution exists.
    \item\label{item:b} the $k$-th moment of job size is finite.
\end{enumerate}

\begin{proposition}\label{promax}
For $n$ jobs with independently distributed workload, the mean value of the maximum task size is in the order of,

\begin{equation}
    \mathbbm{E}[\eta] = \begin{cases}
        O(\log (\mathbbm{E}[n])), & \text{case \ref{item:a}} , \\
        O((\mathbbm{E}[n])^{1/k}), & \text{case \ref{item:b}}.
    \end{cases}
\end{equation}
\end{proposition}
\begin{proof}
Consider an increasing convex function $g(x)$, by Jensen's inequality, we have
\begin{align*}
g(\mathbbm{E}[\eta])\leq \mathbbm{E}[g(\eta)] \leq \mathbbm{E}[\sum_{i=1}^{n}g(p_{i})] = \mathbbm{E}[n]\mathbbm{E}[g(p_{i})].
\end{align*}
Since the $g^{-1}(\cdot)$ is also increasing, hence
\begin{align*}
\mathbbm{E}[\eta]  \leq g^{-1}(\mathbbm{E}[n]\mathbbm{E}[g(p_{i})]).
\end{align*}
Let $s>0$ and 
\begin{equation*}
    g(x) = \begin{cases}
        e^{sx}, & \text{case \ref{item:a}} , \\
        x^{k}, & \text{case \ref{item:b}}.
    \end{cases}
\end{equation*}
then we have
\begin{equation}
    \mathbbm{E}[\eta] \leq \begin{cases}
        \min_{s\in D(s)}\frac{\log (\mathbbm{E}[n]) + \log(\mathbbm{E}[e^{sp_{i}}])}{s} , & \text{case \ref{item:a}} , \\
        (\mathbbm{E}[n])^{1/k}\cdot \mathbbm{E}^{1/k}[p^{k}_{i}], & \text{case \ref{item:b}}.
    \end{cases}
\end{equation}
where $D(s)=\{s>0|\mathbbm{E}[e^{sp_{i}}]<\infty\}$. The proof is complete.
\end{proof}

\subsection{Optimality in M/M/1}

For single server with Poisson arrival and 
exponentially distributed workload, we claim that $\mathsf{NP}$-$\mathsf{SRPT}$  is asymptotic optimal without any additional assumptions. 
\begin{theorem}\label{mm1opt}
 $\mathsf{NP}$-$\mathsf{SRPT}$ is asymptotic optimal in M/M/1.
\end{theorem}
We first introduce the following propositions that will be used in our proof.

\begin{proposition}[\hspace*{-0.6em}\cite{bansal2018achievable}]\label{pro2}
For M/M/1 model and any work-conserving algorithm, let $n_{\mathrm{busy}}$ be the number of arrivals in a busy period, then 
\begin{align*}
\mathbbm{E}[n_{\mathrm{busy}}]=O\Big(\frac{1}{1-\rho}\Big).   
\end{align*}
\end{proposition}

\begin{proofof}{Theorem \ref{mm1opt}}
Firstly, it has been shown in \cite{DBLP:journals/orl/Bansal05} that, the average response time under SRPT in M/M/1 satisfies
\begin{align*}
\frac{\mathbbm{E}[F^{\mathrm{SRPT-1}}_{\rho}]}{\mu(1-\rho)\log (1/(1-\rho))}\in \Big[\frac{1}{18e}, 7\Big]
\end{align*}
for $\rho \in [2/3,1)$. Based on Proposition \ref{promax} and Proposition \ref{pro2}, we have
\begin{align*}
\mathbbm{E}[\eta] =O(\log(\mathbbm{E}[n_{\mathrm{busy}}])) = O\Big(\log \frac{1}{1-\rho}\Big).  
\end{align*}
Combined with Theorem \ref{lemma1}, this implies that
\begin{align*}
\mathbbm{E}{[F_{\rho}^{ \mathsf{NP-SRPT}}]}- \mathbbm{E}{[F_{\rho}^{\mathrm{SRPT}_{1,N}}]} \leq O\Big(\log^{2} \frac{1}{1-\rho}\Big), 
\end{align*}
which is a lower order term compared to $\mathbbm{E}[F^{\mathrm{SRPT-1}}_{\rho}]$.
\end{proofof}



\subsection{Beyond Exponential Job Size Distribution}

% \cite{omahen1978analysis} \cite{artalejo2001analysis} \cite{zuk2024exact}

In the study of $\mathsf{NP}$-$\mathsf{SRPT}$, it is crucial to analyze the expected length of busy periods, which could help bound $\mathbbm{E}[\eta]$. Notably, previous works have established insights into the analysis of busy periods in M/M/c queuing systems\cite{omahen1978analysis, artalejo2001analysis}. In this section, we extend the analysis in \cite{omahen1978analysis} to M/G/N and prove an upper bound on the expected length of the busy period under $\mathsf{NP}$-$\mathsf{SRPT}$, with the following assumption. 

\begin{assumption}\label{residualass}
For any $a\geq 0$, there exist constants $r_{\max}$ such that  the expected size of the residual job, \ie, the amount of work remaining after a certain point in time or after a certain amount of work has been completed, satisfies 
\begin{align*}
\mathbbm{E}[p-a|p>a]\leq r_{\max}.
\end{align*}
\end{assumption}

In simpler terms, this assumption states that regardless of the current finished workload, the expected size of the remaining work will always be no more than $r_{\max}$, ie, being finite. It actually generalizes the concept of job size characterized by the exponential and \emph{new better than used} (NBUE) distribution.

\begin{lemma}
Under Algorithm $\mathsf{NP}$-$\mathsf{SRPT}$  and Assumption \ref{residualass}, 
\begin{align*}
\mathbbm{E}[\eta] = \begin{cases}
O(\log (1/(1-\rho))), &\text{case \ref{item:a}}\\
O((1-\rho)^{-\frac{1}{k}-\epsilon}), &\text{case \ref{item:b}}
\end{cases}  
\end{align*}
\end{lemma}





\begin{proof}
To analyze the busy periods under the $\mathsf{NP}$-$\mathsf{SRPT}$  policy, we classify two types of busy periods in an $N$-server system:
\begin{itemize}
\item \emph{Full busy period}. A time interval during which all $k \leq N$ servers are occupied. It starts when a new arrival finds $k-1$ customers already in the system and ends at the first departure epoch when exactly $k-1$ customers remain in the system. The length of such a busy period is denoted by $T_k$.
\item \emph{Partial busy period}. A time interval during which at least one server is busy. It begins when a new arrival finds the system empty and ends at the first epoch when the system becomes empty again.
\end{itemize}
Conditioning on whether a departure or a new arrival occurs first, the expected length of a full busy period can be expressed as:
\begin{align}\label{condition_pro}
&\mathbbm{E}[T_{k}|\text{start with} \{\mathsf{J}_{i}\}_{i=1}^{k}, p_{\mathsf{J}_{i}}\leq p_{\max}]\notag\\
=&\mathbbm{P}(\text{departure first})\cdot \mathbbm{E}[\text{Time to first departure}|\text{departure first}]\notag\\
&+ \mathbbm{P}(\text{arrival first})\cdot \mathbbm{E}[T_{k+1}|\text{start with} \{\mathsf{J}^{\prime}_{i}\}_{i=1}^{k}\cup\{\mathsf{J}_{k+1}\}]\notag\\
&+ \mathbbm{P}(\text{arrival first})\cdot \mathbbm{E}[T_{k}|\text{start with} \{\mathsf{J}^{\prime\prime}_{i}\}_{i=1}^{k}\}],
\end{align}
for any initial job collection $\{\mathsf{J}_{i}\}_{i=1}^{k}$. 



Since we consider an $M/G$ system, where job arrivals follow a Poisson process, the probability that an arrival occurs before a departure is:
\begin{align*}
&\mathbbm{P}(\text{arrival first})\\
=&\int_{0}^{\infty}\mathbbm{P}(\text{minimum remaining workload of jobs under processing}\geq s)\cdot \lambda e^{-\lambda s} \mathrm{d}s\\
\leq & \int_{0}^{2r_{\max}} \lambda e^{-\lambda s} \mathrm{d}s + \frac{1}{2}\int_{2r_{\max}}^{\infty}{\lambda e^{-\lambda s} \mathrm{d}s}\\
= & 1-\frac{1}{2}e^{-2\lambda r_{\max}} \leq 1-\frac{1}{2}e^{-\frac{2r_{\max}^{2}}{N}},
\end{align*}
where the second inequality follows from Markov inequality and Assumption \ref{residualass}.

Now, define the worst-case expected length of a full busy period starting with $k$ jobs and job sizes bounded by $p_{\max}$:
\begin{align*}
L_{k}(p_{\max}) = \sup_{\{\mathsf{J}_{i}\}_{i=1}^{k}} \mathbbm{E}[T_{k}|\text{start with} \{\mathsf{J}_{i}\}_{i=1}^{k}, p_{\mathsf{J}_{i}}\leq p_{\max}].
\end{align*}
Using (\ref{condition_pro}), we derive
\begin{align*}
& L_{k}(p_{\max}) \leq \frac{1}{\mu} + \Big(1-\frac{1}{2}e^{-\frac{2r_{\max}^{2}}{N}}\Big)(L_{k+1}(p_{\max})+L_{k}(p_{\max}))\\
\Rightarrow & L_{k}(p_{\max}) \leq \frac{2e^{\frac{2r_{\max}^{2}}{N}}}{\mu}+\Big(2e^{\frac{2r_{\max}^{2}}{N}}-1\Big)L_{k+1}(p_{\max}).
\end{align*}
This recursion implies that $L_k(p_{\max}) = O(L_N(p_{\max}))$ for all $k \leq N$, given a fixed number of servers. 


Since $L_{N}(p_{\max})$ is no more than the busy period of a single server with the same arrivals and initial workload of $Np_{\max}$, we obtain
\begin{align*}
L_{k}(p_{\max}) = O\Big(\frac{p_{\max}}{1-\rho}\Big), \forall k \leq N.
\end{align*}
Let $\mathbb{E}[\mathsf{B}^{(N)}_{\mathsf{NP-SRPT}}]$ denote the expected duration of a partial busy period, defined as the time from the first job arrival in an empty $N$-server system until the system becomes empty again under the $\mathsf{NP}$-$\mathsf{SRPT}$ policy. Then
\begin{align*}
\mathbbm{E}[\mathsf{B}^{(N)}_{ \mathsf{NP-SRPT}}] \leq &\mathbbm{E}_{p_{\max}}\Big[\sum_{k=1}^{N} {L_{k}(p_{\max})}\Big] \\
=& O\Big(\frac{\log \mathbbm{E}[\mathsf{B}^{(N)}_{ \mathsf{NP-SRPT}}]}{1-\rho}\Big).
\end{align*}
Solving this inequality yields:
\begin{align*}
\mathbbm{E}[\mathsf{B}^{(N)}_{ \mathsf{NP-SRPT}}] &= O\Big(\frac{1}{(1-\rho)^{1+\epsilon}}\Big), \forall \epsilon > 0.
\end{align*}
This completes the proof, following the arguments in Proposition~\ref{promax}.
% \begin{align*}
% \mathbbm{E}[\eta]&\leq \mathbbm{E}[p_{\max}] = O\Big(\log \frac{1}{1-\rho}\Big).
% \end{align*}
% The proof is complete.
\end{proof}


\paragraph{Additional lower bounds on optimal response time.} In addition to exponential distribution, Lin et al. \cite{lin2011heavy} also gave a characterization of the heavy-traffic behavior of SRPT with general job size distribution. We first introduce the concept of Matuszewska index, which plays a significant role in the result.

\begin{definition}[Upper Matuszewska Index \cite{lin2011heavy}]
Let $f$ be a positive function defined in $[0,\infty)$, the upper Matuszewska index is defined as the infimum of $\alpha$ for which there exists a constant $C=C(\alpha)$ such that for each $\bar{\lambda}>1$, 
% $\lim_{x\rightarrow \infty}\frac{f(\lambda x)}{f(x)}\leq C\lambda^{\alpha}$
\begin{align*}
\lim_{x\rightarrow \infty}\frac{f(\lambda x)}{f(x)}\leq C\lambda^{\alpha},
\end{align*}
holds uniformly for $\lambda\in [1, \bar{\lambda}]$.
\end{definition}
This index helps us understand the asymptotic behavior of function $f(\cdot)$.


\begin{proposition}[\hspace*{-0.6em}\cite{lin2011heavy}] \label{flowboundfact}In an M/G/1 queue, if the upper Matuszewska index of the job size distribution is less than $-2$, then
\begin{align*}
\mathbbm{E}{[F^{\mathrm{SRPT-1}}_{\rho}]}=\Theta \Big(\frac{1}{(1-\rho)\cdot G^{-1}(\rho)}\Big),
\end{align*}
where $G^{-1}(\cdot)$ denotes the inverse of $G(x)=\rho_{\leq x}/\rho=\int_{0}^{x}{tf(t) \mathrm{d}t}/\mathbbm{E}[p_{i}]$.
% and where $\rho_{\leq x}=\lambda \mathbbm{E}[S\cdot \mathbbm{1}_{S\leq x}]=\lambda \cdot \int_{0}^{x}{t f_{S}(t)}dt$.
\end{proposition}
%The cumulative distribution function $F(x)=1-e^{-\mu x}$, 
For example, exponential distribution has an upper Matuszewska index $M_{f}=-\infty$ and $G^{-1}(\rho)=\Theta(\log (1/(1-\rho)))$.
%hence Theorem \ref{mmonethm} is also implied by Proposition \ref{flowboundfact}. In addition, from Proposition~\ref{flowboundfact}, we can see that the following theorrem holds.
\begin{theorem}\label{generalthem}
The average response time under $\mathsf{NP}$-$\mathsf{SRPT}$  is asymptotic optimal in M/GI/N under Assumption \ref{residualass}, if upper Matuszewska index of job size distribution is less than $-2$ and
\begin{align*}
G^{-1}(\rho)= \begin{cases}
o\Big(\frac{1}{(1-\rho)\cdot \log^{2}(1/(1-\rho))}\Big), &\text{case \ref{item:a}}\\
o\Big(\frac{1}{(1-\rho)^{1-1/k-\epsilon}\cdot \log(1/(1-\rho))}\Big), & \text{case \ref{item:b}}
\end{cases}
\end{align*}
\end{theorem}
Theorem \ref{generalthem} identifies sufficient conditions under which the $\mathsf{NP}$-$\mathsf{SRPT}$  scheduling policy achieves asymptotic optimality in terms of average response time. Examples of the class of distribution in Theorem \ref{generalthem} include but not limited to \emph{Weibull distribution}, \emph{Pareto distribution} and \emph{regularly varying distributions} \cite{lin2011heavy}. 




