\section{Proof of Lemma \ref{num_of_job_bound}}\label{appendixcomproof}
\begin{proof}
%We relate the number of jobs alive under the optimal algorithm and the corresponding remaining workload, which mainly benefits from the fact that the remaining workload of jobs in the same class has a constant gap. 
In the following of the proof, we use $\mathcal{C}^{[k]}(\pi, t)=\cup_{i=1}^{k}\mathcal{C}_{i}(\pi, t)$ to denote the collection of jobs in the first $k$ classes, and let $W_{\pi}^{[k]}(t)=\sum_{i=1}^{k} {W_{\pi}^{(i)}(t)}$ represent the total remaining workload of jobs in the first $k$ classes, where $W_{\pi}^{(k)}(\pi, t)$ denotes the amount of remaining workload of jobs in class $\mathcal{C}_k(\pi,t)$. $W_{\pi^{*}_{1,N}}^{(k)}(t)$ and $W_{\pi^{*}_{1,N}}^{[k]}(t)$ are defined in a similar way for $\pi^{*}_{1,N}$. Without loss of generality, we assume $\log p_{\max}$ and $\log p_{\min}$ are integers. 


For $\forall t\geq 0$, the number of unfinished jobs under the optimal algorithm is no less than,
%lower bound the number of jobs alive under optimal algorithm via the
\begin{align}
n_{\pi^{*}_{1,N}}(t) \ge & \sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{W_{\pi^{*}_{1,N}}^{(k)}(t)}{2^{k}}}\notag\\
= &\sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{\Big[W_{\pi^{*}_{1,N}}^{[k]}(t)-W_{\pi^{*}_{1,N}}^{[k-1]}(t)\Big]}{2^{k}}}\notag\\
=&\frac{W_{\mathrm{\pi^{*}_{1,N}}}^{[\log p_{\max}+1]}(t)}{2^{\log p_{\max}+1}}+\sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{W_{\mathrm{\pi^{*}_{1,N}}}^{[k]}(t)}{2^{k+1}}}\notag\\
\geq& \sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{W_{\pi^{*}_{1,N}}^{[k]}(t)}{2^{k+1}}}\label{jobaliveoptimal}.
\end{align}
On the other hand, the number of jobs alive under $\mathsf{NP}$-$\mathsf{SRPT}$  can be upper bounded in a similar fashion,
\begin{align*}
n_{ \mathsf{NP-SRPT}}(t)\leq & \sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{W_{ \mathsf{NP-SRPT}}^{(k)}(t)}{2^{k-1}}}\\
=&\sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{\Big[W_{ \mathsf{NP-SRPT}}^{[k]}(t)-W_{ \mathsf{NP-SRPT}}^{[k-1]}(t)\Big]}{2^{k-1}}}\\
% \tag{definition of $W^{[k]}_{ \mathsf{NP-SRPT}}(t)$}\\
=&\sum_{k=\log p_{\min}}^{\log p_{\max}}{\frac{W_{ \mathsf{NP-SRPT}}^{[k]}(t)}{2^{k}}}+\frac{W_{ \mathsf{NP-SRPT}}^{[\log p_{\max}+1]}(t)}{2^{\log p_{\max}}}\\
\leq & \sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{W_{ \mathsf{NP-SRPT}}^{[k]}(t)}{2^{k-1}}}.
\end{align*}
Using Lemma~\ref{remaining_workload}, we are able to relate the number of unfinished jobs under two algorithms,
\begin{align*}
n_{ \mathsf{NP-SRPT}}(t) \leq& \sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{W_{ \mathsf{NP-SRPT}}^{[k]}(t)}{2^{k-1}}}\\
\leq &\sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{W_{\pi^{*}_{1,N}}^{[k]}(t)}{2^{k-1}}}+\sum_{k=\log p_{\min}}^{\log p_{\max}+1}{\frac{N\cdot (2^{k}+\eta)}{2^{k-1}}}\\
\leq &4n_{\pi^{*}_{1,N}}(t)+4N\cdot \Big(\log \alpha+\beta+1\Big),
%\leq & 4n_O(t)+N\cdot (4\log B+2\eta+4)\tag{Inequality (\ref{jobaliveoptimal})}.
\end{align*}
where the last inequality follows from inequality (\ref{jobaliveoptimal}). 
\end{proof}







