\section{Stochastic Domination for Randomised Colouring}\label{sec:stochastic-dominance}

In this section, we briefly explain the issue with applying stochastic dominance as done in~\cite[Lemma 5.2]{HKMT21}. There, at its core, the authors aim to apply \cite[Lemma 1.8.7]{Doer-21} stated by Doerr, which says that a sequence of arbitrary binary random variables $X_1,\ldots, X_n$ is stochastically dominated by independent random variables $X^*_1,\ldots, X^*_n$ if $$\Pro{X_i = 1 | X_1 = x_1,\ldots, X_{i-1} = x_{i-1}} \leq \Pro{X^*_i = 1}.$$

for all $i \in [1..n]$ and all $x_1, \ldots x_{i-1} \in \{0, 1\}$ with $\Pro{X_1 = x_1, \ldots, X_{i-1} = x_{i-1}} > 0$. The upshot of using stochastic domination lies in the applicability of Chernoff bounds for the random variable $X = X_1 + \ldots +X_n$. 

In~\cite[Lemma 5.2]{HKMT21}, the authors define $Z_u$ to be the indicator random variable that is $1$ if vertex $u$ is uncoloured after iteration $i$ and then basically sate that $\Pro{Z_u = 1} \leq \deg(u)/|\mathsf{ColourSpace}(u)|$, and that this holds \emph{irrespective} of other $Z_{u'}$. While this is true if we condition on the candidate colour of $u'$, observe that in order to apply \cite[Lemma 1.8.7]{Doer-21}, the upper bound on $\Pro{Z_u |Z_{u'} = z_{u'} }$ needs to hold true for \emph{all} $z_{u'} \in \{0,1\}$ with $\Pro{Z_{u'} = z_{u'}} > 0$.

Now, consider as an example a graph that consists of two vertices $V = \{\{u\},\{u'\}\} $ with edge $e = \{u,u'\}$ and at iteration $i$, an uncoloured vertex $v \in V$ picks its candidate colour u.a.r. from all available candidate colours. Let $Z_u$ be the indicator random variable that is $1$ if $Z_u$ is uncoloured after iteration $i$. Fixing a vertex $u$ we have indeed $\Exp{Z_u} \leq \deg(u)/|\mathsf{ColourSpace}(u)|$. However, when we condition on the event $Z_{u'} =1$ which has probability $\Pro{Z_{u'} =1} > 0$, then $u$ must have surely tried the same candidate colour as $u'$ giving $\Pro{Z_{u} | Z_{u'} = 1} = 1 \not\leq \deg(u)/|\mathsf{ColourSpace}(u)|$ and thus, the stochastic domination does not apply.

\section{Maximum Degree of a Hyperbolic Random Graph (Theorem~\ref{the:max-degree})}\label{sec:max-degree}

In the original work by Gugelmann, Konstantinos and Peter~\cite{gpp-rhg-12} the statement for the maximum degree was given without providing a definition for \whp This is not meant as a criticism to the authors as their proof is correct in the sense that it shows an \aas guarantee according to our definitions. In any case, to avoid any possible confusion, we provide a proof for our stated probabilistic guarantees.

\maxDegree*


\begin{proof}
    We start by showing the lower bound. Let $r_{high} := (2-1/\alpha)\log(n) + 2\log(\log(n))/\alpha$. Using \Cref{lem:measure-inner-disk} we obtain for the expected number of vertices in $\B_0(r_{high})$ that 
    $$n\cdot\mu(\B_0(r_{high})) = n(1-o(1))e^{-\alpha\left(R-r_{high}\right)} = \Theta(1)\log^2(n).$$


Using a Chernoff bound we have $|V \cap \B_0(r_{high})| \in \Theta(\log^2(n))$ \wehp Next we lower bound the vertex degree for a vertex $u \in V \cap \B_0(r_{high})$. Using \Cref{lem:vertex-degree} it holds
$$
\E{\deg(u)} \geq \Theta(1)e^{\left(R-r_{high}\right)/2} = \Theta(1)n^{\frac{1}{2\alpha}}\cdot\log^{-1/\alpha}(n),
$$
and using another Chernoff bound the lower bound is complete by getting $\deg(u) \geq \Theta(1)n^{\frac{1}{2\alpha}}\cdot\log^{-1/\alpha}(n) \> n^{\frac{1}{2\alpha}}\log^{-2}(n)$ \wehp since $\alpha > 1/2$.

For the upper bound we set $r_{low}:= (2-1/\alpha)\log(n) - \log(\log(n))/\alpha$ and use \Cref{lem:measure-inner-disk} to show that the expected number of vertices in $\B_0(r_{low})$ is
$$
n\cdot\mu(\B_0(r_{low})) = n(1-o(1))e^{-\alpha\left(R-r_{low}\right)} =\Theta(1)(1/\log(n)) \in o(1).
$$

Using Markov's inequality there is no vertex in the area $\B_0(r_{low})$ \aas Let us write $A$ for the event that $\{V \cap \B_0(r_{low}) = \emptyset\}$. Then, since $\mu(B_r(R) \cap \disk)$ is monotonically decreasing in $r$ (see \cite[Lemma 3.3]{gpp-rhg-12}), we obtain by using \Cref{lem:vertex-degree} that the expected degree for a vertex $u \in V \cap \disk$ conditioned on event $A$ is  

$$
\E{\deg(u)|A} \leq n\cdot\mu(\B_{r_{low}}(R)\cap \disk)) = \Theta(1)e^{(R-r_{low})/2} = \Theta(1)(n\cdot\log(n))^{\frac{1}{2\alpha}},
$$

Using a Chernoff bound and $\alpha > 1/2$ it follows $\deg(u) \leq \Theta(1)(n\cdot\log(n))^{\frac{1}{2\alpha}} < n^{\frac{1}{2\alpha}}\cdot\log(n)$ \wehp conditioned on the event $A$. The proof for the upper bound is complete by a union bound over all vertices over vertices with radii larger than $r_{\text{low}}$, where the probabilistic guarantee stems from the fact that event $A$ occurs \aas

\end{proof}


\section{Degree of a Vertex (Lemma~\ref{lem:vertex-degree})}\label{sec:degree}

\degree*

\begin{proof}
Since a vertex $u$ with radius $r$ has $\dist(u,v) \leq R$ if $r(v) \leq R - r$ we have for the area of the ball $B_u(R)$ intersecting the disk $\disk$
\begin{align*}
    \mu(\mathcal{B}_u(R) \cap \disk) = \mu(\mathcal{B}_0(R-r)) + \int_{R-r}^R \int_{-\theta_R(x,r)}^{\theta_R(x,r)}\rho(x) \dd\theta dx.
\end{align*}
By \cite[Corollary 5]{bks-hudg-23} we have  $\sqrt{e^{(R-r-x)}} \leq \theta_R(r,x) \leq \pi \sqrt{e^{(R-r-x)}}$ for $x+r\geq R$ since $r\geq 1$ by the hypothesis of our statement. Thus, for every $x \in [R-r, R)$, there exists a $\tau$ with $1 \leq \tau \leq \pi$ such that  
\begin{align*}
     \mu(\mathcal{B}_u(R) \cap \disk) &=\mu(\mathcal{B}_0(R-r)) + 2 \int_{R-r}^R \tau e^{\frac{R-r-x}{2}}\frac{\alpha\sinh(\alpha x)}{2\pi(\cosh(\alpha R) - 1)} \dd x\\
    &= \mu(\mathcal{B}_0(R-r)) + \frac{  \alpha e^{(R-r)/2}}{\pi(\cosh(\alpha R) - 1)}\int_{R-r}^{R} \tau e^{-x/2}\sinh(\alpha x) \dd x.
\end{align*}    

We proceed by using $\pi$ as an upper bound on $\tau$. The lower bound follows analogously by using $\tau \geq 1$. We get for the integral above using $\tau \leq \pi$

\begin{align*}
    \int_{R-r}^{R}\pi e^{-x/2}\sinh(\alpha x) \dd x &= \left[\frac{2\pi}{4\alpha^2 - 1}e^{-x/2}(2\alpha \cosh(\alpha x ) + \sinh(\alpha x))\right]_{R-r}^R\\
    &= \frac{2\pi}{4\alpha^2 -1}\left(e^{-R/2}(2\alpha \cosh(\alpha R) + \sinh(\alpha R))\right)\\
    &-\frac{2\pi}{4\alpha^2 -1}\left(e^{-(R-r)/2}(2\alpha \cosh(\alpha (R-r)) + \sinh(\alpha (R-r))\right).
\end{align*}

We then obtain by similar calculations to \cite[Lemma 3.2]{gpp-rhg-12}
\begin{align*}
\frac{  \alpha e^{(R-r)/2}}{\pi(\cosh(\alpha R) - 1)}\int_{R-r}^{R} \tau e^{-x/2}\sinh(\alpha x) \dd x \leq \frac{(1+o(1))\alpha e^{-r/2}}{\alpha - 1/2},  
\end{align*}

and then using \Cref{lem:measure-inner-disk}

\begin{align*}
    \mu(\mathcal{B}_u(R) \cap \disk) &=\mu(\mathcal{B}_0(R-r)) + 2 \int_{R-r}^R \tau e^{\frac{R-r-x}{2}}\frac{\alpha\sinh(\alpha x)}{2\pi(\cosh(\alpha R) - 1)} \dd x\\
    &\leq (1+o(1))e^{-\alpha r} + \frac{(1+o(1))\alpha e^{-r/2}}{\alpha - 1/2}\\
    &\leq \frac{(1+o(1))\alpha e^{-r/2}}{\alpha - 1/2},
\end{align*}

since $\alpha > 1/2$. The desired bound follows since $\deg(u)$ is a Poisson random variable so the expected vertices in the area is $n \cdot  \mu(\mathcal{B}_u(R) \cap \disk)$. The lower bound follows by doing the same calculations using $\tau \geq 1$.

\end{proof}

\section{Proof of Leaves Lemma (Lemma~\ref{lem:leaf})}\label{sec:leavesproof}

\leavesLemma*

\begin{proof}
The idea goes as follows: first, we consider the set of vertices $U = V \cap \B_0(R-\startlayer-1)$, i.e., the set of vertices with smaller radius than the set $V_{\startlayer}$. For $u \in U$, we then write $N_0(u)$ for the set of vertices $V_0 \cap N(u)$ and let $\xi(u)$ be the largest angle that is spanned among a pair of vertices in $N_0(u)$ (see \Cref{fig:leaves}a). This is useful in the following sense: let $\Xi(u)$ be the sector that is defined by bisector $\varphi(u)$ and angle $\xi(u)$. Then whenever we consider a vertex $v \in V \cap (\mathcal{A}_0 \setminus \Xi(u))$, we know that $v$ has no edge to $u$. Thus, an upper bound on the angles $\sum_{u \in U} \xi(u) =: \xi$ gives us the size of the layer $\mathcal{A}_0$ on which the probability of events for vertices $V \cap \mathcal{A}_0$ are independent of $U$. Then let $\Xi := \cup_{u \in U}\Xi(u)$ and in a second step we operate on the sub area $\mathcal{A}_0\setminus\Xi$. We show the desired properties by revealing enough leaves in $\mathcal{A}_0\setminus\Xi$ that have only a single vertex $u \in V_{\startlayer}$ as a neighbour.


To bound the angle $\xi$ recall that $\Xi := \cup_{u\in U}\Xi(u)$ where for $u \in U$ the area $\Xi(u)$ is the sector with bisector $\varphi(u)$ and angle $\xi(u)$. Using \Cref{lem:max-angle} we obtain $\xi(u) \leq 2\theta_R(r(u), R-1)$ since $\theta_R(\cdot,\cdot)$ is monotonically decreasing in both arguments. Then an upper bound for the angle of $\Xi$ is given by summing over all upper bounds of the angles of all $\Xi(u)$. This yields

$$\xi = \sum_{u \in U}{\xi(u)} \leq \sum_{u \in U}{2\theta_R(r(u), R-1)}.$$

 Moreover let $A_\finallayer$ be the layer of largest index $\finallayer$ that is non-empty. Since the set $U$ are the set of vertices located layers larger than $\startlayer$ and a vertex in layer $\mathcal{A}_\ell $ has radius at least $R - \ell - 1$, we obtain  via $\theta_R(\cdot, \cdot)$ being monotonically decreasing in its two arguments

 $$
 \xi \leq \sum_{\ell = \startlayer + 1}^{\finallayer}\sum_{v \in V_\ell}2\theta_R(R-\ell-1,R - 1) \in \sum_{\ell = \startlayer + 1}^{\finallayer}\bigO(\max(ne^{-\alpha \ell}, \log^2(n))\cdot\theta_R(R-\ell-1,R - 1),
 $$

 where we used \Cref{lem:layer-properties} by which $|V_\ell| \in \bigO(\max(ne^{-\alpha \ell}, \log^2(n))$ \wehp Next let us write $\ell_0 := \lceil \alpha^{-1}(\log(n) - 2\log(\log(n)))\rceil$. Then we use  \Cref{lem:layer-properties} by which $\finallayer \leq \lceil\alpha^{-1}\cdot(\log(n) + \log(\log(n)) \rceil$ \aas and obtain

$$
\xi  \in \sum_{\ell = \startlayer + 1}^{\ell_0}\mathcal{{\bigO}}\left(e^{-\ell(\alpha-1/2)}\right) + \sum_{\ell_0 + 1}^{\finallayer} \bigO\left(\log^{2 + \frac{1}{2\alpha}}(n)\cdot n^{-\frac{2\alpha - 1}{2\alpha}}\right),
$$

where we used \Cref{lem:max-angle} to obtain the upper bound $\theta_R(R-\ell-1, R-1) \leq \Theta(1)e^{\ell/2 - \log(n)}$ which is monotonically increasing in $\ell$ for $\theta_R(R- \ell -1, R-1)$. Using that there are $\bigO(\log(n))$ layers and $\alpha > 1/2$ it follows that

$$
\xi  \in \mathcal{{\bigO}}\left(\log(n)\cdot e^{-\startlayer(\alpha-1/2)}\right) + o(1) \in o(1),
$$


where we used in the last step that $\startlayer\geq c \log(\log(n))$ by the hypothesis of our lemma. Thus, for $c \geq 2(\alpha - 1/2)^{-1}$ the term is vanishing and we conclude $\xi \in o(1)$ \aas 

Now, we partition the rest disk $\mathcal{D}_R\setminus\Xi$ into $k = \left\lceil ne^{-\alpha\startlayer} \right\rceil$ disjoint sectors such that each has angle $\phi = (2\pi-\xi)/k = \Theta(1)n^{-1}e^{\alpha\startlayer}$. Let us write $\Phi_i$ for $i$-th sector with angle $\phi$ and we denote the intersection of a sector and the layer $\mathcal{A}_{\startlayer}$ by $\mathcal{A}_{\startlayer} \cap \Phi_i =: \mathcal{C}_i$ (see \Cref{fig:leaves}b).
Fixing any area $\mathcal{C}_i$, we obtain for its measure 
\begin{equation}\label{eq:non-vanishing-probability}
    \mu(\mathcal{C}_i) = \mu(\mathcal{A}_{\startlayer} \cap \Phi_i) = \mu(\B_0(R-\ell)\setminus\B_0(R-\ell-1)\cdot \phi = \Theta(1)e^{-\alpha\startlayer}\cdot n^{-1}e^{\alpha\startlayer} \in \Theta(1/n),
\end{equation}
where we used \Cref{lem:measure-inner-disk} and $\phi = \Theta(1)n^{-1}e^{\alpha\startlayer}$. We conclude that $\E{|V \cap \mathcal{C}_i|} \in \Theta(1)$. Since the distribution of the vertices follows Poisson point distribution we get for any $i \in k$ a non-vanishing probability for the event that there is exactly one vertex in $\mathcal{C}_i$. 

In the next step, we count the number of vertices in $\mathcal{A}_{\startlayer}$ that have constant fraction of its neighbour as leaves. To this end, let $A_i$ be the event that a vertex $u \in V \cap \mathcal{C}_i$ has $\Theta(\deg(v))$ leaves in layer $\mathcal{A}_0$. Recall that $\startlayer \geq c\log(\log(n)) \in \omega(1)$ by which we get with \Cref{lem:leaves} in conjunction with \Cref{eq:non-vanishing-probability} using law of total expectation $\E{A_i} \geq \E{A_i | |\mathcal{C}_i| = 1}\Prob{|\mathcal{C}_i| = 1} \in \Omega(1)$.

Now recall that we partitioned $\mathcal{D}_R\setminus\Xi$ into $k$ sectors and define $A = \sum_{i}^{\lfloor k/2\rfloor} \indicator{A_i}$. We note that $A$ is crude lower bound on the desired random variable we are looking for in our lemma as $A_i$ is the event that $\mathcal{C}_i$ contains a vertex where a constant fraction of its neighbours are leaves while only located in $\mathcal{A}_0\setminus \Xi$. By linearity of expectation we obtain 
\begin{align}\label{eq:lin-exp}
    \E{A} = \Theta(k) \E{A_i} \in \Omega(k).
\end{align}
We proceed by showing independence between $A_i$ and $A_j$ for $|i-j|>1$. First observe that $\Phi_i \cap \Phi_j = \emptyset$. Moreover recall that $\phi = \Theta(1)n^{-1}e^{\alpha\startlayer}$, such that the leaves located in $\B_0(R)\setminus\B_0(R-1)$ have a neighbour in $\mathcal{D}_R\setminus\Xi$ with angle distance at most $\theta_R(R-\startlayer-1, R-1) \leq \Theta(1)n^{-1}e^{\eta/2} \in o(\phi)$ using \Cref{lem:max-angle}. Finally recall that we only operate on the sub disk $\mathcal{D}_R\setminus\Xi$ where vertices in layer $\mathcal{A}_0$ do not have a neighbour with radius at most $R - \startlayer - 1$. It follows that the area of leaves are independent and thus, also the events $A_i$ and $A_j$ for $|i-j|>1$.

To finish the proof recall that $\startlayer \leq \alpha^{-1}(\log(n) - \log(\log(n)) -c)$ and thus, $k \geq c\cdot\log(n)$ which implies $\E{A} \geq \Theta(1)c \cdot \log(n)$ by \Cref{eq:lin-exp}. A Chernoff bound yields $\Prob{A \in o(k)} \leq n^{-c'}$ for any constant $c'>$ given that $c$ was chosen large enough. Another Chernoff bound gives us in conjunction with \Cref{lem:measure-inner-disk} that $\Prob{|V_{\startlayer}| \in \omega(k)} \leq n^{-c'}$ for any constant $c'>0$. A union bound over the two events concludes the proof where the probabilistic guarantee \aas stems from the fact that we conditioned on the event that $\finallayer \leq \lceil \alpha^{-1}(\log(n) + \log(\log(n)))\rceil$ to bound $\xi$ by $o(1)$.
\end{proof}

\section{Concentration bounds}\label{item:prob-guarantees} We wish to obtain concentration results for our algorithms and graphs. For an event $A$ we write
\begin{itemize}
    \item $A$ holds \emph{asymptotically almost surely} (\aas) if $\Pro{A} \in 1 - o (1)$,
     \item $A$ holds \emph{with high probability} (\whp) if $\Pro{A} \in 1 - \bigO(1/n)$ and
     \item $A$ holds \emph{with extreme high probability} (\wehp) if $\Pro{A} \in 1 - n^{-\omega(1)}$.
\end{itemize}
\smallskip
To obtain such guarantees, we use the following concentration bounds (see, e.g. \cite{Prob-Method-16, mu-pc-05}).

\begin{lemma}[Markov's inequality]\label{lem:markov}
    Let $X$ be a random variable with expectation $\Exp{X}$. Then for $a > 0$, $\Pro{X \geq a} \leq a^{-1}\Exp{X}$.
\end{lemma}

\smallskip

\begin{theorem}[Chernoff bound]\label{lem:Chernoff}
For $i \in [k]$, let $X_i \in \{0,1\}$ be independent random variables and $X = \sum_i X_i$. Then
%
\begin{align*}
    \Pro{X\geq \frac{3}{2}\Exp{X}} \leq \exp{\left(-\frac{\Exp{X}}{12}\right)} \text{ and }
    \Pro{X\leq \frac{1}{2}\Exp{X}} \leq \exp{\left(- \frac{\Exp{X}}{8}\right)}.
\end{align*}
%
\end{theorem}

The following is a Chernoff\footnote{For convenience, we refer to both as a Chernoff bound whenever using either of the two.} type deviation bound (see e.g. \cite[Lemma 6]{Kiwi2024}) which is necessary for the distribution of vertices as it follows a Poisson point distribution.

\begin{lemma}[Poisson Chernoff bound]\label{lem:Poisson-Chernoff}
    Let $X$ have a Poisson distribution with mean $\E{X}$. Then for $a \geq e^{3/2}$,
    \begin{align*}
        \Prob{X\leq \frac{1}{2}\mathbb{E}[X]} \leq \exp{(- \mathbb{E}[X]/8)} \text{ and }
    \Prob{X\geq a\mathbb{E}[X]} \leq \exp{(a\cdot \mathbb{E}[X] /2)}.
    \end{align*}
\end{lemma}

Finally, for analysing the \RCTID algorithm, we use the following variant of an Azuma-Hoeffding bound (see e.g. \cite[Corollary A.5]{BEPS}).

\begin{lemma}[Azuma-Hoeffding]\label{lem:BEPS}
    Let $Z = Z_1 + \ldots + Z_n$ be the sum of n random variables and $X_0,\ldots, X_n$ be a sequence, where $Z_i$ is uniquely determined by $X_0,\ldots, X_n$, $\Exp{Z_i| X_0,\ldots, X_{i-1}}$, $\Exp{Z} = \sum_i \Exp{Z_i}$, and $a_i \leq Z_i \leq a'_1$. Then
    $$
    \Pro{Z \geq \Exp{Z} + a}\leq \exp{\left(-\frac{a^2}{2\sum_i(a'_i - a_i)^2}\right)}.
    $$
\end{lemma}












