\subsubsection*{Approximate HC trees with recursive balanced min-cuts and sparsest cuts}
% One of the first observations by Dasgupta's work is the structure of the optimal trees and the computational complexity to compute them:
% \begin{lemma}[\!\!\citep{Dasgupta16}]
% \label{fact:opt-tree-binary}
% It is NP-hard to find the optimal clustering tree.
% \end{lemma}
Dasgupta's work proved that finding the optimal trees for the hierarchical clustering function is NP-hard \citep{Dasgupta16}. Consequently, significant attention has been directed towards developing \emph{approximation algorithms} for efficient hierarchical clustering. A well-known approach involves obtaining an approximation of the optimal hierarchical clustering by iteratively employing \emph{sparsest cuts} on the graph, e.g., \citep{Dasgupta16,Deng0U0Z25}.  
Formally, we can define the sparsest cuts and the HC trees created by recursively applying the sparsest cuts on the induced subgraphs as in \Cref{def:sparse-cut} and \Cref{def:sparse-cuts-procedure}.

\begin{definition}[\textbf{Sparsest Cuts}]\label{def:sparse-cut}
For any parameter $\beta$ such that $0 < \beta < 1$, we say that a cut $(A^* ,B^*)$ is a \emph{sparsest cut} if its \emph{sparsity (edge expansion)} is minimized, i.e.
\[ \frac{w(A^*,B^*)}{\min\{\card{A^*},\card{B^*}\}} \leq \frac{w(A,B)}{\min\{\card{A},\card{B}\}}\] 
for any cut $(A,B)$ of $G$.
\end{definition}

\begin{definition}[\textbf{Recursive Sparsest Cut Procedure}]\label{def:sparse-cuts-procedure}
We say an HC tree $\cT$ is obtained by the \emph{recursive sparsest procedure} on $G$ if for each non-leaf node $z$ of $\cT$, the $\cut(\cT[z])$ is obtained by a (possibly approximate) sparsest cut $(A,B)$ on the subgraph induced by $\cT[z]$. We call an HC tree obtained by recursively applying (approximate) sparsest cuts on induced subgraphs as a recursive sparsest cut HC tree.
\end{definition}

Previous work (see, e.g.~\citep{charikar2017approximate,AssadiCLMW22}) proved that if one applies the procedure in \Cref{def:sparse-cuts-procedure}, we can get an $O(1)$ approximation of the optimal HC tree. 
\begin{proposition}[\citep{charikar2017approximate,AssadiCLMW22}]\label{prop:const-recursive-HC}
	For any graph $G=(V,E,w)$, let $\cT_{sparse}$ be an HC tree obtained by the recursive sparsest cut procedure in \Cref{def:sparse-cuts-procedure}, there is 
    \[
    \cost_G(\cT_{sparse}) \leq O(1) \cdot \OPT(G).
    \]
 % \begin{itemize}
 %     \item Let $\cT_{balanced}$ be a $(1/3)$-balanced tree obtained by the procedure in \Cref{def:beta-min-procedure} with $\beta=\frac{1}{3}$, there is 
 %    \[
 %    \cost_G(\cT_{balanced}) \leq O(1) \cdot \OPT(G).
 %    \]
 %    \item L
 % \end{itemize}
\end{proposition}


Note that finding the exact sparsest cut for \Cref{prop:const-recursive-HC} is NP-hard. The first way to circumvent this issue is to use approximation algorithms, especially for the best-known $O(\sqrt{\log{n}})$ approximation for sparsest cut in polynomial time (\citep{AroraHK04}). The formal guarantee is as follows.
\begin{proposition}[\citep{AroraHK04}]
\label{prop:sparse-cut}
There exists a randomized algorithm that given a graph $G=(V,E,w)$, with high probability, in $\tilde{O}(\card{V}^2)$ time finds a partition $A \cup B=V$ such that
\[\frac{w(A,B)}{\min\{\card{A},\card{B}\}} \leq O(\sqrt{\log{\card{V}}})\cdot \frac{w(A^*,B^*)}{\min\{\card{A^*},\card{B^*}\}},\]
where $(A^*,B^*)$ is the sparsest cut of $G$. 
\end{proposition}
We cannot immediately massage \Cref{prop:sparse-cut} with \Cref{prop:const-recursive-HC} since \Cref{prop:const-recursive-HC} does \emph{not} state what will happen for \emph{approximate} sparsest cuts. Fortunately, by the results in \citep{charikar2017approximate,AssadiCLMW22}, we can indeed obtain an $O(\alpha)$-approximation algorithm for $\OPT(G)$ by recursively applying the $\alpha$-approximate sparsest cut.
\begin{proposition}[\citep{charikar2017approximate,AssadiCLMW22}]
\label{prop:beta-compute}
Let $\cT$ be a recursive sparsest cut tree obtained by recursively applying $\alpha$-approximation sparsest cuts on the induced subgraphs (as in \Cref{def:sparse-cuts-procedure}). Then, we have
\begin{align*}
\cost_G(\cT) \leq O(\alpha)\cdot \OPT(G).
\end{align*}
% The polynomial-time efficiency and the $O(\sqrt{\log{n}})$ approximation guarantee are also true for HC trees obtained by recursive sparsest cuts.
\end{proposition}

There is another way to deal with the NP-hardness issue of the sparsest cut. If we can reduce the \emph{input size}, we can possibly obtain the \emph{exact optimal} cuts on induced subgraphs of size $O(\log{n})$. This strategy allows us to leverage our strong partial tree whose `unknown' clustering is only restricted to the induced subgraphs with $O(\log{n})$ size.

\subsection{A Polynomial-time Algorithm for \texorpdfstring{$O(1)$}{O1}-approximation on Dasgupta's HC Objective}
\label{subsec:constant-poly-time-HC}
We now introduce our algorithm that finds an HC tree with $O(1)$-approximation to Dasgupta's objective in polynomial time. The formal statement is given as follows.

\thmconstantpolytimehc*

Our algorithm of \Cref{thm:constant-poly-time-HC} is simply as follows.

\begin{algorithm}
\caption{A polynomial-time algorithm for the Dasgupta's HC objective} \label{alg:HC-Das}
\KwIn{Input graph $G=(V,E,w)$; Splitting oracle $\cO$}
\KwOut{A hierarchical clustering tree $\cT$}
Run the strong partial tree approximation algorithm in \Cref{thm:strong-partial-tree} to obtain partial tree $\pTree$ \;
\For{each super-vertex in $\pTree$}{
On input vertex set $S$, \emph{exhaustively search} the sparsest cut $(A,B)$ on the induced subgraph $G[S]$\;
Partition the vertices as $S\rightarrow (A,B)$, and recurse on $G[A]$ and $G[B]$\; 
}
\end{algorithm}

We now prove the efficiency and the approximation guarantees for Dasgupta's objective. The following lemma provides the efficiency for \Cref{alg:HC-Das}.

\begin{lemma}
\label{lem:HC-das-poly-efficiency}
\Cref{alg:HC-Das} runs (deterministically) in $O(n^{50002})$ time and uses $O(n^3)$ queries.
\end{lemma}
\begin{proof}
By \Cref{thm:strong-partial-tree}, the first step of the algorithm that computes the strong partial tree takes $\tilde{O}(n^3)$ time and $O(n^3)$ queries. Note that we only take queries in this step.

For the second step, when the input size is $s$, an exhaustive search on the sparsest cut takes $O(2^s)$ time. As such, let $X$ be the set of induced vertices for a single super-vertex of $\pTree$, since we have $\card{X}\leq 50000\log{n}$, it only takes $O(n^{50000})$ time to find the sparsest cut. Similarly, we can show that in each recursive call, the runtime is at most $O(n^{50000})$. By \Cref{fct:num-splits-tree}, there are at most $O(\log{n})$ nodes in a binary tree with $O(\log{n})$ leaves. As such, the recursive sparsest cut for a single super-vertex in $\pTree$ takes $O(n^{50000}\cdot \log{n})$ time. There are at most $O(n)$ super-vertices in the tree; therefore, the total runtime of the second step takes $O(n^{50000}\cdot \log{n}\cdot n)=O(n^{50002})$ time.

Combining the efficiency of the two steps gives us the desired efficiency bound. 
\end{proof}

We now move to the approximation guarantee of the algorithm.
\begin{lemma}
\label{lem:HC-das-const-approx}
Conditioning on the high probability guarantees of \Cref{thm:strong-partial-tree}, \Cref{alg:HC-Das} outputs an HC tree $\cT$ that achieves $O(1)$-approximation to the Dasgupta's objective.
\end{lemma}
\begin{proof}
For any partial tree $\pTree$, we first partition the edges in to $E_{\text{cross}}$ and $E_{\text{same}}$ based on whether the edge $(u,v)\in E$ crosses different partial trees, i.e.,
\begin{enumerate}
\item $(u,v)\in E_{\text{cross}}$ iff $u\in X$ and $v\in Y$ for some super-vertices $X\neq Y$ in $\pTree$.
\item $(u,v)\in E_{\text{same}}$ iff $u,v \in X$ for some super-vertex $X$ in $\pTree$.
\end{enumerate}
Since $E=E_{\text{cross}} \cup E_{\text{same}}$, by using \Cref{obs:edge-partition}, we can show that $\OPTdas = \cost_{G}(\cTstar)= \cost_{G}(\cTstar, E_1)+\cost_{G}(\cTstar, E_2)$. We now analyze the costs w.r.t. to $E_1$ and $E_2$, respectively.
\begin{enumerate}
\item For $E_{\text{cross}}$, we argue that $\cost_{G}(\cT, E_{\text{cross}})=\cost_{G}(\cTstar, E_{\text{cross}})$. To see this, note that if $u$ and $v$ are of different super-vertices, by the definition of partial HC trees that are \emph{strongly consistent} with the optimal tree $\cTstar$, there is 
\[\leaves{\cT}{\lcatree{u}{v}{\cT}} = \leaves{\cTstar}{\lcatree{u}{v}{\cTstar}}.\]
As such, we have $\cost_{G}(\cT, E_{\text{cross}})=\cost_{G}(\cTstar, E_{\text{cross}})$ by the definition of the cost function.
\item For $E_{\text{same}}$, we argue that $\cost_{G}(\cT, E_{\text{same}})\leq O(1)\cdot \cost_{G}(\cTstar, E_{\text{same}})$. Formally, for each super-vertex $X$, we can use \Cref{prop:const-recursive-HC} on $G[X]$ to argue that the $\cost_{G}(\cT, E_{\text{same}}[X])\leq O(1)\cdot \cost_{G}(\cTstar, E_{\text{same}}[X])$, where $E_{\text{same}}[X]$ stands for the set of edges in $E_{\text{same}}$ with \emph{both} endpoints in $X$. Therefore, we can apply this calculation to every super-vertex to get the desired approximation factor.
\end{enumerate}
We now use \Cref{obs:edge-partition} again on $E_{\text{cross}}$ and $E_{\text{same}}$ to bound that
\begin{align*}
\cost_{G}(\cT)&=\cost_{G}(\cT, E_{\text{cross}}) + \cost_{G}(\cT, E_{\text{same}}) \\
&\leq \cost_{G}(\cTstar, E_{\text{cross}}) + O(1)\cdot \cost_{G}(\cTstar, E_{\text{same}})\\
&\leq O(1)\cdot \paren{\cost_{G}(\cTstar, E_{\text{cross}}) + \cost_{G}(\cTstar, E_{\text{same}})}\\
&= O(1)\cdot\cost_{G}(\cTstar)=O(1)\cdot \OPTdas,
\end{align*}
as desired.
\end{proof}

\paragraph{Finalizing the proof of \Cref{thm:constant-poly-time-HC}.} With \Cref{alg:HC-Das}, we can obtain the poly-time efficiency from \Cref{lem:HC-das-const-approx}. Furthermore, since the strong partial tree algorithm of \Cref{thm:strong-partial-tree} succeeds with high probability, the approximation guarantee of \Cref{lem:HC-das-const-approx} holds with high probability as well. This concludes the proof.

\subsection{An \texorpdfstring{$\tilde{O}(n^3)$}{nto3} Time Algorithm for \texorpdfstring{$O(\sqrt{\log\log{n}})$}{rootloglogn}-approximation on Dasgupta's HC Objective}
\label{subsec:loglogn-n4-time-HC}
One drawback of the algorithm we have in \Cref{subsec:constant-poly-time-HC} is that the efficiency is ``theoretical only'' -- after all, a runtime of $O(n^{50002})$ is nowhere near being practical. Observe that the subroutine that leads to the very large exponent is the exhaustive search of the \emph{optimal} sparsest cut. Therefore, we can hope to use some more efficient approximation for sparsest cuts while not sacrificing too much on the approximation guarantee. This intuition leads us to the following theorem.



\thmrootloglogtimehc*

Our algorithm for \Cref{thm:root-loglog-n4-time-HC} is almost identical to that of \Cref{thm:constant-poly-time-HC} -- the only difference is that we substitute the exact sparsest cuts with \emph{approximate} ones. The description of the algorithms is as follows.

\begin{algorithm}
\caption{An $\Otilde(n^3)$ time algorithm for the Dasgupta's HC objective}\label{alg:HC-Das-fast}
\KwIn{Input graph $G=(V,E,w)$; Splitting oracle $\cO$}
\KwOut{A hierarchical clustering tree $\cT$}
Run the strong partial tree approximation algorithm in \Cref{thm:strong-partial-tree} to obtain partial tree $\pTree$ \;
\For{each super-vertex in $\pTree$}{ 
On input vertex set $S$, find an $O(\sqrt{\log \card{S}})$-approximation of the sparsest cut $(A,B)$ on the induced subgraph $G[S]$ using the algorithm of \Cref{prop:sparse-cut}\; 
Partition the vertices as $S\rightarrow (A,B)$, and recurse on $G[A]$ and $G[B]$ \;
}
\end{algorithm}

We now proceed to prove the efficiency and the approximation guarantees for Dasgupta's objective with \Cref{alg:HC-Das-fast}. Again, we first characterize the efficiency of the algorithm.

\begin{lemma}
\label{lem:HC-das-n4-efficiency}
With high probability, \Cref{alg:HC-Das-fast} runs in $O(n^3\log{n})$ time and uses $O(n^3)$ queries.
\end{lemma}
\begin{proof}
The first step of the algorithm that computes the strong partial tree takes $O(n^3\log{n})$ time and $O(n^3)$ queries by \Cref{thm:strong-partial-tree}. We need to argue that the second step takes at most $O(n^3\log{n})$ time as well. Note that by \Cref{prop:sparse-cut}, the algorithm, with high probability, runs in $\tilde{O}(s^2)$ time and finds an $O(\sqrt{\log s})$-approximation of the sparsest cut $(A,B)$, where $s$ is the input size. In our case, for a single super-vertex of $\pTree$ with $\card{X}\leq 50000\log{n}$, the running time is therefore $O(\log^2{n})$ only. By \Cref{fct:num-splits-tree}, there are at most $O(\log{n})$ nodes in a binary tree with $O(\log{n})$ leaves, which implies $O(\log^3{n})$ running time for a single super-vertex. Finally, with at most $O(n)$ super-vertices in the tree, the second step only takes $O(n\cdot \log^3{n})=O(n^3\log{n})$ time, as desired.
\end{proof}

We now move to the approximation guarantee of the \Cref{alg:HC-Das-fast}.
\begin{lemma}
\label{lem:HC-das-sqrt-loglog-approx}
Conditioning on the high probability guarantees of \Cref{thm:strong-partial-tree}, \Cref{alg:HC-Das-fast} outputs an HC tree $\cT$ that achieves $O(\sqrt{\log\log{n}})$-approximation to the Dasgupta's objective.
\end{lemma}
\begin{proof}
Similar to the proof of \Cref{lem:HC-das-const-approx}, for any partial tree $\pTree$, we first partition the edges in to $E_{\text{cross}}$ and $E_{\text{same}}$ based on whether the edge $(u,v)\in E$ crosses different partial trees, i.e.,
\begin{enumerate}
\item $(u,v)\in E_{\text{cross}}$ iff $u\in X$ and $v\in Y$ for some super-vertices $X\neq Y$ in $\pTree$.
\item $(u,v)\in E_{\text{same}}$ iff $u,v \in X$ for some super-vertex $X$ in $\pTree$.
\end{enumerate}
Again, by using \Cref{obs:edge-partition}, we can show that $\OPTdas = \cost_{G}(\cTstar)= \cost_{G}(\cTstar, E_1)+\cost_{G}(\cTstar, E_2)$. The costs w.r.t. to $E_1$ and $E_2$ are therefore as follows.
\begin{enumerate}
\item For $E_{\text{cross}}$, we have that $\cost_{G}(\cT, E_{\text{cross}})=\cost_{G}(\cTstar, E_{\text{cross}})$ by using the same argument of \Cref{lem:HC-das-const-approx}. 
\item For $E_{\text{same}}$, we argue that $\cost_{G}(\cT, E_{\text{same}})\leq O(\sqrt{\log\log{n}})\cdot \cost_{G}(\cTstar, E_{\text{same}})$. Formally, since algorithm in \Cref{prop:sparse-cut} finds an $O(\sqrt{\log s})$-approximation for each super-vertex $X$, we can use \Cref{prop:const-recursive-HC} on $G[X]$ to argue that the $\cost_{G}(\cT, E_{\text{same}}[X])\leq O(\sqrt{\log\log{n}})\cdot \cost_{G}(\cTstar, E_{\text{same}}[X])$ since $s=O(\log{n})$. Therefore, we can apply the same argument to every super-vertex to get the desired approximation factor.
\end{enumerate}
We now use \Cref{obs:edge-partition} again on $E_{\text{cross}}$ and $E_{\text{same}}$ to bound that
\begin{align*}
\cost_{G}(\cT)&=\cost_{G}(\cT, E_{\text{cross}}) + \cost_{G}(\cT, E_{\text{same}}) \\
&\leq \cost_{G}(\cTstar, E_{\text{cross}}) + O(\sqrt{\log\log{n}})\cdot \cost_{G}(\cTstar, E_{\text{same}})\\
&\leq O(\sqrt{\log\log{n}})\cdot \paren{\cost_{G}(\cTstar, E_{\text{cross}}) + \cost_{G}(\cTstar, E_{\text{same}})}\\
&= O(\sqrt{\log\log{n}})\cdot\cost_{G}(\cTstar)=O(\sqrt{\log\log{n}})\cdot \OPTdas,
\end{align*}
as desired.
\end{proof}

\paragraph{Finalizing the proof of \Cref{thm:root-loglog-n4-time-HC}.} With \Cref{alg:HC-Das-fast}, we can obtain the $O(n^4)$ time efficiency from \Cref{lem:HC-das-n4-efficiency} with high probability. Therefore, we can apply a union bound on the high probability events of \Cref{lem:HC-das-n4-efficiency} and \Cref{lem:HC-das-const-approx} to get the desired efficiency and approximation guarantee.











