\newcommand{\Esame}{\ensuremath{E^{\textnormal{same}}_{\textnormal{high}}}\xspace}
\newcommand{\Ediff}{\ensuremath{E^{\textnormal{diff}}_{\textnormal{high}}}\xspace}

\section{Near-linear Time Algorithms for Moseley-Wang Hierarchical Clustering Objective}
\label{sec:MW-objective-algs}
We introduce our algorithm for the Moseley-Wang HC objective in this section. The algorithm is based on the weakly consistent trees as in \Cref{thm:weak-partial-tree}, and our analysis is more involved compared to the results in \Cref{sec:dasgupta-objective} -- it requires a careful handling of the contributions of the `less significant edges' to the Moseley-Wang objective.

Our main result is a near-linear time algorithm for the Moseley-Wang objective that achieves $(1-o(1))$ multiplicative approximation.

\thmhcalgmw*


Our algorithm is simply as follows.
\begin{algorithm}
\caption{A near-linear time algorithm for the Moseley-Wang HC objective}\label{alg:HC-MW}
\KwIn{Input graph $G=(V,E,w)$; Splitting oracle $\cO$}
\KwOut{A hierarchical clustering tree $\cT$}
Run the weak partial tree approximation algorithm in \Cref{thm:weak-partial-tree} to obtain partial tree $\pTree$\;
\For{each super-vertex in $\pTree$}{ 
partition the leaves \emph{arbitrarily} to obtain an HC tree $\cT$\; 
}
\end{algorithm}
Since each super-vertex contains $O(\log{n})$ vertices, we can always partition the super-vertices in $\polylog{n}$ time\footnote{An arbitrary recursive balanced partition only requires a run time of $O(\log{n}\cdot \log\log{n})$}. There are at most $O(n/\log{n})$ such super-vertices, and the total runtime is at most $O(n\cdot \polylog{n})$, which is dominated by the runtime of the weakly-consistent partial tree construction as in \Cref{thm:weak-partial-tree}.

To prove the approximation guarantee of \Cref{thm:hc-alg-MW}, we will show the following technical lemma that lower bounds the number of non-leaves between $\cT$ and $\cTstar$.

\begin{lemma}
\label{lem:num-non-leaf-weak-tree}
Let $\cT$ be a hierarchical clustering tree obtained by \Cref{alg:HC-MW}, and let $u,v\in V$ be any two vertices. Then, conditioning on the high probability event that $\pTree$ is a partial tree that is weakly consistent with $\cTstar$, there is
\begin{itemize}
\item If $u$ and $v$ are in the same super-vertex $X$ of $\pTree$, then, there is
\begin{align*}
\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}\geq n - 50000\log{n}.
\end{align*}
\item If $u$ and $v$ are in different super-vertices $X$ and $Y$ of $\pTree$, then, there is
\begin{align*}
\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}\geq \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}} - 50000\log{n}.
\end{align*}
Furthermore, if 
\[\leaves{\cTstar}{\lcatreeset{X}{\cTstar}}\cap \leaves{\cTstar}{\lcatreeset{Y}{\cTstar}}=\emptyset,\]
then, we additionally have 
\[\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}= \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}}.\]
\end{itemize}
\end{lemma}
\begin{proof}
% For any two leaves $u,v \in V$ of $\cT$, we consider two cases based on their relationship in the partial tree $\pTree$:
We prove the two cases separately as follows.
\begin{itemize}[leftmargin=5pt]
\item \textbf{$u$ and $v$ are in the same super-vertex $X$ of $\pTree$.} % In this case, we lower bound the number of the non-leaves by $\nonleaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X$. 
By our construction, every leaf that is outside the subtree induced by $\leaves{\cT}{\lcatreeset{X}{\cT}}$ counts as a non-leave of $(u,v)$. As such, since $\card{X}\leq 50000\log{n}$, it is straightforward to get that
\[\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}\geq n - 50000\log{n}.\]
%separately looking into $\nonleaves{\cT}{\lcatree{u}{v}{\cT}} \cap X$ and $\nonleaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X$, and we compare them with $\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}} \cap X$ and $\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}} \setminus X$. By \textit{weak contraction property}, the set of $X$ corresponds to a collection of maximal trees in $\cTstar$. Furthermore, since $\card{X}\leq 50000 \log{n}$, and difference between number of non-leaves in $\cT$ and $\cTstar$ \emph{restrict on} $X$ is upper-bounded by the size of $X$, i.e.
% \[\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}} \cap X}\geq \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}} \cap X}-50000 \log{n}.\]
% For the set $\nonleaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X$, we argue that $\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X}\geq \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}} \setminus X}$. To see this, note that by the \emph{subtree preserving property}, we have $\lcatree{u}{v}{\cT}=\lcatreeset{X}{\cT}$. As such, we have $\card{\leaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X} = 0$. On the other hand, we have $\card{\leaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X}\geq 0$. Therefore, we have $\card{\leaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X}\geq \card{\leaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X}$, which implies
% \[\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}} \setminus X}\geq \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}} \setminus X},\]
% as desired.

\item \textbf{$u$ and $v$ are in different super-vertices $X,Y$ of $\pTree$.} Suppose w.log. that $u\in X$ and $v \in Y$. By the \textit{subtree preserving property}, we have $\leaves{\cT}{\lcatree{u}{v}{\cT}}=\leaves{\cTstar}{\lcatreeset{X\cup Y}{\cTstar}}$. We now discuss further two sub-cases:
\begin{enumerate}[label=\alph*).]
\item If $\leaves{\cTstar}{\lcatreeset{X}{\cTstar}}$ and $\leaves{\cTstar}{\lcatreeset{Y}{\cTstar}}$ are disjoint. In this case, we have exactly $\leaves{\cTstar}{\lcatreeset{X\cup Y}{\cTstar}}=\leaves{\cTstar}{\lcatree{u}{v}{\cTstar}}$, which implies $\leaves{\cT}{\lcatree{u}{v}{\cT}}=\leaves{\cTstar}{\lcatree{u}{v}{\cTstar}}$. Therefore, we have
\[\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}= \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}}.\]
This proves the ``furthermore'' part of the second case.

\item If $\leaves{\cTstar}{\lcatreeset{X}{\cTstar}}$ and $\leaves{\cTstar}{\lcatreeset{Y}{\cTstar}}$ have intersections. In this case, note that by the \textit{weak contraction property}, we must have \emph{inclusion} relationship between $\leaves{\cTstar}{\lcatreeset{X}{\cTstar}}$ and $\leaves{\cTstar}{\lcatreeset{Y}{\cTstar}}$. Suppose without loss of generality, that $\leaves{\cTstar}{\lcatreeset{X}{\cTstar}} \supseteq \leaves{\cTstar}{\lcatreeset{Y}{\cTstar}}$, the differences between $\leaves{\cTstar}{\lcatreeset{X\cup Y}{\cTstar}}$ and $\leaves{\cTstar}{\lcatree{u}{v}{\cTstar}}$ is at most the set of $X$. Since $\card{X}\leq 50000\log{n}$, we have
\[\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}\geq \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}} - 50000\log{n},\]
as desired.
\end{enumerate}
\end{itemize}
This concludes the proof of \Cref{lem:num-non-leaf-weak-tree}. %\myqed{\Cref{lem:num-non-leaf-weak-tree}}
\end{proof}

To prove the approximation guarantee of \Cref{thm:hc-alg-MW}, we will need a handful of structural observations for the optimal HC trees in the Moseley-Wang objective. We first observe that for any optimal HC tree $\cTstar$ necessarily has a ``monotone edge weight'' property between an internal node and its descendants.

\begin{figure}[!htb]
	\centering
	\includegraphics[width=0.8\textwidth]{figures/structure-observation-MW-OPT}
	\caption{\label{fig:mw-OPT-structure} An illustration of the edge weights and leaves described in \Cref{clm:weight-property-internal-nodes}.}
\end{figure}

\begin{claim}
\label{clm:weight-property-internal-nodes}
% \chen{This claim is incorrect in the current form; find something similar that makes it work.}
Let $z_{1}$ and $z_{2}$ be any two internal nodes of the optimal HC tree $\cTstar$ under the Moseley-Wang objective, and let $z_{2}$ be a descendant node of $z_{1}$. We use $w_1$ and $w_2$ to denote the total weights of the edges induced by $z_1$ and $z_2$, respectively. Furthermore, let $w_3$ be the total weights of the edges induced on the internal nodes between $z_1$ and $z_2$.

Suppose the partition induced by $z_{1}$ is $S\rightarrow (A, S\setminus A)$, and let $B$ and $C$ be the set of vertices induced by $z_{2}$ such that $B\cup C\subseteq S\setminus A$. Furthermore, let $D=(S\setminus A)\setminus (B\cup C)$, and suppose $\max\{\card{B},\card{C}\}\geq \card{A}$. Then, there is
\begin{align*}
\frac{w_1-(\frac{\card{A}}{\card{D}}+1) \cdot w_3}{\card{A}+\card{D}}\leq \frac{w_2}{\max\{\card{B},\card{C}\}}.
\end{align*}
An illustration of the edges and leaves used in the statement can be found in \Cref{fig:mw-OPT-structure}.
\end{claim}
\begin{proof}
The claim is similar in spirit to the ``switching lemma'' under Dasgupta's objective as proved in \citep{HogemoBBPT21}. Suppose w.log. that $\card{B}\geq \card{C}$. For the purpose of this proof (and also that of \Cref{clm:weight-property-w-A-B}), we let $\rev_{G}(\cT, E_{1})$ be the revenue induced by a subset of edges $E_{1}$ with $\cT$ being the HC tree of $G$. We further observe some useful relationships between the weights $w_1$, $w_2$, $w_3$ and the weights $w(A,B)$, $w(A,C)$, $w(A,D)$, $w(B,C)$, $w(B,D)$, and $w(C,D)$ as follows.
\begin{align*}
w_1 = w(A,D)+w(A,B)+w(A,C) \qquad w_2=w(B,C) \qquad w_3 \geq w(B,D) + w(C,D).
\end{align*}
We first prove a self-contained structural claim that the edge weights between $A$ and $B$ cannot be too much bigger than $w_3$. More formally, the claim is as follows.
\begin{claim}
\label{clm:weight-property-w-A-B}
Let $A$, $B$, $C$, and $D$ be the set of vertices and $w_1$, $w_2$, and $w_3$ be the edge weights as prescribed in \Cref{clm:weight-property-internal-nodes}. Furthermore, let $E(A,B)$ be the edges between $A$ and $B$, and $w(A,B)$ be the weights of $E(A,B)$. Then, there is
\begin{align*}
w(A,B)\leq \frac{\card{A}}{\card{D}}\cdot w_{3}.
\end{align*}
\end{claim}
\begin{proof}
As consistent with the proof of \Cref{clm:weight-property-internal-nodes}, we assume w.log. that $\card{B}\geq \card{C}$. Let us construct a tree $\cT^{(1)}$ based on $\cTstar$ by switching the subtrees induced by $A$ and $D$. Note that in such change of HC tree, the only edges that will have a changed revenue are $E(A,B)$, $E(A,C)$, $E(A,D)$, $E(B,C)$, and edges accounted by $w_3$, which we call $E_3$ (including but not limited to $E(B,D)$ and $E(C,D)$), and edges in. We list these changes as follows. 
\begin{enumerate}
\item $E(A,B)$: we have that $\rev_{G}(\cT^{(1)}, E_{A,B})-\rev_{G}(\cTstar, E_{A,B})\geq \card{D}\cdot w(A,B)$.
\item $E(A,C)$: we have that $\rev_{G}(\cT^{(1)}, E_{A,C})-\rev_{G}(\cTstar, E_{A,C})\geq \card{D}\cdot w(A,C)$.
\item $E(A,D)$: we have that $\rev_{G}(\cT^{(1)}, E_{A,D})-\rev_{G}(\cTstar, E_{A,D}) = 0$.
\item $E(B,C)$: we have that $\rev_{G}(\cT^{(1)}, E_{B,C})-\rev_{G}(\cTstar, E_{B,C}) = 0$.
\item $E_3$: we have that $\rev_{G}(\cT^{(1)}, E_{3})-\rev_{G}(\cTstar, E_{3}) \geq - w_3 \cdot \card{A}$.
\end{enumerate}
To maintain the optimality of $\cTstar$, there should be $\rev_{G}(\cT^{(1)})-\rev_{G}(\cTstar)\leq 0$. As such, we have
\begin{align*}
&0 \geq \rev_{G}(\cT^{(1)})-\rev_{G}(\cTstar)\\
&= \paren{\rev_{G}(\cT^{(1)}, E_{A,B})-\rev_{G}(\cTstar, E_{A,B})} + \paren{\rev_{G}(\cT^{(1)}, E_{A,C})-\rev_{G}(\cTstar, E_{A,C})} 
\\ 
& \quad + \paren{\rev_{G}(\cT^{(1)}, E_{A,D})-\rev_{G}(\cTstar, E_{A,D})} + \paren{\rev_{G}(\cT^{(1)}, E_{B,C})-\rev_{G}(\cTstar, E_{B,C})} \\
& \quad + \rev_{G}(\cT^{(1)}, E_{3})-\rev_{G}(\cTstar, E_{3})\\
&\geq \paren{w(A,B)+w(A,C)}\cdot \card{D}-w_3 \cdot \card{A}.
\end{align*}
As such, we can move the terms around, and obtain that
\begin{align*}
w(A,B)\leq w(A,B)+w(A,C) \leq \frac{\card{A}}{\card{D}}\cdot w_3,
\end{align*}
as desired. 
\myqed{\Cref{clm:weight-property-w-A-B}}
\end{proof}

We now use \Cref{clm:weight-property-w-A-B} to prove \Cref{clm:weight-property-internal-nodes}. 
We again construct a tree $\cT^{(2)}$ based on $\cTstar$ by switching the subtrees induced by \emph{$A$ and $B$} (note that this is different from the proof of \Cref{clm:weight-property-w-A-B}). Observe again that only the edges that have different revenue contribution in $\cT^{(2)}$ vs. $\cTstar$ are $E(A,B)$, $E(A,C)$, $E(A,D)$, $E(B,C)$, and edges accounted by $w_3$. We again list all the changes of revenue induced on these edges.

\begin{enumerate}
\item $E(A,B)$: we have that $\rev_{G}(\cT^{(2)}, E_{A,B})-\rev_{G}(\cTstar, E_{A,B})=0$.
\item $E(A,C)$: we have that $\rev_{G}(\cT^{(2)}, E_{A,C})-\rev_{G}(\cTstar, E_{A,C})\geq (\card{B}+\card{D})\cdot w(A,C)$.
\item $E(A,D)$: we have that $\rev_{G}(\cT^{(2)}, E_{A,D})-\rev_{G}(\cTstar, E_{A,D}) \geq \card{B}\cdot w(A,D)$.
\item $E(B,C)$: we have that $\rev_{G}(\cT^{(2)}, E_{B,C})-\rev_{G}(\cTstar, E_{B,C}) \geq -(\card{A}+\card{D}) \cdot w(B,C)$.
\item $E_3$: we have that $\rev_{G}(\cT^{(2)}, E_{3})-\rev_{G}(\cTstar, E_{3}) \geq - \card{A}\cdot w_3$.
\end{enumerate}

Therefore, by the optimally of $\cTstar$, there should be $\rev_{G}(\cT^{(2)})-\rev_{G}(\cTstar)\leq 0$. As such, we have
\begin{align*}
&0 \geq \rev_{G}(\cT^{(2)})-\rev_{G}(\cTstar)\\
&= \paren{\rev_{G}(\cT^{(2)}, E_{A,B})-\rev_{G}(\cTstar, E_{A,B})} + \paren{\rev_{G}(\cT^{(2)}, E_{A,C})-\rev_{G}(\cTstar, E_{A,C})} 
\\ 
& \quad + \paren{\rev_{G}(\cT^{(2)}, E_{A,D})-\rev_{G}(\cTstar, E_{A,D})} + \paren{\rev_{G}(\cT^{(2)}, E_{B,C})-\rev_{G}(\cTstar, E_{B,C})} \\
& \quad + \paren{\rev_{G}(\cT^{(2)}, E_{3})-\rev_{G}(\cTstar, E_{3})}\\
&\geq (\card{B}+\card{D})\cdot w(A,C) + \card{B}\cdot w(A,D)  -(\card{A}+\card{D}) \cdot w(B,C) - w_3 \cdot \card{A}.
\end{align*}
As such, by moving the terms around, we can get that 
\begin{align*}
\card{B} \cdot \paren{w(A,C) +  w(A,D)} & \leq (\card{B}+\card{D})\cdot w(A,C) + \card{B}\cdot w(A,D) \\
& \leq (\card{A}+\card{D})\cdot w(B,C)+  \card{A} \cdot w_3.
\end{align*}
We can use the observation that $w_1 = w(A,B)+w(A,C)+w(A,D)$ to obtain that
\begin{align*}
\card{B} \cdot w_1 & = \paren{w(A,C) + w(A,B) +  w(A,D)} \\
& \leq (\card{A}+\card{D})\cdot w(B,C)+ \card{A}\cdot w_3 + \card{B}\cdot w(A,B)
\end{align*}
by adding $\card{B}\cdot w(A,B)$ on both sides. Now, we can apply \Cref{clm:weight-property-w-A-B} to obtain that
\begin{align*}
\card{B} \cdot w_1 & \leq (\card{A}+\card{D})\cdot w(B,C)+ \card{A}\cdot w_3 + \card{B}\cdot \frac{\card{A}}{\card{D}}\cdot w_3\\
&\leq (\card{A}+\card{D})\cdot w(B,C) + \card{B}\cdot w_3 + \card{B}\cdot \frac{\card{A}}{\card{D}}\cdot w_3 \tag{using $\card{A}\leq \card{B}$}
\end{align*}
Note that $w(B,C)=w_2$. As such, the above implies that
\begin{align*}
\card{B} \cdot \paren{w_1 - (1+\frac{\card{A}}{\card{D}})w_3} \leq (\card{A}+\card{D})\cdot w_2.
\end{align*}
Moving the turns around in the above inequality gives us the desired bound. \myqed{\Cref{clm:weight-property-internal-nodes}}
\end{proof}

We now use \Cref{clm:weight-property-internal-nodes} to show that the set of edges $(u,v)$ such that 
\begin{enumerate}[label=\alph*).]
\item has at most $O(\log^2{n})$ non-leaves in $\cTstar$; and
\item let $X$ and $Y$ be corresponding super-vertices that contain $u$ and $v$ in a weakly consistent partial tree $\pTree$; there is $\leaves{\cTstar}{\lcatreeset{X}{\cTstar}} \cap \leaves{\cTstar}{\lcatreeset{Y}{\cTstar}} \neq \emptyset$.
\end{enumerate}
can contribute to at most an $o(1)$ fraction of the optimal cost. This means that our estimation with non-leaves using \Cref{lem:num-non-leaf-weak-tree} would lead to a good approximation. The formal statement is as follows.

\begin{lemma}
\label{lem:MW-opt-structure}
Let $\pTree$ be an arbitrary partial HC tree that is weakly consistent with the optimal HC tree $\cTstar$ under the Moseley-Wang objective. Define $\Elow(\pTree) \subseteq V\times V$ as the edges such that for any $(u,v)\in \Elow(\pTree)$, there is
\begin{enumerate}[label=\alph*).]
\item $\card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}}\leq 50000\cdot \log^2{n}$.
\item Let $X$ and $Y$ be corresponding super-vertices that contain $u$ and $v$ in $\pTree$; there is 
\[\leaves{\cTstar}{\lcatreeset{X}{\cTstar}} \cap \leaves{\cTstar}{\lcatreeset{Y}{\cTstar}} \neq \emptyset.\]
\end{enumerate}
Then, for sufficiently large $n$, the total contribution of revenue from the edges in $\Elow(\pTree)$ is at most $50000\cdot \frac{\log^4{n}}{n}$ fraction of $\OPTmw$, i.e.,
\begin{align*}
\sum_{e=(u,v)\in \Elow(\pTree)} w(e)\cdot \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}} \leq O(\frac{\log^4{n}}{n}) \cdot \OPTmw.
\end{align*}
\end{lemma}
\begin{proof}
For any two super-vertices $X$ and $Y$ in the partial HC tree $\pTree$, by the \emph{weak contraction property}, if $\leaves{\cTstar}{\lcatreeset{X}{\cTstar}} \cap \leaves{\cTstar}{\lcatreeset{Y}{\cTstar}}$ is not empty, the only possible case is to have \emph{inclusion} relationships between the two sets of leaves. Suppose w.log. that $\leaves{\cTstar}{\lcatreeset{X}{\cTstar}}\supseteq \leaves{\cTstar}{\lcatreeset{Y}{\cTstar}}$. 
Let $\tilde{Y}$ be the set of vertices induced by the sibling node of $X$ in $\pTree$, and it is straightforward to see that $Y\subseteq \tilde{Y}$. We further let $Y'$ be the \emph{larger} immediate child of the tree induced by $\tilde{Y}$.

By the conditions of $i).$ $\card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}}\leq 50000\cdot \log^2{n}$, $ii).$ $\card{X}\leq 5000\log{n}$, and $iii).$ the inclusion relationship between the leaves, there is
\[\card{\tilde{Y}}\geq n-50000\cdot (\log^2{n}+\log{n}); \qquad \card{Y'}\geq \frac{n-50000\cdot (\log^2{n}+\log{n})}{2}.\]

We now use \Cref{clm:weight-property-internal-nodes} inductively to bound the weights of $w(E_1)$ for the sets of edges $E_1\subseteq \Elow$ that are split by some internal nodes of $X$.
Let $E_2$ be the set of edges that is split in the subtree induced by $Y'$, and let $\tilde{X}$ be vertices that are split by $E_1$ and as the sibling of $\tilde{Y}$. Our induction hypothesis is that
\begin{align*}
w(E_1)< \frac{C \cdot \log{n} \cdot w(E_2)}{n-50000\cdot (\log^2{n}+\log{n})}
\end{align*}
for some absolute constant $C$.

To prove this statement, we first look at the base case. By the size bound on $X$, it is straightforward to see that
\[\card{X}-\card{\tilde{X}}\leq 50000\log{n}.\]
In the base case, we pick edges $E_1 \subseteq \Elow$ such that $E_2$ is split immediately after $E_1$, i.e., $E_1$ are the edges between $\tilde{X}$ and $\tilde{Y}$. Now, we can use \Cref{clm:weight-property-internal-nodes} with $A\gets \tilde{X}$, $B\gets Y'$, and $D\gets \emptyset$ ($w_3=0$) to argue that
\begin{align*}
\frac{w(E_1)}{\card{X}}\leq \frac{w(E_1)}{\card{\tilde{X}}}< \frac{w(E_2)}{\card{Y'}}.
\end{align*}
By the size upper bound of $X$ and the size lower bound of $Y'$, the above inequality implies that
\begin{align*}
\frac{w(E_1)}{50000\log{n}}< \frac{2 \cdot w(E_2)}{n-50000\cdot (\log^2{n}+\log{n})}<\frac{C \cdot \log{n} \cdot w(E_2)}{n-50000\cdot (\log^2{n}+\log{n})}
\end{align*}
for any $C>2$, which proves the base case.

For the inductive step, let us suppose the statement holds until some internal node $z$, and we look into $E_1\subseteq \Elow$ that is induced on $\pa{z}$. We again use \Cref{clm:weight-property-internal-nodes} by letting $A\gets \tilde{X}$, $B\gets Y'$, and $D\gets X\setminus \tilde{X}$. Define $E_3$ as the set of edges that are split between $z$ and $\lcatreeset{\tilde{Y}}{\cTstar}$. By the induction hypothesis, for every node between $z$ and $\lcatreeset{\tilde{Y}}{\cTstar}$, the total induced weights is at most
\begin{align*}
\frac{C \cdot \log{n} \cdot w(E_2)}{n-50000\cdot (\log^2{n}+\log{n})}.
\end{align*}
Furthermore, since $\frac{\card{X}}{\card{\tilde{X}}}\leq \card{X} \leq 50000 \log{n}$, and $z$ and $\pa{\lcatreeset{\tilde{Y}}{\cTstar}}$ are in the same $X$ of $\pTree$, we can bound the total weights in $E_3$ as follows
\begin{align*}
w(E_3)\leq 50000\cdot \log{n}\cdot \frac{C \cdot \log{n} \cdot w(E_2)}{n-50000\cdot (\log^2{n}+\log{n})}.
\end{align*}
Furthermore, by the size upper bound of $X$, we have $\card{A}+\card{D}\leq 50000\cdot \log{n}$ in \Cref{clm:weight-property-internal-nodes}. Combining the above gives us that for sufficiently large $n$, we have
\begin{align*}
\frac{1}{2}\cdot \frac{w(E_1)}{\card{X}}\leq \frac{w(E_1)-(50000 \log{n} + 1)\cdot w(E_3)}{\card{X}} \leq \frac{w(E_1)-(\frac{\card{X}}{\card{\tilde{X}}}+1) \cdot w(E_3)}{\card{X}} < \frac{w(E_2)}{\card{Y'}},
\end{align*}
where the first inequality follows from the fact that $w(E_3)=O(\frac{\log^2{n}}{n})\cdot w(E_2)$, the second inequality follows from that $\card{X}/\card{\tilde{X}}\leq \card{X} \leq 50000 \log{n}$, and the last inequality follows from \Cref{clm:weight-property-internal-nodes}.
Therefore, we can again obtain that 
\begin{align*}
\frac{w(E_1)}{100000\log{n}}< \frac{4 \cdot w(E_2)}{n-50000\cdot (\log^2{n}+\log{n})},
\end{align*}
which means $w(E_1)< \frac{C \cdot \log{n} \cdot w(E_2)}{n-50000\cdot (\log^2{n}+\log{n})}$ for a sufficiently large constant $C$ ($C=400000$ suffices). This concludes our inductive proof for the weight bound of any $E_1 \subseteq \Elow$ in any $X$.

Using $w(E_1)\leq \frac{C\cdot \log{n}}{n-50000\cdot (\log^2{n}+\log{n})} \cdot w(E_2)$ for any $(u,v)\in \Elow$, we note that a trivial lower bound of the optimal revenue is
\[\OPTmw = \Omega(\log{n}\cdot w(E_2)),\]
since this is the revenue induced on the edge set $E_2$ only. On the other hand, since we need the inclusion relationship between the leaves, and by the fact that the number of non-leaves is at most $\log^2{n}$, there are at most $50000(\log^2{n}+\log{n})$ edges in $\Elow$, i.e.,
\[\card{\Elow}\leq 50000(\log^2{n}+\log{n}).\]
Therefore, the total contribution of revenue by $\Elow$ is at most 
\begin{align*}
& \sum_{e=(u,v)\in \Elow(\pTree)} w(e)\cdot \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}} \\
&\leq \sum_{e=(u,v)\in \Elow(\pTree)} w(e)\cdot \log^2{n} \tag{by the number of non-leaves}\\
&\leq \max\{w(E_1)\mid E_1 \subseteq \Elow \}\cdot 50000(\log^2{n}+\log{n}) \cdot \log^2{n} \tag{uniform upper bound}\\
&\leq \frac{C\cdot \log{n}}{n-50000\cdot (\log^2{n}+\log{n})} \cdot w(E_2) \cdot 50000(\log^2{n}+\log{n}) \cdot \log^2{n} \tag{by the relationship between $w(E_2)$ and $w(E_1)$ for $E_1\subseteq \Elow$}\\
&\leq O(\frac{\log^4{n}}{n}\cdot \OPTmw), \tag{by the lower bound of $\OPTmw$}
\end{align*}
as desired. %\myqed{\Cref{lem:MW-opt-structure}}
\end{proof}

\paragraph{Finalizing the proof of \Cref{thm:hc-alg-MW}. } We have discussed that the algorithm enjoys $\tilde{O}(n^2)$ running time and $O(n^2)$ query efficiency. For the approximation guarantee, note that each edge $(u,v)$ gains a revenue of $w_{u,v}\cdot \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}}$ in the optimal tree $\cTstar$. For edges $(u,v)\not\in \Elow$, let $\Esame$ be the set of edges where $u$ and $v$ are in the same super-vertex, and $\Ediff$ be the set of edges where $u$ and $v$ are in different super-vertices. We now have
\begin{itemize}
\item For edges in $\Esame$, we have $\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}\geq n - 50000\log{n}$ that by \Cref{lem:num-non-leaf-weak-tree}. On the other hand, any vertex pair has at most $n$ non-leaves in the graph. Therefore, we have that
\begin{align*}
\rev_{G\cap \Esame}{(\cT)} &= \sum_{e\in \Esame} w(e)\cdot \card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}\\
&\geq \sum_{e\in \Esame} w(e)\cdot n - 50000\log{n}\\
&\geq  \sum_{e\in \Esame} w(e)\cdot n \cdot (1-\frac{50000\log{n}}{n})\\
&\geq (1-\frac{50000\log{n}}{n}) \cdot \rev_{G\cap \Esame}{(\cTstar)}.
\end{align*}
\item For edges in $\Ediff$, we have 
\begin{align*}
\card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}} & \geq \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}}-50000\log{n} \\
& \geq (1-O(\frac{1}{\log{n}}))\cdot \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}},
\end{align*}
where the first inequality follows from \Cref{lem:num-non-leaf-weak-tree}, and the second inequality is from the fact that $\card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}}\geq 50000\cdot \log^2{n}$ for every $(u,v)\not\in \Elow$. As such, we have that
\begin{align*}
\rev_{G\cap \Ediff}{(\cT)} &= \sum_{e\in \Ediff} w(e)\cdot \card{\nonleaves{\cT}{\lcatree{u}{v}{\cT}}}\\
&\geq \paren{1-O(\frac{1}{\log{n}})} \cdot  \sum_{e\in \Ediff} w(e)\cdot \card{\nonleaves{\cTstar}{\lcatree{u}{v}{\cTstar}}}\\
&= \paren{1-O(\frac{1}{\log{n}})} \cdot \rev_{G\cap \Ediff}{(\cTstar)}.
\end{align*}
\end{itemize}
Therefore, by additionally using \Cref{lem:MW-opt-structure}, we have that
\begin{align*}
\rev_{G}(\cT)&\geq \rev_{G\cap \Esame}{(\cT)} + \rev_{G\cap \Ediff}{(\cT)}\\
&\geq (1-O(\frac{1}{\log{n}})) \cdot \rev_{G\cap \Esame}{(\cTstar)} + \rev_{G\cap \Ediff}{(\cTstar)}\\
&\geq (1-O(\frac{1}{\log{n}})) \cdot \paren{\rev_{G\cap \Esame}{(\cTstar)} + \rev_{G\cap \Ediff}{(\cTstar)}}\\
&\geq (1-O(\frac{1}{\log{n}})) \cdot \paren{1-O(\frac{\log^4{n}}{n})} \cdot \rev_{G}(\cTstar) \tag{using \Cref{lem:MW-opt-structure}} \\
&\geq (1-o(1))\cdot \rev_{G}(\cTstar),
\end{align*}
as desired.

\begin{remark}
\label{rmk:MW-obj-strong-tree}
We can observe that if we run \Cref{alg:HC-MW} with the \emph{strongly consistent} partial HC tree, we can get a similar (and even stronger) approximation guarantee, albeit with worse efficiency ($\Otilde(n^3)$ time). Concretely, note that if we use the strongly consistent partial HC tree, the additive error again only happens on $E^{\text{same}}$, and we do \emph{not} need \Cref{lem:MW-opt-structure} to bound the contributions of the edges in $\Elow(\pTree)$ (since $=\emptyset$). In this way, we can further decrease the $o(1)$ term to $O(\frac{\log{n}}{n})$. However, the sacrifice of the running time is too significant, and we skip the details of this algorithm.
\end{remark}





\section{Learning-Augmented Sublinear Algorithms for Hierarchical Clustering}
\label{sec:hc-oracle-sublinear-algs}
In this section, we explore \emph{sublinear} algorithms for hierarchical clustering with the splitting oracle. 
Among these is a \emph{semi-streaming} algorithm, capable of computing an $O(1)$ approximation of Dasgupta's HC objective within \emph{polynomial time}. Additionally, we introduce a PRAM algorithm that achieves a $(1-o(1))$ approximation of the Moseley-Wang objective, utilizing $\tilde{O}(n^2)$ work and $\polylog{n}$ depth. From a technical standpoint, these algorithms represent straightforward extensions of the results outlined in \Cref{thm:hc-alg-MW,thm:constant-poly-time-HC,thm:root-loglog-n4-time-HC}. Despite their simplicity, these algorithms demonstrate the advantages of the splitting oracle in modern sublinear computation models. Specifically, we compare our sublinear algorithms with previous results as follows:
\begin{enumerate}
\item In the streaming setting, \citep{AssadiCLMW22,AgarwalKLP22} designed single-pass streaming algorithms that achieve $\tilde{O}(n)$ memory usage and $O(1)$-approximation to Dasgupta's objective, albeit in \emph{exponential time}. By improving the time efficiency to polynomial time, our streaming result echoes a similar narrative in the offline setting, demonstrating significantly more efficient constructions with the splitting oracle.
\item For the parallel setting, \citep{agarwal2024parallel} (cf. \citep{AgarwalKLP22}) provided parallel algorithms (in the PRAM and the similar MPC settings, see \Cref{sec:pram-mpc-models} for details of these models) for Dasgupta's objective with $\tilde{O}(n^2)$ work and $\polylog{n}$ depth that achieve $\polylog{n}$ approximation. Since the objectives are different, their result is not directly comparable to ours; however, the conceptual message here is still that the splitting oracle is able to significantly improve the approximation guarantee and the efficiency.
\end{enumerate}

We discuss these algorithms and their analysis for the rest of this section.

\subsection{A single-pass semi-streaming HC algorithm for Dasgupta's objective}
\label{subsec:hc-alg-streaming}
We present our algorithm for the semi-streaming algorithm in this part. To begin with, we need to define the \emph{model} for streaming hierarchical clustering with the splitting oracle.

\paragraph{Graph streaming with offline splitting oracle.} We focus on the (dynamic) graph streaming model with the \emph{offline} splitting oracle. In this model, the edges of the graph are inserted and deleted (together with their edge weights), and the algorithm is asked to output an HC tree by the \emph{end} of the stream. Additionally, the algorithm is given an offline splitting oracle $\cO$ \emph{before} the graph stream, and the algorithm is allowed to make unlimited computations before the stream starts. The total memory cost is the total number of bits the algorithm maintains at any point, including those dedicated to edge representation and those generated through offline computations. 

For polynomial-time efficiency, we assume that the stream itself is of $\poly(n)$ length since otherwise, the stream itself will take super-polynomial time to complete. Under the above model and setting, the formal statement of our result is as follows.
\begin{theorem}
\label{thm:hc-das-streaming}
There exists a single-pass (dynamic) streaming algorithm that given a weighted undirected graph $G=(V,E,w)$ in a $\poly(n)$-length dynamic stream and an offline splitting oracle $\cO$, with high probability, in $O(n\cdot \log^{3}{n})$ (bits) space and polynomial time computes a hierarchical clustering tree $\cT$ such that $\cost_{G}(\cT)\leq O(1)\cdot \OPTdas(G)$, where $\OPTdas(G)$ is the cost of the optimal hierarchical clustering tree $\cTstar$, i.e., $\OPTdas(G)=\cost_{G}(\cTstar)$.
\end{theorem}

\begin{proof}
The algorithm is to simply first construct a strong partial tree $\pTree$ with the algorithm of \Cref{def:strongly-consistent-tree} \emph{before} the stream starts, and store edges only inside the same super-vertices during the stream. By the end of the stream, we compute recursive sparsest cuts on the vertices induced on super-vertices of $\pTree$, and output in the same manner of \Cref{alg:HC-Das}. The formal description is as follows.

\begin{algorithm}
\caption{A polynomial-time single-pass semi-streaming algorithm for the Dasgupta's HC objective} \label{alg:HC-streaming-poly-time}
\KwIn{Input graph $G=(V,E,w)$; Splitting oracle $\cO$}
\KwOut{A hierarchical clustering tree $\cT$}
\textbf{Before} the start of the stream, run the strong partial tree approximation algorithm in \Cref{thm:strong-partial-tree} to obtain partial tree $\pTree$\;
\For{each edge $(u,v)$ with during the insertion/deletion stream}{
If $u,v\in X$ for any super-vertex $X$ in $\pTree$, update $(u,v)$ with the same insertion/deletion update\;
Otherwise, ignore the edge\;
}
\For{each super-vertex in $\pTree$ after the stream, run recursive sparsest cut as follows}{
On input vertex set $S$, \emph{exhaustively search} the sparsest cut $(A,B)$ on the induced subgraph $G[S]$.\;
Partition the vertices as $S\rightarrow (A,B)$, and recurse on $G[A]$ and $G[B]$.\;
}
\end{algorithm}

% In what follows, we analyze \Cref{alg:HC-streaming-poly-time} and prove \Cref{thm:hc-das-streaming}.

We first prove the time and space efficiency. Essentially, \Cref{alg:HC-streaming-poly-time} computes a strong partial tree $\pTree$ before the stream starts, and only main edges inside each super-vertex of $O(\log{n})$ size. By \Cref{thm:strong-partial-tree}, the pre-processing part takes polynomial ($O(n^3\log{n})$) time and $O(n\log{n})$ space. Furthermore, for each super-vertex, we maintain at most $O(\log^{2}n)$ edges; each edge could have at most $\poly(n)$ updates, which means an additive space of $O(\log{n})$ bits suffices for each edge. Therefore, we record at most $O(\log{n})$ bits for each edge. There are at most $n$ super-vertices, which means the algorithm maintains the information of $O(n\log^2{n})$ edges, which takes $O(n\log^3 {n})$ bits. After the stream, we partition the super-vertices with the edges stored, and write down the rest of the HC tree. The time efficiency of the post-processing part is exactly as \Cref{lem:HC-das-poly-efficiency}.

For the approximation guarantee, note that we are essentially simulating \Cref{alg:HC-Das} with the same input and output guarantees. As such, we can simply use \Cref{lem:HC-das-const-approx} to argue the approximation guarantee.
\end{proof}


\subsection{Parallel HC algorithms for Moseley-Wang Objective}
We now move the PRAM hierarchical clustering algorithm for the Moseley-Wang objective with near-linear $\tilde{O}(n^2)$ work and $\polylog(n)$ depth. The formal statement of the algorithm is as follows.
%\Cref{cor:parallel-weak-partial-tree}
%\Cref{thm:hc-alg-MW}

\begin{theorem}
\label{thm:hc-MW-PRAM}
There exists a PRAM algorithm that given a weighted undirected graph $G=(V,E,w)$ and a splitting oracle $\cO$, with high probability, in $O(n^2 \cdot \polylog{n})$ work and $\polylog{n}$ depth computes a hierarchical clustering tree $\cT$ such that $\rev_{G}(\cT)\geq (1-o(1))\cdot \OPTmw(G)$, where $\OPTmw(G)$ is the revenue of the optimal hierarchical clustering tree $\cTstar$, i.e., $\OPTmw(G)=\rev_{G}(\cTstar)$.
\end{theorem}
\begin{proof}
The algorithm is to run the PRAM weak partial tree algorithm in \Cref{cor:parallel-weak-partial-tree} to obtain $\pTree$, and arbitrarily partition the vertices in the super-vertices of $\pTree$. The formal description of the algorithm is as follows.

\begin{algorithm}
\caption{A near-linear work, poly-logarithmic depth PRAM algorithm for the Moseley-Wang HC objective} \label{alg:HC-MW-PRAM}
\KwIn{Input graph $G=(V,E,w)$; Splitting oracle $\cO$}
\KwOut{A hierarchical clustering tree $\cT$}
Run the PRAM weak partial tree approximation algorithm in \Cref{cor:parallel-weak-partial-tree} to obtain partial tree $\pTree$\;
\For{each super-vertex in $\pTree$}{
Partition the leaves \emph{arbitrarily} to obtain an HC tree $\cT$\; 
}
\end{algorithm}

By \Cref{cor:parallel-weak-partial-tree}, the first step that computes the weak partial tree $\pTree$ only takes $\tilde{O}(n^2)$ work and $\polylog{n}$ depth. For the second step, since the partition is arbitrary, we can simply perform arbitrary balanced cuts on the vertices for each super-vertex $X$. For an individual $X$, this procedure can be done in $O(\log{n}\cdot \log\log{n})$ work and $O(\log\log{n})$ depth. By accounting for all the super-vertices, we blow up the work by at most an $O(n)$ factor and the depth remains the same since we can partition super-vertices in parallel. Therefore, the second step takes $O(n\cdot \log^2{n})$ work and $O(\log\log{n})$ depth. Therefore, the entire procedure takes $\tilde{O}(n^2)$ work and $\polylog{n}$ depth.

The output of \Cref{thm:hc-MW-PRAM} follows exactly the same rules of \Cref{alg:HC-MW}; therefore, the approximation guarantee follows from \Cref{thm:hc-alg-MW}.
\end{proof}

\begin{remark}
By the reduction of \Cref{prop:PRAM-to-MPC}, the result of \Cref{thm:hc-MW-PRAM} also implies a fully-scalable Massively Parallel Computation (MPC) algorithm that computes the HC tree $\cT$ with $(1-o(1))\cdot \OPTmw(G)$ revenue in $\tilde{O}(n^2)$ total memory and $\polylog{n}$ depth. The memory on each machine here is allowed to be $O(n^{\alpha})$ for any $\alpha\in (0,1)$, and we use $\tilde{O}(n^{2-\alpha})$ total machines in the MPC algorithm.
\end{remark}



\section{Preliminaries for Partial HC Tree Algorithms}
\label{sec:partial-tree-prelims}
We will discuss the construction of partial HC trees for the rest of this paper (\Cref{sec:partial-tree-prelims,sec:strong-partial-tree,sec:weak-partial-tree}). In this section, we first introduce the several notions that are essential in the \emph{analysis} of the partial HC tree algorithms. We use these notions extensively in the analysis of both \Cref{thm:strong-partial-tree} (\Cref{sec:strong-partial-tree}) and \Cref{thm:weak-partial-tree} (\Cref{sec:weak-partial-tree}). 

In the high-level overview, we slightly abused the notation to use $V$ to denote the subset of vertices. In our formal description of the algorithms, we will use $\Vp \subseteq V$ as the set of vertices of the current recursion step, and use $\np=\card{\Vp}$ as the size of the set. 

\subsection{Composable vertex sets and restricted subtrees}
To continue, we first introduce the notions of \emph{composable vertex sets} for a graph and the HC tree restricted to the sets.

\begin{definition}[Composable vertex sets]
\label{def:comp-set}
Let $G=(V,E)$ be a $n$-vertex graph and $\cT$ be a hierarchical clustering of $G$. For a subset $\Vp\subseteq V$, we say $\Vp$ is a \emph{composable (vertex) set} of $(G, \cT)$ if $\Vp$ can be written in a disjoint union of the leaves of \emph{maximal trees}, i.e., a union of vertices $\Vp=\cup_{i} \Vp_{i}$, such that \emph{all} $\Vp_{i}$ satisfies that 
\[\leaves{\cT}{\lcatreeset{\Vp_{i}}{\cT}} = \Vp_{i}.\]
In the special case, we say $\Vp$ is a \emph{single composable (vertex) set} if there is \emph{only one} such maximal tree, i.e., $\leaves{\cT}{\lcatreeset{\Vp}{\cT}} = \Vp$.
\end{definition}

In other words, if a vertex set $\Vp$ is composable, it means if we only look at the leaves of $\Vp$, they still form subtrees of $\cT$. An illustration of composable sets can be found in \Cref{fig:composable-sets}.

\begin{figure}[!htb]
	\centering
	\includegraphics[scale=0.6]{figures/composeable-and-maximal-vertex-sets}
	\caption{\label{fig:composable-sets} An illustration of the composable vertex sets and maximal trees as in \Cref{def:comp-set}.}
\end{figure}

We can define the HC tree restricted to composable subsets of vertices as follows.
% \chen{The notion of HC tree restricted to subset (\Cref{def:restrict-tree}) might not be useful anymore}

\FloatBarrier
\begin{definition}[Hierarchical clustering tree restricted to subset]
\label{def:restrict-tree}
Let $G=(V,E)$ be a $n$-vertex graph and $\cT$ be a hierarchical clustering of $G$. For any \emph{composable} subset $S\subseteq V$ such that $\card{S}\geq 2$, we call $\cT(S)$ as \emph{$\cT$ restricted to $S$} if $\cT(S)$ is a new binary tree constructed with the following process
\begin{tbox}
\begin{enumerate}
\item Extract $\cT'$ from $\cT$ by taking the induced subtree of the internal node $\lcatreeset{S}{\cT}$.
\item Remove all subtrees whose leaves contain \emph{only} vertices \emph{not} in $S$ from $\cT'$.
\item If there exists an internal node $x$ that only has \emph{a single} child, contract $x$ and its child to one node. Repeat until all internal node has two children nodes.
\end{enumerate}
\end{tbox}
\end{definition}
\FloatBarrier

Note that the algorithm in \Cref{def:restrict-tree} is a \emph{thought process}, and it only serves the purpose of analysis. The third line eventually terminates since there exists at least one subtree with two leaves for any \emph{composable} set $S$ with at least two vertices. An illustration of HC trees restricted to subsets can be shown in \Cref{fig:HC-restricted-to-subset}.
\begin{figure}[!htb]
	\centering
	\includegraphics[scale=0.6]{figures/HC-restrict-subset}
	\caption{\label{fig:HC-restricted-to-subset} An illustration of the HC tree $\cT$ to be restricted on a subset of vertices $S$.}
\end{figure}

We now provide the following observation that the new tree $\cT(S)$ preserves the \emph{relative order} of split away vertices of $\cT$. 
\begin{observation}
\label{obs:split-away-preserv}
For any triplet of vertices $(u,v,w)$, the orders of split-away for $(u,v,w)$ are the same in $\cT(S)$ and $\cT$, i.e., $w$ splits away from $(u,v)$ in $\cT(S)$ \emph{if and only if} $w$ splits away from $(u,v)$ in $\cT$.
\end{observation}
\begin{proof}
We first observe that the orders of split away for any triplet $(u,v,w)$ are the same in $\cT$ and $\cT'$ since $\cT'$ is a \emph{subtree} of $\cT$. Furthermore, since $S$ is a \emph{conposeable set}, every subtree we remove from $\cT'$ is necessarily a \emph{maximal} subtree, i.e., fix the removed vertex set $S$, the leaves of $\lcatreeset{S}{\cT'}$ is $S$ itself.

Let $x$ be the lowest common ancestor of $(u,v)$ in $\cT'$, and $x'$ be the lowest common ancestor of $(u,v,w)$ in $\cT'$. By our definition, we have $\levelr{\cT'}{x'}>\levelr{\cT'}{x}$. In $\cT(S)$, if none of $x$ and $x'$ is contracted in line 3, then the order of splits away trivially remains the same as in $\cT'$. 

On the other hand, if at least one of $x$ and $x'$ is contracted, and let the new internal nodes be $y$ and $y'$, we claim that there is
still $\levelr{\cT(S)}{y'}>\levelr{\cT(S)}{y}$. This is simply because every removed tree is a maximal tree, and the only case that $y$ and $y'$ are merged is that the induced vertices of $y'$ become empty, which contradicts the fact that $(u,v)$ is not removed. Therefore, the split order between $(w,u,v)$ is the same as in $\cT'$, which in turn is the same in $\cT$. 
\end{proof}

\subsection{Small-tree splitting order}
We now introduce the following notion of \emph{small-tree split order}, which we frequently use in our analysis.
\begin{definition}[Small-tree split order]
\label{def:small-tree-split}
Consider any subset $S\subseteq V$ and the hierarchical clustering tree $\cTstar(S)$ restricted to $S$, and consider the following process that divides the \emph{leaves} of $S$:
\begin{tbox}
\begin{enumerate}
\item Starting from the root $r$, let the split be $S \rightarrow (S^1_{l}, S^1_{r})$, and assume w.log. $\card{S^1_{l}}\leq \card{S^1_{r}}$. Let $\Vsmall_{1}$ be the vertices (leaves) induced by the ``smaller subtree'' $S^1_{l}$.
\item Starting from the lowest common ancestor of $S^1_{r}$, recursively define $\Vsmall_{\ell}$ as the vertices contained in the ``smaller subtree'' of level $\ell$ (by splitting from the ``larger subtree'' of level $\ell-1$). 
\end{enumerate}
\end{tbox}
\noindent
For the convenience of notation, we define $\Vsmall_{\ell}=\emptyset$ when $\ell$ is larger than the depth of the tree. For any integer $N \in [0, \nh]$, we can define the \emph{first $N$ vertices in the small-tree split order} by taking the first $N$ vertices in the order of $\Vsmall_{1}$, $\Vsmall_{2}$, etc.. Inside each set $\Vsmall_{i}$, we pick vertices in an arbitrarily \emph{fixed} order. We use the notation $\Vbefore{N}$ to denote the \emph{first} $N$ vertices in the small-tree split order, and we use $\Vafter{N}$ to denote the \emph{last} $N$ vertices in the small-tree split order. 
\end{definition}


Intuitively, we can think of the small-tree split order as we always write the ``smaller'' tree on the left-hand side, and recurse on the ``larger'' tree for this procedure, then take leaves from the left-most vertices. Note that \emph{every} vertex has to belong to $\Vsmall_{i}$ for \emph{some} $i$. An illustration can be found in \Cref{fig:small-tree-split-order}. 

Based on the notion of small-tree split order, we can define the notion of \emph{induced leaves} of the first or last $N$ vertices in the small-tree split order as follows.

\begin{definition}[Induced leaves of the $N$ first split vertices]
\label{def:small-tree-induced-leaves}
Let $\cTstar(S)$ and $S$ be the hierarchical clustering tree and the set of leaves. For any integers $N \in [0, \nh]$, we define the induced leaves of $\Vbefore{N}$ as the union of the $\cup_{i=1}^{\ell} \Vsmall_{i}$, where $\ell$ is the \emph{maximum} level such that $\Vsmall_{\ell}$ contains at least one vertex in $\Vbefore{N}$.
% \begin{enumerate}[leftmargin=12pt]
% \item The induced leaves of $\Vbefore{N}$ is defined as the union of the $\cup_{i=1}^{\ell} \Vsmall_{i}$, where $\ell$ is the \emph{maximum} level such that $\Vsmall_{\ell}$ contains at least one vertex in $\Vbefore{N}$.
% \item The induced leaves of $\Vafter{M}$ is defined as the union of the $\cup_{i=\ell}^{\infty} \Vsmall_{i}$ (define $\Vsmall_{i}=\emptyset$ if the split has ended), where $\ell$ is the \emph{minimum} level such that $\Vsmall_{\ell}$ does \emph{not} contain any vertex in $\Vbefore{M}$.
% \end{enumerate}
\end{definition}
\noindent
An illustration of the induced leaves in \Cref{def:small-tree-induced-leaves} can be found in \Cref{fig:small-tree-induced-leaves}.

