\subsubsection{The algorithm} 
We now present the actual algorithm. We first give two ``tester'' subroutines that serves as a more general version of the \texttt{counterpart-tester-strong} algorithm we used in \Cref{alg:strong-partial-tree}.

\FloatBarrier
\begin{algorithm}
\caption{$\testalg{u}{t}{\textnormal{threshold}_1}{\textnormal{threshold}_2}$: an algorithm to test whether $t$ is among the ``counterpart'' of $u$} \label{alg:tester}
\KwIn{Vertex set $\Vh$; a splitting oracle $\cO$; baseline vertex $u$; test vertex $v$; $\text{threshold}_1\in (0,\np)$, $\text{threshold}_2\in (0,\np)$}
\KwOut{Whether $v$ is a ``counterpart'' of $u$}
Initialize counters $c_1\gets 0$, $c_2 \gets 0$\;
\For{Every vertex $t\in \Vh$}{
If $v$ splits away from $(u,t)$, increase $c_1$ by 1\;
If $t$ splits away from $(u,v)$, increase $c_2$ by 1\;
}
\If{$c_1\leq \textnormal{threshold}_1$ and $c_2 \leq \textnormal{threshold}_2$}{
Return ``$v$ is a counterpart of $u$''.
}
\end{algorithm}

% It is not immediate clear what intuitively the name ``counterpart'' stands for. To help the readers understand, consider the thought process that we write down the split on the root as the smaller and the larger subtrees; then, we recursively further write down the split induced by the node of the larger side (again to small and large subtrees). If we pick any vertex $v$ from the ``smaller subtree'' at some node $x$, then \Cref{alg:tester} will return the ``bigger subtree'' on $x$ with appropriate parameters. A more formal description of this thought process is in the small-tree splitting order defined in \Cref{def:small-tree-split}.
\Cref{alg:tester} is very similar to \Cref{alg:tester-strong}, and the difference is that instead of testing on $\Vp$ set, we query on the $\Vh$ set instead. This is more than a simple notation change: it allows us to separate the vertices ``to be tested'' (e.g., vertices in $\Vp$) vs. the set we ``used in the tests'' (e.g., vertices in $\Vh$).

Next, we introduce the tester that given vertices $u\in \Vsmall_{\ell_{1}}$ and $t \in \Vsmall_{\ell_{2}}$, returns whether $\ell_2 < \ell_1$, i.e., whether $t$ is ``split earlier'' in the small-tree split order of $u$. 

\FloatBarrier
\begin{algorithm}
\caption{$\testalgprev{u}{t}{\textnormal{threshold}}$: an algorithm to test whether $t$ is among the ``predecessor'' of $u$} \label{alg:tester-prev}
\KwIn{Vertex set $\Vh$; a splitting oracle $\cO$; baseline vertex $u$; test vertex $t$; $\text{threshold}\in (0,\np)$}
\KwOut{Whether $t$ is a ``predecessor'' of $u$}
Initialize counters $c\gets 0$ \;
\For{Every vertex $s\in \Vh$}{
If $t$ splits away from $(u,s)$, increase $c$ by 1\;
}
\If{$c\geq \textnormal{threshold}$}{
Return ``$t$ is a predecessor of $u$''.
}
\end{algorithm}

Note that unlike \Cref{alg:tester}, the vertex $t$ passes the test in \Cref{alg:tester-prev} if the number of ``split away'' is lower-bounded. With the $\testalgprev{u}{t}{\textnormal{threshold}}$ algorithm, we can now define the following algorithm that tests whether a root split has happened in the previous iteration.

\FloatBarrier
\begin{algorithm}
\caption{$\testorphan$: an algorithm to obtain any vertex that is split earlier than the orphaned vertex set in the small-tree split order} \label{alg:orphan-test}
\KwIn{Vertex set $\Vp$ of size $\np$; the horizon set $\Vh$ of size $\nh$; a splitting oracle $\cO$}
\KwOut{Vertex $X^*$ that is either empty or contain ``predecessor'' of orphaned sets}
% \nonl\algcomment{Finding a set of good vertices $\ustar$}\\
Sample a set $U'$ of $100 \log{n}$ vertices from $\Vp$ using \emph{fresh randomness}\;
\For{$u' \in U'$}{
\For{$v \in \Vh$}{
\If{$\nh\leq 3\np$}{
$\textnormal{threshold-pred} \gets 3\np/2$\;
}
\Else{
$\textnormal{threshold-pred} \gets 2\nh/3$\;
}
Add $x$ to $X$ if $\testalgprev{u}{v}{\textnormal{threshold-pred}}$ (\Cref{alg:tester-prev}) reports ``$v$ is a predecessor of $u$''\label{line:pred-test}\;
}
Record the size $\card{X}$ for this choice of $u'$\;
}
Return $X^*$ as the largest size of $X$\;
\end{algorithm}

We now continue to the presentation of our tree-split algorithm. The full algorithm is as \Cref{alg:split}.


\FloatBarrier
\begin{algorithm}
\caption{$\splitalg{\Vp, \Vh}{\cO}$: an algorithm that splits $\Vp$ to $T$ and $\Vp\setminus T$} \label{alg:split}
\KwIn{Vertex set $\Vp$ of size $\np$; the horizon set $\Vh$ of size $\nh$; a splitting oracle $\cO$}
\KwOut{Vertex sets $T$, $\Vp\setminus T$; new horizon set $\Vh$}
% \nonl\algcomment{Finding a set of good vertices $\ustar$}\\
\label{line:split-sample}Sample a set $U$ of $500 \log{n}$ vertices from $\Vp$\;
\For{$u \in U$}{
Initialize $T \gets \emptyset$\;
\For{$v \in \Vh$}{ \label{line:test-good-T} 
Run $\testalg{u}{v}{3\nh/5}{\nh/6}$\; 
Add $v$ to $T$ if $v$ is a ``counterpart'' of $u$\;
}
Record the size $\card{T}$ for this choice of $u$\;
}
Pick $(T^*, \Vp\setminus T^*)$ such that $T^*\gets T$ is with the largest size\; 
\If{$T^* \cap \Vp = \emptyset$}{
\nonl\algcomment{Test whether a root split happened in the last iteration}\;
$X^* \gets \testorphan$  (using \Cref{alg:orphan-test})\;
\If{$X^* \neq \emptyset$}{\label{line:large-orphan}
\nonl\algcomment{The case of non-root split}\;
Pick an arbitrary $\ustar \in X^*$\;
Initialize $T^* \gets \emptyset$\;
\For{$v \in \Vh$}{
Run $\testalg{\ustar}{v}{3\nh/5}{\nh/6}$\; 
Add $v$ to $T^*$ if $v$ is a ``counterpart'' of $\ustar$\;
}
Output with the same rules of the $T^*\cap \Vp \neq \emptyset$ case\;
}
\Else{ 
\nonl\algcomment{Case for root split}\;
Let $\Vh\gets \Vp$, run and output with $\splitalg{\Vp, \Vp}{\cO}$ \label{line:recursion-call}\;
Enforce a \emph{single level} of recursion call (return ``FAIL'' if $\Vp=\Vh$ and the algorithm enters the above line again with $\Vp=\Vh$)\;
}
}
\Else{ \label{line:output-lines}
\nonl\algcomment{Keep the current horizon}\;
Output $(T^*\cap \Vp, \Vp\setminus T^*)$ as the partition and keep the same $\Vh$\; 
Output $\ustar$ as the vertex $u \in U$ corresponding to the output $T^*$\; 
}
\end{algorithm}
\FloatBarrier

\noindent
Note that in Line~\ref{line:split-sample}, we sample $500 \log{n}$ as opposed to $500 \log{\np}$ vertices (this is on purpose as opposed to being a typo). % Also, by setting $\text{threshold}_2 = \np$ in Line~\ref{line:test-good-u}, we essentially only count how many ``other vertices'' splits away from $(u,v)$. 
The formal guarantee of the tree split algorithm is as follows.


\begin{lemma}
\label{lem:tree-split}
Suppose $\Vp$ is a composable set with size $\np$ that satisfies the \emph{weak contraction property} as prescribed in \Cref{def:weakly-consistent-tree}, and suppose $\np \geq 50000 \log{n}$. Furthermore, let $\Vh$ be a single composable set (e.g., $\Vh$ induces a maximal tree in $\cTstar$) of $\nh$ vertices, and suppose 
\[\Vp =\cup_{i=1}^{\ell} \Vsmall_{i}\] 
for some $\ell$ in the small-tree split order of $\Vh$. Then, given a splitting oracle $\cO$ with correct probability at least $9/10$, \Cref{alg:split} with high probability outputs composable sets $T^{*}\cap \Vp$ and $\Vp\setminus T^{*}$ and a vertex $\ustar$ such that 
\begin{enumerate}[leftmargin=12pt]
\item\label{eff-split:T} $T^*$ induces a \emph{single} maximal subtree in $\cTstar(\Vp)$. 
\item\label{eff-split:out-degree} $\Vp\setminus T^{*}$ satisfies the \emph{weak contraction property} as prescribed in \Cref{def:weakly-consistent-tree}, and in particular, the subtrees induced by $\Vp\setminus T^{*}$ have
\begin{enumerate}
\item one edge connected to the node $\pa{\lcatreeset{\Vp}{\cTstar}}$ (if it exist).
\item one edge connected to the node that induces $T^{*}$ in $\cTstar$.
\end{enumerate}
\item\label{eff-split:easy-to-merge} The lowest common ancestor between the nodes in $T$ is an (immediate) child node of the lowest common ancestor between $T\cup \{\ustar\}$ in $\cTstar(\Vp)$, i.e.,
\[\lcatreeset{T\cup \{\ustar\}}{\cTstar(\Vp)} = \pa{\lcatreeset{T}{\cTstar(\Vp)}}. \]
\item \label{eff-split:size-bounds} Size properties: \emph{at least one} of the following guarantees hold.
\begin{enumerate}
\item \label{case:large-orphan} The new set $\Vp\setminus T^*$ has at least $\frac{99}{100}$ fraction of vertices that are orphaned vertices, i.e., the new $\Vorphan$ set accounts of at least $\frac{99}{100}$ fraction of vertices in $\Vp\setminus T^*$;
\item \label{case:large-T-star} The size of $T^*$ satisfies the following properties:
\begin{enumerate}
    \item\label{eff-split:size-lb} The size of $T^{*}\cap \Vp$ is at least $\frac{1}{200}\cdot \np$, i.e., 
    \[\card{T^{*}\cap \Vp} \geq \frac{1}{200}\cdot \np.\]
    \item\label{eff-split:size-ub} If $\Vh=\Vp$, the size of $T^{*}\cap \Vp$ is at most $(1-\frac{1}{10000 \log^2{\np}})\cdot \np$, i.e.,
    \[\card{T^{*}\cap \Vp} \leq (1-\frac{1}{10000 \log^2{\np}})\cdot \np.\]
\end{enumerate}
\end{enumerate}
% \item The lowest common ancestor of $T$ in $\cTstar(\Vp)$ on a \emph{lower level} than the lowest common ancestor of $\Vp\setminus T$ in $\cTstar(\Vp)$, i.e., 
% \[\distr{\cTstar(\Vp)}{\lcatreeset{\cTstar(\Vp)}{T}}\leq \distr{\cTstar(\Vp)}{\lcatreeset{\cTstar(\Vp)}{\Vp \setminus T}}.\]
\end{enumerate}
Furthermore, case \cref{case:large-T-star} always happens if $\Vh = \Vp$, and the algorithm runs in time $O(\nh^2 \cdot \log n)$.
\end{lemma}

We now proceed to the analysis to prove \Cref{lem:tree-split}.

