\begin{lemma}[Cf. \Cref{lem:counterpart-test-strong}]
\label{lem:counterpart-test}
For any composable $\Vh$ such that $\card{\Vh} \geq 50000 \log{n}$, let $\ell^*$ be the maximal level that $\Vsmall_{\ellstar}$ contains a vertex in $\Vbefore{\nh/5}$. With high probability, Line~\ref{line:test-good-T} in \Cref{alg:split} satisfies the following properties.
\begin{enumerate}[label=\alph*).]
\item \label{line:split-balance-later} For any vertex $u\in \cup_{i=\ellstar+1}^{\infty} \Vsmall_{i}$, there are
\begin{itemize}
\item No vertex $v \in \cup_{i=\ellstar+1}^{\infty} \Vsmall_{i}$ can be added to $T$ by Line~\ref{line:test-good-T} of \Cref{alg:split}.
\item No vertex $v \in \cup_{i=1}^{\ellstar-1} \Vsmall_{i}$ can be added to $T$ by Line~\ref{line:test-good-T} of \Cref{alg:split}.
\end{itemize}
\item \label{line:split-balance-middle} For every level $\ell\leq \ellstar$ and vertices $u\in \Vsmall_{\ell}$, with high probability, there are 
\begin{itemize}
\item No vertex $v\in \Vsmall_{\ell}$ can be added to $T$ by Line~\ref{line:test-good-T} of \Cref{alg:split}.
\item No vertex $v\in \Vsmall_{k}$ for $k<\ell$ can be added to $T$ by Line~\ref{line:test-good-T} of \Cref{alg:split}.
\end{itemize}
\item \label{line:split-balance-earlier} There exists a $\tilde{\ell}$ such that $\card{\cup_{i=1}^{\tilde{\ell}} \Vsmall_{i}}\geq \frac{\nh}{25}$, and for any $\ell\leq \tilde{\ell}$ and any vertex $u\in \Vsmall_{\ell}$, with high probability, all vertices $v\in \Vsmall_{k}$ for $k>\ell$ are added to $T$ by Line~\ref{line:test-good-T} of \Cref{alg:split}.
\end{enumerate}
\end{lemma}
\begin{proof}
% ===================
Let $\ellstar$ be the maximal level that the $\Vsmall_{\ellstar}$ contains a vertex in $\Vbefore{\nh/5}$, and suppose the split on this level results in $(S^{\ellstar}_{l}, S^{\ellstar}_{r})$. We again assume w.log. that $\card{S^{\ellstar}_{l}}\leq \card{S^{\ellstar}_{r}}$, which means $S^{\ellstar}_{l}$ becomes $\Vsmall_{\ellstar}$. The bounds in \Cref{obs:split-structure} still hold with parameter $\nh$, i.e., $\frac{2\nh}{5} < \card{\cup_{i=\ellstar+1}^{\infty} \Vsmall_{i}} \leq \frac{4\nh}{5}$.
We now proceed to the proofs of \Cref{line:split-balance-later}, \Cref{line:split-balance-middle}, and \Cref{line:split-balance-earlier}, respectively. 

\paragraph{Proof of \Cref{line:split-balance-later}} Fix any vertex $u\in \cup_{i=\ellstar+1}^{\infty} \Vsmall_{i}$. For the first statement, note that for every $v\in \cup_{i=\ellstar+1}^{\infty} \Vsmall_{i}$, all the vertices in $\cup_{i=1}^{\ellstar} \Vsmall_{i}$ are \emph{splitting away} from $(u,v)$. Define $X_{u,v,t}$ as the indicator random variable answered by $\cO$ as ``$t$ splits away from $(u,v)$'', and define $X_{u,v}=\sum_{t\in\Vp}X_{u,v,t}$ as the total number of vertex split away from $(u,v)$. By \Cref{obs:split-structure}, the expected number of split away reported by oracle $\cO$ is at least
\begin{align*}
\expect{X_{u,v}}\geq \frac{9}{10}\cdot \frac{\nh}{5} = \frac{9}{50}\cdot \nh.
\end{align*}
Note also that $X_{u,v}$ is a summation of $0/1$ independent random variables. As such, we can apply the Chernoff bound to get that
\begin{align*}
\Pr\paren{X_{u,v}\leq \frac{\nh}{6}} & = \Pr\paren{X_{u,v}\leq \frac{25}{27}\cdot \expect{X_{u,v}}} \\
& \leq \exp\paren{-\frac{(2/27)^2}{3}\cdot \expect{X_{u,v}}}\\
& \leq \frac{1}{10}\cdot \frac{1}{n^3} \tag{$\frac{9}{50}\cdot \nh \geq 9000 \log{n}$ using the lower bound on the size of $\Vh$}. 
\end{align*}
For the second statement, note that for any $t\in \cup_{i=\ellstar}^{\infty} \Vsmall_{i}$, $v$ actually splits away from $(u,t)$. As such, there is at least $\frac{4\nh}{5}$ vertices such that ``$v$ splits away from $(u,t)$'' -- this is because the LCA between $(u,v)$ has to be higher than the LCA between $(u,t)$ for any $t\in \cup_{i=\ellstar}^{\infty} \Vsmall_{i}$. As such, define $Y_{u,v}$ as the number of total answers of ``$v$ splits away from $(u,t)$'' by $\cO$, we again have
\begin{align*}
\expect{Y_{u,v}} \geq \frac{9}{10}\cdot \frac{4\nh}{5}=\frac{18}{25}\cdot \nh.
\end{align*}
As such, we again have
\begin{align*}
\Pr\paren{Y_{u,v}\leq \frac{3\nh}{5}} &= Pr\paren{Y_{u,v}\leq \frac{15}{18}\cdot \expect{X_{u,v}}}\\
&\leq \frac{1}{10}\cdot \frac{1}{n^3} \tag{$\frac{9}{50}\cdot \nh \geq 9000 \log{n}$ using the lower bound on the size of $\Vh$}.
\end{align*}
By a union bound over at most $n$ vertices, no vertex $v\in \cup_{i=1}^{\ellstar-1} \Vsmall_{i}$ or $v\in \cup_{i=\ellstar+1}^{\infty} \Vsmall_{i}$ can pass the test and be recorded as a `counterpart'.

\paragraph{Proof of \Cref{line:split-balance-middle}}
We now show that vertices $v \in \cup_{i=1}^{\ell} {\Vsmall_{i}}$ cannot pass the ``counterpart'' test. For vertices in $v \in \Vsmall_{\ell}$, we claim that there are too many vertices $t$ that split away from $(u,v)$. To see this, let us define $A_{u,v}$ as the total number of answers of ``$t$ splits away from $(u,v)$'' answered by $\cO$. Note that for any vertex $t \in \cup_{i=\ellstar+1}^{\infty} \Vsmall_{i}$, the answer is always ``yes'' since $\ell^{*}\geq \tilde{\ell}\geq \ell$. Therefore, we can lower bound the expectation of $A_{u,v}$ with $\expect{A_{u,v}}\geq \frac{2}{5}\nh\cdot \frac{9}{10} \geq \frac{9}{25}\cdot \nh$. Therefore, we can apply Chernoff bound to get
\begin{align*}
\Pr\paren{A_{u,v}\leq \frac{\nh}{6}} & \leq \exp\paren{-\frac{(1/2)^2}{3}\cdot \expect{A_{u,v}}}\leq \frac{1}{10}\cdot \frac{1}{n^3}.
\end{align*}
We now turn to the vertices that are in $\cup_{i=1}^{\ell-1} {\Vsmall_{i}}$. Note that by definition, there is $\card{\cup_{i=\ell}^{\infty} {\Vsmall_{i}}} \geq \card{\cup_{i=\ellstar}^{\infty} {\Vsmall_{i}}} \geq \frac{4}{5}\cdot \nh$. For any $t \in \cup_{i=\ellstar}^{\infty} {\Vsmall_{i}}$, $v$ splits away from $(u,t)$. As such, define $B_{u,v}$ as the number of answers by $\cO$ with ``$v$ splits away from $(u,t)$'', there is $\expect{B_{u,v}}\geq \frac{18}{25}\cdot \nh$. Once again, by applying Chernoff bound, there is % \chen{constants are not correct -- come back and fix them later}
\begin{align*}
\Pr\paren{B_{u,v}\leq \frac{3\nh}{5}} & \leq \exp\paren{-\frac{(1/5)^2}{3}\cdot \expect{B_{u,v}}}\leq \frac{1}{10}\cdot \frac{1}{n^3}.
\end{align*}
Applying a union bound over the cases and all $\nh\leq n$ vertices gives us the desired statements.

\paragraph{Proof of \Cref{line:split-balance-earlier}} % We first prove the first bullet, which requires a cases analysis. 
We fix $\tilde{\ell}$ as the minimum level such that the union of $\cup_{i=1}^{\tilde{\ell}}\Vsmall_{i}$ has at least $\nh/25$ vertices. Let $\ell\leq \tilde{\ell}$, and for any vertex $v$ in $\Vsmall_{k}$ for $k>\ell$, define the following two random variables: $X_{u,v}$ as the number of answers that ``$t$ splits away from $(u,v)$'', and $Y_{u,v}$ as the number of answers that ``$v$ splits away from $(u,t)$''. We shall show that both terms are not large and $v$ can always pass the test. (Note that $X$ and $Y$ are overloaded and are \emph{not} related to their meaning in the proof of Line~\ref{line:split-balance-later}.)

% By definition, there must be $\tilde{\ell}\leq \ellstar$ since the former requires a smaller number of induced vertices. We now conduct a cases analysis as follows.

% \begin{itemize}[leftmargin=20pt]
% \item \textbf{Case A). $\tilde{\ell}=\ellstar$}
% \end{itemize}

Note that by definition, we have $\card{\cup_{i=1}^{\tilde{\ell}-1} \Vsmall_{i}}<\frac{\nh}{25}$. Since $\ell\leq \tilde{\ell}$, for any vertex $u \in \cup_{i=1}^{\ell}\Vsmall_{i}$, only vertices $t\in \cup_{i=1}^{\ell-1} \Vsmall_{i}$ are \emph{actually} splitting away from $(u,v)$ for $v \in \cup_{i=\ell}^{\infty} \Vsmall_{i}$. As such, we have 
$\expect{X_{u,v}}\leq (\frac{1}{10}+\frac{1}{25})\cdot \nh = \frac{7}{50}\cdot \nh$ by the correct probability of $\cO$.
For $X_{u,v}$, we also note that if the answer is at most $3000 \log{n}$, then the vertex trivially passes the test. Therefore, we assume $X_{u,v}\geq \expect{X_{u,v}}\geq 3000 \log{n}$, and we again apply Chernoff for the tail bound:
\begin{align*}
\Pr\paren{X_{u,v}\geq \frac{\nh}{6}} & \leq \exp\paren{-\frac{(4/21)^2}{3}\cdot \expect{Y_{u,v}}}\\
& \leq \frac{1}{10}\cdot \frac{1}{n^3} \tag{using the condition $\expect{Y_{u,v}}\geq 3000 \log{n}$}. 
\end{align*}
For $Y_{u,v}$, note that only $t\in \Vsmall_{\tilde{\ell}}$ can report ``$v$ splits away from $(u,t)$'' since the LCA between $(u,t)$ is at least $\tilde{\ell}$ for any other $v$. Therefore, the number of signals we can possibly get is $\nh/2$ plus the noise induced by the oracle $\cO$. As such, we again have 
$\expect{Y_{u,v}}\leq 11\nh/20$.
Also, note that if $Y_{u,v}$ is less than $30000 \log{n}$, the vertex $v$ would always pass the test, which allows us to assume w.log. that $\expect{Y_{u,v}}\geq 30000 \log{n}$. Therefore, we can again apply Chernoff bound to show
\begin{align*}
\Pr\paren{Y_{u,v}\geq \frac{3\nh}{5}} & \leq \exp\paren{-\frac{(1/11)^2}{3}\cdot \expect{Y_{u,v}}}\\
& \leq \frac{1}{10}\cdot \frac{1}{n^3} \tag{using the condition $\expect{Z_{u,v}}\geq 30000 \log{n}$}. 
\end{align*}
\myqed{\Cref{lem:counterpart-test}}
\end{proof}

A direct corollary of \Cref{lem:counterpart-test} is that the set $T$ induced by any $u\in \cup_{i=1}^{\tilde{\ell}} \Vsmall_{i}$ is larger than the $T$ induced by $u\in \cup_{i=\tilde{\ell}+1}^{\infty} \Vsmall_{i}$, and the ``higher level'' vertices in $\cup_{i=1}^{\tilde{\ell}} \Vsmall_{i}$ induces larger sets. More formally, we can summarize this observation as follows.
\begin{lemma}
\label{lem:counterpart-set-larger}
Conditioning on the high-probability event of \Cref{lem:counterpart-test}, the following statements are true:
\begin{itemize}
\item Let $T_1$ be the vertex set induced by $u_1 \in \cup_{i=1}^{\tilde{\ell}} \Vsmall_{i}$ from Line~\ref{line:test-good-T} in \Cref{alg:split}, and let $T_2$ be the vertex set induced by $u_2 \in \cup_{i=\tilde{\ell}+1}^{\infty} \Vsmall_{i}$ from Line~\ref{line:test-good-T} in \Cref{alg:split}. We have $\card{T_1}\geq \card{T_2}$.
\item Let $\ell_{1}\leq \ell_{2}\leq \tilde{\ell}$. Let $T_1$ be the vertex set induced by $u_1 \in \Vsmall_{\ell_{1}}$ from Line~\ref{line:test-good-T} in \Cref{alg:split}, and let $T_2$ be the vertex set induced by $u_2  \in \Vsmall_{\ell_{2}}$ from Line~\ref{line:test-good-T} in \Cref{alg:split}. We have $\card{T_1}\geq \card{T_2}$.
\end{itemize}
\end{lemma}
\begin{proof}
We prove the second bullet first since the conclusion can be used to prove the first bullet. Note that conditioning on the high-probability event of \Cref{lem:counterpart-test}, if $\ell_{1}\leq \ell_{2}$, we have $T_{2}\subseteq T_{1}$ by \Cref{line:split-balance-earlier}. Therefore, we have $\card{T_1}\geq \card{T_2}$.

For the first bullet, note that conditioning on the high-probability event of \Cref{lem:counterpart-test}, the set $T_{2}$ can either be $\Vsmall_{\tilde{\ell}}$ (by \Cref{line:split-balance-later}) or $\cup_{i=\tilde{\ell}+1}^{\infty} \Vsmall_{i}$ (by \Cref{line:split-balance-middle}). In either case, the size of such a set is at most $\cup_{i=\tilde{\ell}+1}^{\infty} \Vsmall_{i}$, which is the set $T_1$ generated by $u\in \Vsmall_{\tilde{\ell}}$. Furthermore, by the result in the second bullet, if $u\in \Vsmall_{i}$ for some $i\leq \tilde{\ell}$, the induced set $T_1$ can only be larger. This proves the first bullet. %\myqed{\Cref{lem:counterpart-set-larger}}
\end{proof}


% \chen{=========================================================}
We now show that conditioning on \Cref{lem:counterpart-test} (resp. \Cref{lem:counterpart-set-larger}), if the size of the orphaned set is relatively small, we will not need the subroutine in Line~\ref{line:large-orphan}, and all the guarantees in \Cref{lem:tree-split} will be satisfied.
\begin{lemma}
\label{lem:small-orphan-case}
Let $\Vp$ and $\Vh$ be as prescribed by \Cref{lem:tree-split}, and suppose the size of the orphaned set is at most $\frac{99}{100}\cdot \np$, i.e., $\card{\Vorphan}\leq \frac{99}{100}\cdot \np$. Then, with high probability, we have $T^* \cap \Vp \neq \emptyset$, and the resulting $T^*$ and $\Vp\setminus T^*$ satisfy the properties of \Cref{lem:tree-split}.
\end{lemma}
\begin{proof}
We discuss the cases based on whether $\Vh=\Vp$ and whether there exists a $\Vsmall_{\ell}$ such that $\card{\Vsmall_{\ell}}\geq \frac{99}{100}\cdot \np$.
\begin{enumerate}
\item \textbf{If $\Vh=\Vp$.} In this case, we show that with high probability, the guarantees in \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge} of \Cref{lem:tree-split} always hold, and the \cref{case:large-T-star} case of \Cref{lem:tree-split} is going to happen. To see this, note that with high probability, we will sample a vertex that is among the first $\frac{\np}{25}$ vertices in the small-tree split order: the probability for us to not sample a vertex from $\Vbefore{\frac{\np}{25}}$ is at most
\begin{align*}
(\frac{24}{25})^{500\log{n}}\leq \frac{1}{10}\cdot \frac{1}{n^2}.
\end{align*}
As such, we can condition on a vertex $v'$ among $\Vbefore{\frac{\np}{25}}$ is sampled. By \Cref{lem:counterpart-test} and \Cref{lem:counterpart-set-larger}, the counterpart set induced by $v' \in \Vbefore{\frac{\np}{25}}$ is among $\cup_{i=1}^{\tilde{\ell}} \Vsmall_{i}$, which necessarily induces a larger set than any other $u\in \cup_{i=\tilde{\ell}+1}^{\infty} \Vsmall_{i}$. Therefore, the induced set $T^*$ must be from the vertex $v'$.

We now use this to verify the desired properties. The proofs of \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge} are straightforward as follows.
\begin{itemize}
\item For \Cref{eff-split:T}, note that by \Cref{lem:counterpart-test}, the induced set $T^*$ is always $\cup_{i=\ell}^{\infty} \Vsmall_{i}$, which forms a maximal subtree in $\cTstar(\Vh)$. Similarly, $T\cap \Vp$ induces a maximal subtree in $\cTstar(\Vp)$.
\item For \Cref{eff-split:out-degree}, note that as long as $T^*$ includes the orphaned set $\Vorphan$, there will be only one edge connecting to the node induces $T^*$ in $\cTstar$. In this case, there is no orphaned set, and \Cref{eff-split:out-degree} holds trivially.
\item \Cref{eff-split:easy-to-merge} directly follows from \Cref{lem:counterpart-test} since $T^*$ is induced by $u^*$.
\end{itemize}

For the size upper and lower bounds (\Cref{eff-split:size-bounds}), we verify that the guarantees for case \ref{case:large-T-star} always holds. Note that conditioning on the high-probability event of \Cref{lem:counterpart-test}, the size is at least $\frac{2\nh}{5}=\frac{2\np}{5}$ (\Cref{obs:split-structure}). Therefore, the set $T^*\cap \Vp=T^*$ has size at least $\frac{2\np}{5}\geq \frac{1}{200}\cdot \np$, which proves the lower bound (\Cref{eff-split:size-lb}). For the upper bound (\Cref{eff-split:size-ub}), we note that for the size of $T^*\cap \Vp$ to be more than $(1-\frac{1}{10000 \log^2{\np}})\cdot \np$, a \emph{necessary} condition is to sample a vertex $u \in \Vbefore{\np/10000\log^2{\np}}$. Since we sample $500\log{n}$ vertices, define $X$ as the random variable for the number of vertices sampled from $\Vbefore{\np/10000\log^2{\np}}$, we have
\begin{align*}
\expect{X}\leq \frac{1}{20\log n}.
\end{align*}
Since $X$ is a summation of independent random variables supported on $[0,1]$, we can apply Chernoff bound to show that
\begin{align*}
\Pr\paren{X\geq 1} &= \Pr\paren{X\geq 50\log{n}\cdot \expect{X}}\\
& \leq \exp\paren{-\frac{2500\log^2{n}\cdot \frac{1}{20\log{n}}}{2+20\log{n}}}\\
&\leq \frac{1}{10}\cdot \frac{1}{n^2}.
\end{align*}
Therefore, we can apply a union bound to show that with high probability, the size of $T^*\cap \Vp$ will \emph{not} be larger than $(1-\frac{1}{10000 \log^2{\np}})\cdot \np$, as desired.
% \chen{============================}

\item \textbf{If $\Vh\neq \Vp$.} We need to handle this case with more care. We first show that at least one vertex that is in $\Vp \setminus \Vorphan$ can be sampled with high probability. To see this, note that by the size bound on $\card{\Vorphan}$, the probability for a vertex in $\Vp\setminus \Vorphan$ to \emph{not} be sampled is at most $99/100$. Therefore, the probability for no vertices in $\Vp\setminus \Vorphan$ to be sampled is at most
\begin{align*}
(99/100)^{500 \log{n}}\leq \frac{1}{10}\cdot \frac{1}{n^2}.
\end{align*}
% \chen{fix the constant later: maybe using $200\log{n}$ instead here to boost probability.}
We condition on the high-probability event that at least one vertex from $\Vp \setminus \Vorphan$ is sampled for the rest of the proof. We now discuss two sub-cases.
    \begin{enumerate}[label=\alph*).]
    \item \textbf{If there exists a $\Vsmall_{\ell}$ such that $\card{\Vsmall_{\ell}} \geq \frac{99}{100}\cdot \np$ and no vertex from $\cup_{i=1}^{\ell-1} \Vsmall_{i}$ is sampled.} In this case, we show that with high probability, \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge} of \Cref{lem:tree-split} always hold, and \cref{case:large-orphan} in \Cref{lem:tree-split} is going to happen. Note that in this case, there exist vertices of $\Vsmall_{\ell}$ that are among $\Vbefore{\np/100}$, and it is of the size at least $\np/100$. As such, the probability for us to sample at least one vertex from $\Vsmall_{\ell}$ is at least
    \begin{align*}
    1-(\frac{1}{100})^{500\log{n}} \geq 1-\frac{1}{10}\cdot \frac{1}{n^5}. 
    \end{align*}
    Let $v \in \Vsmall_{\ell}$ be the sampled vertex. Note that since $\Vh\neq \Vp$, the vertex we sample from $\Vsmall_{\ell}$ is among the vertices of $\cup_{i=1}^{\tilde{\ell}}\Vsmall_{i}$ in \Cref{lem:counterpart-test}. Therefore, by the same argument of the $\Vh= \Vp$ case, if we pick $T^*$ with the largest size, the entire set of $\cup_{i=\ell+1}^{\infty} \Vsmall_{i}$ is going to be included in $T^*$. Therefore, the properties of \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge} follow from the same argument of the $\Vh=\Vp$ case. 

    Furthermore, by the condition that no vertex from $\cup_{i=1}^{\ell-1} \Vsmall_{i}$ is sampled, we cannot have larger such $T^*$ sets (see~\Cref{lem:counterpart-set-larger}). As such, the set we will pick is necessarily the set $T$ corresponds to $v \in \Vsmall_{\ell}$, and $\Vsmall_{\ell}$ becomes the new $\Vorphan$ set of the next iteration.

    Finally, note that we have $\card{\Vsmall_{\ell}} \geq \frac{99}{100}\cdot \np$. And after we remove $T^*$ from $\Vp$, we have $(\Vp \gets \Vp\setminus T^*)$, which means $(\np \gets \np - C)$ for some $C>0$. As such, for the next iteration, we must have $\card{\Vorphan}\geq \frac{99}{100}\cdot \np$. 

    \item \textbf{If there exists a $\Vsmall_{\ell}$ such that $\card{\Vsmall_{\ell}} \geq \frac{99}{100}\cdot \np$ and a vertex from $\cup_{i=1}^{\ell-1} \Vsmall_{i}$ is sampled.}
    In this case, we show that \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge} of \Cref{lem:tree-split} always hold, and \cref{case:large-T-star} of \Cref{lem:tree-split} is going to happen with high probability. Note that since a vertex $v'\in \cup_{i=1}^{\ell-1} \Vsmall_{i}$ is sampled, and since $v'$ is among $\cup_{i=1}^{\tilde{\ell}}\Vsmall_{i}$ in \Cref{lem:counterpart-test}, the \emph{entire set} of $\Vsmall_{\ell}$ is going to be included in $T^*$. The properties as prescribed by \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge} follow from the argument in the $\Vp=\Vh$ case, and the size lower bound becomes 
    \[\card{T^*\cap \Vp}\geq \frac{99}{100}\cdot \np\geq \frac{1}{200}\cdot \np,\]
    as desired. Finally, note that we do not need to guarantee the size upper bound (\Cref{eff-split:size-ub}) since we will not be able to meet the $\Vh=\Vp$ condition.


    \item \textbf{If $\card{\Vsmall_{\ell}} < \frac{99}{100}\cdot \np$ for all $\ell$ among $\Vp$.} In this case, we show that \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge} of \Cref{lem:tree-split} always hold, and \cref{case:large-T-star} case of \Cref{lem:tree-split} will happen. We first show the size lower bound of \cref{case:large-T-star}: note that with high probability, we can sample one vertex that is among the first $1/200$ vertices to be split in $\Vp$ in the small-tree split order: the probability for us to \emph{not} sample any vertex among the first $n/200$ vertices in the small-tree split order is at most
    \begin{align*}
    \paren{\frac{199}{200}}^{500\log{n}}\leq \frac{1}{3}\cdot \frac{1}{n^2}.
    \end{align*}
    % \chen{fix the constant by using larger leading constant for $\log{n}$.} 
    Therefore, we condition on the event that a vertex $v'$ in $\Vbefore{\np/200}$ is sampled. Since we have the condition that $\card{\Vsmall_{\ell}} < \frac{99}{100}\cdot \np$ for all $\ell$ among $\Vp$, a vertex among $\Vbefore{\np/200}$ can induce at most $\frac{99\np}{100}+\frac{\np}{200}=\frac{199}{200}\cdot \np$ vertices. As such, let $\ell'$ be the level in the small-tree split order of $v'$, we have 
    \[\card{\cup_{i=\ell'+1}^{\infty}\Vsmall_{i}}\geq \frac{1}{200}\cdot \np.\]
    Furthermore, as in the case analysis of $\Vh\neq \Vp$, which means $v'$ is among the vertices of $\cup_{i=1}^{\tilde{\ell}}\Vsmall_{i}$ in \Cref{lem:counterpart-test}. Therefore, the properties of \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge} follow from the same argument as in the $\Vh=\Vp$ case.

    For the size bounds of $T^*\cap \Vp$, by \Cref{lem:counterpart-set-larger}, if we pick the largest $T^*$ by the subroutine of line Line~\ref{line:test-good-T}, at least the entire set of $\cup_{i=\ell'+1}^{\infty}\Vsmall_{i}$ is going to be included, which means the size of $T^*\cap \Vp$ is of size at least $\frac{1}{200}\cdot \np$. This gives us the size lower bound. 

    Finally, we again note that we do \emph{not} need to guarantee the size upper bound (\Cref{eff-split:size-ub}) since we will not be able to meet the $\Vh=\Vp$ condition.
    \end{enumerate}
\end{enumerate}
%\myqed{\Cref{lem:small-orphan-case}}
\end{proof}

We now handle the case when $\Vorphan$ becomes large. We first note that if we happen to sample a vertex $u\in \Vp \setminus \Vorphan$, we can still guarantee $T^* \cap \Vp \neq \emptyset$ and obtain the properties as prescribed by \Cref{lem:tree-split}.

\begin{lemma}
\label{lem:large-orphan-good-sample}
Let $\Vp$ and $\Vh$ be as prescribed by \Cref{lem:tree-split}, and suppose the size of the orphaned set is more than $\frac{99}{100}\cdot \np$, i.e., $\card{\Vorphan}> \frac{99}{100}\cdot \np$. Furthermore, suppose $U \cap (\Vp\setminus \Vorphan) \neq \emptyset$. Then, with high probability, we have $T^* \cap \Vp \neq \emptyset$, and the resulting $T^*$ and $\Vp\setminus T^*$ satisfy the properties of \Cref{lem:tree-split}.
\end{lemma}
\begin{proof}
In the lemma statement, we have already conditioned on a vertex sampled from $\Vp\setminus \Vorphan$. Furthermore, we can again show that the probability for us to sample a vertex among the first $\nh/25$ in the small-tree split order is at least
\[1-(\frac{24}{25})^{500\log{n}}\geq 1-\frac{1}{10}\cdot \frac{1}{n^2}.\]
The events of $U \cap (\Vp\setminus \Vorphan) \neq \emptyset$ and $U\cap \Vbefore{\nh/25} \neq \emptyset$ are \emph{not} independent. Nevertheless, we can still apply a \emph{union bound} and argue that both events happen with high probability. 

Conditioning on the high-probability events as above, we can argue by \Cref{lem:counterpart-test} and \Cref{lem:counterpart-set-larger} that the entire set of $\Vorphan$ is going to be included by the subroutine as defined in line~Line~\ref{line:test-good-T} of \Cref{alg:split}, which gives us the size lower bound. We do \emph{not} need to guarantee the size upper bound since we cannot meet the condition of $\Vh=\Vp$.

Finally, for properties of \Cref{eff-split:T}, \Cref{eff-split:out-degree}, and \Cref{eff-split:easy-to-merge}, we can repeat our proofs in \Cref{lem:small-orphan-case}. We provide the analysis again for the purpose of self-contained proof.
\begin{itemize}
\item For \Cref{eff-split:T}, note that by \Cref{lem:counterpart-test}, the induced set $T^*$ is always $\cup_{i=\ell}^{\infty} \Vsmall_{i}$. Therefore, $T\cap \Vp$ induces a maximal subtree in $\cTstar(\Vp)$.
\item For \Cref{eff-split:out-degree}, note that as long as $T^*$ includes the orphaned set $\Vorphan$, there will be only one edge connecting to the node induces $T^*$ in $\cTstar$. This is exactly what we proved in the lemma.
\item \Cref{eff-split:easy-to-merge} directly follows from \Cref{lem:counterpart-test} since $T^*$ is induced by $u^*$.
\end{itemize}
This concludes the proof of \Cref{lem:large-orphan-good-sample}. %\myqed{\Cref{lem:large-orphan-good-sample}}
\end{proof}

By \Cref{lem:large-orphan-good-sample}, the only case of concern now is when $T^* \cap \Vp = \emptyset$, i.e., $\card{\Vorphan}> \frac{99}{100}\cdot \np$ and $U$ does \emph{not} contain samples from $\Vp \setminus \Vorphan$. We now show that our procedure in Line~\ref{line:large-orphan} can effectively distinguish between the cases of $\Vp \setminus \Vorphan=\emptyset$ (root cut) and $\Vp \setminus \Vorphan$ being small.

\begin{lemma}
\label{lem:large-orphan-bad-sample}
Let $\Vp$ and $\Vh$ be as prescribed by \Cref{lem:tree-split}, and suppose the size of the orphaned set is more than $\frac{99}{100}\cdot \np$, i.e., $\card{\Vorphan}> \frac{99}{100}\cdot \np$. Furthermore, suppose $T^* \cap \Vp = \emptyset$ in Line~\ref{line:large-orphan} of \Cref{alg:split}. Then, the following statements are true.
\begin{enumerate}[label=(\roman*).]
\item\label{item:large-orphan-non-root} If $\Vp \setminus \Vorphan \neq \emptyset$, with high probability, we have $X^*\neq \emptyset$ and $X^* \subseteq (\Vp \setminus \Vorphan)$, i.e., $X^*$ only contains vertices in $\Vp$ but not in $\Vorphan$.
\item\label{item:large-orphan-root} If $\Vp \setminus \Vorphan = \emptyset$, with high probability, we have $X^* = \emptyset$.
\end{enumerate}
\end{lemma}
\begin{proof}
Consider the small-tree splitting order of $\Vh$, and let $u\in \Vsmall_{\ell}$ for some $\ell\leq \tilde{\ell}$, where $\Vsmall_{\tilde{\ell}}=\Vorphan$. We prove that with high probability, $i).$ no vertices $v \in \Vp \cap (\cup_{i=\ell}^{\infty} \Vsmall_{\ell})$ can be added to $X$ by Line~\ref{line:pred-test}; and $ii).$ all vertices in $v\in \Vp \cap (\cup_{i=1}^{\ell-1} \Vsmall_{\ell})$ are added to $X$ by Line~\ref{line:pred-test}. (Note that this is why we name the subroutine as a ``predecessor'' test.)

We first observe that by our definition, there is $\Vorphan \subseteq \Vp \cap (\cup_{i=\ell}^{\infty} \Vsmall_{\ell})$. Too see $i)$, note that any $v\in \Vp \cap (\cup_{i=\ell}^{\infty} \Vsmall_{\ell})$ can only split away from $(u,t)$ for $t \in \Vsmall_{\ell}$: this is true since for every $t\not\in \Vsmall_{\ell}$, the lowest common ancestor between $(u,t)$ induces a subtree in $\Vh$ that contains $v$. Moreover, since $\Vsmall_{\ell}\subseteq \Vp$, we have $\card{\Vsmall_{\ell}}\leq \np$. Define $X_{v}$ as the number of answers ``$v$ splits away from $(u,t)$'' for $t\in \Vh$ from $\cO$. By our choice of the parameter \emph{threshold-pred}, we assume w.log. $X_{v}\geq \np$ since otherwise $v$ will not join $X$ anyway. If $\nh\leq 3\np$, we have $\expect{X_{v}}\leq \np+\frac{\nh}{10}=\frac{13}{10}\cdot \np$ in expectation.  Since $X_{v}$ is a summation of independent random variables supported on $\{0,1\}$, we can apply Chernoff bound to obtain that
\begin{align*}
\Pr\paren{X_{v}\geq \frac{3}{2}\cdot \np} &= \Pr\paren{X_{v}\geq \frac{15}{13}\cdot \expect{X_{v}}}\\
&\leq \exp\paren{-\frac{(2/13)^2}{3}\cdot \expect{X_{v}}}\\
&\leq \frac{1}{10}\cdot \frac{1}{n^3}. \tag{using the condition on the lower bound of $X_{v}$}
\end{align*}
On the other hand, if $\nh> 3\np$, we have $\expect{X_{v}}\leq \frac{\nh}{3}+\frac{\nh}{10}=\frac{13}{30}\cdot \nh$. We again assume w.log. that $X_{v}\geq \np$, and we can apply Chernoff bound to obtain that
\begin{align*}
\Pr\paren{X_{v}\geq \frac{2}{3}\cdot \nh} &= \Pr\paren{X_{v}\geq \frac{20}{13}\cdot \expect{X_{v}}}\\
&\leq \exp\paren{-\frac{(8/13)^2}{3}\cdot \expect{X_{v}}}\\
&\leq \frac{1}{10}\cdot \frac{1}{n^3}. \tag{using the condition on the lower bound of $X_{v}$}
\end{align*}
Therefore, we can apply a union bound and argue that with high probability, no vertices $v \in \Vp \cap (\cup_{i=\ell}^{\infty} \Vsmall_{\ell})$ can be added to $X$ by Line~\ref{line:pred-test}, as desired by $i)$.

We now proceed to show $ii).$ all vertices in $v\in \Vp \cap (\cup_{i=1}^{\ell-1} \Vsmall_{\ell})$ are added to $X$ by Line~\ref{line:pred-test}. Note that $v\in \Vp \cap (\cup_{i=1}^{\ell-1} \Vsmall_{\ell})$ implies $v\in \Vp\setminus \Vorphan$. Therefore, $v$ splits from $(u,t)$ for every $t$ in the orphaned set \emph{and} for every $t$ as the sibling of $\Vorphan$, i.e., $t \in \cup_{i=\tilde{\ell}+1}^{\infty} \Vsmall_{i}$. Define $Y_{v}$ as the number of answers ``$v$ splits away from $(u,t)$'' for $t \in \Vh$ from $\cO$. By our choice of the parameter \emph{threshold-pred}, if $\nh\leq 3\np$, since we have $\card{\Vorphan}\geq \frac{99}{100}\np$ and $\card{\cup_{i=\tilde{\ell}+1}^{\infty} \Vsmall_{i}}\geq \card{\Vorphan}$, we have $\expect{Y_{v}}\geq \frac{9}{10}\cdot \frac{199}{100}\cdot \np$ in expectation. Since $Y_{v}$ is a summation of independent random variables supported on $\{0,1\}$, we can apply Chernoff bound to obtain that
\begin{align*}
\Pr\paren{Y_{v}\leq \frac{3}{2}\cdot \np} &= \Pr\paren{Y_{v}\leq \frac{17}{15}\cdot \expect{Y_{v}}}\\
&\leq \exp\paren{-\frac{(2/15)^2}{3}\cdot \expect{Y_{v}}}\\
&\leq \frac{1}{10}\cdot \frac{1}{n^3}. \tag{using $\expect{Y_{v}}\geq \frac{17}{10}\cdot \np$}
\end{align*}
On the other hand, if $\nh> 3\np$, we have at least $\nh-\frac{1}{100}\np \geq \frac{299}{300}\nh$ vertices $t$ such that $v$ splits away from $(u,t)$. Therefore, we have $\expect{Y_{v}}\geq \frac{9}{10}\cdot \frac{299}{300}\cdot \nh\geq \frac{4}{5}\cdot \nh$ in expectation. Therefore, we can again apply Chernoff bound to obtain that
\begin{align*}
\Pr\paren{Y_{v}\leq \frac{2}{3}\cdot \nh} &= \Pr\paren{Y_{v}\geq \frac{5}{6}\cdot \expect{Y_{v}}}\\
&\leq \exp\paren{-\frac{(1/6)^2}{3}\cdot \expect{Y_{v}}}\\
&\leq \frac{1}{10}\cdot \frac{1}{n^3}. \tag{using $\expect{Y_{v}}\geq \frac{4}{5}\cdot \nh\geq \frac{4}{5}\cdot \np$}
\end{align*}
Therefore, we can apply a union bound to obtain the desired statement on $ii)$.

By our statements in $i)$ and $ii)$ as above, we can already conclude that $X^* \subseteq (\Vp \setminus \Vorphan)$. Therefore, \Cref{item:large-orphan-root} of \Cref{lem:large-orphan-bad-sample} follows straightforwardly since if $\Vp \setminus \Vorphan=\emptyset$, any of its subset can only be empty as well. For \Cref{item:large-orphan-non-root}, what remains to show is that with high probability, there is $X^* \neq \emptyset$. Note that if $u\in \Vorphan$ and $\Vp \setminus \Vorphan \neq \emptyset$, then by our statements in $i)$ and $ii)$ above, the set $X^*$ will \emph{not} be empty. Since we assume $\card{\Vorphan}\geq \frac{99}{100}\cdot \card{\Vp}$, the probability for $U'$ to \emph{not} have any vertex $u\in \Vorphan$ is at most
\begin{align*}
(\frac{1}{100})^{100\log{n}}\leq \frac{1}{10}\cdot \frac{1}{n^3},
\end{align*}
as desired. Thus, with high probability, $X^*$ is not empty, which proves \Cref{item:large-orphan-non-root} and concludes the proof of \Cref{lem:large-orphan-bad-sample}.
\end{proof}

