\section{The asymptotic behavior of the condition numbers}


In this section and the next two, the asymptotic (long-time) behavior of the condition numbers (\ref{Ktayz0}) and (\ref{KAy0}) is illustrated. In light of (\ref{magnification}), this also illustrates the asymptotic behavior of the normwise relative error $\delta(t)$. The proofs for all results presented here can be found in \cite{Maset2022}, as previously remarked.




\subsection{Notations}




We need some notations now introduced. 
\begin{itemize}
	\item$\Lambda=\{\lambda_1,\ldots,\lambda_p\}$, where $\lambda_1,\ldots,\lambda_p$ are distinct, is the set of the eigenvalues of $A$ (the spectrum of $A$). The imaginary part of $\lambda_i\in\Lambda$ is denoted by $\omega_i$.
	\item We assume to have a Jordan basis
	\begin{equation}
	v^{(i,j,k)},\ i\in\{1,\ldots,p\},\ j\in\{1,\ldots,d_i\}\text{\ and\ }k\in\{1,\ldots,m_{ij}\},  \label{JJ}
	\end{equation}
	of $\mathbb{C}^n$ constituted by $d_i$ Jordan chains
	$$
	v^{(i,j,1)},\ldots,v^{(i,j,m_{ij})},\ j\in\{1,\ldots,d_i\},
	$$
	for each eigenvalue $\lambda_i\in\Lambda$, where $d_{i}$ is the geometric multeplicity of $\lambda_i$. The lenghts $m_{ij}$, $j\in\{1,\ldots,d_i\}$, of the Jordan chains corresponding to  $\lambda_i$ are the orders of the $d_i$ Jordan mini-blocks corresponding to $\lambda_i$ in the JCF of $A$. 
	\item Let $V$ be the $n\times n$ matrix whose columns are the elements (\ref{JJ}) of the Jordan basis, ordered lexicographically by means of the indeces $(i,j,k)$. The rows of the inverse $V^{-1}$ are denoted by
	$$
	w^{(i,j,k)},\ i\in\{1,\ldots,p\},\ j\in\{1,\ldots,d_i\}\text{\ and\ }k\in\{1,\ldots,m_{ij}\},
	$$
	also ordered lexicographically  by means of the indeces $(i,j,k)$. The columns $v^{(i,j,k)}$ of $V$ and the rows $w^{(i,j,k)}$ of $V^{-1}$ are \emph{(right) generalized eigenvectors} and \emph{left generalized eigenvectors}, respectively, of $A$ corresponding to the eigenvalue $\lambda_i$. The columns $v^{(i,j,1)}$ and the rows $w^{(i,j,1)}$ are \emph{(right) eigenvectors} and \emph{left eigenvectors}, respectively, corresponding to $\lambda_i$. 


	\item For any $u\in\mathbb{C}^n$, the components of $u$ in the Jordan basis are denoted by
	$$
	\alpha_{ijk}(u),\ i\in\{1,\ldots,p\},\ j\in\{1,\ldots,d_i\}\text{\ and\ }k\in\{1,\ldots,m_{ij}\},
	$$ 
	where $\alpha_{ijk}(u)$ is the component along the element $v^{(i,j,k)}$ of the Jordan basis.

	\item The spectrum $\Lambda$ of $A$ is partitioned by decreasing real parts. Let $r_1,\ldots,r_q$ be the distinct decreasing real parts of the eigenvalues of $A$. For any $j\in\{1,\ldots,q\}$, let $\Lambda_j$ be the set of the eigenvalues with real part $r_j$ (see Figure \ref{Fig0}). Thus, $\Lambda_1$ is the set of the rightmost eigenvalues of $A$.

	\begin{figure}[tbp]
		\includegraphics[width=1\textwidth]{fig2.png}
		\caption{Partition of the eigenvalues $\protect\lambda_1,\ldots,\protect%
			\lambda_p$ of $A$ by decreasing real part. The eigenvalues are marked by ``x''.}
		\label{Fig0} 
	\end{figure}
\end{itemize} 

In the asymptotic behavior of the condition numbers, a crucial role is played by the $n\times n$ matrix
\begin{equation}
Q_1(t)=\sum\limits_{\substack{\lambda _{i}\in \Lambda _1\\ j\in\{1,\ldots,d_i\}\\ m_{ij}=M_1}}\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}v^{%
		\left( i,j,1\right) }w^{\left( i,j,M_1\right) },  \label{Q}
\end{equation}
where $\sqrt{-1}$ is the imaginary unit and 
$$
M_1=\max\limits_{\lambda_i\in\Lambda_1}\max\limits_{j\in\{1,\ldots,d_i\}}m_{ij}
$$
is the maximum length of Jordan chains (maximum order of Jordan mini-blocks) corresponding to rightmost eigenvalues of $A$. In (\ref{Q}), the sum is over all Jordan chains, corresponding to rightmost eigenvalues, whose length $m_{ij}$ is equal to the maximum length $M_1$. In other words, over all Jordan mini-blocks, corresponding to rightmost eigenvalues, whose order is equal to the maximum order $M_1$.
Observe that, for $u\in\mathbb{C}^n$, we have
\begin{equation}
	Q_1(t)u=\sum\limits_{\substack{\lambda _{i}\in \Lambda _1\\ j\in\{1,\ldots,d_i\}\\ m_{ij}=M_1}}\mathrm{e}^{\sqrt{-1}\ \omega _{i}t}\alpha_{ijM_1}(u)v^{%
		\left( i,j,1\right) }.  \label{Qu}
\end{equation}
\begin{definition}
We say that $u\in\mathbb{C}^n$ satisfies the \emph{Rightmost Last Generalized Eigenvectors (RLGE) condition} if some coefficient $\alpha_{ijM_1}(u)$ in (\ref{Qu}) is non-zero,
i.e. $u\in\mathbb{C}^n$ has some non-zero component along the last generalized eigenvectors $v^{(i,j,M_1)}$ of the Jordan chains, corresponding to rightmost eigenvalues, with the maximum length $M_1$.
\end{definition}

Note that if $u$ does not satisfy the RLGE condition, then $Q_1(t)u = 0$ for all $t \in \mathbb{R}$.

Two important properties of the matrix $Q_1(t)$ are
\begin{equation}
	\inf\limits_{t\in\mathbb{R}}\Vert Q_1(t)\Vert>0,  \label{infQ1}
\end{equation}
where $\Vert Q_1(t)\Vert$ is the matrix norm induced by the vector norm on $\mathbb{C}^n$, and
\begin{equation}
	\inf\limits_{t\in\mathbb{R}}\Vert Q_1(t)u\Vert>0  \label{infQ1u}
\end{equation}
for $u$ satisfying the RLGE condition.

\subsection{Asymptotic equivalence}


For the description of the asymptotic behavior of the condition numbers, we use the following notion of asymptotic equivalence. Let $a(t)$ and $b(t)$ be real functions of $%
t\in \mathbb{R}$. We say that $a(t)$ and $b(t)$ are \emph{asymptotically equivalent} and write
\begin{equation*}
	a\left( t\right) \sim b\left( t\right),\ t\rightarrow +\infty,  \label{sim}
\end{equation*}
if
\begin{equation*}
	\lim\limits_{t\rightarrow +\infty }\frac{a(t)}{b(t)}=1.
\end{equation*}
In other words, we can say that the asymptotic equivalence holds if
\begin{equation*}
	\lim\limits_{t\rightarrow +\infty }\chi(t)=0,
\end{equation*}
where $\chi(t)$ is the relative error of $a(t)$ with respect to $b(t)$, i.e. we have
$$
a(t)=b(t)\left(1+\chi(t)\right).
$$


\subsection{The asymptic behavior of $K(t,y_0,\widehat{z}_0)$ and $K(t,y_0)$}

The next theorem describes the asymptotic behaviors of the condition numbers $K(t,y_0,\widehat{z}_0)$ and $K(t,y_0)$.

\begin{theorem}\label{Theorem4}
For $y_0$ and $\widehat{z}_0$ satisfying the RLGE condition, we have
$$ 
K(t,y_0,\widehat{z}_0)\sim K_\infty(t,y_0,\widehat{z}_0):= \frac{\left\Vert
	Q_1(t)\widehat{z}_{0}\right\Vert }{\left\Vert Q_1(t)\widehat{y}%
	_{0}\right\Vert },\ t\rightarrow +\infty,
	$$	
	and
	$$ 
	K(t,y_0)\sim K_\infty(t,y_0):= \frac{\left\Vert
		Q_1(t)\right\Vert }{\left\Vert Q_1(t)\widehat{y}%
		_{0}\right\Vert },\ t\rightarrow +\infty.
	$$
\end{theorem}




We can observe the following.

\begin{itemize}
	\item [1.] The  RLGE condition is a generic condition for $y_0$ and $\widehat{z}_0$.
	\item  [2.] By (\ref{infQ1u}), we have
	\begin{equation*}
	0<\inf\limits_{t\in\mathbb{R}}K_\infty(t,y_0,\widehat{z}_0)\text{\ \ and\ \ }\sup\limits_{t\in\mathbb{R}}K_\infty(t,y_0,\widehat{z}_0)<+\infty %\label{infsupKyz}
	\end{equation*}
	and, by  (\ref{infQ1}) and  (\ref{infQ1u}), we have
	$$
	0<\inf\limits_{t\in\mathbb{R}}K_\infty(t,y_0)\text{\ \ and\ \ }\sup\limits_{t\in\mathbb{R}}K_\infty(t,y_0)<+\infty.
	$$
	\item [3.] If $\Lambda_1$ consists of a (unique) real eigenvalue $\lambda_1$, then
	$$
	Q_1(t)=Q_1=\sum\limits_{\substack{j\in\{1,\ldots,d_1\}\\ m_{1j}=M_1}}v^{%
		\left( 1,j,1\right) }w^{\left(1,j,M_1\right) },
	$$
	where
	$$
	M_1=\max\limits_{j\in\{1,\ldots,d_1\}}m_{1j},
	$$
	is a constant function of $t$ and then
	$$
	K_\infty(t,y_0,\widehat{z}_0)=K_\infty(y_0,\widehat{z}_0)=\frac{\left\Vert
		Q_1\widehat{z}_{0}\right\Vert }{\left\Vert Q_1\widehat{y}%
		_{0}\right\Vert }
		$$
		and
		$$
		K_\infty(t,y_0)=K_\infty(y_0)= \frac{\left\Vert
		Q_1\right\Vert }{\left\Vert Q_1\widehat{y}%
		_{0}\right\Vert }
	$$
	are constant functions of $t$. 
\end{itemize}
In view of points 1-2-3  and (\ref{magnification}), we can state a fact B) regarding the relative error of the perturbed solution, analogous to fact A) concerning the absolute error of the perturbed solution and presented at the beginning of the paper.
\begin{itemize}
	\item [B)] \emph{In a generic situation for the initial value and the perturbation of the initial value (namely they satisfy the RLGE condition), the relative error of the perturbed solution asymptotically (as $t\rightarrow +\infty$) neither diverges nor decays to zero. Instead, it converges to a non-zero constant, in case of a real eigenvalue as  rightmost eigenvalue, and to an oscillating function bounded and uniformly away from zero, otherwise.}
\end{itemize}

For any $y_0$ and $\widehat{z}_0$, not only for $y_0$ and $\widehat{z}_0$ satisfying the RGLE condition, there are functions 
$$
t\rightarrow K_\infty\left(t,y_0,\widehat{z}%
_0\right)\text{\ \ and\ \ }t\rightarrow K_\infty\left(t,y_0\right),\ t\in\mathbb{R},
$$
such that
\begin{equation*}
K(t,y_0,\widehat{z}_0)\sim K_\infty(t,y_0,\widehat{z}_0)\text{\ \ and\ \ }K(t,y_0)\sim K_\infty(t,y_0),\ t\rightarrow +\infty. \label{simsim}
\end{equation*}
They are called the \emph{asymptotic directional condition number} and the \emph{asymptotic condition number}, respectively, of the problem (\ref{due}). Such functions for the general case are described in \cite{Maset2022}.



\subsection{Is $K_\infty(t,y_0)$ the worst $K_\infty(t,y_0,\widehat{z}_0)$?}

By definition, the condition number $K\left(
t,y_{0}\right)$ is the worst condition number $K\left( t,y_{0},%
\widehat{z}_0\right)$ as $\widehat{z}_0$ varies, at a specific time $t$. An interesting question is the following. Does this fact hold asymptotically as $t\rightarrow +\infty$? Specifically, is the asymptotic condition number $K_\infty\left(
t,y_{0}\right)$ the worst asymptotic condition number  $K_\infty\left( t,y_{0},%
\widehat{z}_0\right)$ as $\widehat{z}_0$ varies? In other terms, do 
\begin{equation*}
	\max\limits_{\substack{ \widehat{z}_0\in \mathbb{C}^{n}  \\ \Vert \widehat{z}%
			_0\Vert =1}}\ \text{(worst case) and }\ t\rightarrow +\infty\ \text{%
		(asymptotic behavior)}
\end{equation*}
commute? The answer is positive, since we have
	\begin{equation}
			\max\limits_{\substack{ \widehat{z}_0\in \mathbb{C}^{n}  \\ \Vert \widehat{z}%
					_0\Vert =1}}\limsup\limits_{t\rightarrow +\infty}\frac{K\left(
				t,y_{0},\widehat{z}_{0}\right)}{K\left( t,y_{0}\right)}=\max\limits_{\substack{ \widehat{z}_0\in \mathbb{C}^{n}  \\ \Vert \widehat{z}%
				_0\Vert =1}}\limsup\limits_{t\rightarrow +\infty}\frac{K_\infty\left(
			t,y_{0},\widehat{z}_{0}\right)}{K_\infty\left( t,y_{0}\right)}=1.  \label{limsup}
	\end{equation}

In line with (\ref{limsup}), we observe the following. If $y_0$ satisfies the RLGE condition and $\Lambda_1$ consists of a real eigenvalue, we have (see point 3 after Theorem \ref{Theorem4})
$$
K_\infty(y_0) = \max\limits_{\substack{ \widehat{z}_0 \in \mathbb{C}^{n}  \\ \Vert \widehat{z}_0 \Vert = 1\\ \widehat{z}_0 \text{\ satisfying the RLGE condition}}} K_\infty\left( y_0, \widehat{z}_0 \right).
$$


\section{The real case}
Now, we consider a real ODE (\ref{ode}). In this case, we
replace $\mathbb{C}$ by $\mathbb{R}$ and we have $A\in\mathbb{R}^{n\times n}$
and $y_0,y(t),\widetilde{y}_0,\widetilde{y}(t)\in\mathbb{R}^n$.

Our results concern the generic situation for the real matrix $A$ where \emph{the set $\Lambda_1$ of the rightmost eigenvalues of $A$ consists of either a real simple eigenvalue or a single pair of complex conjugate simple eigenvalues}.
\subsection{Notations}\label{Notations}
We introduce some notations.
\begin{itemize}
	\item [1)] In the case where $\Lambda_1$ consists of a real simple eigenvalue $\lambda_1$, let $w^{(1)}$ (a row real vector) be a left eigenvector  corresponding to $\lambda_1$ and let $\widehat{w}^{(1)}=\frac{w^{(1)}}{\Vert w^{(1)} \Vert }$ be its normalization. Here,
	$$\Vert w^{\left( 1\right)} \Vert=\max\limits_{\substack{ u\in \mathbb{R}^{n}  \\
			\Vert u\Vert=1}}\vert w^{\left( 1\right) }u\vert
	$$ is the real induced norm of the real matrix $w^{(1)}$.

	We say that $\Lambda_1$ \emph{is real} when $\Lambda_1$ consists of a real simple eigenvalue. 
	\item [2)] In the case where $\Lambda_1$ consists of a single pair of complex conjugate simple eigenvalues $\lambda_1$ and $\overline{\lambda_1}$, with $\lambda_1$ having positive imaginary part $\omega_1$, let $w^{(1)}$  (a complex row vector)  and $v^{(1)}$ (a complex column vector)  be left and right, respectively, eigenvectors corresponding to $\lambda_1$ and let  $\widehat{w}^{(1)}=\frac{w^{(1)}}{\Vert w^{(1)} \Vert }$ and $\widehat{v}^{(1)}=\frac{v^{(1)}}{\Vert v^{(1)} \Vert }$ be their normalizations. Here, $$\Vert w^{\left( 1\right) }\Vert=\max\limits_{\substack{ u\in \mathbb{C}^{n}  \\ %
			\Vert u\Vert=1}}\vert w^{\left( 1\right) }u\vert$$ is the complex induced norm of the complex matrix $w^{(1)}$.

		Moreover, given the polar forms
	\begin{eqnarray*}
		&&\widehat{v}_k^{\left( 1\right) }=\left\vert \widehat{v}_{k}^{\left(
			1\right) }\right\vert \mathrm{e}^{\sqrt{-1}\alpha _{1k}},\ k\in\{1,\ldots ,n\},\\
		&&\widehat{w}_l^{\left( 1\right) }=\left\vert \widehat{w}_{l}^{\left(
			1\right) }\right\vert \mathrm{e}^{\sqrt{-1}\beta _{1l}},\ l\in\{1,\ldots ,n\},
			\end{eqnarray*}
	of the components of the complex vectors $\widehat{v}^{\left( 1\right) }$ and $\widehat{w}^{\left( 1\right) }$ and the polar form
	\begin{eqnarray*}
		&&\widehat{w}^{\left( 1\right) }u=\left\vert\widehat{w}^{\left( 1\right)
		}u\right\vert\mathrm{e}^{\sqrt{-1}\gamma _1\left( u\right) }
	\end{eqnarray*}
	of the complex scalar $\widehat{w}^{\left( 1\right) }u$, where $u\in\mathbb{R}^n$, we introduce the vector
	\begin{equation*}
	\widehat{\Theta }_1\left( t,u\right) :=\left( \left\vert \widehat{v}%
	_{k}^{\left( 1\right) }\right\vert \cos \left( \omega _{1}t+\alpha
	_{1k}+\gamma_1\left( u\right) \right) \right) _{k=1,\ldots
		,n}\in \mathbb{R}^{n}
\end{equation*}
and the matrix
\begin{equation*}
	\widehat{\Theta }_1\left( t\right) =\left( \left\vert \widehat{v}%
	_{k}^{\left( 1\right) }\right\vert \left\vert \widehat{w}_{l}^{\left(
		1\right) }\right\vert \cos \left( \omega _{1}t+\alpha _{1k}+\beta _{1l}\right) \right) _{k,l=1,\ldots ,n}\in \mathbb{%
		R}^{n\times n}.
\end{equation*}
We say that $\Lambda_1$ \emph{is complex} when $\Lambda_1$ consists of a single complex conjugate pair of simple eigenvalues.


\end{itemize}

\subsection{The asymptic behavior of $K(t,y_0,\widehat{z}_0)$ and $K(t,y_0)$}

Next two results, derived by Theorem \ref{Theorem4}, consider the generic situation for $A$, described at the beginning of this Section 4, and a generic situation for $y_0$ and $\widehat{z}_0$. The generic situation for $y_0$ and $\widehat{z}_0$ is the RLGE condition, which becomes $w^{(1)}y_0\neq 0$ and  $w^{(1)}\widehat{z}_0\neq 0$ in the generic situation for $A$ we are considering.
\begin{theorem}
Assume that $A$ is a real matrix such that $\Lambda_1$ is real. For $y_0$ and $\widehat{z}_0$ such that $w^{(1)}y_0\neq 0$ and  $w^{(1)}\widehat{z}_0\neq 0$, we have (recall point 3 after Theorem \ref{Theorem4})
	\begin{equation*}
		K_\infty\left(y_{0},\widehat{z}_{0}\right)=\frac{\left\vert
			\widehat{w}^{(1)}\widehat{z}_{0}\right\vert }{\left\vert \widehat{w}^{(1)}\widehat{y}%
			_{0}\right\vert }\text{\ \ and\ \ }K_\infty\left(y_{0}\right)=\frac{1}{\left\vert \widehat{w}^{(1)}\widehat{y}%
		_{0}\right\vert  }.
\end{equation*}
\end{theorem}

\begin{theorem} \label{Thcomplex}
	Assume that $A$ is a real matrix such that $\Lambda_1$ is complex. For $y_0$ and $\widehat{z}_0$ such that $w^{(1)}y_0\neq 0$ and  $w^{(1)}\widehat{z}_0\neq 0$, we have
	\begin{eqnarray*}
		K_\infty\left( t,y_{0},\widehat{z}_{0}\right) = \mathrm{OSF}(y_0,\widehat{z}_0)\cdot\mathrm{OT}(t,y_0,\widehat{z}_0)\text{\ \ and\ \ }	K_\infty\left( t,y_{0}\right) = \mathrm{OSF}(y_0)\cdot\mathrm{OT}(t,y_0),
	\end{eqnarray*}
	where
	\begin{equation}
	\mathrm{OSF}(y_0,\widehat{z}_0):=\frac{\left\vert
		\widehat{w}^{(1)}\widehat{z}_{0}\right\vert }{\left\vert \widehat{w}^{(1)}\widehat{y}%
		_{0}\right\vert }\text{\ \ and\ \ }\mathrm{OSF}(y_0):=\frac{1}{\left\vert \widehat{w}^{(1)}\widehat{y}%
		_{0}\right\vert }  \label{OSFOSF}
	\end{equation}
	and
	\begin{equation}
	\mathrm{OT}(t,y_0,\widehat{z}_0):= \frac{\left\Vert \widehat{\Theta}_1
		\left( t,\widehat{z}_{0}\right) \right\Vert }{\left\Vert \widehat{\Theta}_1
		\left( t,\widehat{y}_{0}\right) \right\Vert }\text{\ \ and\ \ }\mathrm{OT}(t,y_0):=\frac{\left\Vert \widehat{\Theta}_1
		\left( t\right) \right\Vert }{\left\Vert \widehat{\Theta}_1
		\left( t,\widehat{y}_{0}\right) \right\Vert }.  \label{OTOT}
	\end{equation}
\end{theorem}
The constants $\mathrm{OSF}(y_0,\widehat{z}_0)$ and $\mathrm{OSF}(y_0)$ are called \emph{oscillation scale factors} and $\mathrm{OT}(t,y_0,\widehat{z}_0)$ and $\mathrm{OT}(t,y_0)$, which are periodic functions of $t$ of period $\frac{\pi}{\omega_1}$, are called \emph{oscillating terms}. Note that the oscillation scale factors depend on the moduli, and the oscillating terms on the angles, in the polar forms of the complex numbers $\widehat{w}^{(1)}\widehat{y}_{0}$ and $\widehat{w}^{(1)}\widehat{z}_{0}$.


	\subsection{The case $\Lambda_1$ complex and the Euclidean norm}\label{Euclidean}
	In this subsection, in the case of $\Lambda_1$ complex, we analyze the oscillation scale factors and the oscillating terms when the vector norm is the Euclidean norm. It will be the norm used throughout the subsection. As in Section 3, the proofs for all results presented here can be found in \cite{Maset2022}. 



	 The protagonists of this subsection are the numbers $V_1$ and $W_1$, which are now introduced.

	\subsubsection{$V_1$ and $W_1$}
	We introduce
	$$
	V_1:=\left\vert \left(\widehat{v}^{(1)}\right)^T\widehat{v}^{(1)}\right\vert\text{\ \ and\ \ }W_1:=\left\vert \widehat{w}^{(1)}\left(\widehat{w}^{(1)}\right)^T\right\vert,
	$$
	moduli of the complex numbers $\left(\widehat{v}^{(1)}\right)^T\widehat{v}^{(1)}$ and $\widehat{w}^{(1)}\left(\widehat{w}^{(1)}\right)^T$. Here $^T$, unlike $^H$, denote pure transposition without conjugation.
	We have $V_1,W_1\in[0,1)$.

	In Figure \ref{FigureVW}, we see, for $n=5,25,100$, the set of the pairs $(V_1,W_1)$ for $50\ 000$ random matrices $A$ of order $n$ such that $\Lambda_1$ is complex. The elements of $A$ are sampled from the standard normal distribution.  Observe that the distribution of the pairs in the square $[0,1)^2$ is not uniform, since the pairs tend to accumulate around the diagonal $V_1=W_1$.

	\begin{figure}[tbp]
		\centering
		\par
		\includegraphics[width=1.1\textwidth]{VW.png}
		\caption{Pairs $(V_1,W_1)$ for $50\ 000$ random matrices $A$ of order $n=5,25,100$.}
		\label{FigureVW}
	\end{figure}

	\subsubsection{The set $\mathcal{W}_1$ and the ellipse $\mathcal{E}_1$}

	As we have seen above in Theorem \ref{Thcomplex}, the asymptotic behavior of the condition numbers is determined by the complex numbers $\widehat{w}^{(1)}\widehat{y}_{0}$ and 	$\widehat{w}^{(1)}\widehat{z}_{0}$, with $\widehat{y}_{0}$ and $\widehat{z}_{0}$ unit real vectors. The moduli determine the oscillation scale factors and the angles in the polar forms determine the oscillating terms. Therefore, we now consider the set 
	\begin{equation*}
		\mathcal{W}_1:=\{\widehat{w}^{(1)}u:u\in\mathbb{R}^n\text{\ and\ }\left\Vert
		u\right\Vert_2=1\}  \label{set}
	\end{equation*}
	of the complex numbers $\widehat{w}^{(1)}u$, by varying the unit real vector $u$.

	Next theorem describes the set $\mathcal{W}_1$.

	\begin{theorem}
		\label{euclidean0} Let
		\begin{equation}
			R_1:=\left[%
			\begin{array}{c}
				\mathrm{Re}(\widehat{w}^{(1)}) \\ 
				\mathrm{Im}(\widehat{w}^{(1)})%
			\end{array}%
			\right]\in\mathbb{R}^{2\times n},  \label{matrixR1}
		\end{equation}
		let $\sigma_1$ and $\mu_1$, with $\sigma_1\geq \mu_1\geq 0$, be the singular values of $R_1$ and let $\alpha^{(1)},\beta^{(1)}\in\mathbb{R}^2$ the corresponding left singular vectors of $R_1$. Remind that the left singular vectors of $R_1$ constitute an orthonormal basis of $\mathbb{R}^2$. We have
		\begin{equation*}
			\sigma_1=\sqrt{\frac{1+W_1}{2}}\text{\ \ and\ \ }
			\mu_1=\sqrt{\frac{1-W_1%
				}{2}}.  \label{wR}
		\end{equation*}

		Consider, in the complex plane, the ellipse $\mathcal{E}_1$ centered at the origin with semi-axes the vectors $\sigma_1
		\alpha^{(1)}$ and $\mu_1\beta^{(1)}$. If $n=2$, the set $\mathcal{W}_1$ is the ellipse $\mathcal{E}_1$. If $n>2$, the set $\mathcal{W}_1$ is the union of the ellipse $\mathcal{E}_1$ and its interior. 

		Moreover, for $u\in\mathbb{R}^n$, we have
		\begin{equation}
			\widehat{w}^{(1)}u=\sigma_1c_1(u)\alpha^{(1)}+\sqrt{-1}\mu_1d_1(u)\beta^{(1)},  \label{w1u}
		\end{equation}     
		where $c_1(u)$ and $d_1(u)$ are the components of $u$ along the first right singular vector of $R_1$ (corresponding to the singular value $\sigma_1$) and the second right singular vector (corresponding to the singular value $\mu_1$), respectively. Remind that the right singular vectors of $R_1$ constitute an orthonormal basis of $\mathbb{R}^n$. 
		\end{theorem}


		\subsubsection{$\mathrm{OSF}(y_0,\widehat{z}_0)$ and $\mathrm{OT}(t,y_0,\widehat{z}_0)$}

The oscillation scale factor $\mathrm{OSF}(y_0,\widehat{z}_0)$ in (\ref{OSFOSF}) is the ratio of the moduli of the complex numbers $\widehat{w}^{(1)}\widehat{z}_{0}$ and $\widehat{w}^{(1)}\widehat{y}_{0}$. Such complex numbers can be arbitrary non-zero points of the set $\mathcal{W}_1$. Thus, as $y_0$ and $\widehat{z}_0$ vary, $\mathrm{OSF}(y_0, \widehat{z}_0)$ can take any value in $\left[\frac{\mu_1}{\sigma_1}, \frac{\sigma_1}{\mu_1}\right]$ for $n=2$, and any value in $(0, +\infty)$ for $n>2$. Moreover, by (\ref{w1u}), we have
	\begin{equation*}
		\mathrm{OSF}(y_0,\widehat{z}_0)=\sqrt{\frac{(1+W_1)c_1(\widehat{z}_0)^2+(1-W_1)d_1(\widehat{z}_0)^2}{(1+W_1)c_1(\widehat{y}_0)^2+(1-W_1)d_1(\widehat{y}_0)^2}}. \label{OSFOSF2}
	\end{equation*}


The next theorem specifies upper and lower bounds of the oscillating term $\mathrm{OT}\left(t,y_0,\widehat{z}_0\right)$ in (\ref{OTOT}). Remind that $\gamma_1(u)$, $u\in\mathbb{R}^n$, is the angle in the polar form of $w^{(1)}u$. Moreover, remind that $V_1\in [0,1)$, as well as $W_1\in[0,1)$.
\begin{theorem} \label{theorem9z}
	For $y_0$ and $\widehat{z}_0$ such that $w^{(1)}y_0\neq 0$ and  $w^{(1)}\widehat{z}_0\neq 0$, we have
	$$
	\sqrt{\frac{1-V_1}{1+V_1}}\leq \mathrm{OT}\left(t,y_0,\widehat{z}_0\right)\leq \sqrt{\frac{1+V_1}{1-V_1}},\ t\in\mathbb{R}.
	$$
Moreover, if $\gamma_{1}(\widehat{z}_0)-\gamma_{1}(\widehat{y}_0)$ is an odd multiple of $\frac{\pi}{2}$, we have
	\begin{equation}
		\min\limits_{t\in\mathbb{R}} \mathrm{OT}\left(t,y_0,\widehat{z}_0\right)=\sqrt{\frac{1-V_1}{1+V_1}}\text{\ \ and\ \ }
		\max\limits_{t\in\mathbb{R}} \mathrm{OT}\left(t,y_0,\widehat{z}_0\right)=\sqrt{\frac{1+V_1}{1-V_1}}. \label{maxminOT}
	\end{equation}
\end{theorem}

Regarding the previous theorem, we can make the following observations.

	\begin{itemize} 
		\item[1.] 	If $V_1$ is not close to 1, then, for any $y_0$ and $\widehat{z}_0$, $\mathrm{OT}(t, y_0, \widehat{z}_0)$ does not assume large or small values as $t$ varies. Therefore, \emph{if $V_1$ is not close to 1, then, for any $y_0$ and $\widehat{z}_0$, the values of $\mathrm{OT}(t, y_0, \widehat{z}_0)$ as $t$ varies have the order of magnitude $1$. Consequently, the values of $K_\infty(t, y_0, \widehat{z}_0)$ as $t$ varies have the same order of magnitude as $\mathrm{OSF}(y_0, \widehat{z}_0)$}.
		\item [2.] If $V_1$ is close to $1$, then, for any $y_0$ and for $\widehat{z}_0$ such that $\gamma_{1}(\widehat{z}_0)-\gamma_{1}(\widehat{y}_0)$ is an odd multiple of $\frac{\pi}{2}$,  $\mathrm{OT}\left(t,y_0,\widehat{z}_0\right)$ assumes both large and small values as $t$ varies.
		\item [3.] The condition that $\gamma_{1}(\widehat{z}_0)-\gamma_{1}(\widehat{y}_0)$ is an odd multiple of $\frac{\pi}{2}$ is equivalent to saying that the vectors $\widehat{w}^{(1)}\widehat{y}_{0}$ and $\widehat{w}^{(1)}\widehat{z}_{0}$ are orthogonal in the complex plane, i.e. 
	\begin{equation}
		(1+W_1)c_1(\widehat{y}_0)c_1(\widehat{z}_0)+(1-W_1)d_1(\widehat{y}_0)d_1(\widehat{z}_0)=0 \label{orthogonal}
		\end{equation}
		by (\ref{w1u}).

		\item [4.] Two particular situations are worth considering.
		\begin{itemize}
			\item If $y_0$ and $\widehat{z}_0$ are orthogonal to the first and second, respectively, right singular vectors of the matrix $R_1$ (i.e. $c_1(\widehat{y}_0)=0$ and $d_1(\widehat{z}_0)=0$ and thus (\ref{orthogonal}) holds), then we have
			\begin{equation*}
				\mathrm{OSF}(y_0,\widehat{z}_0)=\sqrt{\frac{1+W_1}{1-W_1}}\cdot \frac{\vert c_1(\widehat{z}_0)\vert}{\vert d_1(\widehat{y}_0)\vert}\text{\ \ and\ \ (\ref{maxminOT})}. 
			\end{equation*}
			If $W_1$ is close to $1$, it is expected to have $\mathrm{OSF}(y_0,\widehat{z}_0)$ large. If $V_1$ is close to $1$,  then $\mathrm{OT}\left(t,y_0,\widehat{z}_0\right)$ assumes both large and small values as $t$ varies.

			\quad Regarding the asymptotic condition number
			$$
			K_\infty(t,y_0,\widehat{z}_0)=\mathrm{OSF}(y_0,\widehat{z}_0)\cdot\mathrm{OT}(t,y_0,\widehat{z}_0),
			$$
			it is expected that it assumes  large values as $t$ varies, if $V_1$ is close to $1$ or $W_1$ is close to $1$.

			\item If $y_0$ and $\widehat{z}_0$ are orthogonal to the second and first, respectively, right singular vectors of $R_1$ (i.e.  $d_1(\widehat{y}_0)=0$ and $c_1(\widehat{z}_0)=0$ and thus (\ref{orthogonal}) holds), then we have
			\begin{equation*}
				\mathrm{OSF}(y_0,\widehat{z}_0)=\sqrt{\frac{1-W_1}{1+W_1}}\cdot \frac{\vert d_1(\widehat{z}_0)\vert}{\vert c_1(\widehat{y}_0)\vert}\text{\ \ and\ \ (\ref{maxminOT})}.
			\end{equation*}
						If $W_1$ is close to $1$, it is expected to have $\mathrm{OSF}(y_0,\widehat{z}_0)$ small. If $V_1$ is close to $1$,  then $\mathrm{OT}\left(t,y_0,\widehat{z}_0\right)$ assumes both large and small values as $t$ varies.

						\quad Regarding the asymptotic condition number
						$$
						K_\infty(t,y_0,\widehat{z}_0)=\mathrm{OSF}(y_0,\widehat{z}_0)\cdot\mathrm{OT}(t,y_0,\widehat{z}_0),
						$$
						it is expected that it assumes  large values as $t$ varies, if $\sqrt{\frac{1-W_1}{1-V_1}}$ is large.
		\end{itemize}
	\end{itemize}



	\subsubsection{$\mathrm{OSF}(y_0)$ and $\mathrm{OT}(t,y_0)$}

	The oscillation scale factor $\mathrm{OSF}(y_0)$ in (\ref{OSFOSF}) is the reciprocal of the modulus  of the complex number $\widehat{w}^{(1)}\widehat{y}_{0}$. Such complex number can be an arbitrary non-zero point in the set $\mathcal{W}_1$. 	Thus, as $y_0$ varies, $\mathrm{OSF}(y_0)$ can take any value in $\left[\frac{1}{\sigma_1},\frac{1}{\mu_1}\right]$ for $n=2$, and any value in $\left[\frac{1}{\sigma_1},+\infty\right)$ for $n>2$.  Moreover, by (\ref{w1u}), we have 
		\begin{equation*}
			\mathrm{OSF}(y_0)=\sqrt{\frac{2}{(1+W_1)c_1(\widehat{y}_0)^2+(1-W_1)d_1(\widehat{y}_0)^2}}. \label{OSF1}
		\end{equation*}

The next theorem specifies upper and lower bounds of the oscillating term $\mathrm{OT}\left(t,y_0\right)$ in (\ref{OTOT}). Let
\begin{equation}
a_{\min}(V_1,W_1):=\left\{
\begin{array}{l}
	\sqrt{\frac{(1+W_1)(1-V_1)}{2(1+V_1)}}\text{\ if\ }V_1\leq W_1\\
	\\
	\sqrt{\frac{1-W_1}{2}}\text{\ if\ }V_1\geq W_1,
\end{array}
\right.  \label{amin}
\end{equation}
let
\begin{equation}
a_{\max}(V_1,W_1):=\sqrt{\frac{(1+W_1)(1+V_1)}{2(1-V_1)}}  \label{amax}
\end{equation}
and let $\theta_1$ be the angle in the complex plane between the real axis and the major semi-axis $\sigma_1\alpha^{(1)}$ of the ellipse $\mathcal{E}_1$ introduced in Theorem \ref{euclidean0}.



\begin{theorem} \label{theorem9}
For $y_0$ such that $w^{(1)}y_0\neq 0$, we have	
	$$
	a_{\min}(V_1,W_1)\leq \mathrm{OT}(t,y_0)\leq a_{\max}(V_1,W_1),\ t\in\mathbb{R}.
	$$
	Moreover, if $\gamma_{1}(\widehat{y}_0)-\theta_{1}$ is an odd multiple of $\frac{\pi}{2}$, then
	\begin{equation}
		\min\limits_{t\in\mathbb{R}} \mathrm{OT}\left(t,y_0\right)=a_{\min}(V_1,W_1)\text{\ \ and\ \ }
		\max\limits_{t\in\mathbb{R}} \mathrm{OT}\left(t,y_0\right)=a_{\max}(V_1,W_1).\label{maxminOT2}
	\end{equation}
\end{theorem}



Regarding the previous theorem, we can make the following observations.


\begin{itemize}
	\item [1.] If $V_1$ is not close to $1$, then, for any $y_0$, $\mathrm{OT}(t,y_0)$ does not assume large values as $t$ varies. If $V_1$ is not close to $1$ or $W_1$ is not close to $1$, then, for any $y_0$, $\mathrm{OT}(t,y_0)$ does not assume small values as $t$ varies. Therefore, \emph{if $V_1$ is not close to 1, then, for any $y_0$, the values of $\mathrm{OT}(t,y_0)$ as $t$ varies have the order of magnitude $1$. Consequently, the values of $K_\infty(t, y_0)$ as $t$ varies have the same order of magnitude as $\mathrm{OSF}(y_0)$}.
	\item [2.] The condition $\gamma_{1}(\widehat{y}_0)-\theta_{1}$ is an odd multiple of $\frac{\pi}{2}$ is equivalent to saying that the vector $\widehat{w}^{(1)}\widehat{y}_{0}$ is orthogonal  in the complex plane  to the major semi-axis $\sigma_1\alpha^{(1)}$ of the ellipse $\mathcal{E}_1$, i.e. $c_1(\widehat{y}_0)=0$ by (\ref{w1u}). This indicates that $y_0$ is orthogonal to the first right singular vector of the matrix $R_1$. In this case, we have
	\begin{equation*}
			\mathrm{OSF}(y_0)=\sqrt{\frac{2}{1-W_1}}\cdot \frac{1}{\vert d_1(\widehat{y}_0)\vert}\text{\ \ and\ \ (\ref{maxminOT2}).}
	\end{equation*}
	If $W_1$ is close to $1$, then $\mathrm{OSF}(y_0)$ is large. If $V_1$ is close to $1$, then $\mathrm{OT}\left(t,y_0\right)$ assumes large values as $t$ varies. If $V_1$ is close to $1$ and $W_1$ is close $1$, then $\mathrm{OT}\left(t,y_0\right)$ assumes small values as $t$ varies.

	Regarding the asymptotic condition number
	$$
	K_\infty(t,y_0)=\mathrm{OSF}(y_0)\cdot\mathrm{OT}(t,y_0),
	$$ it assumes large values as $t$ varies, if $V_1$ is close to $1$ or $W_1$ is close to $1$.
\end{itemize}



\subsubsection{Is $V_1$ close to $1$?}\label{V1close1}

We have seen in points 1, following Theorems \ref{theorem9z} and \ref{theorem9}, that the asymptotic condition numbers have the same order of magnitude as the oscillation scale factors when $V_1$ is not close to 1, since, in this case, the oscillating terms have the order of magnitude $1$. Therefore, it is of interest to understand how frequently $V_1$ is close to 1.

The following table shows, for the $50\ 000$ random matrices of Figure \ref{FigureVW},  the percentages of cases with $V_1$ greater than $0.9$, $0.99$, $0.999$ and $0.9999$.
\begin{equation}
	\begin{tabular}{|l|l|l|l|l|}
		\hline
		& $V_1>0.9$ & $V_1>0.99$ & $V_1>0.999$ & $V_1>0.9999$ \\
		\hline
		$n=5$ &  6\%   & 0.6\% &  0.05\% &  0.002\% \\
		\hline
		$n=25$ & 4\%   & 0.4\% &  0.03\% &  0.002\%  \\
		\hline
		$n=100$  &  3\%   & 0.3 \% & 0.03\% & 0.004\%   \\
		\hline	  
	\end{tabular}
	\label{table}
\end{equation}

We have strong evidence that $V_1$ is rarely close to 1.

Regarding the order of magnitude of the oscillating terms when $V_1$ is close to $1$, note that
$$
\frac{1}{k} \leq \sqrt{\frac{1-V_1}{1+V_1}}\leq \mathrm{OT}(t,y_0,\widehat{z}_0) \leq \sqrt{\frac{1+V_1}{1-V_1}} \leq k%, \ t \in \mathbb{R},
$$
and
$$
\frac{1}{k} \leq a_{\mathrm{min}}(V_1, W_1) \leq \mathrm{OT}(t,y_0) \leq a_{\mathrm{max}}(V_1, W_1) \leq k%, \ t \in \mathbb{R},
$$
where
$$
k = \sqrt{\frac{2}{1 - V_1}}.
$$
The values of $k$ for $V_1 = 0.9, 0.99, 0.999, 0.9999$ in the table (\ref{table}) above are
