\section{The onset of the asymptotic behavior}

As mentioned in the introduction, it is important to understand when the condition numbers $K(t,y_0,\widehat{z}_0)$ and $K(t,y_0)$ begin to get close to their asymptotic versions $K_\infty(t,y_0,\widehat{z}_0)$ and $K_\infty(t,y_0)$.

In this section, we investigate such a question by considering, as in the previous section, a real ODE (\ref{ode}). We assume that the real matrix $A$ satisfies a condition a little bit stronger than the generic condition of the previous section, where we assumed that $\Lambda_1$ consists of either a real simple eigenvalue or a single pair of
complex conjugate simple eigenvalues. Here, we assume that, \emph{for any $j\in\{1,\ldots,q\}$, $\Lambda_j$ (see Figure \ref{Fig0}) consists of either a real simple eigenvalue or a single pair of
complex conjugate simple eigenvalues}. This latter condition, nonetheless, remains a generic condition for the real matrix $A$.

Once again, the proofs of the  results presented in this section can be found in \cite{Maset2022}.

\subsection{Notations}

We introduce for $\Lambda_j$, $j\in\{1,\ldots,q\}$, notations similar to the notations 1) and 2) introduced for $\Lambda_1$ in Subsection \ref{Notations}.
\begin{itemize}
	\item [1)] In the case where  $\Lambda_j$ consists of a real simple eigenvalue $\lambda_j$, let $w^{(j)}$  and $v^{(j)}$ be left and right, respectively, eigenvectors corresponding to $\lambda_j$. The normalized vector $\widehat{w}^{(j)}$ is defined similarly to $\widehat{w}^{(1)}$.

	We say that $\Lambda_j$ \emph{is real} when $\Lambda_j$ consists of a real simple eigenvalue. 

	\item [2)] In the case where $\Lambda_j$ consists of a single pair of complex conjugate simple eigenvalues $\lambda_j$ and $\overline{\lambda_j}$, with $\lambda_j$ having a positive imaginary part $\omega_j$, let $w^{(j)}$ and $v^{(j)}$ be left and right, respectively, eigenvectors corresponding to $\lambda_j$.

	Moreover, we introduce the normalized vectors $\widehat{w}^{(j)}$ and $\widehat{v}^{(j)}$, the vector $\widehat{\Theta}_j(t,u) \in \mathbb{R}^{n}$, with $u \in \mathbb{R}^{n}$, the matrix $\widehat{\Theta}_j(t) \in \mathbb{R}^{n \times n}$ and the scalars $V_j, W_j \in [0,1)$, defined similarly to $\widehat{w}^{(1)}$, $\widehat{v}^{(1)}$, $\widehat{\Theta}_1(t,u)$, $\widehat{\Theta}_1(t)$, $V_1$, and $W_1$.

	We say that $\Lambda_j$ \emph{is complex} when $\Lambda_j$ consists of a single complex conjugate pair of simple eigenvalue. 
\end{itemize}
We also introduce the values
\begin{equation}
f_j:=\Vert w^{(j)} \Vert\cdot \Vert v^{(j)} \Vert\in [1,+\infty),\ j\in\{1,\ldots,q\}.  \label{fj}
\end{equation}
\subsection{Approximation with a given precision}

The closeness of the condition numbers to their asympototic version is measured by using the following notion of \emph{approximation with a given precision}. For $a,b\in\mathbb{R}$ and $\epsilon\geq 0$, we write
$$
a\approx b\text{\ with precision\ }\epsilon
$$
if
$$
a=b(1+\chi)\text{\ with\ }\vert \chi\vert \leq\epsilon,
$$
i.e. the relative error $\chi$ of $a$ with respect to $b$ has modulus not larger than $\epsilon$.

\subsection{Closeness to the asymptotic behavior}\label{Ctoacnum}


The next theorem describes how the condition numbers get closer to their asymptotic versions, as $t$ increases.



\begin{theorem}\label{onset}
	Assume that $A$ is a real matrix such that, for any $j\in\{1,\ldots,q\}$, $\Lambda_j$ is real or $\Lambda_j$ is complex. For $y_0$ and $\widehat{z}_0$ such that $w^{(1)}y_0\neq 0$ and  $w^{(1)}\widehat{z}_0\neq 0$, we have
	$$
	K\left( t,y_{0},\widehat{z}_{0}\right) \approx K_\infty\left( t,y_{0},%
		\widehat{z}_{0}\right)\text{\ with precision\ } \frac{\epsilon(t,		\widehat{z}_0)+\epsilon(t,\widehat{y}_0)}{1-\epsilon(t,\widehat{y}%
			_0)}
	$$
	and 
	$$
	K\left( t,y_{0}\right) \approx K_\infty\left( t,y_{0}\right)\text{\ with
			precision\ }\frac{\epsilon(t)+\epsilon(t,\widehat{y}_0)}{%
			1-\epsilon(t,\widehat{y}_0)}
	$$
whenever $\epsilon(t,\widehat{y}_0)<1$, where
	\begin{equation*}
		\epsilon(t,u):=\sum\limits_{j=2}^{q}\mathrm{e}^{\left( r_{j}-r_{1
			}\right) t}\frac{f_j}{f_1}\cdot\frac{\left\vert \widehat{w}^{(j)}u\right\vert%
		}{\left\vert \widehat{w}^{(1)}u\right\vert}G_j\left(t,u\right),\ u=\widehat{y}_0,\widehat{z}_0,
	\end{equation*}
and
	\begin{equation*}
		\epsilon(t):=\sum\limits_{j=2}^{q}\mathrm{e}^{\left( r_{j}-r_{1
			}\right) t}\frac{f_j}{f_1}G_j(t).
	\end{equation*}
Here, $G_j(t,u)$ and $G_j(t)$, $j\in\{2,\ldots,q\}$, are defined as follows.
\begin{itemize}
	\item [1)]  	If both $\Lambda_j$ and $\Lambda_1$ are real, then
	\begin{equation*}
		G_j(t,u)=1\text{\ \ and\ \ }G_j(t)=1.
	\end{equation*}
	\item [2)]  If $\Lambda_j$ is complex and $\Lambda_1$ is real, then
	\begin{equation*}
		G_j(t,u)=2\left\Vert \widehat{\Theta}%
		_j(t,u)\right\Vert\text{\ \ and\ \ }G_j(t)=2\left\Vert \widehat{\Theta}_j(t)\right\Vert.
	\end{equation*}
	\item [3)]  If $\Lambda_j$ is real and $%
	\Lambda_1$ is complex, then
	\begin{equation*}
		G_j(t,u)=\frac{1}{2\left\Vert 
			\widehat{\Theta}_1(t,u)\right\Vert}\text{\ \ and\ \ }G_j(t)=\frac{1}{2\left\Vert \widehat{\Theta}_1(t)\right\Vert}.
	\end{equation*}
	\item [4)]  If both $\Lambda_j$ and $\Lambda_1$ are complex, then
	\begin{equation*}
		G_j(t,u)=\frac{\left\Vert \widehat{%
				\Theta}_j(t,u)\right\Vert}{\left\Vert \widehat{\Theta}_1(t,u)\right\Vert}%
		\text{\ \ and\ \ }G_j(t)=\frac{%
			\left\Vert \widehat{\Theta}_j(t)\right\Vert}{\left\Vert \widehat{\Theta}%
			_1(t)\right\Vert}.
	\end{equation*}

\end{itemize}
\end{theorem}

Regarding points 2), 3), and 4) in the previous theorem, the following can be stated.
\begin{itemize}
	\item [2bis)] If $\Lambda_j$ is complex and $\Lambda_1$ is real and the vector norm is a $p$-norm, then
	\begin{equation*}
		G_j(t,u)\leq 2\text{\ \ and\ \ }G_j(t)\leq 2.
	\end{equation*}
	\item [3bis)] If $\Lambda_j$ is real and $%
	\Lambda_1$ is complex and the vector norm is the Euclidean norm, then
	\begin{equation*}
		G_j(t,u)\leq \sqrt{\frac{1}{2(1-V_1)}}\text{\ \ and\ \ }G_j(t)\leq\sqrt{\frac{1}{a(V_1,W_1)}},
	\end{equation*}
	where
	$$
	a(V_1,W_1):=\left\{
	\begin{array}{l}
		(1-V_1)(1+W_1)\text{\ if\ }V_1\leq W_1\\
		\\
		(1+V_1)(1-W_1)\text{\ if\ }V_1\geq W_1.
	\end{array}
	\right.
	$$
	\item [4bis)]If  both $\Lambda_j$ and $\Lambda_1$ are complex and the vector norm is the Euclidean norm, then
	\begin{equation*}
		G_j(t,u)\leq\sqrt{\frac{1+V_j}{1-V_1}}\text{\ \ and\ \ }G_j(t)\leq\sqrt{\frac{(1+W_j)(1+V_j)}{a(V_1,W_1)}}.
	\end{equation*}
\end{itemize}



Observe that $\epsilon(t,u)\rightarrow 0$ and $\epsilon(t)\rightarrow 0$, as $t\rightarrow +\infty$, since $r_j-r_1<0$, $j\in\{2,\ldots,q\}$, in the exponential functions. Thus, we retrieve
\begin{equation*}
	K(t,y_0,\widehat{z}_0)\sim K_\infty(t,y_0,\widehat{z}_0)\text{\ \ and\ \ }K(t,y_0)\sim K_\infty(t,y_0),\ t\rightarrow +\infty. 
\end{equation*}



In conclusion, the onset of the asymptotic behavior, i.e. when the
condition numbers  begin to get close to their asymptotic versions, is determined by how rapidly $%
\epsilon(t,u)$, $u=\widehat{y}_0,\widehat{z}_0$, and $\epsilon(t)$ reach small values. The factors influencing this can be found in the expressions for $\epsilon(t,u)$ and $\epsilon(t)$ in the previous Theorem \ref{onset}. They are, for $j\in\{2,\ldots,q\}$:
\begin{itemize}
	\item the decreasing exponentials $\mathrm{e}^{(r_j-r_1)t}$;
	\item the ratios $\frac{f_j}{f_1}$;
	\item the ratios $\frac{\left\vert \widehat{w}^{(j)}u\right\vert%
	}{\left\vert \widehat{w}^{(1)}u\right\vert}$;
	\item the numbers $G_j(t,u)$ and $G_j(t)$.
\end{itemize}
An exploration of such factors influencing how rapidly  $K(t,y_0)$ get close to $K_\infty(t,y_0)$ is presented in the next section.




\section{Some considerations}

This section discusses two important issues concerning the asymptotic condition number $K_\infty(t,y_{0})$. It is the most important between the two asymptotic condition numbers since, in general, we have no information about the direction of perturbation $\widehat{z}_0$. 

As in the previous section, we assume the generic situation of a real matrix $A$ in (\ref{ode}) such that, for any $j\in\{1,\ldots,q\}$, $\Lambda_j$ is real or $\Lambda_j$ is complex, and of an initial value $y_0$ such that $w^{(1)}y_0\neq 0$. 

It is of interest to know:
\begin{itemize}%[align=center]
	\item [AWC)] for which initial values $y_0$ the problem (\ref{due}) is \emph{asymptotically well-conditioned}, i.e. $K_\infty(t,y_0)$ does not assume large values as $t$ varies;
	\item [ONS)] \emph{the onset of the asymptotic behavior}, i.e. when $K(t,y_0)$ begins to be close to $%
	K_\infty(t,y_{0})$; as we have seen, this happens as soon as $\epsilon(t,\widehat{y}_0)$ and $\epsilon(t)$ are small.
\end{itemize}

\subsection{The case $\Lambda_1$ real} 

Suppose that $\Lambda_1$ is real. We have
\begin{equation*}
K_\infty(y_{0})=\frac{1}{\left\vert \widehat{w}^{(1)}\widehat{y}%
		_{0}\right\vert}%\in[1,+\infty).
\end{equation*}
Thus, regarding the issue AWC) for $\Lambda_1$ real, we can conclude that:
\begin{itemize}%[align=center]
	\item [AWCr)] \emph{the problem (\ref{due}) is asymptotically well-conditioned if and only
	if $\left\vert \widehat{w}^{(1)}\widehat{y}_{0}\right\vert$ is not small}.
\end{itemize}

Concerning the onset of the asymptotic behavior, by Theorem \ref{onset} and the point 2bis) immediately after the theorem, we have,  when the vector norm is a $p$-norm,
\begin{eqnarray*}
	\max\{\epsilon(t,\widehat{y}_0),\epsilon(t)\}\leq 2\sum\limits_{j=2}^{q}\mathrm{e}^{\left(r_{j}-r_{1 }\right) t}\frac{f_j}{f_1} \max\left\{1,
	\frac{\left\vert \widehat{w}^{(j)}\widehat{y}_0\right\vert}{\left\vert \widehat{w}^{(1)}\widehat{y}_0\right\vert}\right\}
	\label{sumssums}
\end{eqnarray*}
and then we have $\max\{\epsilon(t,\widehat{y}_0),\epsilon(t)\}\leq \epsilon$, where $\epsilon>0$, if
\begin{equation*}
	\frac{t}{\widehat{t}}\geq \max\limits_{j\in\{2,\ldots,q\}}\frac{1}{\left(r_{1}-r_{j}\right) \widehat{t}}\left(\log\frac{2(q-1)}{\epsilon}+\log\frac{f_j}{f_1}
	+\max\left\{0,\log\frac{\left\vert \widehat{w}^{(j)}\widehat{y}%
		_0\right\vert}{\left\vert \widehat{w}^{(1)}\widehat{y}%
		_0\right\vert}\right\}\right),
\end{equation*}
where $\widehat{t}$ is the time used as time unit. If $r_1\neq 0$, one possible choice for the time unit is the \emph{characteristic time} $\frac{1}{\vert r_1\vert}$.
Thus, regarding the issue ONS) for $\Lambda_1$ real  and a $p$-norm as vector norm, by Theorem \ref{onset} we can conclude that:
\begin{itemize}%[align=center]
	\item [ONSr)] \emph{for $\overline{\epsilon}>0$, we have $K(t,y_0)\approx K_\infty(y_0)$ with precision $\overline{\epsilon}$ if 
\begin{eqnarray}
	&&\frac{t}{\widehat{t}}\geq \max\limits_{j\in\{2,\ldots,q\}}\frac{1}{\left(r_{1}-r_{j}\right) \widehat{t}}\left(\log 2+\log\frac{2+\overline{\epsilon}}{\overline{\epsilon}}+\log(q-1)\right. \notag\\
	&&\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad  \left.+\log\frac{f_j}{f_1}
	+\max\left\{0,\log\frac{\left\vert \widehat{w}^{(j)}\widehat{y}%
		_0\right\vert}{\left\vert \widehat{w}^{(1)}\widehat{y}%
		_0\right\vert}\right\}\right). \notag \\
		 \label{epsilon<}
\end{eqnarray}
Therefore, the smaller  the right-hand side in (\ref{epsilon<}), the earlier the onset of the asymptotic behavior}.
\end{itemize}

\subsection{The case $\Lambda_1$ complex} \label{lambdacomplex}

Suppose that $\Lambda_1$ is complex and the vector norm is the Euclidean norm.

We have
\begin{equation*}
	K_\infty(t,y_{0})=\mathrm{OSF}(y_0)\cdot \mathrm{OT}(t,y_0),
\end{equation*}
where the oscillation scale factor $\mathrm{OSF}(y_0)$ is given by 
$$
\mathrm{OSF}(y_0)= \frac{1}{\left\vert \widehat{w}^{(1)}\widehat{y}%
	_{0}\right\vert}.%\in\left[\frac{1}{\sigma_1},+\infty\right).
$$
If $V_1$ is not close to $1$, then the values of $K_\infty(t,y_0)$ as $t$ varies have the same order of magnitude as $\mathrm{OSF}(y_0)$, since the values of $\mathrm{OT}(t,y_0)$ as $t$ varies have the order of magnitude $1$ (see point 1 after Theorem \ref{theorem9}). Thus, regarding the issue AWC) for $\Lambda_1$ complex and the Euclidean norm as vector norm, we can conclude that:
\begin{itemize}%[align=center]
	\item [AWCc)] \emph{if $V_1$ is not close to $1$, then the problem (\ref{due}) is asymptotically well-conditioned if and only
	if $\left\vert \widehat{w}^{(1)}\widehat{y}_{0}\right\vert$ is not small}.
	\end{itemize}

If $V_1$ is close to $1$, then $\left\vert \widehat{w}^{(1)}\widehat{y}_{0}\right\vert$ does not determine the asymptotic well-conditioning of the problem (\ref{due}), unlike when $V_1$ is not close to $1$, since it no longer guaranteed that the values of $\mathrm{OT}(t, y_0)$ as $t$ varies maintain the order of magnitude of $1$. Indeed, if $V_1$ is
close to $1$ and $y_0$ is orthogonal to the first right singular vector of the matrix $R_1$ in (\ref{matrixR1}), then $\mathrm{OT}(t,y_{0})$ assume large values as $t$ varies (see point 2 after Theorem \ref{theorem9}). On the other hand, if $W_1$ is not close to $1$, then, for such $y_0$, 
$$
\mathrm{OSF}(y_0)=\frac{1}{\left\vert \widehat{w}^{(1)}\widehat{y}_{0}\right\vert}=\sqrt{\frac{2}{1-W_1}}\cdot \frac{1}{\vert d(\widehat{y}_0)\vert}
$$
is not large if $\vert d(\widehat{y}_0)\vert$ is not small, e.g. if $y_0$ is the second right singular vector of the matrix $R_1$. If this occurs, we have a situation where $K_\infty(t,y_0)$ assumes large values as $t$ varies, i.e. the problem (\ref{due}) is not asymptotically well-conditioned, although $\left\vert \widehat{w}^{(1)}\widehat{y}_{0}\right\vert$ is not small. 

However, by recalling Subsection \ref{V1close1}, observe that $V_1$ is rarely close to $1$. 



Concerning the onset of the asymptotic behavior, by Theorem \ref{onset} and points 3bis) and 4bis) immediately after the theorem, we have
\begin{eqnarray*}
	\max\{\epsilon(t,\widehat{y}_0),\epsilon(t)\}\leq \frac{2}{\sqrt{1-V_1}}\sum\limits_{j=2}^{q}\mathrm{e}^{\left(r_{j}-r_{1 }\right) t}\frac{f_j}{f_1} \max\left\{1,
	\frac{\left\vert \widehat{w}^{(j)}\widehat{y}_0\right\vert}{\left\vert \widehat{w}^{(1)}\widehat{y}_0\right\vert}\right\}.
\end{eqnarray*}
(The term $\frac{2}{\sqrt{1-V_1}}$ is obtained by comparing all the upper bounds for $G_j(t,u)$ and $G_j(t)$, $j \in \{2, \ldots, q\}$, provided in 3bis) and 4bis) and by noting that $a(V_1, W_1) \geq 1 - V_1$).
Thus, regarding the issue ONS) for $\Lambda_1$ complex and the Euclidean norm as vector norm, by Theorem \ref{onset} we can conclude that:
\begin{itemize}%[align=center]
	\item [ONSc)] \emph{for $\overline{\epsilon}>0$, we have $K(t,y_0)\approx K_\infty(t,y_0)$ with precision $\overline{\epsilon}$ if
	\begin{eqnarray}
		&&\frac{t}{\widehat{t}}\geq\max\limits_{j\in\{2,\ldots,q\}}\frac{1}{\left(r_{1}-r_{j}\right) \widehat{t}}\left(\log 2+\log\frac{2+\overline{\epsilon}}{\overline{\epsilon}}+\log(q-1)\right.\notag\\
			&&\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad  \left.+\frac{1}{2}\log\frac{1}{1-V_1}+\log\frac{f_j}{f_1}
			+\max\left\{0,\log\frac{\left\vert \widehat{w}^{(j)}\widehat{y}%
				_0\right\vert}{\left\vert \widehat{w}^{(1)}\widehat{y}%
				_0\right\vert}\right\}\right).\notag \\
			\label{epsilonc<}
	\end{eqnarray}
	Therefore, the smaller  the right-hand side in (\ref{epsilonc<}), the earlier the onset of the asymptotic behavior}.
\end{itemize}
By comparing (\ref{epsilon<}) and (\ref{epsilonc<}), we observe the presence of the term $\frac{1}{2}\log\frac{1}{1-V_1}$ in (\ref{epsilonc<}). If $V_1$ is close to $1$,  we could observe a delayed onset of the asymptotic behavior, compared to the case where $V_1$ is not close to $1$ or to the case where $\Lambda_1$ is real.


\subsection{Non-normal matrices}

Suppose that the vector norm is the Euclidean norm. For a normal matrix $A$, we have
$f_j=1,\ j\in\{1,\ldots,q\}$, and, in the case of  $\Lambda_1$ complex, $V_1=0$. On the other hand, a non-normal matrix $A$ can exhibit $f_j$ values that are arbitrarily large, as well as $V_1$ values that are arbitrarily close to $1$.


It is important to understand the impact of the non-normality of the matrix $A$ on the two aforementioned issues AWC) and ONS).
\begin{itemize}
	\item [AWCnn)] Regarding the asymptotic well-conditioning of the problem (\ref{due}), we can say that \emph{the non-normality of $A$ has an impact only if $\Lambda_1$ is complex}. In fact,  if $\Lambda_1$ is real, or $\Lambda_1$ is complex and $V_1$ is not close to $1$, then the problem (\ref{due}) is asymptotically well-conditioned if and only if $\vert \widehat{w}^{(1)}\widehat{y}_0\vert$ is not small, where the quantity $\vert \widehat{w}^{(1)}\widehat{y}_0\vert$ is unrelated to the non-normality. On the other hand, if $\Lambda_1$ is complex and $V_1$ is close to $1$, a case possible only for $A$ non-normal, the quantity $\vert \widehat{w}^{(1)}\widehat{y}_0\vert$ does not determine the asymptotic well-conditioning of the problem (\ref{due}) (recall the previous Subsection \ref{lambdacomplex}).
	\item [ONSnn)] Regarding the onset of the asymptotic behavior, if some ratio $\frac{f_j}{f_1}$, $j\in\{2,\ldots,q\}$, is large, or $\Lambda_1$ is complex and $V_1$ is close to 1, cases possible only for $A$ non-normal, \emph{the onset of the asymptotic behavior could be delayed} (recall (\ref{epsilon<}) and (\ref{epsilonc<})).
\end{itemize}

It's worth noting that in ONSnn) the focus is on the ratios $\frac{f_j}{f_1}$, $j\in\{2,\ldots,q\}$, which can be much smaller than the large values of $f_j$ characterizing an high non-normality of the matrix $A$. More details are given in the next example.




\begin{example}
	In Figure \ref{logfjf1104}, for the Euclidean norm as vector norm, we see the maxima
	\begin{equation}
	M=\max\limits_{j\in\{2,\ldots,n\}}\log f_j \text{\ \ and\ \ }\widehat{M}=\max\limits_{j\in\{2,\ldots,n\}}\log \frac{f_j}{f_1}, \label{Maxima}
	\end{equation}
for $10\ 000$ matrices $A$ of order $n=500$, whose elements are sampled from the standard normal distribution. It appears that the values $\widehat{M}$ are smaller than the values $M$. The following table provides some statistical details:
	$$
	\begin{tabular}{|c|c|c|c|}
		\hline
