        f_s(x_{s1}, x_{s2}) = \begin{cases}
            \frac{\frac{L_1}{v_{w1}} + \frac{L_2}{v_{w2}} - 1}{\sqrt{T_2^2 + T_1^2}}, &x_{s1} \in [0, T_1), \, x_{s2} \in [0, T_2), \, x_{s2} = -\frac{T_2}{T_1} x_{s1} + T_2; \\
            \frac{1}{v_{w1}}, &x_{s1} \in [T_1, L_1], \, x_{s2} = 0; \\
            \frac{1}{v_{w2}}, &x_{s1} = 0, \, x_{s2} \in [T_2, L_2],
        \end{cases}
    \end{align*}
    where $T_1 = L_1 - v_{w1} + \frac{L_2}{v_{w2}} v_{w1}$, $T_2 = L_2 - v_{w2} + \frac{L_1}{v_{w1}} v_{w2}$.
    \begin{align*}
        f_w(x_{w1}, x_{w2}) = \frac{1}{\sqrt{L_1^2 + L_2^2}}, \quad x_{w1} \in [0, L_1], \, x_{w2} \in [0, L_2], \, x_{w2} = -\frac{L_2}{L_1} x_{w1} + L_2.
    \end{align*}
\end{theorem}

