\begin{theorem}\label{thm:nash-equilibrium-two-items-case3}
    Given the profile $(B_1, B_2, v_{11}, v_{12}, v_{21}, v_{22})$ with $B_1 \neq B_2$, if $v_{s1} > L_1$ and $v_{s2} = L_2$, then the following strategies can form a Nash equilibrium:
    \begin{align*}
        f_s(x_{s1}, x_{s2}) = \begin{cases}
            1 - \frac{L_2}{v_{w2}}, &x_{s1} = L_1, \, x_{s2} = 0; \\
            \frac{1}{v_{w2}}, &x_{s1} = L_1, \, x_{s2} \in (0, T_2]; \\
            \frac{\frac{L_1}{v_{w1}}}{\sqrt{L_1^2 + (L_2 - T_2)^2}}, & \begin{array}{l}
                x_{s1} \in [0, L_1), \, x_{s2} \in (T_2, L_2], \\ 
                x_{s2} = -\frac{L_2 - T_2}{L_1} x_{s1} + L_2,
            \end{array}
        \end{cases}
    \end{align*}
    where $T_2 = -\frac{L_1}{v_{w1}} v_{w2} + L_2$.
    \begin{align*}
        f_w(x_{w1}, x_{w2}) = \begin{cases}
            \frac{1}{v_{s2}}, &x_{w1} = 0, \, x_{w2} \in [T_4, L_2]; \\
            \frac{\frac{L_1}{v_{s1}}}{\sqrt{L_1^2 + T_4^2}}, &x_{w1} \in (0, L_1], \, x_{w2} \in [0, T_4), \, x_{w2} = -\frac{T_4}{L_1} x_{w1} + T_4,
        \end{cases}
    \end{align*}
    where $T_4 = L_2 - \frac{v_{s1} - L_1}{v_{s1}} v_{s2}$.
\end{theorem}

