\noindent {\textbf{Proof of Lemma \ref{lem:pure-Nash-Equilibirum-single-item}}}
\begin{proof}
    First, we prove that $(B_1, B_2)$ is a pure strategy Nash equilibrium when this condition is met.
    When player $-i$ bids $x_{-i} = B_{-i}$, we have
    \begin{align*}
        u_i(B_i, B_{-i}) = \frac{1}{2} v_i - B_i \geq 0 \geq u_i(x_i, B_{-i}), \quad \forall x_i \in [0, B_i),
    \end{align*}
    which means that player $i$'s utility will not increase if his bid deviates from $B_i$ to $x_i \in [0, B_i)$.
    Therefore, we can easily verify that $(B_1, B_2)$ is a pure strategy Nash equilibrium.

    Next, we prove that there is no other pure strategy Nash equilibrium besides $(B_1, B_2)$.
    When player $-i$ bids $x_{-i} \in [0, B_{-i})$, for any bid $x_i$, player $i$ has motivation to deviate from $x_i$. 
    To discuss in detail, if player $i$ bids $x_{i} \in [0, x_{-i}]$, we have $u_{i}(x_{i}, x_{-i}) < u_{i}(x_{-i} + \varepsilon, x_{-i})$ as long as $0 < \varepsilon < B_{i} - x_{-i}$; 
    if player $i$ bids $x_{i} \in (x_{-i}, B_i]$, we have $u_{i}(x_{i}, x_{-i}) < u_{i}(x_{i} - \varepsilon, x_{-i})$ as long as $0 < \varepsilon < x_{i} - x_{-i}$. 
    Thus, there exists no pure strategy Nash equilibrium when player $i$ bids $x_{i} \in [0, B_{i})$.
    Therefore, $(B_1, B_2)$ is unique pure strategy Nash equilibrium.

    Finally, we prove that there is no pure strategy Nash equilibrium when this condition is not met.
    If $B_1 \neq B_2$, or $B_1 = B_2$ and $B_2 > \frac{1}{2} \min\{v_1, v_2\}$, let $R_1 = \min\{v_1, B_1\}$, $R_2 = \min\{v_2, B_2\}$, and $i^* = \arg\max_{i \in \{1, 2\}} R_i$, so $R_{i^*} \geq R_{-i^*}$.
    We here discuss two cases.
    \begin{enumerate}[label = Case (\arabic*), left = 1.5em]
        \item $R_{i^*} > R_{-i^*}$. 
        The bid of player $-i^*$ is $x_{-i^*} \in [0, R_{-i^*}]$, we discuss the following situations.
        \begin{itemize}
            \item Player $-i^*$ bids 0. 
            We have that $u_{i^*}(\varepsilon, 0) = v_{i^*} - \varepsilon > u_{i^*}(0, 0) = \frac{1}{2} v_{i^*}$ for sufficiently small $\varepsilon > 0$. 
            However, the $\varepsilon > 0$ can be infinitely small, the best response for player $i^*$ does not exist. 
            Therefore, a bid of 0 by player $-i^*$ cannot constitute a pure Nash equilibrium.
            \item Player $-i^*$ bids $x_{-i^*} \in (0, R_{-i^*})$.
            For $\forall x_{i^*} \in [0, x_{-i^*})$, we have $u_{i^*}(x_{i^*}, x_{-i^*}) = 0 - x_{i^*} \leq 0$, which means that if the bid of player $i^*$ is less than that of player $-i^*$, player $i^*$ will not get positive utility.
            For $x_{i^*} = x_{-i^*}$, we have $u_{i^*}(x_{i^*}, x_{-i^*}) = \frac{1}{2} v_{i^*} - x_{i^*} < v_{i^*} - (x_{i^*} + \varepsilon) = u_{i^*}(x_{i^*} + \varepsilon, x_{-i^*})$ for sufficiently small $\varepsilon > 0$.
            Note that $x_{-i^*} < R_{-i^*} < R_{i^*} \leq v_{i^*}$, therefore we have $u_{i^*}(x_{i^*} + \varepsilon, x_{-i^*}) > 0$.
            We can derive that $u_{i^*}(x_{i^*}, x_{-i^*}) < u_{i^*}(x_{-i^*} + \varepsilon, x_{-i^*})$ for $\forall x_{i^*} \in [0, x_{-i^*})$ and $u_{i^*}(x_{-i^*}, x_{-i^*}) < u_{i^*}(x_{-i^*} + \varepsilon, x_{-i^*})$.
            However, the $\varepsilon > 0$ can be infinitely small, the best response for player $i^*$ does not exist.
            Therefore, a bid of $x_{-i^*} \in (0, R_{-i^*}]$ by player $-i^*$ cannot constitute a pure Nash equilibrium.
            \item Player $-i^*$ bids $x_{-i^*} = R_{-i^*}$.
            Player $i^*$'s best response is to bid $R_{-i^*}$. 
            To discuss in detail, $u_{i^*}(R_{-i^*}, R_{-i^*}) > 0 \geq u_{i^*}(x_{i^*}, R_{-i^*})$ for any $x_{i^*} \in [0, R_{-i^*})$, $u_{i^*}(R_{-i^*}, R_{-i^*}) = v_{i^*} - R_{-i^*} > v_{i^*} - x_{i^*} =  u_{i^*}(x_{i^*}, R_{-i^*})$ for any $x_{i^*} \in (R_{-i^*}, R_{i^*}]$. 
            However, if Player $i^*$ bid $R_{-i^*}$, $u_{-i^*}(R_{-i^*}, 0) = 0 > u_{-i^*}(R_{-i^*}, R_{-i^*})$. Therefore, there is no pure Nash equilibrium in this case.
        \end{itemize}
        \item $R_{i^*} = R_{-i^*}$.
        We discuss the following situations.
        \begin{itemize}
            \item $R_{i^*} = v_{i^*}$ or $R_{-i^*} = v_{-i^*}$.
            We only discuss the situation where $R_{i^*} = v_{i^*}$; the situation where $R_{-i^*} = v_{-i^*}$ is similar and thus omitted.

            When $x_{-i^*} \in [0, R_{-i^*})$, if player $i^*$ bids $x_{i^*} \in [0, x_{-i^*})$, we have $u_{i^*}(x_{i^*}, x_{-i^*}) < u_{i^*}(x_{-i^*} + \varepsilon, x_{-i^*})$ as long as $\varepsilon < R_{-i^*} - x_{-i^*}$;
            if player $i^*$ bids $x_{i^*} = x_{-i^*}$, we have $u_{i^*}(x_{i^*}, x_{-i^*}) < u_{i^*}(x_{i^*} + \varepsilon, x_{-i^*})$ as long as $\varepsilon < R_{-i^*} - x_{i^*}$;
            if player $i^*$ bids $x_{i^*} > x_{-i^*}$, we have $u_{i^*}(x_{i^*}, x_{-i^*}) < u_{i^*}(x_{i^*} - \varepsilon, x_{-i^*})$ as long as $\varepsilon < \frac{1}{2} (x_{i^*} - x_{-i^*})$.
            Therefore, when player $-i^*$ bids $x_{-i^*} \in [0, R_{-i^*})$, there is no pure strategy Nash equilibrium.

            When $x_{-i^*} = R_{-i^*}$, we can deduce that if player $i^*$ bids 0, $u_{i^*}(0, R_{-i^*}) = 0$; 
            if player $i^*$ bids $x_{i^*} \in (0, R_{-i^*})$, $u_{i^*}(x_{i^*}, R_{-i^*}) < 0$; 
            if player $i^*$ bids $x_{i^*} = R_{-i^*}$, there are 3 cases: if $B_{i^*} = B_{-i^*}$, then $u_{i^*}(R_{-i^*}, R_{-i^*}) = \frac{1}{2} v_{i^*} - R_{-i^*} < 0$; if  $B_{i^*} > B_{-i^*}$, then $u_{i^*}(R_{-i^*}, R_{-i^*}) = 0$; if $B_{i^*} < B_{-i^*}$, then $u_{i^*}(R_{-i^*}, R_{-i^*}) < 0$.
            Therefore, if $B_{i^*} \leq B_{-i^*}$, then player $i^*$ can only bid 0; if $B_{i^*} > B_{-i^*}$, then player $i^*$ can bid 0 or $v_{i^*}$.

            However, if player $i^*$ bids $x_{i^*} = 0$, we have $u_{-i^*}(0, 0) = \frac{1}{2} v_{-i^*} < v_{-i^*} - \varepsilon = u_{-i^*}(0, \varepsilon)$ for sufficiently small $\varepsilon > 0$.
            Since $\varepsilon$ can be arbitrarily close to 0, player $-i^*$ does not have a best response to player $i^*$, so a pure strategy Nash equilibrium does not exist.
            If $B_{i^*} > B_{-i^*}$ and player $i^*$ bids $x_{i^*} = v_{i^*}$, then player $-i^*$'s best response is to bid 0, which is different from $R_{-i^*}$. Therefore, there is no pure Nash equilibrium.
            \item $R_{i^*} = B_{i^*}$ and $R_{-i^*} = B_{-i^*}$.
            In this situation, we can know that $B_{i^*} = B_{-i^*} \leq \min\{v_1, v_2\}$.
            We have proven that when $B_{i^*} = B_{-i^*} \leq \frac{1}{2} \min\{v_1, v_2\}$, $(B_{i^*}, B_{-i^*})$ is a pure strategy Nash equilibrium.
            Now we argue the situation where $\frac{1}{2} \min\{v_1, v_2\} < B_{i^*} = B_{-i^*} \leq \min\{v_1, v_2\}$.
            Similar to the above explanation, when $x_{-i^*} \in [0, R_{-i^*})$, there is no pure strategy Nash equilibrium.
            When $x_{-i^*} = R_{-i^*}$, if player $i^*$ bids 0, $u_{i^*}(0, R_{-i^*}) = 0$; 
            if player $i^*$ bids $x_{i^*} \in (0, R_{-i^*})$, $u_{i^*}(x_{i^*}, R_{-i^*}) < 0$; 
            if player $i^*$ bids $x_{i^*} = R_{-i^*}$, let $\hat{i} = \arg \min_{i \in \{1,2\}} \{v_i\}$, $u_{\hat{i}}(R_{\hat{i}}, R_{-\hat{i}}) = \frac{1}{2} v_{\hat{i}} - R_{\hat{i}} < 0$.
            This implies that there will always be a player who gets a higher utility by bidding 0 compared to bidding other values, while the other player will bid a sufficiently small $\varepsilon > 0$. 
            Clearly, this cannot constitute a pure strategy Nash equilibrium.
        \end{itemize}
    \end{enumerate}
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Lemma \ref{lem:support-single-battlefield-supremum}}}
\begin{proof}
    We first demonstrate that $\overline{x}_1 = \overline{x}_2$.
    We prove it by contradiction. 
    Without loss of generality, assume $\overline{x}_1 > \overline{x}_2$.
    For player 1, within the interval $(\overline{x}_2, \overline{x}_1]$, there must exist a bid $x \in Supp(F_1)$. 
    At this bid, we can derive that the utility of player 1 is $u_1(x, F_2) = v_1 - x$.
    Consider another bid $x' \in (\overline{x}_2, \overline{x}_1)$ and $x' < x$, if player 1 bids $x'$, we have that $u_1(x', F_2) = v_1 - x'$.
    Therefore, $u_1(x', F_2) > u_1(x, F_2)$, which means that if player 1's bid deviates from $x$ to $x'$, his utility increases, implying that $x$ is not in his strategy's support, which is a contradiction.

    We next prove that $L = \overline{x}_1 = \overline{x}_2$.
    Without loss of generality, we assume $v_1 \geq v_2$.
    We need to discuss four cases.
    \begin{enumerate}[label = Case (\arabic*), left = 1.5em]
        \item $B_1 \geq v_2$ and $B_2 \geq v_2$.
        We have $L = \min\{B_1, B_2, v_1, v_2 \} = v_2$ because of $v_1 \geq v_2$.
        If player 2's bid exceeds $v_2$, then his utility will definitely be negative. 
        Therefore, player 2's bid will not exceed $v_2$.
        Player 1's bid will not exceed $v_2$ either.
        If $\overline{x}_1 = \overline{x}_2 < L$, for player 1, $\lim_{x_1 \rightarrow \overline{x}_1^-} u_1(x_1, F_2) \leq v_1 - \overline{x}_1 = \lim_{x_1 \rightarrow \overline{x}_1^+} u_1(x_1, F_2)$, which contradicts the fact that $\overline{x}_1$ is the supremum of $Supp(F_1)$.
        Therefore, we conclude that $\overline{x}_1 = \overline{x}_2 = L$.
        \item $B_2 < v_2$ or $B_1 < v_2$. We prove it by contradiction.
        Let $L = B_i$, since player $i$ can't bid more than $L$, suppose the common supremum is $T < L$.
        For any $i$, consider player $i$'s utility when bidding out of $Supp(F_i)$, we have
        \begin{align*}
            \lim_{\varepsilon \rightarrow 0^+} u_i(T + \varepsilon, F_{-i}) = \lim_{x_i \rightarrow T^+} u_i(x_i, F_{-i}) = v_i - T > 0.
        \end{align*}
        This implies that the expected utility of player $i$ in the Nash equilibrium is at least $v_i - T > 0$, and thus $\lim_{x_i \rightarrow \underline{x}_{i}^+} u_i(x_i, F_{-i}) > 0$. 
        This means that $Supp(F_{-i})$ has a positive measure at $\underline{x}_{i}$.
        This indicates that both infimums of players' equilibrium strategies are the same and have positive measure. 
        However, for any $i$, player $i$ can bid $\underline{x}_{i} + \varepsilon$ so that $u_i(\underline{x}_{i} + \varepsilon, F_{-i}) > u_i(\underline{x}_{i}, F_{-i})$ for sufficiently small $\varepsilon$. This would be contradicted to the fact that player $i$'s support has a positive measure at $\underline{x}_i$.
        Therefore, we conclude that $T = L$.
        \item $B_2 < v_2$ and $B_1 \geq v_2$.
        Based on Case (2), it is easy to conclude that $L = \min\{B_1, B_2, v_1, v_2 \} = B_2$ is the supremum of the supports of players' strategies.
        \item $B_2 \geq v_2$ and $B_1 < v_2$.
        Based on Case (2), it is easy to conclude that $L = \min\{B_1, B_2, v_1, v_2 \} = B_1$ is the supremum of the supports of players' strategies.
    \end{enumerate}
    Therefore, we can conclude that $L = \min\{B_1, B_2, v_1, v_2 \} = \overline{x}_1 = \overline{x}_2$ in the Nash equilibrium.
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Lemma \ref{lem:support-single-battlefield-infimum-1}}}
\begin{proof}
    If $\underline{x}_i > 0$, then we have $\forall x_i \in [\underline{x}_i, \overline{x}_i)$, $u_i(x_i, \overline{x}_{-i}) < 0 = u_i(0, \overline{x}_{-i})$.
    This means that the utility obtained by player 1 when bidding 0 is higher than the utility obtained when bidding $x_i \in (0, \overline{x}_i)$.
    If player $i$ bids $x_i \in (\underline{x}_i, \overline{x}_i)$, then $u_i(x_i, \overline{x}_{-i}) < 0$.
    Therefore, we have $\forall x_i \in (\underline{x}_i, \overline{x}_i)$, $x_i \notin Supp(F_i)$.
    It implies that $Supp(F_i) = \{0, 1\}$.

    For player $-i$, we have
    \begin{align*}
        [F_i(0) + \frac{1}{2}(1 - F_i(0))] v_{-i} - L \geq \lim_{x_{-i} \rightarrow 0^+} u_{-i}(F_i, x_{-i}) = \lim_{\varepsilon \rightarrow 0^+} F_i(0) v_{-i} - \varepsilon,
    \end{align*}
    then we can get that $F_i(0) \leq 1 - \frac{2L}{v_{-i}}$ and $1 - F_i(0) \geq \frac{2L}{v_{-i}}$, which means that player $i$ bids $\underline{x}_i$ with a probability of no more than $1 - \frac{2L}{v_{-i}}$, and bids $\overline{x}_i$ with a probability of no less than $\frac{2L}{v_{-i}}$.
    It implies that $F_i(0) \leq 1 - \frac{2L}{v_{-i}}$.

    For player $i$, because of $0 \in Supp(F_i)$, then $i$'s utility is 0.
    For player $-i$, we can deduce that utility is at most $v_{-i} - 2L$.
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Lemma \ref{lem:support-single-battlefield-infimum-2}}}
\begin{proof}
    We first demonstrate that $\underline{x}_1 = \underline{x}_2$.
    We prove it by contradiction. 
    Without loss of generality, assume $\underline{x}_1 < \underline{x}_2$.
    For player 1, within the interval $[\underline{x}_1, \underline{x}_2)$, there must exist a bid $x$ in the support of player 1's strategy. 
    At this bid, we can derive that the utility of player 1 is $u_1(x, F_2) = -x$.
    Consider another bid $x' \in (\underline{x}_1, \underline{x}_2)$ and $x' < x$, if player 1 bids $x'$, we have that $u_1(x', F_2) = -x'$.
    Therefore, we have $u_1(x', F_2) > u_1(x, F_2)$, which means that if player 1's bid deviates from $x$ to $x'$, his utility increases, implying that $x$ is not in his strategy's support, which is a contradiction.

    We next prove that $0 = \underline{x}_1 = \underline{x}_2$.
    If $\underline{x}_1 = \underline{x}_2 > 0$, we consider three cases.
    \begin{itemize}
        \item Neither player has placed a mass point at $\underline{x}_1$.
        Then we have $\lim_{x_1 \rightarrow \underline{x}_i^+} u_1(x_1, F_2) = -\underline{x}_i < 0$, and $u_1(0, F_2) = 0$. 
        Obviously, player 1 can deviate from bidding $\underline{x}_1$ to 0 to achieve higher utility.
        \item Only one player, assuming player 1, places a mass at $\underline{x}_1$.
        Then player 1 gets negative utility at bid $\underline{x}_1$, and player 1 can benefit by deviating from bidding $\underline{x}_1$ to 0.
        \item Both players place masses at $\underline{x}_1$.
        Then we have that, for player 1, $u_1(\underline{x}_1, F_2) < \lim_{\varepsilon \rightarrow 0^+} u_1(\underline{x}_1 + \varepsilon, F_2)$, which means that player 1 can get more utility by transferring the mass at $\underline{x}_1$ to $\underline{x}_1 + \varepsilon$.
    \end{itemize}
    Therefore, there is always a player who increase utility by changing bid when $\underline{x}_1 = \underline{x}_2 > 0$.
    We can conclude that $\underline{x}_1 = \underline{x}_2 = 0$.
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Lemma \ref{lem:support-single-battlefield-continuously-nomass}}}
\begin{proof}
    Without loss of generality, let $B_1 \leq B_2$. According to our auction $\mathcal{G} = \{\{1, 2\}, \{1\}, B_1, B_2, v_{1}, v_{2}, u_1, u_2\}$, we can construct a new all-pay auction $\hat{\mathcal{G}} = \{\{1, 2\}, \{1\}, \hat{v}_{1}, \hat{v}_{2}, u_1, u_2\}$ with no budget constraint, where value $\hat{v}_1 = L$, $\hat{v}_2 = v_2$.

    Let $F_1, F_2$ be equilibrium strategies of player $1, 2$. 
    We can construct strategies of player 1 and 2,
    \begin{align*}
        \hat{F}_1 = F_1, \quad
        \hat{F}_2 = \begin{cases}
            \frac{F_2(x)}{F_2(L^{-})}, & x \in [0,L); \\
            1, & x = L.
        \end{cases}
    \end{align*}
    We have $u_1(x, \hat{F}_2) = \hat{F}_2(x) \cdot \hat{v}_1 - x = F_2(x) \cdot v_{i} - x = u_1(x, F_2)$.
    Obviously, when $\forall x \in Supp(\hat{F}_1)$ where $Supp(\hat{F}_1)$ is the support of strategy of player $1$, $u_1(x, \hat{F}_2)$ can be maximized.
    Similary, we have $u_2(\hat{F}_1, x) = \hat{F}_1(x) \cdot \hat{v}_2 - x = F_1(x) \cdot v_2 - x = u_1(x, F_2)$.
    When $\forall x \in Supp(\hat{F}_2)$ where $Supp(\hat{F}_2)$ is the support of strategy of player $2$, $u_2(\hat{F}_1, x)$ can be maximized.
    Thus for this new auction, by Lemma \ref{lem:support-single-battlefield-Baye-1996}, $\hat{F}_{1}$ and $\hat{F}_{2}$ are the equilibrium strategies of players 1 and 2, which are continuously randomized over the interval $(0, L)$ without any mass points. We can build a one-to-one mapping from set of bid in equilibrium strategies in $\mathcal{G}$ to those in $\hat{\mathcal{G}}$.

    Therefore, over the interval $(0, L)$, equilibrium strategy $F_1, F_2$ in our auction $\mathcal{G}$ and equilibrium strategy $\hat{F}_1, \hat{F}_2$ in the new auction $\hat{\mathcal{G}}$ share the same property of being continuous without any mass points.
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Propositon \ref{propositon-single-item}}}
\begin{proof}
    Let $B_1 = B_2 = 2$, and $v_1 = 4$, $v_2 = 3$, then $L = 2$.
    By possible structures of the support of the players' strategies, we consider three cases:
    \begin{itemize}
        \item Case 1: $Supp(F_1) = \{2\}$ and $Supp(F_2) = \{2\}$.
        Player 1's utility is 0, and player 2's utility is $-\frac{1}{2}$.
        Player 2 can change bid from 2 to 0, which increases utility from $-\frac{1}{2}$ to 0.
        Clearly, this cannot constitute a Nash equilibrium.
        \item Case 2: If $i = 1$, then $Supp(F_1) = \{0, L\}$ and $Supp(F_{2}) = \{L\}$.
        By Lemma \ref{lem:support-single-battlefield-infimum-1}, we can know that the probability of player 1 bidding 0 does not exceed $1 - \frac{2L}{v_{2}} < 0$.
        Obviously, it is impossible.
        If $i = 2$, then $Supp(F_2) = \{0, L\}$ and $Supp(F_{1}) = \{L\}$.
        By Lemma \ref{lem:support-single-battlefield-infimum-1}, we can know that the probability of player 2 bidding 0 does not exceed $1 - \frac{2L}{v_{1}} = 0$.
        When the probability of player 2 bidding 0 is exactly equal to 0, Case 2 reduces to Case 1.
        Therefore, Nash equilibrium does not exist.
        \item Case 3: $\overline{Supp(F_i)} = \{x | 0 \leq x \leq L\}$, $\forall i \in \{1, 2\}$.
        Note that both players do not place a mass at $L$.
        Because if player $i^* \in \{1, 2\}$ place a mass at $L$, then according to the tie-breaking rule, we have
        \begin{align*}
            \lim_{x \rightarrow L^-} u_{-i^*}(F_i, x) &= F_{i^*}(L^-)v_{-i^*} - L \\
            &< (F_{i^*}(L^-) + \frac{1}{2}(1 - F_{i^*}(L^-)))v_{-i^*} - L \\
            &= u_{-i^*}(F_i, L).
        \end{align*}
        It implies that $\exists \delta > 0$ such that $x \in (L - \delta, L)$, $u_{-i^*}(F_i, x) < u_{-i^*}(F_i, L)$.
        It means that the interval $(L - \delta, L) \cap Supp(F_{-i^*}) = \emptyset$, which contradicts Lemma  \ref{lem:support-single-battlefield-continuously-nomass}.
        Since both players do not place a mass at $L$, we can get $u_1 = 2$ and $u_2 = 1$.
        However, both players obtaining positive utility implies that both players have placed mass at 0.
        Hence, there will always be one player who moves the mass at 0 to $\epsilon > 0$ to increase utility as long as $\epsilon$ is small enough.
        This contradicts the fact that 0 is the infimum of supports of players' strategies.
        So, Nash equilibrium does not exist.
    \end{itemize}
    By analyzing all possible structure of support, we can conclude that there is no structure that can satisfy Nash equilibrium.
    Therefore, Nash equilibrium does not exist in this instance.
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Lemma \ref{lem:support-single-battlefield-endpoint-measure}}}
\begin{proof}
    For \textbf{Case 1}, we have $\min\{B_s, v_s\} > \min\{B_w, v_w\} = L$.
    In Nash equilibrium, player $s$'s utility is positive, which means that player $w$ places a mass at $0$.
    For player $s$, if he places a mass at 0, then when $\varepsilon$ is small enough, we have 
    \begin{align*}
        u_s(0, F_w) = \frac{F_w(0)}{2} v_s < F_w(0) v_s - \varepsilon = u_s(\varepsilon, F_w).
    \end{align*}
    It means that player $s$ can move the mass at 0 to $\varepsilon$, thereby increasing utility.
    So, player $s$ does not place a mass at $0$.
    Therefore, player $w$'s utility is $0$.
    We can get $\lim_{x \rightarrow L^-}u_w(F_s, x) = F_s(L^-) v_w - L = 0$, so $F_s(L^-) = \frac{L}{v_w}$.
    The probability that player $s$ bids at $L$ is $1 - \frac{L}{v_w}$.
    If player $w$ places a mass at $L$, then $\exists \delta > 0$ such that for $x \in (L - \delta, L)$, we have $F_w(x) < 1$, and
    \begin{align*}
        u_s(x, F_w) = F_w(x) v_s - (L - \delta) &= F_w(x) v_s - L + \delta \\
        &< v_s - L \\
        &= \lim_{\varepsilon \rightarrow 0^+} F_w(L + \varepsilon) v_s - (L + \varepsilon).
    \end{align*}
    Hence, we can derive that the utility for player $s$ when bidding $L + \varepsilon$ is higher than the utility when bidding $x \in (L - \delta, L)$.
    It implies that $x \in (L - \delta, L)$ is not best response to $F_w$, which contradicts with Lemma \ref{lem:support-single-battlefield-continuously-nomass}.
    Therefore, player $w$ does not place a mass at $L$.
    Then, we can get player $s$'s utility, that is $v_s - L$.
    The probability that player $w$ bids at $0$ can be calculated by the equation $v_s - L = F_w(0) v_s$, that is $\frac{v_s - L}{v_s}$.

    For \textbf{Case 2}, we consider two subcases:
    \begin{itemize}
        \item \text{subcase 2.1:} when $L = \min\{B_s, v_s\} < \min\{B_w, v_w\}$.
        In Nash equilibrium, player $w$'s utility is positive because player $w$ can ensure that his utility is at least $v_w - L - \varepsilon$ by bidding $L + \varepsilon$ as long as $\varepsilon$ is sufficiently small.
        So, we can deduce that player $s$ places a mass at 0, while player $w$ does not place a mass at 0.
        Then we konw that player $s$'s utility is 0.
        According to $0 = F_w(L^-)v_s - L$, we have $F_w(L^-) = \frac{L}{v_s} = 1$, implying player $w$ does not place a mass at $L$.
        According to the tie-breaking rule, we know that $s$ does not place a mass at $L$.
        Then, player $w$'s utility is $F_s(L) v_w - L = v_w - L$.
        Due to $v_w - L = F_s(0) v_w$, we have $F_s(0) = \frac{v_w - L}{v_w}$, implying that the probability that player $s$ bids at 0 is $\frac{v_{w} - L}{v_{w}}$.
        \item \text{subcase 2.2:} when $L = \min\{B_s, v_s\} = \min\{B_w, v_w\}$.
        We note that no player will place a mass at $L$.
        Hence, player $s$'s utility is 0, and player $w$'s utility is $v_w - L$.
        It means that the probability that player $s$ bids at 0 is $\frac{v_w - L}{v_w}$, and player $w$ does not place a mass at 0.
    \end{itemize}
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Lemma \ref{lem:support-single-battlefield-nash-equilibrium-support}}}
\begin{proof}
    For Case (1), we prove it by contradiction.
    Suppose there exists a player $i$ such that $\underline{x}_i < \overline{x}_i = L$.
    By Lemma \ref{lem:support-single-battlefield-infimum-1} and Lemma \ref{lem:support-single-battlefield-endpoint-measure}, there must be a player $i^*$ whose utility is 0.
    We consider two cases:
    \begin{itemize}
        \item If only one player has infimum less than supremum, then we have $Supp(F_{i^*}) = \{0, L\}$, $u_{i^*}(0, F_{-i^*}) = 0$ and $u_{i^*}(L, F_{-i^*}) = \frac{1}{2}v_{i^*} - L > 0$.
        This obviously contradicts $Supp(F_{i^*}) = \{0, L\}$.
        \item If the infimum of support of players' strategies is smaller than the supremum, then we have $Supp(F_{i^*}) = \{x| 0 \leq x \leq L\}$. We also have $u_{i^*}(L, F_{-i^*}) = (F_{-i^*}(L^-) + \frac{1}{2}(1 - F_{-i^*}(L^-)))v_{i^*} - L = (\frac{1}{2} + \frac{1}{2}F_{-i^*}(L^-))v_{i^*} - L > \frac{1}{2}v_{i^*} - L > 0$.
        This obviously contradicts $Supp(F_{i^*}) = \{x| 0 \leq x \leq L\}$.
    \end{itemize}
    Therefore, $\underline{x}_i = \overline{x}_i$ for any $i \in \{1, 2\}$.

    For Case (2), we prove it by contradiction.
    Suppose the infima of both players' strategy supports are 0.
    Then according to Lemma \ref{lem:support-single-battlefield-endpoint-measure}, there must exist a player $i^*$ whose utility is 0.
    Similar to the previous case, player $i^*$ can gain zero utility by bidding 0, while player $i^*$ can gain a positive utility by bidding $\overline{x}_{i^*} = L$, which contradicts our supposition.
    Therefore, at least one player must have an equal infimum and supremum for their strategy support.
    We now consider two cases:
    \begin{itemize}
        \item If every player has an equal infimum and supremum, then we have $Supp(F_{i'}) = \{L\}$ for any $i' \in \{1, 2\}$, and it is easy to verify that $(L, L)$ can form a Nash equilibrium by Lemma \ref{lem:pure-Nash-Equilibirum-single-item}.
        \item If only one player has an equal infimum and supremum, then we have $Supp(F_{i^*}) = \{0, L\}$, by Lemma \ref{lem:support-single-battlefield-infimum-1}, it is easy to verify that this can form a Nash equilibrium when player $i^*$ bids $L$ with a probability of no less than $\frac{2L}{v_{-i^*}}$ and 0 with a probability of no higher than $1 - \frac{2L}{v_{-i^*}}$, while player $-i^*$ bids $L$.
    \end{itemize}

    For Case (3), we prove it by contradiction.
    Suppose there exists a player whose support has an equal infimum and supremum. We consider two cases:
    \begin{itemize}
        \item if for some $i$, $\min\{B_i, v_i \} > \min\{B_{-i}, v_{-i} \}$, then we have $L \in Supp(F_i)$ and $L \in Supp(F_{-i})$.
        However, when player $-i$ bids $L$, its utility is negative, which contradicts $L \in Supp(F_{-i})$.
        \item if $\min\{B_1, v_1 \} = \min\{B_{2}, v_{2} \}$, then we consider three subcases:
        \begin{itemize}
            \item subcase 1: if $L = B_1$, then $B_1 = v_{2} = L$, $B_{2} > B_1$.
            Player 2's utility is $\frac{1}{2}v_{2} - L = \frac{1}{2} L - L < 0$ when he bids $L$.
            \item subcase 2: if $L = B_{2}$, then $B_{2} = v_1 = L$, $B_1 > L$.
            Player 1's utility is $\frac{1}{2}v_1 - L = \frac{1}{2} L - L < 0$ when he bids $L$.
            \item subcase 3: if $L \neq B_{1}$ and $L \neq B_{2}$, then $L = v_1 = v_{2}$.
            Player 1 and player 2 will both get negative utility when they bid $L$.
        \end{itemize}
        Therefore, the infimum of the support for both players' strategies is smaller than the supremum.
        Additionally, we can verify that if $Supp(F_i) = \{x|0 \leq x \leq L\}$ for any $i \in \{1, 2\}$, by Lemma \ref{lem:support-single-battlefield-endpoint-measure}, a Nash equilibrium can be formed.
    \end{itemize}
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Theorem \ref{thm:nash-equilibrium-single-battlefield}}}
\begin{proof}
    For \textbf{Case 1}, by Lemma \ref{lem:support-single-battlefield-nash-equilibrium-support}, it is easy to know that $\underline{x}_i = \overline{x}_i$ for any $i \in \{1, 2\}$.
    By Lemma \ref{lem:pure-Nash-Equilibirum-single-item}, we have that Nash equilibrium is $(B_1, B_2)$.

    For \textbf{Case 2}, by Lemma \ref{lem:support-single-battlefield-nash-equilibrium-support}, we have that
    \begin{itemize}
        \item $\underline{x}_i = \overline{x}_i$ for any $i \in \{1, 2\}$, by Lemma \ref{lem:pure-Nash-Equilibirum-single-item}, the Nash equilibrium is $(B_i, B_{-i})$.
        \item $\underline{x}_i = 0$ and $\underline{x}_{-i} = \overline{x}_{-i}$, by Lemma \ref{lem:support-single-battlefield-infimum-1}, the Nash equilibrium is that player $i$ bids 0 with a probability of no higher than $1 - \frac{2L}{v_{-i}}$ and bids $L$ with a probability of no less than $\frac{2L}{v_{-i}}$; player $-i$ bids $B_{-i}$.
    \end{itemize}

    For \textbf{Case 3}, by Lemma \ref{lem:support-single-battlefield-nash-equilibrium-support}, we have that $\underline{x}_i = 0$ for any $i \in \{1, 2\}$.
    By Lemma \ref{lem:support-single-battlefield-endpoint-measure}, we have that
    \begin{itemize}
        \item when $v_s > L$, for $x \in (0, L)$, $v_s - L = F_w(x)v_i - x$,  thence $F_w(x) = \frac{v_s - L + x}{v_i}$.
        For $x \in [0, L)$, $0 = F_s(x) v_w - x$, thence $F_s(x) = \frac{x}{v_w}$.
        Therefore, Nash equilibrium is as follows:
        \begin{align*}
            F_s(x) = \begin{cases}
                \frac{x}{v_w} \quad &x \in [0, L), \\
                1, & x = L,
            \end{cases}
            \quad
            F_w(x) = \begin{cases}
                \frac{v_s - L}{v_s}, & x = 0, \\
                \frac{v_s - L + x}{v_s}, & x \in (0, L].
            \end{cases}
        \end{align*}
        \item when $v_s = L$, for $x \in [0, L]$, $0 = F_w(x)v_s - x$, thence $F_w(x) = \frac{x}{v_s}$.
        For $x \in (0, L]$, $v_w - L = F_s(x) v_w - x$, thence $F_s(x) = \frac{v_w - L + x}{v_w}$.
        Therefore, Nash equilibrium is as follows:
        \begin{align*}
            F_s(x) = \begin{cases}
                \frac{v_w - L}{v_w}, & x = 0, \\
                \frac{v_w - L + x}{v_w}, & x \in (0, L],
            \end{cases}
            \quad
            F_w(x) = \frac{x}{v_s}, \quad x \in [0, L].
        \end{align*}
    \end{itemize}
\end{proof}

