\noindent {\textbf{Proof of Theorem \ref{thm:two-item-nash-equilibrum-symmetric}}}
\begin{proof}
    We fix $f_1(x_{11}, x_{12})$, and the marginal distribution is $F_{1j}(x_{1j}) = \frac{x_{1j}}{c}$, $x_{1j} \in [0, c]$, $\forall j \in \{1, 2\}$.

    If player 2 bids $(x_{21}, x_{22})$ that satisfies $x_{21} \in [0, c]$ and $x_{22} \in [0, c]$, then player 2's utility is
    \begin{align*}
        F_{11}(x_{21}) v_{21} - x_{21} + F_{12}(x_{22}) v_{22} - x_{22} = (x_{21} + x_{22})(\frac{v_{21}}{c} - 1).
    \end{align*}
    Note that $0 \leq x_{21} + x_{22} \leq B_2$.
    If $c < v_{21}$, then we have $c = B_2$ and $\frac{v_{21}}{c} - 1 > 0$.
    So player 2 can bid $(x_{21}, x_{22})$ satisfying $x_{21} + x_{22} = B_2$ to maximize his utility.
    Obviously, the strategy $f_2(x_{21}, x_{22})$ we construct meets the condition where $x_{21} + x_{22} = B_2$.
    If $c = v_{21}$, then we have $\frac{v_{21}}{c} - 1 = 0$.
    So regardless of how player 2 bids, player 2's utility is always 0.
    Obviously, the strategy $f_2(x_{21}, x_{22})$ we constructed is a best response to $f_1$ when $x_{21} \in [0, c]$ and $x_{22} \in [0, c]$.

    If player 2 bids $(x_{21}, x_{22})$ that satisfies $x_{2j} > c$, $\exists j \in \{1, 2\}$.
    We have two cases:
    \begin{itemize}
        \item Case 1: $c = B_2$. It is impossible to bid $x_{2j} > c$.
        \item Case 2: $c = v_{2j}$. Then on the item 2, player 2's utility is $v_{2j} - x_{2j} < 0$.
    \end{itemize}
    Hence, we can deduce that if $x_{2j} > c$, $\exists j \in \{1, 2\}$, player 2's utility is less than utility of the case where $x_{2j} \in [0, c]$, for any $j \in \{1, 2\}$.
    Therefore, we can conclude that $f_2$ is a best response to $f_1$.

    Similarly, fixing $f_2$, we can conclude that $f_1$ is a best response to $f_2$.
    Therefore, the strategy profile $(f_1, f_2)$ is a Nash equilibrium.
\end{proof}

\vspace{5pt}
\noindent {\textbf{Proof of Theorem \ref{thm:nash-equilibrium-two-items-case1}}}
\begin{proof}
    Before proving it, we need to note the following facts: $x_{i1} + x_{i2} \leq B_i$, $\forall i \in \{s, w\}$, $L_1 = \min\{v_{w1}, B_w\}$ and $L_2 = \min\{v_{w2}, B_w\}$.

    First, we prove $f_w(x_{w1}, x_{w2})$ is a best response to $f_s(x_{s1}, x_{s2})$.

    We calculate the marginal distribution of player $s$ over the two items, which are:
    \begin{align*}
        F_{s1}(x_{s1}) = \begin{cases}
            \frac{x_{s1}}{v_{w1}}, \quad &x_{s1} \in [0, L_1); \\
            1, \quad &x_{s1} = L_1;
        \end{cases}
        \quad
        F_{s2}(x_{s2}) = \begin{cases}
            \frac{x_{s2}}{v_{w2}}, &x_{s2} \in [0, L_2); \\
            1, &x_{s2} = L_2.
        \end{cases}
    \end{align*}
    When player $w$ bids $(x_{w1}, x_{w2})$ satisfying $x_{w1} \in [0, L_1]$ and $x_{w2} \in [0, L_2]$, the utility is as follows:
    \begin{align*}
        u_w(f_s(x_{s1}, x_{s2}), (x_{w1}, x_{w2})) &= u_{w1}(F_{s1}(x_{s1}), x_{w1}) + u_{w2}(F_{s2}(x_{s2}), x_{w2}) \\
        &= \frac{x_{w1}}{v_{w1}} v_{w1} - x_{w1} + \frac{x_{w2}}{v_{w2}} v_{w2} - x_{w2} \\
        &= 0.
    \end{align*}
    It implies that as long as player $w$'s bid $x_{wj}$ satisfies $x_{wj} \leq L_j$, their utility on item $j$ is always 0, regardless of the value of $L_j$.
    It is clear that the strategy $f_w(x_{w1}, x_{w2})$ we constructed satisfies $x_{wj} \leq L_j$.
    Therefore, $f_w(x_{w1}, x_{w2})$ is a best response to $f_s(x_{s1}, x_{s2})$ when $x_{w1} \in [0, L_1]$ and $x_{w2} \in [0, L_2]$.

    When the situation occurs where $x_{wj} > L_j$, $\exists j \in \{1, 2\}$, according to the different values of $L_j$, we further divide it into the following four situations, and we analyze each situation in detail.
    \begin{itemize}
        \item Case (1.1): $L_1 = B_w$ and $L_2 = B_w$;
        \item Case (1.2): $L_1 = B_w$ and $L_2 = v_{w2}$;
        \item Case (1.3): $L_1 = v_{w1}$ and $L_2 = v_{w2}$;
        \item Case (1.4): $L_1 = v_{w1}$ and $L_2 = B_w$.
    \end{itemize}
    Dut to $x_{w1} + x_{w2} \leq B_s$, the Case (1.1) will not happen.

    For Case (1.2), $L_1 = B_w$ and $L_2 = v_{w2}$, we have the following subcases:
    \begin{itemize}
        \item subcases 1.2.1: $x_{w1} > L_1 = B_w$ and $x_{w2} > L_2$. Obviously, it can not happen.
        \item subcases 1.2.2: $x_{w1} \leq L_1 = B_w$ and $x_{w2} > L_2$. Obviously, player $w$'s utility is 0 on the item 1 and negative on the item 2.
        The total utility is negative.
        \item subcases 1.2.3: $x_{w1} > L_1 = B_w$ and $x_{w2} \leq L_2$. Obviously, it can not happen.
    \end{itemize}

    For Case (1.3), $L_1 = v_{w1}$ and $L_2 = v_{w2}$, we have the following subcases:
    \begin{itemize}
        \item subcases 1.3.1: $x_{w1} > L_1$ and $x_{w2} > L_2$. Obviously, player $w$'s utility is negative on the item 1 and item 2.
        \item subcases 1.3.2: $x_{w1} \leq L_1$ and $x_{w2} > L_2$. Obviously, player $w$'s utility is 0 on the item 1 and negative on the item 2.
        The total utility is negative.
        \item subcases 1.3.3: $x_{w1} > L_1$ and $x_{w2} \leq L_2$. Obviously, player $w$'s utility is negative on the item 1 and 0 on the item 2.
        The total utility is negative.
    \end{itemize}

    For Case (1.4), $L_1 = v_{w1}$ and $L_2 = B_w$, this is similar to Case (2).

    Therefore, if $\exists j \in \{1, 2\}$, player $w$ bids $x_{wj} > L_j$, player $w$ always gets negative utility.
    Player $w$ will not bid more than $L_j$ on any item $j$.
    Hence, $f_w(x_{w1}, x_{w2})$ is a best response to $f_s(x_{s1}, x_{s2})$ for any $(x_{w1}, x_{w2})$ that satisfies $x_{w1} + x_{w2} \leq  B_w$.

    Next, we prove $f_s(x_{s1}, x_{s2})$ is a best response to $f_w(x_{w1}, x_{w2})$.
    We calculate the marginal distribution of player $w$ over the two items, which are:
    \begin{align*}
        F_{w1}(x_{w1}) = \begin{cases}
            1 - \frac{L_1}{v_{s1}}, &x_{w1} = 0; \\
            1 - \frac{L_1}{v_{s1}} + \frac{x_{w1}}{v_{s1}}, &x_{w1} \in (0, L_1];
        \end{cases}
    \end{align*}
    \begin{align*}
        F_{w2}(x_{w2}) = \begin{cases}
            1 - \frac{L_2}{v_{s2}}, &x_{w2} = 0; \\
            1 - \frac{L_2}{v_{s2}} + \frac{x_{w2}}{v_{s2}}, &x_{w2} \in (0, L_2].
        \end{cases}
    \end{align*}
    When player $s$ bids $(x_{s1}, x_{s2})$ satisfying $x_{s1} \in [0, L_1]$ and $x_{s2} \in [0, L_2]$, the utility is as follows:
    \begin{align*}
        u_s((x_{s1}, x_{s2}), f_w(x_{w1}, x_{w2})) &= u_{s1}(x_{s1}, F_{w1}(x_{w1})) + u_{s2}(x_{s2}, F_{w2}(x_{w2})) \\
        &= (1 - \frac{L_1}{v_{s1}} + \frac{x_{s1}}{v_{s1}}) v_{s1} - x_{s1} + (1 - \frac{L_2}{v_{s2}} + \frac{x_{s2}}{v_{s2}}) v_{s2} - x_{s2} \\
        &= v_{s1} - L_1 + v_{s2} - L_2.
    \end{align*}
    It implies that as long as player $s$'s bid $x_{sj}$ satisfies $x_{sj} \leq L_j$, their utility on item $j$ is always $v_{s1} - L_1 + v_{s2} - L_2$.
    It is clear that the strategy $f_s(x_{s1}, x_{s2})$ we constructed satisfies $x_{sj} \leq L_j$.
    Therefore, $f_s(x_{s1}, x_{s2})$ is a best response to $f_w(x_{w1}, x_{w2})$ when $x_{s1} \in [0, L_1]$ and $x_{s2} \in [0, L_2]$.
    If $\exists j \in \{1, 2\}$ such that $x_{sj} > L_j$, then player $s$'s utility on the item $j$ is $v_{sj} - x_{sj}$, which is less than $v_{sj} - L_j$.
    It means that on item $j$, as long as player $s$'s bid exceeds $L_j$, his utility will be less than $v_{sj} - L_j$, which will cause his total utility to be less than $v_{s1} - L_1 + v_{s2} - L_2$.
    Therefore, we can conclude that on every item, player $s$'s bid does not exceeds $L_j$.
    Hence, $f_s(x_{s1}, x_{s2})$ is a best response to $f_w(x_{w1}, x_{w2})$ for any $(x_{s1}, x_{s2})$ that satisfies $x_{s1} + x_{s2} \leq  B_s$.
\end{proof}


\begin{theorem}\label{thm:nash-equilibrium-two-items-case4}
    Given the profile $(B_1, B_2, v_{11}, v_{12}, v_{21}, v_{22})$ with $B_1 \neq B_2$, if $v_{s1} = L_1$ and $v_{s2} > L_2$, then the following strategies can form a Nash equilibrium:
    \begin{align*}
        f_s(x_{s1}, x_{s2}) = \begin{cases}
            \frac{1}{v_{w2}}, &x_{s1} = 0, \, x_{s2} \in [T_2, L_2]; \\
            \frac{\frac{L_1}{v_{w1}}}{\sqrt{L_1^2 + T_2^2}}, &x_{s1} \in (0, L_1], \, x_{s2} \in [0, T_2), \, x_{s2} = -\frac{T_2}{T_1} x_{s1} + T_2,
        \end{cases}
    \end{align*}
    where $T_2 = \frac{L_1}{v_{w1}} v_{w2}$.
    \begin{align*}
        f_w(x_{w1}, x_{w2}) = \begin{cases}
            \frac{1}{v_{s1}}, &x_{w1} \in [T_3, L_1], \, x_{w2} = 0; \\
            \frac{\frac{L_2}{v_{s2}}}{\sqrt{L_2^2 + T_3^2}}, &x_{w1} \in [0, T_3), \, x_{w2} \in (0, L_2],
        \end{cases}
    \end{align*}
    where $T_3 = L_1 - v_{s1} + \frac{L_2}{v_{s2}} v_{s1}$.
\end{theorem}

