\label{tab:tag-mapping}
\begin{tabular}{p{5cm} p{2cm}}
\toprule
\textbf{Annotation Tag / Mark} & \textbf{Mapped Text} \\
\midrule
\texttt{hesitation}         & \# \\
\texttt{speech-unit-question}    & ? \\
\texttt{speech-unit-statement}  & . \\
\texttt{speech-unit-incomplete} & ... \\
\texttt{partial} (word)         & word- \\
\texttt{backchannel}            & word only (mark dropped) \\
\texttt{disfluency}             & word only (mark dropped) \\
