\section{DEM-C Formulation of Rigid Body Contact}

\subsection{Derivation of Collision Force in Global Frame}
\label{app:fcol_global}

The evolution of $p_i, v_i \in \mathbb{R}^3$, which denote the position and velocity of the center of mass of the $i$-th sphere, is given by Newton's second law of motion:
\begin{equation*}
    \frac{\D p_i}{\D t} = v_i, \quad m_i \frac{\D v_i}{\D t} = f_i + f_i^\text{col},
\end{equation*}
where $f_i$ and $f_i^\text{col}$ are the external and collision force acting on the $i$-th sphere. Consider the $k$-th contact between the $i_k$- and $j_k$-th spheres, and let $\nu_k, \tau_{k,1}, \tau_{k,2}$ be the orthonormal coordinate frame local to the contact: $\nu_k$ is normal to the contact plane and points toward the $j_k$-th sphere while $\tau_{k,1}, \tau_{k,2}$ span the contact plane. We decompose the contact force acting on the $j_k$-th sphere due to the $k$-th contact in this local coordinate frame as \begin{equation*}
    f_{(k)}^\text{col} = \gamma_{k,n} \nu_k + \gamma_{k,1} \tau_{k,1} + \gamma_{k,2} \tau_{k,2};
\end{equation*}
an equal and opposing force $-f_{(k)}^\text{col}$ is active on the $i_k$-th sphere by Newton's third law. We obtain the contact force on the $i$-th sphere by summing the contribution from all collision pairs:
\begin{equation}
    \label{eq:fcol_local}
    f_i^\text{col}
    = \sum_{\substack{k = 1\\j_k = i}}^{n_c} f_{(k)}^\text{col} + \sum_{\substack{k = 1\\i_k = i}}^{n_c} (- f_{(k)}^\text{col})
    = \sum_{\substack{k = 1\\j_k = i}}^{N_c} (\gamma_{k,\nu} \nu_k + \gamma_{k,1} \tau_{k,1} + \gamma_{k,2} \tau_{k,2}) - \sum_{\substack{k = 1\\i_k = i}}^{n_c} (\gamma_{k,\nu} \nu_k + \gamma_{k,1} \tau_{k,1} + \gamma_{k,2} \tau_{k,2}).
\end{equation}
To derive the collision force in the global coordinates, we define the $\text{L2G}_k$ operator that maps a vector $y \in \mathbb{R}^3$ in the local coordinate frame of the $k$-th contact to a global vector $z = \text{L2G}_k(y) \in \mathbb{R}^{3 n_b}$. The components of the output vector $z = (z_1, \ldots, z_{3 n_b})$ of this operation is related to the components of the input vector $y = (y_1, y_2, y_3)$ as
\begin{equation*}
    z_\ell =
    \begin{cases}
        -y_{\ell + 3 - 3 i_k} & \text{if} \quad 3 i_k - 2 \leq \ell \leq 3 i_k \\
        y_{\ell + 3 - 3 j_k} & \text{if} \quad 3 j_k - 2 \leq \ell \leq 3 j_k \\
        0 & \text{otherwise}.
    \end{cases}
\end{equation*}
Let $d_{k,\nu} = \text{L2G}_k(\nu_k)$, $d_{k,1} = \text{L2G}_k(\tau_{k,1})$, and $d_{k,2} = \text{L2G}_k(\tau_{k,2})$ be the global direction vectors associated with the local frame. Then, given the expression of global collision force in \cref{eq:fcol_global},
\begin{equation*}
    f^\text{col} = \sum_{k = 1}^{n_c} (\gamma_{k,\nu} d_{k,\nu} + \gamma_{k,1} d_{k,1} + \gamma_{k,2} d_{k, 2}),
\end{equation*}
it is straightforward to verify that $f^\text{col}(3 i - 2 : 3 i)$, the segment of the global collision force vector corresponding to sphere $i$, agrees with \cref{eq:fcol_local}.

We use this $\text{L2G}_k$ operator to also define the generalized vectors corresponding to the linearized direction vectors of the $k$-th contact: $\widehat{d}_{k,\ell} = \text{L2G}_k(\widehat{\tau}_{k,\ell})$ for $1 \leq \ell \leq s$.

\subsection{Dissipation Formulation of Coulomb Friction}
\label{app:coulomb}

The Coulomb model imposes two restrictions on the frictional contact force: (i) the maximum magnitude of the frictional force is proportional to the magnitude of the normal contact force, and (ii) the frictional force opposes the relative motion between the pair of particles. Given coefficient of friction $\mu$, the first condition yields an inequality constraint,
\begin{equation*}
    \sqrt{\gamma_{k,1}^2 + \gamma_{k,2}^2} \leq \mu \gamma_{k,\nu},
\end{equation*}
that defines the Coulomb friction cone. To obtain a mathematical expression for the second condition, we observe that for a given vector $y \in \mathbb{R}^3$ and the generalized velocity vector $v = (v_1, \ldots, v_{n_b})$ of the system, we have
\begin{equation*}
    \text{L2G}_k(y)^\top v = -y^\top v_{i_k} + y^\top v_{j_k} = y^\top (v_{j_k} - v_{i_k}).
\end{equation*}
It follows that
\begin{equation*}
    \begin{split}
        (\gamma_{k,1} d_{k,1} + \gamma_{k,2} d_{k,2})^\top v
        &= \gamma_{k,1} d_{k,1}^\top v + \gamma_{k,2} d_{k,2}^\top v \\
        &= \gamma_{k,1} \text{L2G}_k(\tau_{k,1})^\top v + \gamma_{k,2} \text{L2G}_k(\tau_{k,2})^\top v \\
        &= \gamma_{k,1} \tau_{k,1}^\top (v_{j_k} - v_{i_k}) + \gamma_{k,2} \tau_{k,2}^\top (v_{j_k} - v_{i_k}) \\
        &= (\gamma_{k,1} \tau_{k,1} + \gamma_{k,2} \tau_{k,2})^\top (v_{j_k} - v_{i_k}) \\
        &= f_{(k)}^{\text{fric},\top} (v_{j_k} - v_{i_k}).
    \end{split}
\end{equation*}
For a given velocity $v$ of the system, minimizing this vector dot product ensures that the friction force $f_{(k)}^\text{fric}$ points in the opposite direction to the relative velocity $v_{j_k} - v_{i_k}$ between the colliding particles projected onto the contact plane. We have reformulated the Coulomb friction model as a maximal dissipation law stated in \cref{eq:coulomb_dissipation}:
\begin{equation*}
    (\gamma_{k,1}, \gamma_{k,2}) = \operatorname*{argmin}_{\sqrt{\widehat{\gamma}_{k,1}^2 + \widehat{\gamma}_{k,2}^2} \leq \mu \gamma_{k,\nu}} (\widehat{\gamma}_{k,1} d_{k,1} + \widehat{\gamma}_{k,2} d_{k,2})^\top v.
\end{equation*}

This property of the $\text{L2G}_k$ operator is also used in \cref{sec:lcp_formulation} to derive a complementarity condition. Note that
\begin{equation*}
    d_{k,\nu}^\top v = \text{L2G}_k(\nu_k)^\top v = \nu_k^\top (v_{j_k} - v_{i_k}),
\end{equation*}
i.e., $d_{k,\nu}^\top v$ is the magnitude of the relative velocity between the particles of the $k$-th contact along the normal direction. It is zero when the particles are colliding, and positive after the contact ends.

