%\subsection{The $g$-index}
%Suppose that an author has $m$ papers with $x_1, \dots, x_m$ citations.
Next, the definition of the $g$-index can be written mathematically as follows,
\begin{equation}
\label{eq:gindexDF}
g\equiv g(\boldsymbol{x})=\max\left\{1\le k\le m\colon \sum_{i=1}^{k}x_{i}\ge k^2\right\}\!.
\end{equation}
Note that if $\boldsymbol{x}=\boldsymbol{0}$ (i.e., all $x_i=0$) then the set under the max-symbol is empty, in which case, by the same convention, we define the maximum as zero. That is to say, the $g$-index for the zero citation vector equals zero:
\begin{equation}\label{eq:g0}
g(\boldsymbol{0})=0.
\end{equation}
Also note that, because the testing range of $k$'s in  \eqref{eq:gindexDF} is bounded by $m$, we must have
\begin{equation}\label{eq:g<m}
g\le m.
\end{equation}

It can be shown that the $g$-index is not smaller than the $h$-index of the same author \citep[Proposition I.2. p.\,133]{egghe2006theory},
\begin{equation}
\label{eq:hg}
h\le g.
\end{equation}
Indeed, if the $h$-index has value $h$ then there are $h$ papers with at least $h$ citations each, and therefore with at least $h\times h=h^2$ citations in total. Hence, the trial value $k=h$ satisfies the inequality condition in \eqref{eq:gindexDF}, which implies that $g\ge k=h$, as claimed.

Denote $s_k=x_1+\dots+x_k$. According to definition \eqref{eq:gindexDF}, the index $g$ is the largest value of $k$ for which $s_k\ge k^2$. But it may be unclear whether the inequality $s_k\ge k^2$ can fail for some $k<g$. Let us show that $s_k\ge k^2$ \emph{for all} $k\le g$.

\begin{lemma}
If $s_k<k^2$ for some $k\ge 1$, then $s_{\ell}<\ell^2$ for all $\ell\ge k$.
\end{lemma}
\proof
Using that $x_k=\min\{x_1,\dots,x_k\}$, we have
$$
k^2>s_k=x_1+\dots+x_k\ge k\myp x_k,
$$
which implies that $k>x_k\ge x_{k+1}$. Hence,
$$
s_{k+1}=s_k+x_{k+1}<k^2+k<(k+1)^2,
$$
that is, $s_{k+1}<(k+1)^2$. The general claim then follows by induction.
\endproof

\begin{lemma}
If $s_k<k^2$ then $g<k$. In particular, if $s_m<m^2$ then $g<m$; otherwise, $g=m$.
\end{lemma}
\proof Readily follows by Lemma 1 and definition \eqref{eq:gindexDF}.
\endproof

Turning to the verification of the required properties (C1)--(C3) for the $g$-index, we see that (C1) automatically holds due to \eqref{eq:g0}. It is also easy to see that (C3) holds as well. However, the result of Lemma 2 suggests that, a bit surprisingly, property (C2) may fail. For instance, for $\boldsymbol{x}=(4)$, we have $g(\boldsymbol{x})=1$, but for $\boldsymbol{y}=(4,0,0,0)$ (i.e., with three fictitious zeros added), definition \eqref{eq:gindexDF} yields $g(\boldsymbol{y})=2$.

To salvage (C2), and also to amplify the role of top-cited papers, it was suggested \citep{egghe2006theory, woeginger2008axiomatic} to lift the constraint $k\le m$ in the definition of the $g$-index (see \eqref{eq:gindexDF}) by complementing the citation vector $\boldsymbol{x}=(x_1,\dots,x_m)$ with  additional zeros, as if such papers have been published. We denote this version of $g$ by $g^*$:
\begin{equation}
\label{eq:gindex*}
g^*\equiv g^*(\boldsymbol{x})=\max\left\{k\ge 1\colon \sum_{i=1}^{k}x_{i}\ge k^2\right\}\!.
\end{equation}

This makes no difference if $g\le m$, because then $g^*=g$. However, the case where $g=m$ may be drastically different.

\begin{lemma}
Suppose that $s_m\ge (m+1)^2$. Then $g^*=\bigl\lfloor\sqrt{s_m}\bigr\rfloor\ge m+1>m=g$.
\end{lemma}
\proof Adding $%\bigl\lfloor\sqrt{s_m}\bigr\rfloor
g^*-m\ge 1$ fictitious zeros to the citation vector $\boldsymbol{x}$, we get a new vector $\boldsymbol{x}'=(x_1,\dots,x_m,0,\dots, 0)$ of dimension $m+(g^*-m)=g^*$, resulting in
$$
\sum_{i=1}^{g^*} x'_i =s_m \ge (g^*)^2,
$$
and it follows that $g^*=\bigl\lfloor\sqrt{s_m}\bigr\rfloor$.
\endproof

A striking example illustrating this situation is the case of John Nash \citep{woeginger2008axiomatic}, with the (rounded) citation vector
$\boldsymbol{x}=(2000, 2000, 1500, 1000, 400, 250, 100, 100)$, for which we get $g=8$ but $g^*=85$.

\subsection*{3. An alternative citation index $\nu$}\label{sec:3.4.3}
Trying to reconcile the definition of the $h$-index given by formula  \eqref{eq:hindexDF}, with the definition of the $g$-index in \eqref{eq:gindexDF} by taking into account the actual citations of the top papers, we propose a new citation index called  the \emph{$\nu$-index}, defined as the maximum integer $\nu$ such that the total sum of citation counts of papers with at least $\nu$ citations each is not less than $\nu^2$. Mathematically, this is expressed as (cf.\ \eqref{eq:hindexDF})
\begin{equation}
  \nu\equiv \nu(\boldsymbol{x})=\max\left\{j\ge 1\colon \sum_{i=1}^{m} x_i\mypp {\bf 1}_{\{x_i\ge j\}}\ge j^2 \right\}\!.
\label{eq:gindexDF-old}
\end{equation}
