% \end{example}

%\null
\begin{lemma}
    The indexes $\nu$ and $\bar{\nu}$ satisfy the basic properties (C1)--(C3).
\end{lemma}
\begin{proof}
Properties (C1) and (C2) are straightforward, since $\nu$ and $\bar{\nu}$ are insensitive to zero values $x_i=0$. Monotonicity (C3) is also obvious because the sums in \eqref{eq:gindexDF-old} and \eqref{eq:nu-bar} are monotone increasing in each component $x_i$.
\end{proof}

The $\nu$-index combines the features of both the $h$-index and the $g$-index. It takes into account citations that are equal to or greater than a minimum threshold value of $\nu$ as in the $h$-index, while also including higher citations as in the $g$-index. This ensures that the $\nu$-index captures the impact of highly cited papers and provides a more balanced picture of their overall scholarly impact. In particular, it may be expected that the $\nu$-index interpolates between $h$ and $g$. The next result supports this conjecture.

\begin{theorem}
The citation indexes $h$, $\nu$, $\bar{\nu}$, $g$ and $g^*$ are in the following relations:
\begin{align}\label{eq:hgnu}
h &\le \nu \le g^*,\\[.3pc]
\label{eq:hg*barnu}
h &\le \bar{\nu} \le g.
\end{align}
\end{theorem}
\proof We only prove inequalities \eqref{eq:hgnu}; the proof of \eqref{eq:hg*barnu} is similar.
First, by definition of $h$ in \eqref{eq:hindexDF} we can write
$$
h\le \sum_{i=1}^m {\bf 1}_{\{x_i\ge h\}}= \frac{1}{h} \sum_{i=1}^m x_i\mypp {\bf 1}_{\{x_i\ge h\}}.
$$
Hence,
$$
\sum_{i=1}^m x_i\mypp {\bf 1}_{\{x_i\ge h\}}\ge h^2,
$$
which implies, according to \eqref{eq:gindexDF-old}, that $\nu\ge h$, as claimed.

%and from the defining condition \eqref{eq:gindexDF-old} we conclude that $h\le\nu$.
%$$
%h\le \sum_{\ell\ge h} m_\ell\le \frac{1}{h}\sum_{\ell\ge h} \ell\mypp m_\ell\le \frac{\nu^2}{h},
%$$
%according to \eqref{eq:gindexDF-M}, and it follows that $h\le \nu$.

Next, let the maximizing sum in \eqref{eq:gindexDF-old} be expressed as
\begin{equation}\label{eq:J}
\nu^2\le \sum_{i=1}^{m} x_i\mypp {\bf 1}_{\{x_i\ge \nu\}}=\sum_{i=1}^{k^*}x_{i},
\end{equation}
thus involving $k^*$ terms $x_{i}$, each one satisfying the inequality \begin{equation}\label{eq:>ell}
x_{i}\ge \nu \qquad (i=1,\dots,k^*).
\end{equation}
If $k^*\le \nu$ then from \eqref{eq:J} we obtain
$$
\nu^2\le \sum_{i=1}^{k^*}x_{i}\le \sum_{i=1}^{\nu}x_{i},
$$
and it follows from  definition \eqref{eq:gindex*} that $g^*\ge \nu$. Alternatively, if $k^*\ge \nu$ then, using \eqref{eq:>ell}, we can write
$$
\sum_{i=1}^{k^*}x_{i}\ge \sum_{i=1}^{\nu}x_{i}\ge \sum_{i=1}^{\nu} \nu=\nu^2,
$$
and, as before, it follows  that $g^*\ge \nu$.
\endproof
