\subsection{MCTS-Style Tree Exploration for \bab-Based Verification}\label{sec:mctsApproach}




\begin{algorithm}[!tb]
\caption{\tool: An MCTS-style verification algorithm}
\label{alg:mcts_nn_verify}
\footnotesize
\begin{algorithmic}[1]
\Require A neural network $\originNetwork$, input and output specification $\Phi$ and $\Psi$, an approximated verifier $\verifier(\cdot)$, a ReLU selection heuristic $\reluHeuristic(\cdot)$, and hyperparameters $\lambda$ and $c$.
\Ensure A $\mathit{verdict} \in \{\true, \false, \mathtt{timeout}\}$ 

\Statex
\State $\langle\specDist, \ce\rangle\gets \verifier(\originNetwork, \Phi, \Psi, \varepsilon)$ \label{line:appToOrigin}
\State $\reward(\varepsilon)\gets \seman{\varepsilon}$ \label{line:originR}
\State $\specTree(\varepsilon) \gets \{\varepsilon\}$ \label{line:originTree}
\If{$\specDist<0$ and $\mathtt{not\;valid}(\ce)$}
\While{not reach termination condition}\label{line:whileLoop}
\State \Call{MCTS-BaB}{$\varepsilon, \originNetwork, \Phi, \Psi$}\label{line:callGreedyBaBRoot}
\EndWhile
\State\label{line:return}\Return
$
\begin{cases}
    \true & \text{if } \reward(\varepsilon) = -\infty \\
    \false & \text{if } \reward(\varepsilon) = +\infty \\
    \mathtt{timeout} & \text{otherwise}
\end{cases}
$
\Else \label{line:originConclude}
\State \label{line:originReturn}\Return
$
\begin{cases}
    \true & \text{if }\specDist > 0 \\
    \false & \text{if } \specDist < 0 \text{ and } \mathtt{valid}(\ce)
\end{cases}
$
\EndIf
\Statex
\Function{MCTS-BaB}{$\reluSpec, \originNetwork, \Phi, \Psi$}
\State $\reluAction_k\gets \reluHeuristic(\reluSpec)$ \label{line:reluSelect} \Comment{select a ReLU}
\If{$\reluSpec \cdot \reluActionPos_k \in \specTree$}\label{line:checkExists}
%\State $\reluSpec^*\gets \argmax_{a\in\{\reluActionPos_k, \reluActionNeg_k\}}{\reward(\reluSpec\cdot a)}$
%to check
\State $\reluSpec^* \gets \argmax_{a\in\{\reluActionPos_k, \reluActionNeg_k\}} \left( \reward(\reluSpec\cdot a) + c\sqrt{\frac{2\ln |\specTree(\reluSpec)|}{|\specTree(\reluSpec\cdot a)|}} \right)$\label{line:UCB1}
\vspace{2pt}
\Statex\Comment{Select a child by UCB1}
\State \Call{MCTS-BaB}{$\reluSpec^*, \originNetwork, \Phi, \Psi$}\label{line:recursiveCall} \Comment{recursive call}
\Else
\For{$a\in\{\reluActionPos_k, \reluActionNeg_k\}$}\label{line:expandChildren}
    \State $\langle\specDist, \ce\rangle \gets \verifier(\originNetwork, \Phi, \Psi, \reluSpec \cdot a)$ \label{line:verifierSubTree}
    \vspace{2pt}
    \State $\reward(\reluSpec\cdot a) \gets    \seman{\reluSpec\cdot a}$ \label{line:rewardSubtree}
    \State $\specTree(\reluSpec\cdot a) \gets \{\reluSpec\cdot a\}$ \label{line:updateTree}
\EndFor
\EndIf
\State $\reward(\reluSpec)\gets \argmax_{a\in\{\reluActionPos_k, \reluActionNeg_k \}}{\seman{\reluSpec\cdot a}}$\label{line:backpropagateR} \Comment{back-propagate rewards}
\vspace{2pt}
\State $\specTree(\reluSpec) \gets \specTree(\reluSpec) \cup \specTree(\reluSpec \cdot \reluActionPos_k) \cup \specTree(\reluSpec \cdot \reluActionNeg_k)$ \label{line:backpropagateTree} \Comment{record new nodes}
\EndFunction
\end{algorithmic}
\end{algorithm}

