    \paragraph{type 1 (0-consecutive participation)} $s^* = 0$;
    \paragraph{type 2 ($k^*$-consecutive participation)} $s^*$ forms a $k^*$-consecutive participation, where
    \begin{align}\label{eq: k* explicit form}
        k^* = \begin{dcases}
            m, \quad\text{if }\; 0 \le \Delta < \frac{2a}{mn};\\
            \ceil*{\frac{2a}{n\Delta}-1} \text{ or } \floor*{\frac{2a}{n\Delta}}, \quad\text{if }\; \frac{2a}{mn} \le \Delta \le \frac{a}{n};\\
