\begin{lemma}
    \label{lemma:lifting}
    Let $g : M \to N$ be a surjection between $\Pscr$-persistence modules, and let $h : P \to N$ with $P$ projective of finite rank.
    There exists a morphism $h' : P \to M$ such that $g \circ h' = h$.
\end{lemma}


