\begin{lemma}
    \label{lemma:betti-table-characterization}
    If $M$ is projective of finite rank, then there exists exactly one function (necessarily of finite support) $\beta^M : \Pscr \to \Nbb$ such that $M \cong \bigoplus_{r \in \Pscr} \Psf_r^{\beta^M(r)}$.\qed
\end{lemma}


\begin{definition}
    The \emph{Betti table} of a persistence module $M : \Pscr \to \vect$
    that is projective of finite rank is the function $\beta^M : \Pscr \to \Nbb$ of Lemma \ref{lemma:betti-table-characterization}.
\end{definition}

The following notation is sometimes convenient.

\begin{notation}
    If $r \in \Pscr$, we let $\delta_r : \Pscr \to \Nbb$ be the function defined by $\delta_r(r) = 1$ and $\delta_r(s) = 0$ if $s \neq r$.
    In particular, $\delta_r = \beta^{\Psf_r} : \Pscr \to \Nbb$.
\end{notation}

\begin{definition}
    Let $M : \Pscr \to \vect$ be a $\Pscr$-persistence module.
    A \emph{finite projective cover} of $M$ is a surjective morphism $P \to M$ where $P$ is projective of finite rank, and $\sum_{r \in \Pscr} \beta^P(r) \in \Nbb$ is minimal.
\end{definition}

