    %\end{itemize}
    A \emph{finite projective $k$-resolution} (resp.~\emph{minimal finite projective $k$-resolution}) of $M$, denoted $C_\bullet \to M$, is a sequence of morphisms
    $C_k \xrightarrow{\partial_{k}} C_{k-1} \xrightarrow{\partial_{k-1}} \cdots \xrightarrow{\partial_2} C_1 \xrightarrow{\partial_1} C_0 \xrightarrow{\partial_0} M$ satisfying 
    \begin{itemize}
        \item $C_0 \to M$ is surjective (resp.~a projective cover);
        \item $\partial_i \circ \partial_{i+1} = 0$, for every $0 \leq i \leq k-1$ (so that $\partial_{i+1}$ factors through $\ker \partial_i$);
        \item $C_{i+1} \xrightarrow{\partial_{i+1}} \ker(\partial_i)$ is surjective (resp.~a projective cover), for every $0 \leq i \leq k-1$;
        \item $C_i$ is projective of finite rank, for every $0 \leq i \leq k$.
    \end{itemize}
\end{definition}

In particular, a minimal finite projective $0$-resolution is simply a projective cover.

\begin{notation}
    Since we only consider finite resolutions, we omit the word ``finite'' and simply say projective $k$-resolution.
    A \emph{(minimal) projective presentation} is a \emph{(minimal) projective $1$-resolution}.
\end{notation}

\begin{definition}
    Let $k \in \Nbb$.
    A persistence module $M : \Pscr \to \vect$ is \emph{finitely $k$-resolvable} if it admits a finite projective $k$-resolution.
\end{definition}



%\luis{I think we actually don't need to know that resolutions have length at most $n$; double-check!}
%\luis{adjust the following for $\Pscr$ vs $\Rbb^n$}

\begin{definition}
    \label{definition:betti-table}
    Let $M : \Pscr \to \vect$ be finitely $k$-resolvable and let $0 \leq i \leq k$.
    The \emph{$i$th Betti table} of $M$ is the function $\beta^M_i : \Pscr \to \Nbb$ (necessarily of finite support) defined as $\beta^M_i \coloneqq \beta^{C_i}$, where $C_\bullet \to M$ is a minimal $k$-resolution of $M$.
\end{definition}

\begin{notation}
When convenient, we write $\beta_i(M)$ instead of $\beta_i^M$ for the Betti tables of a persistence module $M$.
\end{notation}

The Betti tables of $M$ are also sometimes called the \emph{(multigraded) Betti numbers} of $M$.
The Betti tables of $M$, as defined in Definition \ref{definition:betti-table}, are independent of the choice of minimal presentation or resolution, thanks to the following standard result.

%\todo{Reviewer 3 writes of the next lemma: Need a citation for Lemma 13.  (But I agree that it is correct).}
