\begin{lemma}
    \label{lemma:minimal-resolution-uniqueness}
    Let $k \in \Nbb$.
    If $M : \Pscr \to \vect$ is finitely $k$-resolvable, then it admits a minimal projective $k$-resolution $C_\bullet \to M$.
    Moreover, any other projective $k$-resolution $C'_\bullet \to M$ has the property that $\beta^{C_i} \leq \beta^{C'_i}$ for all $0 \leq i \leq k$.
    %Moreover, $C_i = 0$ for all $i > n$.
\end{lemma}

