\begin{example}
    \label{example:resolution-of-H_0}
    Consider the graph $G = (V,E,\partial)$ with $V = \{x,y\}$, $E = \{a,b\}$, and $\partial(a) = \partial(b) = (x,y)$.
    Consider the filtration $f : G \to \Rbb^2$ with $f(x) = f(y) = (0,0)$, $f(a) = (0,1)$, and $f(b) = (1,0)$.
    Then, a minimal resolution of $H_0(G,f)$ is given by
    \[
    0 \to \Psf_{(1,1)} \cdot \{\alpha\} \xrightarrow{\partial_2} \Psf_{(1,0)} \cdot \{a\} \oplus \Psf_{(0,1)} \cdot \{b\} \xrightarrow{\partial_1} \Psf_{(0,0)} \cdot \{x\} \oplus \Psf_{(0,0)} \cdot \{y\} \xrightarrow{\partial_0} H_0(G,f),
    \]
    where $\partial_0(\{x\}) = [x]$, $\partial_0(\{y\}) = [y]$, $\partial_1(\{a\}) = \partial_1(\{b\}) = \{y\} - \{x\}$, and $\partial_2(\{\alpha\}) = \{a\} - \{b\}$.
    In particular, $\beta_0(H_0(G,f)) = \delta_{(0,0)} + \delta_{(0,0)}$, $\beta_1(H_0(G,f)) = \delta_{(1,0)} + \delta_{(0,1)}$, and $\beta_2(H_0(G,f)) = \delta_{(1,1)}$.
    This can be easily checked by hand, but it also follows from \cref{theorem:betti-tables-minimal-filtered-graph,theorem:second-betti-table}, since $(G,f)$ is a minimal filtered graph, in the sense of Definition \ref{definition:minimal-filtered-graph}, which we give in the next section.
\end{example}


