\section{Theory}
\label{section:theory}



\begin{comment}
\paragraph{Minimal filtered graphs}
\end{comment}

We start with a simple, standard result which says that a projective presentation of $0$-dimensional homology is given by using the grades of vertices as generators, and the grades of edges as relations.
Proofs can be found in \cref{section:proofs-theory}.

\begin{lemma}
    \label{definition:H0-H1}
    Let $\Pscr$ be a poset, let $(G,f)$ be a $\Pscr$-filtered graph, and consider the following morphism of projective modules
    \begin{align*}
        \label{equation:standard-presentation}
        \bigoplus_{e \in E} \Psf_{f(e)} \cdot \{e\}
        \;\;\;       & \xrightarrow{\;\;\;\partial_1^{(G,f)}\;\;\;}\;\;\;
        \bigoplus_{v \in V} \Psf_{f(v)} \cdot \{v\}                                  \\
        \{e\} \;\;\; & \xmapsto{\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;} \;\;\;\{e_1\} - \{e_0\}\nonumber
    \end{align*}
    Then $H_0(G,f) \cong \coker\left(\partial_1^{(G,f)}\right)$ and $H_1(G,f) \cong \ker\left(\partial_1^{(G,f)}\right)$.
    In particular, $H_0(G,f)$ is a finitely presentable persistence module.
\end{lemma}

The point of minimal filtered graphs, which we now introduce, is that
%Minimal filtered graphs are graphs where contracting any edge will produce a change in $H_0$ or $H_1$, and where deleting any edge will produce a change in $H_0$; the point being that minimal filtered graphs
they make the presentation in Lemma \ref{definition:H0-H1} minimal (see \cref{theorem:betti-tables-minimal-filtered-graph}).

\begin{definition}
    \label{definition:minimal-filtered-graph}
    Let $(V, E, \partial,f)$ be a filtered graph and let $e \in E$.
    \begin{itemize}
        \item The edge $e$ is \emph{collapsible} if $e_0 \neq e_1$ and $f(e) = f(e_i)$ for some $i \in \{0,1\}$.
        \item The edge $e$ is \emph{deletable} if $[e_0] = [e_1] \in \pi_0(V, E\setminus \{e\}, \partial, f)(f(e))$.
    \end{itemize}
    A filtered graph $(G,f)$ is
    \begin{itemize}
        \item \emph{vertex-minimal} if it does not contain any collapsible edges.
        %if $|[v]_{\pi_0(G,f)(f(v))}| = 1$, for every $v \in V$;
        \item \emph{edge-minimal} if it does not contain any deletable edges.
        %if $[e_0] \neq [e_1] \in \pi_0(G\setminus \{e\}, f)(f(e))$, for every $e \in E$.
        \item \emph{minimal} if it is vertex-minimal and edge-minimal.
    \end{itemize}
\end{definition}

\begin{example}
    \label{example:minimal-vs-not-minimal}
    The graph of Example \ref{example:resolution-of-H_0} is minimal, as neither of the two edges is collapsible or deletable.
    On the other hand, the graph of \cref{fig:graded-graph} is not minimal since $h_1$, $h_2$, $d_1$, $d_2$, and $d_3$ are collapsible, and $e_3$ is deletable.
\end{example}

