As their name suggests, collapsible and deletable edges can be collapsed or deleted:

\begin{construction}
    \label{construction:collapse-deletion}
    Let $(G,f) = (V, E, \partial,f)$ be a filtered graph.
    \begin{itemize}
        \item If $e \in E$ is collapsible, let $i \in \{0,1\}$ be such that $f(e) = f(e_i)$.
        Define the \emph{simple collapse} $G\downarrow e \coloneqq (V\setminus \{e_i\}, E \setminus \{e\}, \partial')$, where $\partial' = (\phi \times \phi) \circ \partial$ and $\phi : V \to V$ is given by $\phi(v) = v$ if $v \neq e_i$ and $\phi(v) = e_{1-i}$ if $v = e_i$.
        \item If $e \in E$ is any edge, define the \emph{simple deletion} $G\setminus e \coloneqq (V, E\setminus \{e\}, \partial)$.
    \end{itemize}
\end{construction}

