We now study the effect of collapsing collapsible edges, and of deleting deletable edges.
We start with a useful observation, whose proof is straightforward.

\begin{lemma}
    \label{lemma:deleting-collapsin-does-not-change}
    Let $(G,f)$ be a filtered graph and let $e$ and $d$ be two different edges of $G$.
    \begin{enumerate}
        \item Assume that $e$ is collapsible.
        If $d$ is not collapsible (resp.~deletable) in $(G,f)$, then $d$ is not collapsible (resp.~deletable) in $(G\downarrow e, f)$.
        \item If $d$ is not collapsible (resp.~deletable) in $(G,f)$, then $d$ is not collapsible (resp.~deletable) in $(G\setminus e, f)$.\qed
    \end{enumerate}
\end{lemma}


%See \cref{section:reducing-graphs}.

\begin{lemma}
    \label{lemma:vertex-reduction-same-homology}
    If $(G,f) = (V,E,\partial,f)$ is a filtered graph and $e \in E$ is collapsible, then $H_i(G,f) \cong H_i(G\downarrow e,f)$ for $i \in \{0,1\}$.
\end{lemma}


\begin{lemma}
    \label{lemma:edge-reduction-H1}
    If $(G,f) = (V,E,\partial,f)$ is a filtered graph and $e \in E$ is deletable, then
    $H_0(G,f) \cong H_0(G \setminus e,f)$ and $H_1(G,f) \cong H_1(G \setminus e ,f) \oplus \Psf_{f(e)}$.
\end{lemma}

