\begin{theorem}
    \label{theorem:betti-tables-minimal-filtered-graph}
    Let $\Pscr$ be a poset, let $(G,f)$ is a $\Pscr$-filtered graph, and let $\partial_1^{(G,f)} : C_1 \to C_0$ be the morphism of Lemma \ref{definition:H0-H1}.
    \begin{enumerate}
        \item If $(G,f)$ is vertex-minimal, then the map $C_0 \to \coker(\partial_1^{(G,f)})$ is a projective cover.
        In this case, $\beta_0\big(H_0(G,f)\big) = \sum_{v \in V} \delta_{f(v)}$.
        \item If $(G,f)$ is a minimal filtered graph, then $C_1 \xrightarrow{\partial_1^{(G,f)}} C_0 \to \coker(\partial_1^{(G,f)})$ is a minimal presentation.
        In this case, we also have 
        $\beta_1\big(H_0(G,f)\big) = \sum_{e \in E} \delta_{f(e)}$.
    \end{enumerate}
\end{theorem}


