We now focus on the case of $\Rbb^2$-filtered graphs.
If $(G,f)$ is an $\Rbb^2$-filtered graph, let $f_{\mathbf x},f_{\mathbf y} : G \to \Rbb$ denote the first and second coordinates of $f$, respectively.

\begin{definition}
    \label{definition:cycle-creating}
    Let $(V,E,\partial,f)$ be a minimal $\Rbb^2$-filtered graph, and let $\prec$ be a total order on the set of edges $E$ that refines the lexicographic order induced by $f$ (i.e., $e \prec e'$ implies that $f_{\mathbf x}(e) < f_{\mathbf x}(e')$ or $f_{\mathbf x}(e) = f_{\mathbf x}(e')$ and $f_{\mathbf y}(e) \leq f_{\mathbf y}(e')$).
    An edge $d \in E$ is \emph{cycle-creating} with respect to $\prec$ if $[d_0] = [d_1] \in \pi_0(V, \{e \in E : e \prec d\}, \partial)$.
\end{definition}

Thus, $d \in E$ is cycle-creating if there exists a list of edges $e^1, \dots, e^k \in E$ with $e^i \prec d$ for $1 \leq i \leq k$, and a list of signs $s^1, \dots, s^k \in \{+,-\}$, such that $s^1 e^1, \dots, s^k e^k$ is a directed path from $d_0$ to $d_1$.
Such a path $w = (s^\bullet, e^\bullet)$ is called a \emph{witness} for $d$, and we denote $f(w) \coloneqq \left(\,f_{\mathbf x}(d)\,,\, \max_{1 \leq i \leq k} f_{\mathbf y}(e^i) \, \right)$.
%\todo{Reviewer 3 and PC remark: What if the $f_y(d)$ is greater than the y-grade of f(w)?  Then, I think Theorem 25 can be incorrect.  So in the definition of the second coordinate of f(w), also let $f_y(d)$ be an argument of the max.}
%\luis{Point out that that cannot happen, and in fact we always have $f(w) > f(d)$ with the current definition.}
A \emph{minimal witness} $w$ of a cycle-creating edge $d$ is one for which $f_{\mathbf y}(w) \in \Rbb$ is as small as possible.
%When considering more than one cycle-creating edge $d$, we write $w_d$ for any chosen minimal witness of $w$.

Since $\prec$ refines the lexicographic order, we have $f_{\mathbf x}(e^i) \leq f_{\mathbf x}(d)$ for all $i$; thus, if $\max_{1 \leq i \leq k} f_{\mathbf y}(e^i) \leq f_{\mathbf{y}}(d)$, we would have that $[d_0] = [d_1] \in \pi_0(V,E \setminus \{d\},\partial,f)(f(d))$, which contradicts the fact that the filtered graph is minimal.
This means that if $w$ is a witness for~$d$,
then $\max_{1 \leq i \leq k} f_{\mathbf y}(e^i) > f_{\mathbf{y}}(d)$, and thus $f(d) < f(w)$.


\begin{theorem}
    \label{theorem:second-betti-table}
    Let $(G,f) = (V,E,\partial, f)$ be a minimal $\Rbb^2$-filtered graph, and $\prec$ a total order on $E$ refining the lexicographic order.
    For each $d \in E$ cycle-creating, let $w_d = (s_d^\bullet, e_d^\bullet)$ be a minimal witness wrt to $\prec$.
    The kernel of the morphism $\partial_1^{(G,f)}$ of Lemma \ref{definition:H0-H1} is given by:
    \begin{align*} \bigoplus_{\substack{d \in E\\\text{cycle-creating}}}
        \Psf_{f(w_d)} \cdot \{d\}
        \;\;\;       & \xrightarrow{\;\;\kappa^{(G,f)}\;\;}\;\;\;
        \bigoplus_{e \in E} \Psf_{f(e)} \cdot \{e\}                                                         \\
        \{d\} \;\;\; & \xmapsto{\;\;\;\;\;\;\;\;\;\;\;\;\;\;} \;\;\;\{d\} - \big(s_d^1 \{e_d^1\} + \cdots + s_d^k\{e_d^k\}\big).
    \end{align*}
    It follows that
    \begin{itemize}
        \item $\beta_0(H_0(G,f)) = \sum_{v \in V} \delta_{f(v)}$;
        \item $\beta_1(H_0(G,f)) = \sum_{e \in E} \delta_{f(e)}$;
        \item $\beta_0(H_1(G,f)) = \beta_2(H_0(G,f)) = \sum_{d \in E, \text{cycle-creating}} \delta_{f(w_d)}$;
        \item $\beta_i(H_0(G,f)) = 0$ for $i \geq 3$, and $\beta_i(H_1(G,f)) = 0$ for $i \geq 1$.
    \end{itemize}
\end{theorem}

\section{Algorithms}
\label{section:algorithms}



\paragraph{Outline}
We first introduce some technical notions and overview the algorithms.

Two $\Pscr$-filtered graph $(G,f)$ and $(G',f')$ are \emph{homology-equivalent} (over~$\kbb$) if $H_0(G,f;\kbb) \cong H_0(G',f';\kbb)$ and $H_1(G,f;\kbb) \cong H_1(G',f';\kbb)$.

\cref{algorithm:vertex-reduction} reduces the input filtered graph to a vertex-minimal filtered graph by collapsing edges; it relies on \cref{algorithm:local-components}, which collapses local collapsible edges.
A \emph{local collapsible edge} of $(G,f)$ is an edge $e$ such that $e_0 \neq e_1$ and $f(e) = f(e_0) = f(e_1)$.
\cref{algorithm:vertex-reduction} then identifies \emph{minimal vertices}, that is, vertices with no adjacent collapsible edge decreasing the grade, and runs a depth-first search from each of these to build and collapse a tree of collapsible edges.

\cref{algorithm:minimal-presentation} first calls \cref{algorithm:vertex-reduction} to perform all collapses and then deletes deletable edges until there are no more deletable edges.
It then builds the presentation of Lemma \ref{definition:H0-H1}.

\cref{algorithm:betti-tables} first calls \cref{algorithm:vertex-reduction} to perform all collapses, and then goes through all edges, with respect to the lex order on their grades, and identifies deletable edges, non-deletable edges, and cycle-creating edges.

\paragraph{Dynamic dendrograms}
Since this is used in \cref{algorithm:betti-tables}, we now introduce the dynamic dendrogram data structure, which, informally,
