\paragraph{Presentation matrices}
In the algorithms, to represent a Betti table $\beta_i(M)$ we use a list of elements of the indexing poset.
If we have represented the $0$th and $1$st Betti tables of $M$ with lists $\beta_0$ and $\beta_1$, we represent a minimal presentation for $M$ with a sparse matrix using coordinate format, that is, with a list of triples $(i,j,v)$ representing the fact that $v$ is the entry at row $i$ and column $j$, and where $i$ represents the $i$th element of $\beta_0$ and $j$ represents the $j$th element of $\beta_1$.

\medskip

\begin{algorithm}[H]
    \caption{Collapse local collapsible edges}
    \label{algorithm:local-components}
    \SetAlgoLined
    \DontPrintSemicolon
    \SetKwInput{Input}{Input}
    \SetKwInput{Output}{Output}
    \Input{Filtered graph $(G,f) = (V,E,\partial,f)$}
    \Output{Filtered graph $(G',f)$ homology-equivalent to $(G,f)$ and without local collapsible edges}
    Initialize dictionary $\phi$ with identity map, $\phi[v] = v$ for $v \in V$ \;
    Initialize empty set $\var{visited}$ \;
    Initialize $E' \gets E$ \;
    \For(\Comment{Run depth-first search from $v$ on local edges}){$v \in V$}{
        Initialize $\var{stack}$ with $(v,\emptyset,v)$ \;
        \While{$\var{stack}$ is not empty}{
            $(v,e,u) \gets \var{stack}.\op{pop}()$ \;
            \If{$u \notin \var{visited}$}{
                add $u$ to $\var{visited}$ \;
                \If{$e \neq \emptyset$}{
                    $\phi[u] \gets v$ \;
                    remove $e$ from $E'$ \;
                }
                \For(\Comment{local collapsible}){$e \in E$ with $\{e_0,e_1\} = \{u,x\}$ and $f(e) = f(x) = f(u)$}{
                    \op{push} $(v,e,x)$ onto $\var{stack}$ \;
                }
            }
        }
    }
    $V' \gets \{v \in V : \phi[v] = v \}$ \;
    \Return $(G',f) = \left(V',E',(\phi \times \phi) \circ \partial, f\right)$
\end{algorithm}

\begin{algorithm}[H]
    \caption{Collapse to vertex-minimal filtered graph}
    \label{algorithm:vertex-reduction}
    \SetAlgoLined
    \DontPrintSemicolon
    \SetKwInput{Input}{Input}
    \SetKwInput{Output}{Output}
    \Input{Filtered graph $(G,f) = (V,E,\partial,f)$}
    \Output{
        Vertex-minimal filtered graph $(G',f)$ homology-equivalent to $(G,f)$, and $\beta_0(H_0(G,f))$
    }
    $(G_i,f) = (V_i,E_i,\partial_i,f) \gets \textrm{\cref{algorithm:local-components}}(G,f)$ \;
    Initialize dictionary $\phi$ with identity map, $\phi[v] = v$ for $v \in V_i$ \;
    Initialize empty set $\var{visited}$ \;
    Initialize $E' \gets E_i$ \;
    \For(\Comment{Run depth-first search from minimal vertices}){$v$ in $V_i$}{
        \If(\Comment{$v$ is not minimal}){$\exists$ edge $e \in E_i$ with $\{e_0,e_1\} = \{u,v\}$ and $f(e) = f(v) > f(u)$}{
            \op{continue} \;
        }
        Initialize $\var{stack}$ with $(v, \emptyset, v)$ \;
        \While{$\var{stack}$ is not empty}{
            $v,e,u \gets \var{stack}.\op{pop}()$ \;
            \If{$u \notin \var{visited}$}{
                add $u$ to $\var{visited}$ \;
                \If{$e \neq \emptyset$}{
                    $\phi[u] \gets v$ \;
                    remove $e$ from $E'$ \;
                }
                \For{every edge $e \in E_i$ with $\{e_0,e_1\} = \{u,x\}$ with $f(e) = f(x) > f(u)$}{
                    \op{push} $(v,e,x)$ onto $\var{stack}$ \;
                }
            }
        }
    }
    $V' \gets \{v \in V_i : \phi[v] = v \}$ \;
    \Return $(G',f) = \left(V', E', (\phi \times \phi) \circ \partial_i, f\right)$
    and $\beta_0 = [f(v) : v \in V'] $ \;
\end{algorithm}


\begin{algorithm}[H]
    \caption{Minimal presentation of $\Pscr$-filtered graph}
    \label{algorithm:minimal-presentation}
    \SetAlgoLined
    \DontPrintSemicolon
    \SetKwInput{Input}{Input}
    \SetKwInput{Output}{Output}
    \Input{Filtered graph $(G,f) = (V,E,\partial,f)$}
    \Output{Minimal presentation of $H_0(G,f;\kbb)$}
    Initialize $\beta_0, \beta_1$ with empty lists\;
    Initialize empty sparse matrix $\Mcal$ and empty dictionary $\mathsf{row\_idx}$\;
    $(V',E',\partial',f) \gets \textrm{\cref{algorithm:vertex-reduction}}(G,f)$\;
    \For(\Comment{Check each edge, and delete it if it is deletable}){$e \in E'$ \label{line:for-deletable}}{
        Define set of vertices
        $V_e \gets \{v \in V' : f(v) \leq f(e)\}$\;
        Define set of edges 
        $E_e \gets \{d \in E' : f(d) \leq f(e)\} \setminus e$\;
        Run breadth-first search on $(V_e,E_e,\partial')$ starting from $e_0$\;
        \If(\Comment{$[e_0] = [e_1] \in \pi_0(V_e,E_e,\partial')$ so $e$ is deletable}){$e_1$ is reachable from $e_0$}{
            $E' \gets E' \setminus \{e\}$\;
        }
    }
    \For{$v \in V'$}{
        $\beta_0.\append(f(v))$\;
        $\mathsf{row\_idx}[v] \gets |\beta_0|$\;
    }
    \For(\Comment{The morphism $\partial_1^{(V',E',\partial')}}$ of Lemma \ref{definition:H0-H1}){$e \in E'$}{
        $\beta_1.\append(f(e))$\;
        $\Mcal.\append(\,\mathsf{row\_idx}[e_0]\,,\,|\beta_1|\,,\,-1\,)$\;
        $\Mcal.\append(\,\mathsf{row\_idx}[e_1]\,,\,|\beta_1|\,,\,1\,)$\;
    }
    \Return $\beta_0, \beta_1, \Mcal$
\end{algorithm}


