\paragraph{Complexity and correctness}
We conclude the paper by using the theoretical results of \cref{section:theory} to prove the main results in the introduction.
Proofs for the results in this section are in \cref{section:proofs-algorithms}.

We start by with a convenient lemma, which gives conditions under which one can collapse an entire subgraph and produce a homology-equivalent filtered graph.
The following definition describes the type of subgraph that can be collapsed.

\begin{definition}
    \label{definition:monotonic-forest}
    Let $(G,f) = (V,E,\partial, f)$ be a filtered graph.
    A subset $E' \subseteq E$ is a \emph{monotonic forest} of $(G,f)$ if:
    \begin{enumerate}
        \item The subgraph of $G$ spanned by the edges in $E'$ is a forest.
        \item For every vertex $v$ in the forest, there exists at most one edge $e \in E'$ such that $\{e_0,e_1\} = \{v,w\}$ and $f(w) < f(v)$.
    \end{enumerate}
\end{definition}

\begin{lemma}
    \label{lemma:collapsible-forest}
    Let $(G,f) = (V,E,\partial,f)$ be a filtered graph, and let $E' \subseteq E$ be a set of collapsible edges, which forms a monotonic forest.
    If $e \in E'$, then all the edges in $E'\setminus\{e\}$ are collapsible in $(G\downarrow e, f)$.
    In particular, the whole forest $E'$ can be collapsed (in any order) to obtain a filtered graph that is homology-equivalent to $(G,f)$.
\end{lemma}

\begin{lemma}
    \label{lemma:algo-1-correct}
    Let $(G,f)$ be a $\Pscr$-filtered graph.
    \cref{algorithm:local-components} outputs
    a filtered graph homology-equivalent to $(G,f)$ and without local collapsible edges in time $O(|G|)$.
    %in linear time a vertex map $\phi$
    %and a set of edges $E'$, such that $\phi$ applied to the vertices of $G$ and
    %edges $E'$ produces graph $G'$ with isomorphic homology groups
    %\dmitriy{better wording} and no local collapsible edges.
\end{lemma}

\begin{proposition}
    \label{proposition:vertex-reduction-correctness}
    Let $(G,f)$ be a $\Pscr$-filtered graph.
    \cref{algorithm:vertex-reduction} outputs a vertex-minimal filtered graph homology-equivalent to $(G,f)$ and $\beta_0(H_0(G,f))$ in $O(|G|)$ time.
\end{proposition}


\begin{proposition}
    \label{proposition:edge-deletion-correctness}
    Let $(G,f)$ be a finite $\Pscr$-filtered graph.
    \cref{algorithm:minimal-presentation} outputs a minimal presentation of $H_0(G,f)$ in $O(\,|G|^2\,)$ time.
\end{proposition}

With these results, we prove Theorem \ref{result:quadratic-time-algo} and Theorem \ref{result:log-linear-time} in \cref{section:proofs-main-theorems}.


