\begin{proof}[Proof of Lemma \ref{lemma:lifting}]
    Let $P = \bigoplus_{i \in I} \Psf_{f(i)} \cdot \{i\}$.
    To define a morphism $P \to M$ it is sufficient to say, for each $j \in J$, to which element of $M(f(j))$ the element $\{j\} \in P(f(j))$ gets mapped to.
    Since $g$ is a surjection, let us choose $m_j \in M(f(j))$ in the preimage of $h_{f(j)}(\{j\}) \in N(f(j))$, for each $j \in J$.
    Let $h' : P \to M$ be defined by mapping $\{j\} \in P(f(j))$ to $m_j \in M(f(j))$.
    It is clear that this morphism satisfies $g \circ h' = h$.
\end{proof}

\begin{lemma}
    \label{lemma:projective-cover-minimal-elements}
    Let $M$ be a $\Pscr$-persistence module and let $g : Q = \bigoplus_{i \in I} \Psf_{f(i)} \cdot \{i\} \to M$ be a finite projective cover.
    For every $j \in I$, we have that $g_{f(j)}(\{j\}) \neq 0 \in M(f(j))$, and $\{j\} \in Q(f(j))$ is the only preimage of $g_{f(j)}(\{j\})$.
\end{lemma}
\begin{proof}
    If $g_{f(j)}(\{j\}) = 0 \in M(f(j))$, then the restriction of $g$ given by
    $\bigoplus_{i \in I \setminus \{j\}} \Psf_{f(i)} \cdot \{i\} \to M$ would be surjective, and thus $\sum_{r \in \Pscr} \beta^Q(r)$ would not be minimal, so $Q \to M$ would not be a projective cover.

    Similarly, if there exists another element of $Q(f(j))$ mapping to $g_{f(j)}(\{j\})$, then this element would be linearly independent of $\{j\}$, and again the restriction of $g$ given by $\bigoplus_{i \in I \setminus \{j\}} \Psf_{f(i)} \cdot \{i\} \to M$ would be surjective, and $Q \to M$ would not be a projective cover.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lemma:minimal-resolution-uniqueness}]
    We start by proving that any finitely $0$-resolvable $M$ admits a projective cover.
    By definition, there exists a surjection $P \to M$ from a projective of finite rank $P$.
    If $\sum_{r \in \Pscr}\beta^P(r)\in \Nbb$ is not minimal, we can remove at least one direct summand of $P$ to get $P' \to M$ still a surjection.
    Proceeding in this way, we necessarily end up with a projective cover of $M$.

    Now, a straightforward inductive argument shows that any $k$-resolvable module admits a minimal projective $k$-resolution.

%    \smallskip
%    
%    The existence of minimal projective resolutions for the case $\Pscr = \Rbb^n$ is well-known (see, e.g., \cite[Corollary~10.6(2)]{chacholski-jin-tombari}, noting that, in the reference, \emph{$\infty$-resolvable} means admitting a projective resolution by finitely presentable modules, and \emph{tame} means finitely presentable).

    \smallskip

    We now prove that, if $g : P \to N$ is a projective cover and $h : Q \to N$ is a surjection from a finitely presentable projective, then $\beta^P \leq \beta^{Q}$.
    The inequality in the statement of the result involving Betti tables follows from this.

    By Lemma \ref{lemma:lifting}, there exist morphisms $g' : P \to Q$ and $h' : Q \to P$ such that $h \circ g' = g$ and $g \circ h' = h$.
    We claim that $h' \circ g' : P \to P$ is the identity; this is sufficient since then $Q \cong P \oplus P'$ for some finitely presentable projective $Q$, and thus $\beta^P \leq \beta^P + \beta^{P'} = \beta^{Q}$.

    Let $P = \bigoplus_{i \in I} \Psf_{f(i)} \cdot \{i\}$.
    Let $j \in J$.
    By Lemma \ref{lemma:projective-cover-minimal-elements}, we have that $(h' \circ g')_{f(j)}(\{j\}) = \{j\} \in P(f(j))$, since $g = g \circ (h' \circ g')$ and $\{j\}$ is the unique element of $P(f(j))$ mapping to $g_{f(j)}(\{j\}) \in M(f(j))$.
    Since the elements $\{j\} \in P(f(j))$ generate $P$, this implies that $h' \circ g'$ is the identity.
    %\todo{missing Hilbert's syzygy thm}
\end{proof}


