\section{Preliminaries}

\textbf{Densest-$k$-Subgraph:} Consider an unweighted, undirected simple graph $\mathcal{G} := (\mathcal{V}, \mathcal{E})$ with vertex set $\mathcal{V} := \{1, \ldots, n\}$ and edge set $\mathcal{E} \subseteq \mathcal{V} \times \mathcal{V}$. The $n \times n$ symmetric adjacency matrix of $\setG$ is denoted as $\mathbf{A}$. The eigen-values of $\vA$ are arranged in non-increasing order of their magnitudes; i.e., we have $|\lambda_1| \geq |\lambda_2| \geq \cdots |\lambda_n|$.
A vertex $\mathcal{S} \subseteq \mathcal{V}$ induces a subgraph $\mathcal{G}_\mathcal{S} = (\mathcal{S}, \mathcal{E}_\mathcal{S})$, where $\mathcal{E}_\mathcal{S} = \{\{u, v\} \in \mathcal{E} \mid u, v \in \mathcal{S}\}$. 
The edge density of the subgraph $\mathcal{G}_\mathcal{S}$ is defined as $d(\mathcal{G}_\mathcal{S}) = \lvert \mathcal{E}_\mathcal{S} \rvert/\binom{|\setS|}{2},$
which measures what fraction of edges in $\setG_{\setS}$ are connected. Note that larger values correspond to dense quasi-cliques, with a maximum value of $1$ for cliques.

The Densest-$k$-Subgraph (D$k$S) problem seeks to find a subset of $k$ vertices $\mathcal{S} \subseteq \mathcal{V}$ that maximizes the edge density. Formally, the problem can be expressed as follows
\begin{equation}\label{eq:dks}
d_k^*:=\max_{\vx \in \setX_k} 
\biggl\{ \frac{\vx^T\vA\vx}{\binom{k}{2}} \biggr\}
\end{equation}
where $\mathcal{X}_k := \{\mathbf{x} \in \{0, 1\}^n : \mathbf{e}^T \mathbf{x} = k\}$ represents the combinatorial selection constraints. Here, each binary vector $\mathbf{x} \in \{0,1\}^n$ represents a vertex subset $\mathcal{S} \subseteq \mathcal{V}$, with $x_i = 1$ if $i \in \mathcal{S}$ and $x_i = 0$ otherwise. %The objective function value equals $d(\mathcal{G}_\mathcal{S})$.

\noindent \textbf{Differential Privacy on Graphs:} Let \( \mathbb{G} \) denote a collection of graphs on a fixed set \( \mathcal{V} \) of nodes. This paper focuses on the notion of edge privacy \cite{blocki2013differentially}, where two graphs \( \mathcal{G}, \mathcal{G}' \in \mathbb{G} \) are considered neighbors, denoted \( \mathcal{G} \sim \mathcal{G}' \), if they have the same vertex set and differ in exactly one edge, meaning \( |\mathcal{E}(\mathcal{G}) - \mathcal{E}(\mathcal{G}')| = 1 \).

\begin{definition}
    \((\epsilon, \delta)\)-Differential Privacy (DP)~\cite{dwork2014algorithmic,blocki2013differentially}. Let \( \epsilon > 0 \) and \( \delta \in [0, 1] \). A randomized algorithm \( \mathcal{A}(\cdot): \mathbb{G} \to \mathbb{R}^k \) is said to be \((\epsilon, \delta)\)-differentially private if it satisfies:
    \begin{equation}
    \Pr(\mathcal{A}(\mathcal{G}) \in S) \leq \exp(\epsilon) \Pr(\mathcal{A}(\mathcal{G}') \in S) + \delta, \label{eq:dp}
    \end{equation}
    \noindent for any outcome \( S \subseteq \mathbb{R}^k \), and for any pair of neighboring datasets \( (\mathcal{G}, \mathcal{G}') \) that differ in a single edge.   
\end{definition}


\noindent \textbf{Function Sensitivity:}~\cite{dwork2014algorithmic}. 
Consider a function $f:\mathbb{G} \rightarrow \mathbb{R}^k$. The {\em local $\ell_2$ sensitivity} of $f$ exhibited by a dataset $\setG \in \mathbb{G}$ is defined as $\textsf{LS}_{f}(\setG) = \max_{\setG': \mathcal{G} \sim \mathcal{G}'} \| f(\setG)  - f(\setG')\|_{2}$,
where the maximum is taken over all neighboring datasets $\setG'$ which differ in one edge from $\setG$. The {\em global $\ell_2$ sensitivity} of $f$ is then
$\textsf{GS}_{f} = \max_{\setG \in \mathbb{G}} \textsf{LS}_{f}(\setG)
$. If we computed the sensitivity calculations w.r.t. the $\ell_1$ norm instead, we would obtain the $\ell_1$ local and global sensitivities of $f$.
