The final proposed solution to approximate D$k$S via PTR is presented in Algorithm ~\ref{alg:ptr}. Note that the steps of the algorithm are in closed-form, and hence it can be executed extremely quickly.

\begin{algorithm}
    \DontPrintSemicolon 
    \SetAlgoLined
    \footnotesize
    \textbf{Input:} Symmetric $A \in \mathbb{R}^{n \times n}$, $p$, $\vv$, privacy parameters $\epsilon_1$,$\epsilon_2$, $\delta > 0$.\;
    \textbf{Output:} Private vertex set $\mathcal{S}_\text{PTR}$.\;
    Compute $\beta$ based on \eqref{eq:ptr_beta} .\;
    Compute $\phi(\mathcal{G})$ based on \eqref{eq:phi} \;
    Compute $\hat{\phi}(\mathcal{G}) = \phi(\mathcal{G}) + \text{Lap}\left(\frac{1}{\epsilon_1}\right)$.\;

    \uIf{$\hat{\phi}(\mathcal{G}) \geq \frac{\ln(1/\delta)}{\epsilon_1}$}
        {
                Compute \( \mathbf{v}_{ptr} = \mathbf{v} + \mathcal{N}\left(0, \frac{2\beta^2 \log(2 / \delta)}{\epsilon_2^2} \cdot \mathbf{I}_n\right) \).\;
                Compute $\mathcal{S}_\text{PTR} =  \operatorname*{arg\,max}_{\mathbf{x} \in \mathcal{X}_k} |\mathbf{v}_{ptr}^T \mathbf{x}|$.\;
                \textbf{Return:} $\mathcal{S}_\text{PTR}$.\;
        }
        \Else{
            \textbf{Return:} \textsf{No Response} .\;
        }
    \caption{DP-D$k$S via PTR $(\mathbf{A},p,\epsilon_1,\epsilon_2,\delta)$}
    \label{alg:ptr}
\end{algorithm}

