&\geq \frac{1}{\binom{k}{2}} \left( \mathbb{E}\left[\mathbf{x}_{r}^{\top} \mathbf{A}_{r} \mathbf{x}_{r}\right] - \mathbb{E}\left[\left|\mathbf{x}_{r}^{\top}(\mathbf{A}-\mathbf{A}_{r})\mathbf{x}_{r}\right|\right] \right)\\
&\geq \frac{1}{\binom{k}{2}} \left(\mathbb{E}\left[\mathbf{x}_{r}^{\top} \mathbf{A}_{r} \mathbf{x}_{r}\right] - k\mathbb{E}\left[\left\|\mathbf{A}-\mathbf{A}_{r}\right\|_2\right]\right),
\end{align*}

in which, the first inequality emerges from the triangle inequality and the second one is due to the fact that for any scalar random variable $a \in \mathbb{R}$, we have $\mathbb{E}(|a|) > |\mathbb{E}(a)|$. To proceed, we need to find an upper bound for $\mathbb{E}[\left\|\mathbf{A}-\mathbf{A}_{r}\right\|_2]$. Therefore, we can state: 
\begin{align*}
\mathbb{E}[\left\| \mathbf{A} - \mathbf{A}_{r} \right\|_2] &= \mathbb{E}\left[\left\| \mathbf{A} - \hat{\mathbf{A}} - 2\lambda_{1} \mathbf{v}_{1}\mathbf{g}^{\top} - \lambda_{1}\mathbf{g}\mathbf{g}^{\top} \right\|_2\right]\\
&\leq \mathbb{E}\left[\left\| \mathbf{A} - \hat{\mathbf{A}}\right\|_2 + 2\lambda_{1} \left\|\mathbf{v}_{1}\right\|_2\left\|\mathbf{g}^{\top}\right\|_2 + \lambda_{1}\left\|\mathbf{g}\mathbf{g}^{\top} \right\|_2\right] \\
& =  \left|\lambda_{2}\right| + 2\lambda_{1} \mathbb{E}\left[\left\|\mathbf{g}^{\top}\right\|_2\right] + \lambda_{1}\mathbb{E}\left[\left\|\mathbf{g}\mathbf{g}^{\top} \right\|_2\right]\\
& \leq \left|\lambda_{2}\right| + 2\sqrt{n}\lambda_{1} \sigma + n \lambda_{1}\sigma^{2},
\end{align*}
where the first and the second inequality comes due to the triangle inequality. In addition, for the third inequality we utilize an upper bound for the Euclidean norm of a Gaussian and i.i.d random vector. Thus, for the lower bound of $\mathbb{E}[d_k^{ptr}]$, we have:
\begin{align*}
&\mathbb{E}[d_k^ptr] \geq \frac{1}{2\binom{k}{2}} \mathbb{E}[\mathbf{x}_{r}^{\top} \mathbf{A}_{r} \mathbf{x}_{r}] - \frac{1}{k-1} \left( \left|\lambda_{2}\right| + 2\sqrt{n}\lambda_{1} \sigma + n \lambda_{1}\sigma^{2}\right).
\end{align*}
Combining the above expression with the lower bound of the optimal edge density, yields \eqref{ptr_edge_density}. 
\fi 

