 & MASE & RMSSE & Coverage & sMIS & Time \\ 
  \midrule
ADAM ETS & \textbf{2.222} & \textbf{1.935} & \textit{0.885} & \textbf{2.122} & \textit{0.386} \\ 
  ES & \textit{2.224} & \textit{1.939} & \textbf{0.898} & \textit{2.196} & 0.477 \\ 
  CES & 2.271 & 1.958 & 0.812 & 3.465 & \textbf{0.236} \\ 
  ETS & 2.263 & 1.970 & 0.882 & 2.258 & 0.409 \\ 
  ARIMA & 2.300 & 1.987 & 0.834 & 3.007 & 1.425 \\ 
  ADAM ARIMA & 2.371 & 2.048 & 0.843 & 3.126 & 1.376 \\ 
  SSARIMA & 2.480 & 2.133 & 0.802 & 3.356 & 1.811 \\ 
   \bottomrule
\end{tabular}
   \caption{Error measures for each of the model evaluated on M1, M3 and Tourism competitions, aggregated using mean values. The \textbf{boldface} indicates the best performing models, while the \textit{italic} indicates the second best ones.}
   \label{tab:competitions}
