           & \mbox{or $1 > R_G \geq 0$ and $m < -\ol r^f$ and $r^f + \frac{r^g - c}{\ol r^g}(m-r^f) \leq 0$} \\
    & \\
    \left(R_G, 0 \right) & \mbox{$1 > R_G > R_F \geq 0$ and $r^f + \frac{r^g - c}{\ol r^g}(m-r^f) > \frac{(\ol r^f + m)^2}{4\ol r^f}$} \\
    & \mbox{or $1 > R_G > 0 > R_F $ and $r^f + \frac{r^g - c}{\ol r^g}(m-r^f) > 0$} \\
    & \mbox{or $1 > R_G \geq 0$ and $m \in [\ol r^f, r^f)$} \\
    & \mbox{or $1 > R_F \geq R_G \geq 0$} \\
    & \\
    \left(R_F, 1-R_F \right) & \mbox{$R_G \geq 1 > R_F \geq 0$} \\
           & \mbox{or $1 > R_G > R_F \geq 0$ and $r^f + \frac{r^g - c}{\ol r^g}(m-r^f) \leq \frac{(\ol r^f + m)^2}{4\ol r^f}$} \\
    & 
\end{cases}.
\end{align*}

Finally, restricting to the cases in which the regularity condition $0 \le R_G, R_F \le 1$ holds, we get exactly the result stated as Theorem \ref{thrm:eq-analysis}:

\begin{align*}
(\alpha, x) = \begin{cases}
    \left(R_G, 0 \right) & \mbox{$1 \geq R_G > R_F \geq 0$ and $U \left(R_G, 0 \right) > U \left(R_F, 1-R_F \right)$} \\
    & \mbox{or $1 \geq R_F \geq R_G \geq 0$} \\
    & \\
    \left(R_F, 1-R_F \right) & \mbox{or $1 \geq R_G > R_F \geq 0$ and $U \left(R_G, 0 \right) \leq U \left(R_F, 1-R_F \right)$}
\end{cases}.
\end{align*}

Notice that in particular, we obtain that Theorem \ref{thrm:eq-analysis} holds for general $\ol$.

This concludes the proof of \Cref{thrm:eq-analysis}.

\begin{proofof}{lemma: condition1}
Denote $h(m) = \frac{(y + m)^2}{4y}$ and $g(m) = m$. Our goal is to show that for every $m \in [-y, y]$, it holds that 
\begin{align}
    h(m) \geq g(m) \label{eq: h geq g}.
\end{align} 
Observe that
\begin{align*}
    h(y) = \frac{(2y)^2}{4y} = y = g(y)
\end{align*}
Therefore, for $m = y$ the inequality~\eqref{eq: h geq g} holds with an equality. Next, we take the derivative.
\begin{align*}
\frac{dh(m)}{dm} = \frac{2(y+m)}{4y} = \frac{y+m}{2y} = \frac{1}{2} + \frac{m}{2y}.
\end{align*}
Notice that for every $m \in [-y, y)$ it holds that $\frac{m}{2y} < \frac{1}{2}$ and therefore $\frac{dh(m)}{dm} < 1$.
On the other hand, it holds that $\frac{dg(m)}{dm} = 1$. Thus, we get that if we start at $m = y$, then $h(m) = g(m)$, but as we decrease the value of $m$, we get that $g(m)$ decreases faster than $h(m)$ for every $m \in [-y, y)$. Therefore, $h(m) > g(m)$ in this range.
This concludes the proof of Lemma~\ref{lemma: condition1}.
\end{proofof}



\section{Omitted Proofs (Section \ref{sec:econ-implications})}
\label{app:omitted-proofs}

\subsection{Proof of Proposition \ref{cor:costly-ds}}

We present and prove the proposition for general $\ol \in (0,1]$, hence the proof of $\ol=1$ (the version that appears in the main paper) follows immediately.

\begin{proposition}
    (Extension of Proposition \ref{cor:costly-ds} for general $\ol$) If $c \in \left( (1-\ol)r^g,r^g \right)$, then for every $m \in (-\ol r^f, 0)$ the unique SPE $(\alpha^{eq}, x^{eq})$ satisfies $\alpha^{eq} > 0$.
\end{proposition}

\begin{proof}
    The conditions on $c$ and $m$ imply that the regularity condition holds with $R_F, R_G > 0$, hence by Theorem \ref{thrm:eq-analysis} (which holds for general $\ol$ by Appendix \ref{app:eq-analysis}) we have that $\alpha^{eq}$ equals either $R_F$ or $R_G$, with both being strictly positive.
\end{proof}

\subsection{Proof of \Cref{cor:pareto}}


We present and prove the proposition for general $\ol \in (0,1]$. The proof for $\gamma = 1$ follows afterwards.

\begin{proposition} \label{cor: pareto with gamma}
    (Extension of Proposition \ref{cor:pareto} for general $\ol$) Assume that the regularity condition holds. Let

    \begin{align*}
        \ovm = \begin{cases}
            \min \left\{ \gamma r^f, r^g(1-\gamma), \frac{r^f (\gamma r^g + 2c)}{r^g + 2r^f} , r^f \frac{\gamma r^g - 2c}{r^g - 2r^f}\right\} & \mbox{$r^g < 2r^f$} \\
            \min \left\{ \gamma r^f, r^g(1-\gamma), \frac{r^f (\gamma r^g + 2c)}{r^g + 2r^f} \right\} & \mbox{$r^g > 2r^f$}
        \end{cases}    
    \end{align*}

    and 
    \begin{align*}
        \unm = \begin{cases}
            \max \left\{ - \gamma r^f, - \frac{1-R_G}{R_G}r^f\right\} & \mbox{$r^g < 2r^f$} \\
            \max \left\{ - \gamma r^f, - \frac{1-R_G}{R_G}r^f, r^f \frac{\gamma r^g - 2c}{r^g - 2r^f}\right\} & \mbox{$r^g > 2r^f$} 
        \end{cases}
    \end{align*}

    Then,
    \begin{enumerate}
        \item If $R_G > 0$, every price $m \in [\unm, \ovm]$ is Pareto improving compared to forcing no data sharing (i.e., $\alpha = 0$).
        \item If $R_G = 0$, there are no Pareto improving prices $m$.
    \end{enumerate}
\end{proposition}

\begin{proof}
Without data sharing, we fix $\alpha = 0$. In this case, the optimal action of GenAI is $x = 1$ if $R_G > 0$ or $x = 0$ if $R_G = 0$.

\paragraph{Case I. $R_G > 0$} Our base line is $V(0, 1) = r^g - c > 0$ and $U(0, 1) = 0$. As noted, there are two possible solutions for this game, which Firm has to choose from.

\begin{itemize}
    \item If $(\alpha^{eq}, x^{eq}) = (R_G, 0)$ then:
    \begin{enumerate}
        \item GenAI's perspective: $V(R_G, 0) = R_G r^g - R_G m \geq V(0, 1)$ and therefore we get that 
        \begin{align}
            m \leq r^g(1-\gamma). \label{eq: rg equalibrium upper}
        \end{align}
        \item Firm's perspective: $U(R_G, 0) = (1-R_G)r^f + R_G m \geq U(0, 1)$ and therefore we get that 
        \begin{align}
            m \geq -\frac{1-R_G}{R_G}r^f. \label{eq: rg equalibrium lower}
        \end{align}.
    \end{enumerate}

    \item If $(\alpha^{eq}, x^{eq}) = (R_F, 1-R_F)$ then:
    \begin{enumerate}
        \item GenAI's perspective: $V(R_F, 1-R_F) = (1-\gamma R_F(1-R_F)) r^g - c(1-R_F) - m R_F \geq V(0, 1)$
        We get the following inequality
        \[
            -\gamma R_F(1-R_F) r^g + R_F c - R_F m \geq 0, 
        \]
        Thus, $m$ has to satisfy one of the following conditions:
        \begin{itemize}
            \item $r^g > 2r^f$: 
            \begin{align}
                m \geq r^f \frac{\gamma r^g - 2c}{r^g - 2r^f} \label{eq: rg above 2rf}
            \end{align}
            \item $r^g < 2r^f$:
            \begin{align}
                m \leq r^f \frac{\gamma r^g - 2c}{r^g - 2r^f} \label{eq: rg below 2rf}
            \end{align}
        \end{itemize}

        \item Firm's perspective: $U(R_F, 1-R_F) = \gamma R_F (1-R_F)r^f + mR_F \geq U(0, 1)$.
        We get the following inequality
        \[
            \gamma (1-R_F)r^f + m \geq 0
        \]
        By extracting $m$, we get that $m \geq -\gamma r^f$.
    \end{enumerate}
\end{itemize}

\paragraph{Case II. $R_G = 0$} in this case, the base line is $(\alpha, x) = (0, 0)$. Therefore, it holds that $V(0, 0) = 0$ and $U(0, 0) = r^f$. Furthermore, we consider only the instances where $R_F \geq R_G$ and therefore the equilibrium is $(\alpha^{eq}, x^{eq}) = (R_G, 0)$

 \begin{enumerate}
     \item GenAI's perspective: $V(R_G, 0) = R_G r^g - R_G m \geq V(0, 0)$ and therefore we get that $m \leq r^g$.
     \item Firm's perspective: $U(R_G, 0) = (1-R_G)r^f + R_G m \geq U(0, 0)$ and therefore we get that $m \geq r^f$.
     Notice that from the condition $0 \leq R_F \leq 1$, it holds that $m \in [-\gamma r^f, \gamma r^f]$, and therefore, there is no $m$ under our conditions that induces a Pareto-improving equilibrium.
 \end{enumerate}

 This concludes the proof of \Cref{cor: pareto with gamma}.
 \end{proof}



We finished with the proof for any $\gamma \in (0, 1]$ and now turn to analyze for $\gamma = 1$.

We begin by presenting the following lemma.
\begin{lemma} \label{lemma: equalibrium RF conditions}
    Let $\gamma = 1$. The profile $(R_F, 1-R_F)$ is an equilibrium if and only if
    \begin{align*}
        m \leq r^f(4R_G - 3).
    \end{align*}
\end{lemma}

\Cref{lemma: equalibrium RF conditions} implies that $m = r^f(4R_G - 3)$ is the boundary for the two equilibria. That is, the profile $(R_F, 1-R_F)$ is the equilibrium for $m \leq r^f(4R_G - 3)$, and $(R_G, 0)$ is the equilibrium when $m > r^f(4R_G - 3)$. Therefore, the values of $m$ that are Pareto-improving can be separated into $2$ disjoint ranges, each induced by a different equilibrium.

We separate our analysis for two cases, namely when $r^g > 2r^f$ and $r^g \leq 2r^f$.

\begin{itemize}
    \item If $r^g > 2r^f$: 
We analyze this case for each equilibrium. Observe that if $(\alpha^{eq}, x^{eq}) = (R_F, 1-R_F)$ then according to \Cref{lemma: equalibrium RF conditions} it must hold that $m \leq r^f(4R_G - 3)$. Therefore, we can now check whether $m \leq r^f(4R^G - 3)$ also satisfies Equation~\eqref{eq: rg above 2rf}.

\begin{align*}
   m \leq r^f(4R_G - 3) = r^f\frac{r^g - 4c}{r^g} < r^f\frac{r^g - 4c}{r^g - 2r^f} < r^f\frac{r^g - 2c}{r^g - 2r^f}.
\end{align*}
Therefore, if $r^g > 2r^f$ then there is no $m \leq r^f(4R_G - 3)$ that results in Pareto improvement. In other words, there are no Pareto-improving prices $m$ that induce the equilibrium $(R_F, 1-R_F)$.
We now turn to the equilibrium profile $(R_G, 0)$. According to \Cref{cor: pareto with gamma} and Equation~\eqref{eq: rg equalibrium lower}, the equilibrium profile $(R_G, 0)$ can be induced by Pareto-improving prices $m$ if and only if $m$ lies in
\[
M_{R_G} = \left( \max\left\{-r^f, -r^f \frac{1-R_G}{R_G}, r^f(4R_G - 3)\right\}, 0 \right].
\]
Thus, to conclude, in the case where $r^g > 2r^f$, the Pareto-improving prices $m \in M_{R_G}$ for which the induced equilibrium is $(R_G, 0)$.

    \item If $r^g < 2r^f$:

In this case, we have 2 possible ranges for $m$, one for the equilibrium $(R_F, 1-R_F)$ and another for $(R_G, 0)$.
Starting with $(R_F, 1-R_F)$, then according to Equation~\eqref{eq: rg below 2rf} and \Cref{lemma: equalibrium RF conditions} we get that $m$ is Pareto-improving if it lies in
\begin{align}
    M_{R_F} =  \left[-r_f, \min \left\{ r^f \frac{r^g - 2c}{r^g - 2r^f}, r^f(4R_G - 3) \right\} \right].
\end{align}

Moving on to the equilibrium $(R_G, 0)$, the conditions for Pareto improvement do not depend on whether $r^g < 2r^f$. Therefore, for the same arguments as before, the Pareto-improving prices are $m \in M_{R_G}$.

Thus, to conclude, for the case where $r^g < 2r^f$, any $m \in M_{R_G} \cup M_{R_F}$ is Pareto-improving.

\end{itemize}

We finish by showing that there are no Pareto-improving prices such that $m > 0$. Observe that if $m$ is Pareto-improving, it must either be in $M_{R_F}$ or $M_{R_G}$. By definition it holds that $M_{R_G} \in \mathbb{R}_{\leq 0}$. Next, we use the following observation to show that $M_{R_F}$ is also in $\mathbb{R}_{\leq 0}$.

\begin{observation} \label{obs: negative expressions Mrf}
If $r^g < 2r^f$ then there is no $r^g > 0$ such that $r^f \frac{r^g - 2c}{r^g - 2r^f} > 0$ and $r^f(4R_G - 3) > 0$.
\end{observation}

Thus, it holds that $M_{R_G} \cup M_{R_F} \in \mathbb{R}_{\leq 0}$.

This concludes the proof of \Cref{cor:pareto}.
























\begin{proofof}{lemma: equalibrium RF conditions}
There are two conditions that must hold:
\begin{align}
    R_G > R_F   \label{eq: welfare RG above RF}
\end{align}
and
\begin{align}
    U(R_G, 0) \leq U(R_F, 1-R_F)    \label{eq: welfare RF opt}
\end{align}

The condition in Inequality~\eqref{eq: welfare RG above RF} yields
\begin{align*}
    m < \frac{r^f}{r^g} \left( r^g(2-\gamma) - 2c \right)
\end{align*}
while the second conditions from Inequality~\eqref{eq: welfare RF opt} results in
\begin{align*}
    m^2 \frac{1}{4\gamma r^f} + m \left( \frac{1}{2} - R_G \right) + r^f \left( \frac{\gamma}{4} - 1 + R_G \right) \geq 0
\end{align*}
Where the solution of the inequality is given by:
\begin{align*}
m_{\pm} = \frac{R_G - \frac{1}{2} \pm \sqrt{(R_G - 1)\left(R_G - \frac{1}{\gamma} \right)}}{\frac{1}{2r^f}}
\end{align*}

For $\gamma = 1$ we get that:
\begin{align*}
m_{\pm} = 2r^f \left( R_G - \frac{1}{2} \pm \left( 1-R_G \right) \right)
\end{align*}
Thus,
\begin{align*}
    & m_+ = r^f \\
    & m_- = r^f(4R_G - 3).
\end{align*}
Finally, we can conclude the values of $m$ that satisfies Inequality~\eqref{eq: welfare RG above RF} and Inequality~\ref{eq: welfare RF opt} are:
\begin{enumerate}
    \item $m < \frac{r^f}{r^g} \left( r^g(2-\gamma) - 2c \right)$
    \item $m \geq m_+$ or $m \leq m_-$.
\end{enumerate}

Observe that
\begin{align*}
    m_- < r^f\left(1-2\frac{c}{r^g}\right) < r^f
\end{align*}
Therefore, we can summarize that the profile $(R_F, 1-R_F)$ is the equilibrium only if $m \leq m_-$.
This concludes the proof of \Cref{lemma: equalibrium RF conditions}.
\end{proofof}




\begin{proofof}{obs: negative expressions Mrf}
Assume in contradiction that there exists $r^g > 0$ such that $r^f \frac{r^g - 2c}{r^g - 2r^f} > 0$ and $r^f(4R_G - 3) > 0$.

Starting with $r^f \frac{r^g - 2c}{r^g - 2r^f} > 0$, Since $r^f < 2r^f$ it must hold that $r^g < 2c$.

Next, observe that
\begin{align*}
r^f(4R_G - 3) = \frac{r^f}{r^g} \left( r^g - 4c \right) < \frac{r^f}{r^g} \left( 2c - 4c \right) < -2c \frac{r^f}{r^g} < 0.
\end{align*}

Which is a contradiction to our assumption.
\end{proofof}

















\subsection{Proof of \Cref{cor:welfare}}

\begin{proof}

The equilibrium analysis reveals two possible equilibria. Let $\theta^{eq} = (\alpha^{eq}, x^{eq})$ denote the equilibrium profile. Therefore, our objective is of the following form:

\begin{align*}
    \alpha + \lambda x &= \begin{cases}
        R_G & \mbox{$\theta^{eq} = (R_G, 0)$} \\
        R_F + \lambda(1-R_F) & \mbox{$\theta^{eq} = (R_F, 1-R_F)$}
    \end{cases} \\
    &= \begin{cases}
        R_G & \mbox{$\theta^{eq} = (R_G, 0)$} \\
        R_F(1-\lambda) + \lambda & \mbox{$\theta^{eq} = (R_F, 1-R_F)$}
    \end{cases}.
\end{align*}

According to \Cref{lemma: equalibrium RF conditions}, the condition for $\theta^{eq} = (R_F, 1-R_F)$ to be an equilibrium is $m \leq m_- = r^f(4R_G - 3)$. 

Notice that if the profile $(R_F, 1-R_F)$ is the equilibrium, then we need to choose $m$ such that
\begin{align*}
    \max_{m} R_F(1-\lambda) + \lambda = \max_{m} R_F(1-\lambda)
\end{align*}
Therefore, we would like to pick the maximal $m$ if $\lambda < 1$ and the minimal $m$ if $\lambda > 1$.

We split our analysis into 4 cases: $\lambda > 1$, $\lambda = 1$, $0 <\lambda < 1$ and $\lambda = 0$.
\begin{enumerate}
    \item Case 1: $\lambda \geq 1$. From our conditions on $m$ and our condition for $R_F \in [0, 1]$ we get that $m_{min}$ is the minimal value in $[-r^f, m_-]$. $m_{min}$ is well defined only if $m_- \geq -r^f$, which implies $r^g \geq 2c$. In this case, the objective function under the profile $(R_F, 1-R_F)$ is given by
        \begin{align*}
            R_F(1-\lambda) + \lambda = \lambda > 1 > R_G.
        \end{align*}
        Since $R_F(1-\lambda) + \lambda > R_G$ we indeed get that $m = -r^f$ maximize our objective function.
        Therefore, to conclude, $m = m_{min}$ is optimal if $\lambda \geq 1$ and $r^g \geq 2c$. If $r^g < 2c$ then $(R_F, 1-R_F)$ is never the equilibrium profile. That is, $(R_G, 0)$ is the equilibrium profile - since $R_G$ does not depend on $m$ then any $m \in [-r^f, r^f]$ is optimal.



    \item Case 2: $\lambda < 1$: For the profile $(R_F, 1-R_F)$ to be the equilibrium and to maximize the objective function, we need to choose the maximal $m$ which satisfies our conditions. 

    The maximal $m = m_{max} = m_-$ is optimal only if it holds that $R_F(1-\lambda) + \lambda \geq R_G$. Plugging $m = m_{max}$ results in:
    \begin{align*}
        \frac{r^f + m_{max}}{2r^f}(1-\lambda) + \lambda - R_G &= \frac{r^f + r^f(4R_G - 3)}{2r^f}(1-\lambda) + \lambda - R_G \\
        &= (2R_G - 1)(1-\lambda) + \lambda - R_G \\
        &= (R_G - 1)(1-2\lambda)
    \end{align*}

    Therefore, we can further split the analysis of $\lambda$ into 3 cases:
    \begin{itemize}
        \item If $\lambda > 0.5$ and $r^g \geq 2c$ then $m = m_{max}$ is optimal.
        \item If $\lambda < 0.5$ then the profile $(R_G, 0)$ maximizes our objective function. Therefore, if $r^g \geq 2c$ then any $m \in (m_-, r^f]$ is optimal, and if $r^g < 2c$ then any $m \in [-r^f, r^f]$ is optimal.
        \item If $\lambda = 0.5$ then both profiles can maximize our objective function. If $r^g < 2c$ then any $m \in [-r^f, r^f]$ is optimal and if $r^g \geq 2c$ then any $m \in [m_-, r^f]$ is optimal.
    \end{itemize}   
\end{enumerate}


Therefore, to summarize, if $r^g < 2c$ then any $m \in [-r^f, r^f]$ is optimal.
If $r^g \geq 2c$ then 
\begin{align*}
    m = \begin{cases}
        -r^f & \mbox{$\lambda \geq 1$} \\
        r^f(4R_G - 3) & \mbox{$0.5 < \lambda < 1$} \\
        m' & \mbox{$\lambda = 0.5$} \\
        m'' & \mbox{$\lambda < 0.5$}
    \end{cases}
\end{align*}
where $m', m''$ can be any value such that $m' \in [r^f(4R_G - 3), r^f]$ and $m'' \in (r^f(4R_G - 3), r^f]$.

This concludes the proof of \Cref{cor:welfare}.
\end{proof}


