\subsubsection{Calculating witness function for $\WT \rel$}\label{sec:calculate-witness-function}
In this subsection, we show how to calculate a frame $\WT F$, the frame classes $\WT \cE$, and a witness function $\WT\omega$ for $\WT\rel$. Since $\PAR\rel \in \SP \cH_2$ is rectangular, we can consider its frame and witness function, denoted as $\cE'$ and $\omega'$. Suppose we have already calculated the frame and witness function for $\PAR\rel$. By applying Lemma~\ref{lem:PAR-exists} and Proposition~\ref{pro:Frame_projection}, we can obtain a witness function and frame for $\WT\rel$ in $O(n)$ time.

To calculate a witness function for $\PAR\rel$, we use two auxiliary lemmas. Once we have a witness function for $\PAR\rel$, we can proceed with calculating a witness function for $\WT\rel$.

\begin{lemma}\label{lem:tool_PAR}
Let $(\vv x, y)\in \rel$  where $\vv x \in H^{n-1}$ and $y \in H$. If there exists $s\in [|\cE_n|]$ such that $|\cE_{n, s}| \equiv 1 \pmod 2$ and $y \in \cE_{n, s}$, then $(\vv x, y) \in \PAR\rel$.
\end{lemma}

\begin{proof}
We need to calculate the number of extensions of $\vv x$.
\begin{align*}
    \ext_\rel(\vv x) &= \sum_{z \in H} \sgn_\rel(\vv x, z)\\
    &= \sum_{z \in \pr_n \rel} \sgn_rel(\vv x , z)\\
    &= \sum_{i \in [|\cE_{n}|]} \sum_{ z\in \cE_{n, i}} \sgn_\rel(\vv x , z)\\
    &= \sum_{ z\in \cE_{n, s}} \sgn_\rel(\vv x , z)\\
    &\equiv |\cE_{n,s}| \equiv 1 \pmod 2.
\end{align*}
The first and second equalities are straightforward, as they follow directly from the definition of the function $\sgn$. The third equality holds because we can partition the set $\pr_n\rel$ into equivalence classes given by the frame $F$. The fourth equality is valid because the relation $\rel$ is rectangular, and so $\vv x$ can be extended to only one class $\cE_{n,s}$.
Since there exists $s \in [|\cE_n|]$ such that $y \in \cE_{n,s}$, the number of extensions of $\vv x$ should be the cardinality of $\cE_{n,s}$. As $|\cE_{n,s}|\equiv 1$, the number of extensions of $\vv x$ is $1$ modulo $2$. Therefore, $(\vv x, y) \in \PAR\rel$.
\end{proof}

\begin{lemma}
Let $a, b \in H$, $k\in[n]$, and $\vv x \in H^n$ be such that $\vv x \in \PAR\rel$ and $\pr_k \vv x = a$. We can check in $O(n^3)$ if $a \sim'_k b$, where $\sim'_k$ is the frame equivalence of $\PAR\rel$.
\end{lemma}

\begin{proof}
As $\PAR\rel \in \SP \cH_2$, we know that $\pr_{[k]}\PAR\rel$ is rectangular. Therefore, if $(\pr_{[k-1]}\vv x, a) \in \pr_{[k]} \PAR\rel$ and $a \sim'_k b$, then $(\pr_{[k-1]} \vv x, b) \in \pr_{[k]}\PAR\rel$. This implies the existence of an extension $(\vv y, c) \in H^{n-k}$ such that $(\pr_{[k-1]}\vv x, a, \vv y, c) \in \PAR\rel$. According to Lemma~\ref{lem:tool_PAR}, we can check if $(\pr_{[k-1]}\vv x, a, \vv y, c) \in \PAR\rel$ by verifying if $c$ belongs to an $\cE_n$ class of $\rel$ with odd cardinality.

We begin by defining the relation $\rela(x_1, ..., x_n)$ as follows:
\[
    \rela(x_1, ..., x_n) = \rel(x_1, ..., x_n ) \wedge ( \bigwedge_{i \in [k-1]} x_s \in C_{d_i}) \wedge (x_k \in C_b)
\]
Essentially, $\rela$ is the same as $\rel$ with its first $k-1$ coordinates fixed to the corresponding coordinates of $\vv x$, and the $k$th coordinate fixed to $b$. We can compute the witness function and frame classes of $\rela$ using Proposition~\ref{pro:Frame_constant_string_existance}, in time $O(n^3)$. We denote the resulting frame classes by $\cE''$. Next, we check if there exists $t \in [|\cE''_{n}|]$ such that $|\cE''_{n,t}|\equiv 1 \pmod 2$. If such a $t$ exists, then by Lemma~\ref{lem:Frame_add_const} and Lemma~\ref{lem:tool_PAR}, we can conclude that $a\sim'_k b$.

This process requires only $O(n^3)$ time to compute the witness function for $\rela$, and then $O(1)$ time to detect whether there exists such a $t$. Therefore, the overall running time of the algorithm is $O(n^3)$.
\begin{algorithm}[H]
\caption{$\mathsf{CheckEpsilonClass}$($\vv x \in H^n, a, b\in H, k \in [n]$)}\label{alg:EpsilonClass}
    \begin{algorithmic}[1]
    \State Construct $\rela$ as $\rela(x_1, ..., x_n) = \rel(x_1, ..., x_n ) \wedge ( \bigwedge_{i \in [k-1]} x_s \in C_{d_i}) \wedge (x_k \in C_b)$
    \State Calculate $\cE''$ classes of $\rela$ with its witness function $\omega''$
    \If {there exists $t \in [|\cE''_{n}|]$ such that $|\cE''_{n,t}|\equiv 1 \pmod 2$}
    \State set $\omega'(k, b) = \omega''(n, c)$, for $c \in \cE''_{n,t}$
    \State \textbf{Return} $\omega'(k, b)$
    \Else
    \State \textbf{Return} $\bot$
    \EndIf
    \end{algorithmic}
\end{algorithm}
Note that if the algorithm $\mathsf{CheckEpsilonClass}$ returns $\vv y \in H^n$ for the input $\vv x \in H$ and $a, b \in H$, then it follows that $\pr_k \vv y = b$ and $\pr_{[k-1]} \vv x = \pr_{[k-1]} \vv y$. This is because, in line (4) of the algorithm, $\omega'(k,b)$ is set to be $\omega''(n,c)$ and we know that $\pr_k \omega''(n,c) = b$ and $\pr_{[k-1]} \omega''(n,c )= \pr_{[k-1]} \vv x$, as per the definition of $\rela$.
\end{proof}

\begin{proposition}\label{pro:calculate-witness}
Given a witness function $\omega$ for $\rel$, a witness function $\WT\omega(k, a)$ for $\WT\rel$ can be found in time $O(n^4)$ for any $k\in[n]$ and $a\in H$,.
\end{proposition}

\begin{proof}
In the first step, we calculate a witness function $\omega'$ and frame $F'$ for $\PAR\rel$. Using Proposition~\ref{pro:Frame_projection} and Lemma~\ref{lem:PAR-exists}, we can then compute the witness function and frame for $\WT\rel$.

In order to compute $\omega'$, we first need to compute $\omega'(n,a)$ for all $a\in H$. This step is relatively simple. Since $a \in \pr_n \PAR\rel$ if and only if there exists $\vv x\in H^{n-1}$ such that $(\vv x, a) \in \PAR\rel$, we can check whether $\ext_\rel(\vv x) \equiv 1 \pmod 2$. By Lemma~\ref{lem:tool_PAR}, $a \in \pr_n \PAR\rel$ if and only if $a \in \cE_{n, s}$ where $s\in [|\cE_{n}|]$ and $|[\cE_{n,s}]| \equiv 1 \pmod 2$.
Clearly, if $a \sim_n b$, then $a \sim'_n b$. Therefore, we can set $\omega'(n,a) = \omega(n,a)$ if $|\cE_{n,s}| \equiv 1 \pmod 2$, and $\omega'(n,a) = \bot$ if $|\cE_{n,s}| \equiv 0 \pmod 2$. Note that this step only takes $O(1)$ time, since $\omega$ is already given to us.

Let $k\in [n-1]$. According to Proposition~\ref{pro:Frame_constant_existance}, we can compute $\omega^{k\leftarrow a}$ and $\cE^{k \leftarrow a}$ in $O(n^2)$ time. Next, we examine $\cE^{k \leftarrow a}_{n, i}$ for $i \in [|\cE^{k \leftarrow a}_{n}|]$. We check whether there exists an $s \in [|\cE^{k\leftarrow a}_{n}|]$ such that $|\cE^{k\leftarrow a}_{n, s}| \equiv 1 \mod 2$. If we find such an $s$, we select $b \in \cE^{k\leftarrow a}_{n, s}$ and set $\omega'(k, a) = \omega^{k\leftarrow a}(n, b)$. Otherwise, we assign $\omega'(k, a) = \bot$. Note that searching for $s$ only requires $O(1)$ time since we only need to look up $|\cE^{k \leftarrow a}_n|$ options, which is less than $|H|$. 
Since $\omega'(k, a) = \omega^{k \leftarrow a}(n,b)$, it follows that $\pr_k \omega'(k, a) = \pr_k\omega^{k \leftarrow a} (n,b)= a$. Also, because of the way we construct $\omega'(k,a)$ and Lemma~\ref{lem:tool_PAR}, we have that $\omega'(k, a) \in \PAR\rel$.

Next, we use Algorithm~$\mathsf{CheckEpsilonClass}(\omega'(k,a), a, b)$ for all $b \in H$ to derive the equivalence relation $\sim'_k$ defined by $\PAR\rel$ for the $k$th coordinate. If the algorithm returns $\vv y$, it means that $a \sim'_k b$ and they are in the same class. Therefore, we set $\omega'(k,b) = \vv y$. Otherwise, $a \not \sim'_k b$. We repeat this process for each $a \in H$ whose witness function has not yet been associated with anything, and at the end, we have the witness function for $\PAR\rel$. By Proposition~\ref{pro:Frame_projection}, we have the witness function for $\WT\rel$, as well.

\begin{algorithm}[H]
\caption{$\mathsf{FindWitnessFunction}(\omega, \cE)$}\label{alg:WitnessFunction}
    \begin{algorithmic}[1]
    \State Compute $\omega$ and $\cE$ for $\rel$.
    \For{\textbf{each} $a \in H$}
        \State Find $s \in \cE_{n}$ such that $a \in \cE_{n,s}$
        \If{ $|\cE_{n,s}| \equiv 1 \pmod 2$}
            \State $\omega'(n,a) \gets \omega(n,a)$
        \Else
            \State Set $\omega'(n,a) \gets \bot$
        \EndIf
    \EndFor

    \For{\textbf{each} $k \in [n-1]$}
        \State Set $D \gets H$
        \While{$D \not = \emptyset$}
            \For{\textbf{each} $a \in D$}
                \State Calculate $\omega^{k\gets a}$ and $\cE^{k \gets a}$
                \If{ there exists $s \in [|\cE^{k\gets a}_{n}|]$ such that $|\cE^{k\gets a}_{n,s}| \equiv 1 \pmod 2$}
                    \State Pick $b\in \cE^{k \gets a}_{n, s}$
                    \State Set $\omega'(k,a) \gets \omega(n, b)$
                    \For{\textbf{each} $ c \in D\setminus \{a \}$}
                        \State Set $\vv y \gets \mathsf{CheckEpsilonClass}(\omega'(k,a), a, c, k)$
                        \If{ $\vv y \not = \bot$}
                            \State Set $\omega'(k,b) \gets \vv y$
                            \State Set $D \gets D \setminus \{c\}$
                        \EndIf
                    \EndFor
                \Else
                    \State Set $\omega'(k,a) \gets \bot$
                \EndIf
            \EndFor
        \EndWhile
    \EndFor
    \State Calculate $\WT\omega$ and $\WT\cE$ based on $\omega'$ and $\cE'$ by projection \Comment{Proposition~\ref{pro:Frame_projection}}
    \State \textbf{Return} $\WT\omega$ and $\WT\cE$
    \end{algorithmic}
\end{algorithm}
\end{proof}

\begin{remark}
    Note that at no point the algorithm explicitly uses the condition of 2-rigidity, although it is among the conditions of Proposition~\ref{pro:parity-algorithm}. However, it uses constant relations in a very essential way, they are used to compute the witness function and frames. In general relational structures, the availability of constant relations is not guaranteed. However, by Theorem~\ref{the:ConstantCSP-main}, we can add constant relations to $\cH$ if $\cH$ is 2-rigid.
\end{remark}

