An important ingredient of the complexity classification of $\#_pCSP$ for graphs \cite{DBLP:conf/stoc/BulatovK22} is the structure of automorphisms of graph products, see \cite{ref:ProductOfGraphs} for non-bipartite graphs and \cite{DBLP:conf/stoc/BulatovK22} for bipartite graphs. We compare the situation for relational structures with the result for non-bipartite graphs stated below. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Automorphisms of structures and automorphisms of products}\label{sec:poduct-auto}
% the result for graphs
Let $G=(V,E)$ be a graph. The graph $G$ is said to be \emph{$\RT$-thin} if it does not have \emph{twin vertices}, that is, vertices with equal neighbourhoods. The graph $G$ is \emph{prime} if for any representation $G=G_1\tm G_2$ one of $G_1,G_2$ is a 1-element graph. A representation $G=G_1\tm\dots\tm G_r$ is said to be \emph{prime factorization of} of $G$ if all the $G_i$'s are prime.

\begin{theorem}[\cite{ref:ProductOfGraphs}, \cite{DBLP:conf/stoc/BulatovK22}]\label{the:splitting_automorphisms}
 Let $G=G_1\tm\dots\tm G_r$ be a prime factorization of a connected $\RT$-thin non-bipartite graph $\sG$, where for $v\in V(G)$, we have $v=(\vc{v}{r})$. Then for any automorphism $\psi$ of $\sG^{\ell}$, there is a permutation $\pi$ of $[\ell]\times [r]$ such that $\psi$ can be split into $r\ell$ automorphisms:
\begin{align*}
    \psi([v_1]\zd [v_\ell])= \left( \vvecad{\psi_{1,1}([v_{\pi(1,1)}])}{\psi_{1,r}([v_{\pi(1,r)}])},...,\vvecad{\psi_{\ell,1}([v_{\pi(\ell,1)}])}{\psi_{\ell,r}([v_{\pi(\ell,r)}])} \right),
\end{align*}
for $(i',j')=\pi(i,j)$, $\psi_{i,j}$ is an isomorphism from the $i'$th copy of $G_{j'}$ to the $i$th copy of $G_j$. 
\end{theorem}

% counterexample for structures
As the following example shows, an analogous result is not true for relational structures.

\begin{example}\label{exa:bad-graph}
Let $\cH = (V, E)$ be a directed graph where $V = \{a, b,c ,d \}$ with directed edges $E = \{ (b, a), (b,c), (c,d) \}$. If we view $\cH$ as a relational structure, then it is 2-rigid. However, the automorphism group of $\cH^2$ has a complicated structure. As is seen in Figure~\ref{fig:bad-example}, $\cH^2$ has the following automorphism: $\pi(a,d)=(c,d), \pi(c,d)=(a,d)$, and $\pi(x,y)=(x,y)$ otherwise.
This automorphism does not have the structure given in Theorem~\ref{the:splitting_automorphisms}.

\begin{figure}[H]
    \centering
    \includegraphics[height=3.5cm]{example-product.eps}
    \caption{The structure of $\cH$ and $\cH^2$}
    \label{fig:bad-example}
\end{figure}
\end{example}


