\section{Products of relational structures and the uniqueness of $\protect\ovarrow\cH^{*p}$}\label{sec:appendix-new}
%% \input{Data/q-appendix-new}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The goal of this subsection is to prove Proposition~\ref{pro:mult-uniqueness-main}.

\renewcommand{\theprop}{2.1}
\begin{prop}
Let $\ovarrow\cH$ be a multi-sorted  structure and $p$ a prime. Then up to an isomorphism there exists a unique $p$-rigid multi-sorted  structure $\ovarrow\cH^{*p}$ such that $\ovarrow\cH\rightarrow_p^* \ovarrow\cH^{*p}$.
\end{prop}

However, in order to do this we first need to introduce some auxiliary tools. In particular we use expansions of multi-sorted structures vertices and their homomorphisms. 
Note that a multi-sorted relational structure $(\ovarrow\cG,\vv a)$ with distinguished vertices can be viewed as an expansion of $\cG$ with $k$ additional unary symbols, one for each distinguished vertex. Also, note that these distinguished vertices may come from different sorts. In such an interpretation a homomorphism of multi-sorted structures with distinguished vertices is just a homomorphism between the corresponding expansions.

Next we introduce two types of products of multi-sorted structures. Recall that the \emph{direct product} of similar multi-sorted $\sg$-structures $\ovarrow\cH,\ovarrow\cG$, denoted $\ovarrow\cH\tm\ovarrow\cG$ is the multi-sorted $\sg$-structure with the base set $\colect{H_i \times G_i}{i\in[k]}$ and such that the interpretation of $\rel\in\sg$ is given by $\rel^{\ovarrow\cH\tm\ovarrow\cG}((a_1,b_1)\zd(a_k,b_k))=1$ if and only if $\rel^{\ovarrow\cH}(\vc ak)=1$ and $\rel^{\ovarrow\cG}(\vc bk)=1$. By $\ovarrow\cH^\ell$ we will denote the \emph{$\ell$th power} of $\ovarrow\cH$, that is, the direct product of $\ell$ copies of $\ovarrow\cH$. The direct product $(\ovarrow\cG,\vv x)\tm(\ovarrow\cH,\vv y)$ of structures $(\ovarrow\cG,\vv x),(\ovarrow\cH,\vv y)$, where $\vv x, \vv y$ are $r$-tuples, is defined to be $(\ovarrow\cG\tm\ovarrow\cH,(\bx[1]_1,\by[1])\zd(\bx[r],\by[r]))$. 

 For $a\in\bigcup_{i\in[k]}H_i$ (or $a\in\bigcup_{i\in[k]}G_i$) we write $\type(a)=i$ if $a\in H_i$ (respectively, $a\in G_i$) Two $r$-tuples $\vv{x} $ and $\vv{y}$ have the same \emph{equality type} if $(x_i, \type(x_i)) = (x_j, \type(x_j))$ if and only if $(y_i, \type(y_i) )= (y_j, \type(y_j))$ for $i,j\in[r]$. 
 Let $(\ovarrow\cG,\vv x)$ and $(\ovarrow\cH,\vv y)$ be multi-sorted structures with $r$ distinguished vertices and such that $\vv x$ and $\vv y$ have the same equality type. Then $(\ovarrow\cG,\vv x)\odot(\ovarrow\cH,\vv y)$ denotes the structure that is obtained by taking the disjoint union of $\ovarrow\cG$ and $\ovarrow\cH$ and identifying every $x_i$ with $y_i$, $i\in[r]$. The distinguished vertices of the new structure are $\vc xr$.

The following statement is straightforward.

\begin{proposition}
Let $(\ovarrow\cG,\vv x),(\ovarrow\cH,\vv y),(\ovarrow\cK,\vv z)$ be similar multi-sorted relational structures with $r$ distinguished vertices. Then
%%
\begin{align*}
\hom((\ovarrow\cG,\vv x)\odot(\ovarrow\cH,\vv y),(\ovarrow\cK,\vv z)) &= \hom((\ovarrow\cG,\vv x),(\ovarrow\cK,\vv z))\cdot\hom((\ovarrow\cH,\vv y),(\ovarrow\cK,\vv z)); \\  
\hom((\ovarrow\cK,\vv z),((\ovarrow\cG,\vv x)\times(\ovarrow\cH,\vv y)) &= \hom((\ovarrow\cK,\vv z),(\ovarrow\cG,\vv x))\cdot\hom((\ovarrow\cK,\vv z),(\ovarrow\cH,\vv y)).   
\end{align*}
Moreover, $\ovarrow\vf\in\Hom((\ovarrow\cK,\vv z),((\ovarrow\cG,\vv x)\times(\ovarrow\cH,\vv y))$ if and only if there exist $\ovarrow\vf_1 \in \Hom((\ovarrow\cK,\vv z),(\ovarrow\cG,\vv x))$ and $\ovarrow\vf_2\in\Hom((\ovarrow\cK,\vv z),(\ovarrow\cH,\vv y))$ such that $\ovarrow\vf(v)=(\ovarrow\vf_1(v),\ovarrow\vf_2(v))$ for $v\in K$.
\end{proposition}

We will also need another simple observation. By $\inj((\ovarrow\cG,\vv{x}),(\ovarrow\cH,\vv{y}))$ we denote the number of injective homomorphisms from $(\ovarrow\cG,\vv x)$ to $(\ovarrow\cH,\vv y)$.

\begin{lemma}[cf. \cite{ref:CountingMod2ToSquarefree}]
Let $(\ovarrow\cG,\vv{x})$ and $(\ovarrow\cH,\vv{y})$ be similar multi-sorted relational structures with $r$ distinguished vertices. If $\vv{x},\vv{y}$ do not have the same equality type, then $\inj((\ovarrow\cG,\vv{x}),(\ovarrow\cH,\vv{y}))=0$.
\end{lemma}
\begin{proof}
    If there are $i, j \in [r]$, where $r$ is the arity of $\vv x$ and $\vv y$, such that $(x_i , \type(x_i))= (x_j, \type(x_j))$ but $(y_i, \type(y_i) )\neq (y_j, \type(y_j))$, then there are no homomorphisms (injective or otherwise) from $(\ovarrow{\cG}, \vv{x})$ to $(\ovarrow{\cH}, \vv{y})$, since $x_i$ cannot be mapped simultaneously to both $y_i$ and $y_j$. Otherwise, there must be $i, j \in [r]$ such that $(x_i , \type(x_i)) \neq (x_j, \type(x_j))$ but $(y_i, \type(y_i) ) = (y_j, \type(y_j))$. Then no homomorphism $\vf$ can be injective because we must have $\vf(x_i) = \vf(x_j) = y_i$.
\end{proof}

Finally, we will use factor structures. Let $\ovarrow\cH$ be a multi-sorted $\sg$-structure and $\ovarrow\th = \colect{\th_i}{i\in[k]}$ a collection of equivalence relations on $H = \colect {H_i}{i\in[k]}$, such that $\th_i\sse H_i^2$ for all $i\in [k]$. By $\ovarrow\cH/_{\ovarrow\th}$ we denote the \emph{factor structure} defined as follows. 
\begin{itemize}
    \item
    $\ovarrow\cH/_{\ovarrow\th}$ is a multi-sorted $\sg$-structure.
    \item 
    Let $H_i/_{\th_i}=\{a/_{\th_i}\mid a\in H_i\}$, where $a/_{\th_i}$ denotes the $\th_i$-class containing $a$. The base set of $\ovarrow\cH/_{\ovarrow\th}$ is $H/_{\ovarrow\th}=\colect{H/_{\th_i}}{i\in[k]}$
    \item
    For any $\rel\in\sg$, say, $s$-ary, $\rel^{\ovarrow\cH/_{\ovarrow\th}}=\{(a_1/_{\th_1}\zd a_s/_{\th_s})\mid (\vc as)\in\rel^{\ovarrow\cH}\}$.
\end{itemize}
The set of all equivalence relations of a multi-sorted set $H$ is denoted $\Part(H)$ and the equivalence relation that is the equality on each set from $H$ is denoted by $\zz$.

Factor structures often appear in relation with homomorphisms. If $\ovarrow\vf$ is a homomorphism from a multi-sorted structure $\ovarrow\cG$ to a multi-sorted structure $\ovarrow\cH$, then the \emph{kernel} $\ovarrow\th$ of $\ovarrow\vf$, denoted $\ker(\ovarrow\vf)$, is a collection of equivalence relations on $G = \colect{G_i}{i\in[k]}$ given by 
\[
\text{For } a,b \in G_i, \; (a,b) \in\th_i \text{ if and only if } \vf_i(a) =\vf_i(b).
\]
For an equivalence relation $\ovarrow\th$ on $G = \colect{G_i}{i\in[k]}$ by $\hom_{\ovarrow\th}(\ovarrow\cG,\ovarrow\cH)$ and $\Hom_{\ovarrow\th}((\ovarrow\cG,\vv x),(\ovarrow\cH,\vv y))$ we denote the number of homomorphisms from $\ovarrow\cG$ to $\ovarrow\cH$ (from $(\ovarrow\cG,\vv x)$ to $(\ovarrow\cH,\vv y)$) with kernel $\ovarrow\th$.
The homomorphism $\ovarrow\vf$ gives rise to a homomorphism $\ovarrow\vf/_{\ovarrow\th}$ from $\ovarrow\cG/_{\ovarrow\th}$ to $\ovarrow\cH$, where $\vf_{i}/_{\th_i}(a/_{\th_i})=\vf_i(a)$, $a\in G_i$. The homomorphism $\ovarrow\vf/_{\ovarrow\th}$ is always injective since all $\vf_i/_{\th_i}$ are injective.

We also define factor structures for structures with distinguished vertices as follows. Let $(\ovarrow\cH,\vv a)$ be a structure with $s$ distinguished vertices and $\ovarrow\th$ an equivalence relation on $H$. Then $(\ovarrow\cH,\vv a)/_{\ovarrow\th}=(\ovarrow\cH/_{\ovarrow\th}, \vv a/_\th)$, where $\vv a/_{\ovarrow\th} = (a_1/_{\th_{\type(a_1)}}\zd a_s/_{\th_{\type(a_s)}})$. 


\begin{lemma}\label{lem:lovasz-multi-structure}
Let $(\ovarrow\cG, \vv{x})$ and $(\ovarrow\cH,\vv y)$ be similar $p$-rigid multi-sorted relational structures with $r$ distinguished vertices. Then, $(\ovarrow\cG, \vv{x}) \cong (\ovarrow\cH,\vv y)$ if and only if 
\begin{equation}
\hom((\ovarrow\cK, \vv{z}) , (\ovarrow\cG, \vv{x})) \equiv \hom((\ovarrow\cK, \vv{z}),(\ovarrow\cH, \vv{y})) \pmod{p} \label{equ:lovasz}
\end{equation} 
for all relational structures $(\ovarrow\cK, \vv z)$ with $r$ distinguished vertices.
\end{lemma}

\begin{proof}
The proof goes along the same lines as that in \cite{ref:CountingModPToTrees_gbel_et_al_LIPIcs}. If $(\ovarrow\cG, \vv{x})$ and $(\ovarrow\cH,\vv y)$ are isomorphic, then \eqref{equ:lovasz} obviously holds for all multi-sorted relational structures $(\ovarrow\cK, \vv{z})$. 

For the other direction, suppose that \eqref{equ:lovasz} is true for all $(\ovarrow\cK, \vv z)$.
First, we claim that this implies that $\vv{x} = (x_1 , \ldots, x_r)$ and $\vv{y} = (y_1, \ldots, y_r)$ have the same equality type. Indeed, if they do not, then without loss of generality there are $i,j\in[r]$ such that $(x_i, \type(x_i)) = (x_j, \type(x_j))$ but $(y_i, \type(y_i))\ne (y_j, \type(y_j))$. 
Let $s = \type(\ovarrow\cH)$, $ X= \{ x_1,\ldots, x_r \}$, and $\ovarrow\cK$ be the relational structure with the base multi-sorted set $K = \colect{K_i}{i\in[k]}$ where $K_i = \{ x \in X\mid \type(x) = i  \}$  with empty predicates, and $(\vc xr)$ as distinguished vertices. Note that there might exist $i$ such that $K_i$ is empty. Then $\hom((\ovarrow\cK, \vv{x}) , (\ovarrow\cG, \vv{x}))=1 \ne 0=  \hom((\ovarrow\cK, \vv{x}),(\ovarrow\cH, \vv{y}))$, a contradiction with the assumption that \eqref{equ:lovasz} holds for all $(\ovarrow\cK,\vv{x})$.

We show by induction on the number of vertices in $\ovarrow\cK$ that 
\begin{equation}\label{lavasEquInj}
\inj((\ovarrow\cK, \vv{z}),(\ovarrow\cG, \vv{x})) \equiv \inj((\ovarrow\cK, \vv{z}),(\ovarrow\cH, \vv{y})) \pmod{p},  
\end{equation}
for all $(\ovarrow\cK, \vv{z})$. Let $n_0 = |\{(x_1, \type(x_1)) , ..., (x_r, \type(x_r)) \}| = |\{(y_1, \type(y_1)) , ..., (y_r, \type(y_r))\}|$ be the number of distinct elements in $\vv x,\vv{y}$. For the base case of the induction, consider a relational structure $(\ovarrow\cK, \vv{z})$  such that $|K| \leq n_0$. If $\vv{z}$ does not have the same equality type as $\vv x,\vv{y}$, then $\inj((\cK, \vv{z}),(\cG, \vv{x})) = \inj((\cK, \vv{z}),(\cH, \vv{y})) = 0$.
If $\vv{x}$ has the same equality type as $\vv x,\vv{y}$, the only homomorphisms from $(\ovarrow\cK,\vv z)$ to $(\ovarrow\cG,\vv x),(\ovarrow\cH,\vv y)$ are the ones that map $z_i$ to $x_i,y_i$, respectively. Therefore, $\inj((\ovarrow\cK, \vv{z}),(\ovarrow\cG,\vv{x}))=\inj((\ovarrow\cK, \vv{z}) , (\cH, \vv{y}))$.

For the inductive step, let $n > n_0$ and assume that (\ref{lavasEquInj}) holds for all $(\ovarrow\cK, \vv{z})$ with $|K| < n$. Let $(\ovarrow\cK,\vv{z})$ be a relational structure with $|K|=n$, and let $\ovarrow\th = \colect{\th_i}{i\in[k]}$ be a collection of equivalence relations on $K$. Then, as is easily seen 
\begin{align*}
    \hom_{\ovarrow\th}((\ovarrow\cK,\vv z),(\ovarrow\cG,\vv x))&= \inj((\ovarrow\cK,\vv z)/_{\ovarrow\th},(\ovarrow\cG,\vv x)),\\
    \hom_{\ovarrow\th}((\ovarrow\cK,\vv z),(\ovarrow\cH,\vv y))&=\inj((\ovarrow\cK,\vv z)/_{\ovarrow\th},(\ovarrow\cH,\vv y)).
\end{align*}
Then
\begin{align*}
\hom((\ovarrow\cK,\vv{z}),(\ovarrow\cG,\vv{x})) &= \inj((\ovarrow\cK,\vv{z}),(\ovarrow\cG,\vv{x})) + \sum_{\ovarrow\th\in\Part(K)-\{\zz\}} \inj((\ovarrow\cK,\vv{z})/_{\ovarrow\th},(\ovarrow\cG,\vv{x})),\\
\hom((\ovarrow\cK,\vv{z}),(\ovarrow\cH,\vv{y})) &= \inj((\ovarrow\cK,\vv{z}),(\ovarrow\cH,\vv{y})) + \sum_{\ovarrow\th\in\Part(K)-\{\zz\}} \inj((\ovarrow\cK,\vv{z})/_{\ovarrow\th},(\ovarrow\cH,\vv{y})).
\end{align*}
Since 
\[
\hom((\ovarrow\cK,\vv{z}),(\ovarrow\cG,\vv{x}))\equiv\hom((\ovarrow\cK,\vv{z}),(\ovarrow\cH,\vv{y}))\pmod p,
\] 
and 
\[
\inj((\ovarrow\cK,\vv{z})/_\th,(\ovarrow\cG,\vv{x}))\equiv\inj((\ovarrow\cK,\vv{z})/_{\ovarrow\th},(\ovarrow\cH,\vv{y}))\pmod p,
\] 
for all $\ovarrow\th\in\Part(K)-\{\zz\}$, it implies 
\[
\inj((\ovarrow\cK,\vv{z}),(\ovarrow\cG,\vv{x}))\equiv\inj((\ovarrow\cK,\vv{z}),(\ovarrow\cH,\vv{y}))\pmod p.
\]
Finally, we prove that \eqref{lavasEquInj} for $(\ovarrow\cK, \vv{z})=(\ovarrow\cG,\vv x)$ implies $(\ovarrow\cG, \vv{x}) \cong (\ovarrow\cH, \vv y)$. An injective homomorphism from a relational structure to itself is an automorphism. Since $(\ovarrow\cG, \vv{x})$ is $p$-rigid, $|\Aut(\ovarrow\cG,\vv x)|=\inj((\ovarrow\cG,\vv x),(\ovarrow\cG,\vv x))\not\equiv0\pmod p$. Therefore,  $\inj((\ovarrow\cG,\vv{x}),(\ovarrow\cH,\vv y))\not\equiv0\pmod p$, meaning there is an injective homomorphism from $(\ovarrow\cG,\vv x)$ to $(\ovarrow\cH,\vv y)$. In a similar way, there is an injective homomorphism from $(\ovarrow\cH,\vv y)$ to $(\ovarrow\cG,\vv x)$. Thus, the two structures are isomorphic.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{pro:mult-uniqueness-main}]
Suppose the contrary, that $\ovarrow\cH_1$ and $\ovarrow\cH_2$ are two different non-isomorphic $p$-reduced forms of $\ovarrow\cH$. By Proposition~\ref{pro:mult-aut-reduction} for any structure $\cG$
\[
\hom(\ovarrow\cG, \ovarrow\cH_1) \equiv \hom(\ovarrow\cG,\ovarrow\cH)\equiv \hom(\ovarrow\cG, \ovarrow\cH_2) \pmod{p}.
\]
By Lemma~\ref{lem:lovasz-multi-structure} we can conclude $\cH_1 \cong \cH_2$. The result follows.
\end{proof}

