%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Proof of Theorem~\ref{the:ConstantCSP-main}}\label{sec:appendix-const}
%% \input{Data/r-appendix-const}

The goal of this subsection is to prove Theorem~\ref{the:ConstantCSP-main}. 

\renewcommand{\thether}{2.6}
\begin{ther}
Let $\cH$ be a multi-sorted relational structure and $p$ prime.\\[1mm]
(1) $\NpCSP(\ovarrow\cH^=)$ is Turing reducible to $\NpCSP(\ovarrow\cH)$;\\[1mm]
(2) Let $\ovarrow\cH$ be $p$-rigid. Then $\NpCSP(\ovarrow\cH^\const)$ is Turing reducible to $\NpCSP(\ovarrow\cH)$. 
\end{ther}

We start by introducing some auxiliary construction. For a relational structure $\cH$ the \emph{indicator problem} $\cI_n(\ovarrow\cH)$ \cite{Jeavons99:expressive} is defined as follows. Let $\ovarrow\cH=(\colect{H_i}{i\in[k]};\vc\rel m)$ be a (multi-sorted) relational structure and $n\in\nat$.
The $n$th indicator problem $\cI_n(\ovarrow\cH)$ for $\ovarrow\cH$ is defined to be  an instance of $\CSP(\ovarrow\cH)$ given by:
\begin{itemize}
    \item The set of variables $V$ is the set $V=\bigcup_{i\in [k]}H_i^n$;
    \item The domains are from $\ovarrow\cH$;
    \item For every (say, $\ell$-ary) relation $\rel_s\sse H_{i_1}\tm\dots\tm H_{i_\ell}$ of $\ovarrow\cH$ and every $\bc^j=(c_{j1}\zd c_{jn})\in H_{i_j}^n$, $j\in[\ell]$,  such that $\{\vc\bc n\}\sse\rel_s$, $\bc_i=(c_{1i}\zd c_{\ell i})$,
$\cI_n(\ovarrow\cH)$ contains the constraint $\ang{(\bc^1\zd\bc^k),\rel_s}$.
\end{itemize}
Let also $RG_n(\ovarrow\cH)$ denote the set of solutions of $\cI_n(\ovarrow\cH)$.

\begin{lemma}[\cite{Bodnarchuk69:Galua1,Geiger68:closed,Jeavons99:expressive}]\label{lem:indicator}
(1) $RG_n(\ovarrow\cH)$ is the set of all $n$-ary polymorphisms of $\ovarrow\cH$.\\[2mm] 
(2) $RG_n(\ovarrow\cH)$ is conjuctive-definable in $\ovarrow\cH$.
%% (3) $\ovarrow\cH$ has a Mal'tsev polymorphism if and only if $RG_3(\ovarrow\cH)$ contains a tuple $\vf$ such that $\vf(c_1,c_1,c_2)=\vf(c_2,c_1,c_1)=c_2$ for any $c_1,c_2\in H_i$ for every $i\in[k]$.
\end{lemma}


\begin{proof}[Proof of Theorem~\ref{the:ConstantCSP-main}]
(1) Let $\cP$ be an instance of $\NpCSP(\ovarrow\cH^=)$. The goal is to eliminate all equality relations $=_{H_i}$ for each domain $H_i$, where $i \in [k]$. To achieve this, we apply a straightforward procedure: For every constraint of the form $=_{H_i}(u, v)$ in $\cP$, we remove it from $\cP$ and replace every occurrence of $v$ with $u$.

The resulting problem instance, denoted as $\cP^*$, belongs to $\NpCSP(\ovarrow\cH)$. This reduction can clearly be executed in polynomial time. Additionally, although the set of solutions to $\cP^*$ differs from the set of solutions to $\cP$ (as some variables are eliminated), both instances have the same cardinality.

(2) We follow the same line of argument as the proof of a similar result in \cite{ref:BULATOV_TowardDichotomy} for exact counting, and \cite{DBLP:conf/stoc/BulatovK22} for modular counting. Let $H = \colect{H}{i\in[k]}$, where $H_i = \{ a_{i,1}, ..., a_{i,\ell_{i}} \}$, and let $\relo = \{(\ovarrow\vf_1(a_{1,1})\zd, \ovarrow\vf_1(a_{1,\ell_1}), \zd \ovarrow\vf_k(a_{k,1}, \zd \ovarrow\vf_k(a_{k,\ell_{k}}))  \mid \ovarrow\vf \in \Hom(\ovarrow\cH, \ovarrow\cH) \}$ be the relation conjunctive definable by Lemma~\ref{lem:indicator} through the indicator problem. By Theorem~\ref{the:ConstantCSP-main}(1) and Lemma~\ref{lem:conjunctive} we may assume that $\ovarrow\cH$ has $=_H$ and $\relo$ as its predicates.

Let $\cP = (V;\cC)$ be an instance of $\NpCSP(\ovarrow\cH^\const)$. We construct an instance $\cP'=(V',\cC')$ of $\NpCSP(\ovarrow\cH)$ as follows. 
\begin{itemize}
    \item 
    $V'= V \cup \bigcup_{i \in [k]} \{v_{a_{i,j}}\mid a_{i,j} \in H_i \}$;
    \item
    $\cC'$ consists of three parts: $\{C=\ang{\bx,\rel}\in\cC\mid \rel\in\sg\}$, $\{\ang{(v_{a_1}\zd v_{a_n}),\relo}\}$, and\linebreak  $\{\ang{(x,v_{a_{i,j}}),=_{H_i}}\mid \ang{(x),C_{a_{i,j}}}\in\cC\}$.
\end{itemize}

The number of solutions of $\cP$ equals the number of solutions $\ovarrow\vf$ of $\cP'$ such that $\vf_i(v_{a_{i,j}}) = a_{i,j}$ for all $a_{i,j} \in H_i$ where $i \in [j], j\in [\ell_i]$. Let $U$ be the set of all such solutions of $\cP'$ and $T=|U|$. Then $T$ can be computed in two stages.

Let again $\Part(H)$ be the poset of partitions of $H = \colect{H_i}{i \in [k]}$. Note that each partition consists of collection of partitions as $\theta = \colect{\theta_i}{i \in [k]}$ where each $\theta_i$ is a partition for $H_i$. For every partition $\th\in\Part(H)$ we define $\cP'_\th$ as the instance $(V',\cC_\th)$, where 
\[
    \cC_\th=\cC'\cup\{ \constCSP{ (v_{a_{i,j}}, v_{a_{i,j'}})}{=_{H_i}}\mid (a_{i,j},a_{i,j'})\in\th_i \}.
\]
Note that if $\ovarrow\vf$ is a solution of $\cP'$, then $\vf$ is a solution of $\cP'_{\theta}$ if and only if $\vf_i(v_{a_{i,j}}) = \vf_i(v_{a_{i,j'}})$ for every $a_{i,j},a_{i,j'}$ from the same class of $\theta_i$. Let us denote by $M(\th)$ the number of solutions of $\cP'_\th$. The number $M(\th)$ can be computed using the oracle $\NpCSP(\cH)$, since we assume that all $=_{H_i}$'s and $\relo$ are predicates of $\cH$.

Next, we find the number of solutions $\ovarrow\vf$ of $\cP'$ that assign $v_{a_{i,j}}$, $a_{i,j}\in H_i$, pairwise different values. Let $W$ be the set of all such solutions. Let us denote by $N(\th)$ the number of all solutions $\vf$ of $\cP'_\th$ such that $\ovarrow\vf_i(v_{a_{i,j}})=\ovarrow\vf_i(v_{a_{i,j'}})$ if and only if $a_{i,j},a_{i,j'}$ belong to the same class of $\th_i$. In particular, $N(\zz)=|W|$. The number $N(\zz)$ can be obtained using the M\"obius inversion formula for the poset $\mathsf{Part}(H)$. Let $\FUNC{w}{H}{\mathbb{Z}}$ be M\"obius-inversion function. Also, observe that for any $\th\in\Part(H)$
\[
M(\th)=\sum_{\eta\ge\th}N(\eta).
\]
Therefore, 
\[
N(\zz) = \sum_{\th\in\Part(H)} w(\th) M(\th).
\]
Thus $N(\zz)$ can be found through a constant number of calls to $\NpCSP(\ovarrow\cH)$.

Now, we express $T$ via $N(\zz)$. Let $G=\Aut(\ovarrow\cH)$ be the automorphism group of $\cH$. We show that $W= \{ g\circ\vf\mid g \in G, \vf \in U \}$. For every solution $\vf$ in $U$ and every $g \in G$, $g\circ\vf$ is also a solution of $\cP'$. Moreover, since $g$ is one-to-one, $g\circ\vf$ is in $W$. Conversely, for every $\psi \in W$, there exists some $g \in G$ such that $g(a) =\psi(v_a)$, $a \in H$. Note that $g^{-1} \in G$ implies $\vf =g^{-1}\circ\psi \in U$, which witnesses that  $\psi= g\circ\vf$ is of the required form.
Finally, for every $\vf,\vf' \in U$ and every $g,g'\in  G$, if $\vf|_{\{v_a\mid a \in H \}}\ne\vf'|_{\{v_a\mid a \in H \}}$ or $g\ne g'$ then $g\circ\vf\ne g'\circ \vf'$. Thus, $N(\zz)=|G|\cdot T$. Since $\cH$ is $p$-rigid,  $|G|\not \equiv 0\pmod p$. Therefore  $T \equiv |G|^{-1}\cdot N(\zz)\pmod{p}$.
\end{proof}


